window.classifyAdminDataError = function (error) {
  const status = Number(error?.status) || 0;
  const code = String(error?.code || "");
  if (status === 401 || code === "AUTH_REQUIRED") return { code: "AUTH_REQUIRED", status: 401 };
  if (status === 403 || /permission[_-]denied/i.test(code)) return { code: "TENANT_FORBIDDEN", status: 403 };
  if (status === 404 || code === "NOT_FOUND") return { code: "NOT_FOUND", status: 404 };
  if (status === 409 || code === "CREDENTIAL_CONFLICT") return { code: "CREDENTIAL_CONFLICT", status: 409 };
  if (status === 503 || code === "PG_UNAVAILABLE") return { code: "PG_UNAVAILABLE", status: 503 };
  return { code: "UNEXPECTED", status: 500 };
};

window.getAdminDataErrorMessage = function (error) {
  const { code } = window.classifyAdminDataError(error);
  const messages = {
    AUTH_REQUIRED: t("auth_session_expired", "Sessiya tugagan. Qayta kiring."),
    TENANT_FORBIDDEN: t("access_denied", "Kirish taqiqlangan."),
    NOT_FOUND: t("resource_not_found", "Ma'lumot topilmadi."),
    CREDENTIAL_CONFLICT: t("staff_pin_taken", "Bu PIN kod boshqa xodimda band."),
    PG_UNAVAILABLE: t("pg_unavailable", "Ma'lumotlar bazasi vaqtincha mavjud emas."),
    UNEXPECTED: t("error_occurred", "Xatolik yuz berdi!"),
  };
  return messages[code];
};

function _shRecordError(path, err) {
  const msg = window.classifyAdminDataError(err).code;
  window._shFirebaseErrors.unshift({ time: new Date(), path: path || "?", message: msg });
  if (window._shFirebaseErrors.length > 50) window._shFirebaseErrors.length = 50;
  if (typeof window._onShFirebaseError === "function") {
    try { window._onShFirebaseError(path, msg); } catch (e) { /* noop */ }
  }
  // Superadmin panelga Firebase permission xatosi haqida signal beramiz.
  // AlertReporter recursion fix: a permission error whose PATH is the
  // systemAlerts tree itself must never be reported THROUGH the very
  // mechanism that writes to systemAlerts — that is exactly the reported
  // "permission denied -> raiseSystemAlert -> write to systemAlerts ->
  // permission denied -> raiseSystemAlert -> ..." loop. Every other path's
  // errors still get reported normally (no blanket swallowing).
  const isAlertReporterPath = typeof path === "string" && path.includes("/systemAlerts");
  if (!isAlertReporterPath && typeof window.reportFirebasePermissionError === "function") {
    try { window.reportFirebasePermissionError(err, path); } catch (e) { /* noop */ }
  }
}

function onValue(dbRef, onNext, onErrorOrOptions, options) {
  let path = "?";
  try { path = dbRef && _shGetRefPath(dbRef); } catch (e) { /* noop */ }

  const listenerId = Symbol();
  window._shActiveListeners.set(listenerId, { path, since: new Date() });

  const wrappedNext = (...args) => {
    try {
      return onNext(...args);
    } catch (e) {
      _shRecordError(path, e);
      throw e;
    }
  };

  const userErrorCb = typeof onErrorOrOptions === "function" ? onErrorOrOptions : null;
  const wrappedError = (err) => {
    _shRecordError(path, err);
    if (userErrorCb) userErrorCb(err);
  };

  let unsubscribe;
  if (userErrorCb) {
    unsubscribe = _onValueRaw(dbRef, wrappedNext, wrappedError, options);
  } else if (onErrorOrOptions && typeof onErrorOrOptions === "object") {
    unsubscribe = _onValueRaw(dbRef, wrappedNext, wrappedError, onErrorOrOptions);
  } else {
    unsubscribe = _onValueRaw(dbRef, wrappedNext, wrappedError);
  }

  return function unsubscribeWrapped(...args) {
    window._shActiveListeners.delete(listenerId);
    return unsubscribe(...args);
  };
}

function _shGetRefPath(dbRef) {
  // Firebase ref obyektidan o'qiladigan yo'l (path) ni chiqarib olish
  try {
    if (dbRef && dbRef._path && dbRef._path.pieces_) {
      return "/" + dbRef._path.pieces_.join("/");
    }
    if (dbRef && typeof dbRef.toString === "function") {
      const full = dbRef.toString();
      // To'liq URL bo'lsa, faqat domendan keyingi qismini qaytaramiz
      const match = full.match(/^https?:\/\/[^/]+(\/.*)$/);
      return match ? decodeURIComponent(match[1]) : full;
    }
  } catch (e) { /* noop */ }
  return "?";
}

