// 🔑 STOL KALITINI STANDARTLASHTIRISH
// Firebase'da stollar har doim "table_5" formatida saqlanadi.
// Ba'zi joylarda faqat "5" (table raqami) ishlatilgani uchun
// noto'g'ri/"fantom" tugunlar yaratilib, admin panelidagi
// Stollar bo'limi yangilanmay qolardi. Shu funksiya orqali
// barcha tables/ yo'llari bitta formatga keltiriladi.
function getTableKey(tableNumberOrKey) {
  const raw = String(tableNumberOrKey ?? "").trim();
  if (!raw) return raw;
  return raw.startsWith("table_") ? raw : `table_${raw}`;
}
window.getTableKey = getTableKey;

