function notifFilterCategory(type) {
  switch (type) {
    case "reservation": return "reservation";
    case "orders": return "orders";
    case "payment": return "payment";
    case "warning": return "warning";
    case "error": return "error";
    case "feedback": return "system";
    case "staff": return "staff";
    default: return "system";
  }
}

function isSameDay(ts1, ts2) {
  const d1 = new Date(ts1), d2 = new Date(ts2);
  return d1.getFullYear() === d2.getFullYear() && d1.getMonth() === d2.getMonth() && d1.getDate() === d2.getDate();
}

function notifPriority(item) {
  if (item.priority) return item.priority;
  switch (item.type) {
    case "error": return "critical";
    case "warning": return "important";
    default: return "normal";
  }
}

function notifPriorityColor(priority) {
  switch (priority) {
    case "critical": return "#dc2626";   // 🔴 Muhim
    case "important": return "#eab308";  // 🟡 Ogohlantirish
    default: return "#3b82f6";           // 🔵 Oddiy
  }
}

function notifDateGroup(ts) {
  const now = new Date();
  const d = new Date(ts);
  const startOfDay = (date) => new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
  const todayStart = startOfDay(now);
  const dayStart = startOfDay(d);
  const diffDays = Math.round((todayStart - dayStart) / 86400000);

  if (diffDays === 0) return t("notif_group_today") || "Bugun";
  if (diffDays === 1) return t("notif_group_yesterday") || "Kecha";
  if (diffDays > 1 && diffDays <= 7) return t("notif_group_last_week") || "O'tgan hafta";
  if (diffDays > 7 && diffDays <= 30) return t("notif_group_last_month") || "O'tgan oy";
  return t("notif_group_older") || "Oldinroq";
}

function notifTypeIcon(type) {
  switch (type) {
    case "reservation": return "📅";
    case "orders": return "🍽";
    case "payment": return "💳";
    case "warning": return "⚠️";
    case "error": return "❌";
    case "feedback": return "⭐";
    default: return "🔔";
  }
}

function formatReservationDateShort(dateStr) {
  if (!dateStr) return "";
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return dateStr;
  const months = [
    t("month_short_jan", "Yan"), t("month_short_feb", "Fev"), t("month_short_mar", "Mar"), t("month_short_apr", "Apr"),
    t("month_short_may", "May"), t("month_short_jun", "Iyun"), t("month_short_jul", "Iyul"), t("month_short_aug", "Avg"),
    t("month_short_sep", "Sen"), t("month_short_oct", "Okt"), t("month_short_nov", "Noy"), t("month_short_dec", "Dek")
  ];
  return `${d.getDate()}-${months[d.getMonth()].toLowerCase()}`;
}

function reservationTimeUntilLabel(dateStr, timeStr) {
  if (!dateStr || !timeStr) return "";
  const target = new Date(`${dateStr}T${timeStr}`);
  if (isNaN(target.getTime())) return "";
  const diffMs = target.getTime() - Date.now();
  if (diffMs <= 0) return t("notif_time_passed") || "Vaqti o'tdi";
  const diffMin = Math.round(diffMs / 60000);
  if (diffMin < 60) return `⏰ ${diffMin} ${t("notif_minutes_suffix") || "daqiqadan"} ${t("notif_later_suffix") || "keyin"}`;
  const diffHr = Math.round(diffMin / 60);
  return `⏰ ${diffHr} ${t("notif_hours_suffix") || "soatdan"} ${t("notif_later_suffix") || "keyin"}`;
}
const tablesAdvancedState = { tables: {}, orders: {} };

window.db = db;

// ROOT CAUSE FIX (superadmin "Restoran login ma'lumotlari" modal breaking
// after visiting a restaurant page and returning): this anonymous sign-in
// used to run UNCONDITIONALLY, on the app's DEFAULT (shared, cross-tab)
// Auth persistence layer. A real staff/manager session (established by
// login.js via signInWithCustomToken() BEFORE redirecting here) should
// never be touched by it — and it wasn't meant to be, since Firebase's own
// signInAnonymously() is a no-op once a user is already signed in. But
// the "Login As" / ?viewAs= flow (superadmin.js's loginAsRestaurantAdmin())
// opens this page with NO prior session at all, so THIS anonymous sign-in
// is what actually establishes one — and because it wrote to the shared
// persistence layer, it was visible to (and could overwrite the identity
// seen by) every other open tab on this origin, including the superadmin
// panel's own tab. A one-line setPersistence() on the superadmin side
// (previous fix) did not reliably prevent this, because the collision
// happens on the WRITE side, not the read side.
//
// Fix: (1) explicitly wait for the SDK to finish restoring any already-
// persisted session before deciding anything (auth.currentUser is not
// reliably populated synchronously on a fresh page load); (2) only fall
// back to signInAnonymously() when there is truly no session yet; (3) when
// that fallback IS needed, switch this auth instance to inMemoryPersistence
// first, so the resulting anonymous identity lives ONLY in this tab's JS
// memory — never written to indexedDB/localStorage/sessionStorage, so it
// is structurally impossible for it to leak into any other tab, including
// the superadmin panel's. A real login.js-issued session is never affected
// by any of this, since step (2) skips the fallback entirely for it.
function _waitForInitialAuthState(authInst) {
  return new Promise((resolve) => {
    const unsubscribe = onAuthStateChanged(authInst, (user) => {
      unsubscribe();
      resolve(user);
    });
  });
}

// Best-effort session-kind label for diagnostics only — never used for any
// authorization decision. providerData is empty for BOTH a real
// signInWithCustomToken() session AND a genuine anonymous one, so it alone
// can't tell them apart (this is exactly what produced the confusing
// "isAnonymous: false, provider: anonymous" log line previously) —
// isAnonymous is checked FIRST, which is the actual authoritative signal.
function _describeSessionProvider(user) {
  if (!user) return null;
  if (user.isAnonymous) return "anonymous";
  return user.providerData?.[0]?.providerId || "custom_token";
}

// Exposed as an awaitable promise (window._adminAuthReady) instead of a
// fire-and-forget IIFE, so the DOMContentLoaded bootstrap below can
// explicitly wait for session establishment to actually finish — and stop
// cleanly on an unresolved restaurant mismatch — instead of racing ahead
// (DOMContentLoaded firing on its own schedule, unrelated to whenever this
// async work happens to finish) and calling checkSubscriptionStatus()/
// init() against whatever auth.currentUser happens to be at that moment.
window._adminAuthReady = (async () => {
  try {
    // Auth root-cause fix pass: "Login As" (superadmin.js's
    // loginAsRestaurantAdmin()) now mints a REAL session server-side
    // (routes/auth.js's /login-as) and hands it here as a one-time
    // ssoToken URL param, instead of leaving this tab with no session at
    // all (which used to fall straight into the anonymous branch below —
    // a session with no restId/role claims, unable to satisfy
    // database.rules.json's auth.token.restId==$restId on ANY restaurant,
    // for ANY read/write). Sign in with it FIRST, before ever considering
    // the anonymous fallback; strip it from the URL immediately after
    // (single-use, no reason to leave it sitting in browser history).
    //
    // Cross-restaurant session leak fix (this pass): this sign-in used to
    // run on Firebase's DEFAULT persistence (browserLocalPersistence/
    // IndexedDB — shared across every tab of this origin AND across page
    // reloads), unlike the anonymous fallback a few lines below, which has
    // ALWAYS deliberately used inMemoryPersistence for exactly this reason
    // (see this file's own much older comment on why: a shared-persistence
    // session written by ONE "Login As" tab is visible to, and gets reused
    // by, every OTHER tab on this origin). Live-reproduced: superadmin opens
    // "Login As" for restaurant B, then opens/reuses another tab for
    // restaurant A — that second tab found restaurant B's real, non-
    // anonymous, restId=B session already sitting in shared storage via
    // _waitForInitialAuthState() below, and (the second bug) nothing ever
    // checked whether that session's restId actually matched the PAGE it
    // was loaded on, so it was used as-is: every restaurants/A/... call
    // then evaluated the Firebase Rule with token.restId=="B", permission
    // denied on everything. Now tab-scoped, exactly like the anonymous
    // fallback — a session minted for one "Login As" tab can no longer
    // leak into a different tab or survive a reload.
    const ssoToken = urlParams.get("ssoToken");
    if (ssoToken) {
      try {
        await setPersistence(auth, inMemoryPersistence);
        await signInWithCustomToken(auth, ssoToken);
      } catch (ssoErr) {
        console.error("[AUTH-DIAG admin.js] ssoToken sign-in failed (falling through to normal session check):", ssoErr.code || ssoErr.message);
      }
      const cleanUrl = new URL(window.location.href);
      cleanUrl.searchParams.delete("ssoToken");
      history.replaceState(null, "", cleanUrl.toString());
    }

    let existingUser = await _waitForInitialAuthState(auth);
    let mismatchDetected = false;
    // Vaqtinchalik, xavfsiz diagnostika — token/parolning o'zi HECH
    // QACHON yo'q, faqat metadata.
    console.log("[AUTH-DIAG admin.js] existing session before decision:", {
      uid: existingUser?.uid || null,
      isAnonymous: existingUser?.isAnonymous ?? null,
      provider: _describeSessionProvider(existingUser),
      url: window.location.href,
    });

    // Cross-restaurant session leak fix — the explicit check the task
    // requires: NEVER trust "a non-null, non-anonymous session" by itself.
    // A real session that happens to be active in this tab must actually be
    // SCOPED to the restaurant this page was opened for (restIdFromUrl, the
    // page's own ?id=/?rest= — not localStorage, which could itself be
    // stale). If it names a DIFFERENT restaurant, it is never used for any
    // read/write here — signed out immediately and treated as no session at
    // all, falling through to the safe (if unauthorized) anonymous branch
    // below rather than silently operating as the wrong restaurant.
    //
    // 🩹 Root-cause fix (subscription/customers/permissions/systemAlerts all
    // denied despite "Firebase autentifikatsiyasi muvaffaqiyatli"): this
    // guard only ever ran when restIdFromUrl was present — but login.js's
    // normal staff-login redirect (the OVERWHELMING majority of real page
    // loads, not just the superadmin "Login As" edge case this guard was
    // originally written for) sends the browser to plain "admin.html" with
    // NO ?rest=/?id= at all, relying entirely on localStorage. On that path
    // this whole block was dead code — a stale, different-restaurant Firebase
    // Auth session sitting in shared browserLocalPersistence (login.js never
    // calls setPersistence — a leftover session from a previous restaurant
    // login on the same browser/kiosk is exactly the scenario the comment
    // above already worried about) sailed through unchecked, `isRealSession`
    // came back true ("Auth muvaffaqiyatli"), and every subsequent
    // restId-scoped read/write (checkSubscriptionStatus, loadCustomersModule,
    // checkPermissions, the systemAlerts diagnostic write) was denied because
    // auth.token.restId didn't match the restId those calls actually use
    // (currentRestaurantId, resolved from THIS SAME localStorage value).
    // Fix: when the URL doesn't specify one, fall back to comparing against
    // localStorage — not because localStorage is trusted as an authorization
    // signal, but because it's the exact value every downstream call in this
    // file is about to use, so a mismatch against it is a real, actionable
    // signal worth catching here instead of surfacing as a confusing
    // permission_denied cascade several function calls later.
    const expectedRestId = restIdFromUrl || localStorage.getItem("restaurantId");
    let haltReason = "restaurant_mismatch";
    if (existingUser && !existingUser.isAnonymous && expectedRestId) {
      // Fail-CLOSED fix: this used to leave sessionRestId as null (falsy)
      // if getIdTokenResult() threw for any reason, which made the "if
      // (sessionRestId && sessionRestId !== restIdFromUrl)" check below
      // FALSE — silently SKIPPING the mismatch check entirely and letting
      // an unverifiable session through unchecked. That's the opposite of
      // what this guard exists for. A distinct "could not verify" state is
      // now tracked separately and treated exactly like a confirmed
      // mismatch — sign out, never use a session whose restaurant binding
      // couldn't be positively confirmed.
      let sessionRestId = null;
      let sessionRole = null;
      let claimsCheckFailed = false;
      try {
        const claimsResult = (await existingUser.getIdTokenResult())?.claims || {};
        sessionRestId = claimsResult.restId ?? null;
        sessionRole = claimsResult.role ?? null;
      } catch (_e) {
        claimsCheckFailed = true;
      }
      // Client-session guard (this pass): the restId check above only ever
      // asked "is this session scoped to the right RESTAURANT?" — never "is
      // this even a STAFF session at all?". Reproduced live: a customer/
      // QR-menu session (routes/qr.js's POST /qr/session — uid
      // client_${restId}_${table}, claims.role:"client", claims.type:
      // "customer") is, BY DESIGN, scoped to the SAME restaurant whose
      // admin.html happens to be open on the same browser — so it sailed
      // straight through the restId-match check above and was accepted as
      // "real": console showed resolvedRestId matching the page, yet every
      // admin-only path (users/admin_1, subscription, systemAlerts) came
      // back permission_denied, because database.rules.json correctly
      // requires a staff role there (never weakened — the fix belongs here,
      // not in Rules). How the client session ended up being *considered*
      // here at all: client.js's signInWithCustomToken() never called
      // setPersistence() first, so it inherited Firebase's default
      // browserLocalPersistence — shared IndexedDB for the whole origin —
      // instead of a tab-scoped persistence; any tab of this origin that
      // later loads with no fresher session of its own (admin.html
      // included) can restore that leftover session as its own
      // auth.currentUser. Fixed at the source too (see client.js), but
      // this check stays regardless — admin.html must never trust a
      // non-staff role even if some other future flow leaks one in here.
      const isClientRole = sessionRole === "client";
      const isMismatch = claimsCheckFailed || sessionRestId !== expectedRestId;
      if (isClientRole) {
        console.error("[AUTH-DIAG admin.js] 🚫 CLIENT-ROLE SESSION REJECTED — admin.html never operates on a customer/QR-menu session, signing out:", {
          uid: existingUser.uid,
          sessionRestId,
          sessionRole,
        });
        await signOut(auth).catch(() => {});
        existingUser = null;
        mismatchDetected = true;
        haltReason = "client_role_forbidden";
      } else if (isMismatch) {
        console.error("[AUTH-DIAG admin.js] 🚫 SESSION/RESTAURANT MISMATCH (or unverifiable) — signing out, never using this session:", {
          uid: existingUser.uid,
          sessionRestId,
          requestedRestId: expectedRestId,
          requestedRestIdSource: restIdFromUrl ? "url" : "localStorage",
          claimsCheckFailed,
        });
        await signOut(auth).catch(() => {});
        existingUser = null;
        mismatchDetected = true;
        haltReason = "restaurant_mismatch";
      }
    }

    if (!existingUser) {
      if (mismatchDetected) {
        // Security requirement: a detected restaurant mismatch (or a
        // rejected client-role session) must NOT silently degrade into an
        // anonymous session either — that would still let the rest of the
        // page's bootstrap (checkSubscriptionStatus -> init() -> every
        // loadXxxSettings()) run against a session with no restId/role
        // claim at all, producing the exact same confusing permission_denied
        // cascade this whole investigation started from, just for a
        // different underlying reason. Stop here and let the
        // DOMContentLoaded handler show a clear, blocking message instead.
        console.error("[AUTH-DIAG admin.js] 🛑 Halting initialization — no anonymous fallback after a " + haltReason + ". Re-open this restaurant from Superadmin's \"Login As\", or log in with a staff account.");
        return { ok: false, reason: haltReason };
      }
      await setPersistence(auth, inMemoryPersistence);
      await signInAnonymously(auth);
      console.log("[AUTH-DIAG admin.js] fell back to in-memory anonymous session:", {
        uid: auth.currentUser?.uid || null,
        isAnonymous: auth.currentUser?.isAnonymous ?? null,
      });
    }

    // Auth root-cause fix pass: this used to log a single, unconditional
    // "Firebase autentifikatsiyasi muvaffaqiyatli" message here regardless
    // of which branch above actually ran — including the anonymous
    // fallback — which is exactly why permission_denied errors right
    // after it looked so confusing (the log said "success" either way).
    // Replaced with one that states plainly which kind of session is
    // actually active, plus the restId/role claims every Firebase Rule
    // and every backend requirePermission() call actually checks — so a
    // real gap is visible here instead of only surfacing as a much more
    // confusing permission_denied several function calls later.
    const finalUser = auth.currentUser;
    let claims = {};
    try {
      claims = finalUser ? (await finalUser.getIdTokenResult())?.claims || {} : {};
    } catch (_e) { /* best-effort diagnostic only */ }
    const isRealSession = !!finalUser && finalUser.isAnonymous !== true;
    const localRestId = localStorage.getItem("restaurantId");
    console.log(
      isRealSession ? t("firebase_auth_ok_log") : "[AUTH-DIAG admin.js] ⚠️ Operating on an ANONYMOUS session — restId/role-gated reads and writes WILL be denied:",
      {
        uid: finalUser?.uid || null,
        isAnonymous: finalUser?.isAnonymous ?? null,
        provider: _describeSessionProvider(finalUser),
        resolvedRestId: claims.restId ?? null,
        resolvedRole: claims.role ?? null,
        // 🆕 [AUTH-RULE-DIAG] — the fields every restaurants/$restId Rule and
        // rbac.js's resolveIdentity() actually check (never the raw token
        // itself). restIdMatchesLocalStorage is the single boolean that
        // directly explains "Auth muvaffaqiyatli" + every downstream
        // restId-scoped permission_denied in the SAME breath: if this is
        // false, every read/write below is doomed regardless of role/rules.
        claimType: claims.type ?? null,
        claimRtdbUserId: claims.rtdbUserId ?? null,
        claimIsSuperAdmin: claims.isSuperAdmin ?? null,
        signInProvider: claims.firebase?.sign_in_provider ?? null,
        localStorageRestId: localRestId,
        restIdMatchesLocalStorage: claims.restId != null ? claims.restId === localRestId : null,
      }
    );
    // Exposed for the 5 known failure points (checkSubscriptionStatus,
    // checkPermissions, applyUserPermissions, loadCustomersModule,
    // AlertReporter) to call right before their own restId-scoped
    // read/write — catches the case where the session CHANGES (another tab
    // signs in/out, a token refresh swaps claims) between this boot-time
    // check and the moment a specific operation actually runs, which the
    // one-shot log above can't see. Re-reads auth.currentUser fresh each
    // time rather than closing over the values above. Never logs the ID
    // token itself — claims only.
    window._authRuleDiag = async function (context, path) {
      const user = auth.currentUser;
      let c = {};
      try { c = user ? (await user.getIdTokenResult())?.claims || {} : {}; } catch (_e) { /* best-effort */ }
      const requestedRestId = localStorage.getItem("restaurantId");
      console.log(`[AUTH-RULE-DIAG] ${context}`, {
        path: path || null,
        authUid: user?.uid || null,
        isAnonymous: user?.isAnonymous ?? null,
        claimRestId: c.restId ?? null,
        claimRole: c.role ?? null,
        claimType: c.type ?? null,
        claimRtdbUserId: c.rtdbUserId ?? null,
        claimIsSuperAdmin: c.isSuperAdmin ?? null,
        requestedRestId,
        restIdMatch: c.restId != null ? c.restId === requestedRestId : null,
      });
    };
    return { ok: isRealSession, reason: isRealSession ? null : "anonymous" };
  } catch (err) {
    console.error(err);
    return { ok: false, reason: "error" };
  }
})();

