// Header sarlavhasi uchun rol → "... paneli" nomi. Bir marta, markazlashtirilgan
// joyda ta'riflangan, shuning uchun yangi rol qo'shilsa faqat shu yerni yangilash kifoya.
const HEADER_PANEL_LABEL = {
  owner: { key: "header_panel_owner", def: "Admin paneli" },
  admin: { key: "header_panel_owner", def: "Admin paneli" }, // eski/legacy rol nomi
  manager: { key: "header_panel_manager", def: "Menejer paneli" },
  cashier: { key: "header_panel_cashier", def: "Kassir paneli" },
  waiter: { key: "header_panel_waiter", def: "Ofitsiant paneli" },
  chef: { key: "header_panel_chef", def: "Oshpaz paneli" },
  head_chef: { key: "header_panel_head_chef", def: "Bosh oshpaz paneli" },
  delivery_manager: { key: "header_panel_courier", def: "Kuryer paneli" },
  courier: { key: "header_panel_courier", def: "Kuryer paneli" },
  inventory_manager: { key: "header_panel_inventory", def: "Ombor paneli" },
  finance: { key: "header_panel_finance", def: "Moliyachi paneli" },
  crm: { key: "header_panel_crm", def: "CRM paneli" },
  hr: { key: "header_panel_hr", def: "HR paneli" }
};

function getHeaderPanelTitle() {
  // window._rbacRole — listenRbacPermissions() orqali Firebase'dan real-time
  // o'qiladigan, sidebar/RBAC tizimining o'zi ishlatadigan YAGONA ishonchli manba.
  //
  // localStorage["role"] endi bu yerda UMUMAN ishlatilmaydi. Sabab: u oldingi,
  // boshqa foydalanuvchi (masalan admin moliyachi hisobini sinab ko'rgan bo'lsa)
  // sessiyasidan qolgan "yopishib qolgan" qiymat bo'lishi mumkin — chunki hech
  // qanday logout/login oqimi uni tozalamaydi. localStorage'ga ishonib header
  // ko'rsatish "boshqa odamning roli" ni ko'rsatib qo'yish xavfini tug'diradi.
  //
  // window._rbacRole hali o'rnatilmagan bo'lsa (Firebase javobi hali kelmagan),
  // null qaytaramiz — chaqiruvchi joy buni "hali tayyor emas" deb talqin qilib,
  // Firebase javobi kelgach qayta chaqiriladi (loadRestaurantNameForHeader
  // listenRbacPermissions() ichida har doim qayta chaqiriladi).
  const role = window._rbacRole;
  if (!role) return null;

  const meta = HEADER_PANEL_LABEL[role];
  if (meta) return t(meta.key, meta.def);

  // Standart ro'yxatda yo'q — custom rol bo'lishi mumkin (Rollar bo'limida
  // yaratilgan). resolveRoleConfig orqali foydalanuvchi bergan chiroyli nomni
  // (masalan "Ombor boshlig'i") olamiz, xom rol ID'sini ko'rsatmaslik uchun.
  if (typeof resolveRoleConfig === "function") {
    const cfg = resolveRoleConfig(role);
    if (cfg && cfg.isCustom && cfg.label) {
      return `${cfg.label} ${t("header_panel_suffix", "paneli")}`;
    }
  }

  return t(`header_panel_${role}`, `${role.charAt(0).toUpperCase()}${role.slice(1)} paneli`);
}

window.loadRestaurantNameForHeader = async function () {
  const restId = localStorage.getItem("restaurantId");
  if (!restId) return;

  try {
    // Permission-denied fix: restaurants/$restId/info has an unconditional
    // ".read": true carve-out (database.rules.json — needed pre-login by
    // login.js), but restaurants/$restId/settings requires a real session
    // (auth != null). Promise.all fails the WHOLE call the instant either
    // promise rejects — on a fresh page load, if this fires before Firebase
    // Auth has finished restoring the session (a real, observed race, not
    // hypothetical), the settings read can reject while info would have
    // succeeded, and the header silently fails to show a name at all
    // instead of falling back to info.name as line below already intends.
    // Promise.allSettled lets each resolve independently — info's value is
    // still used even if settings currently can't be read; a later,
    // successful call (listenRbacPermissions() already re-invokes this)
    // picks up settings.restaurantName once a session exists.
    const [settingsResult, infoResult] = await Promise.allSettled([
      get(ref(db, `restaurants/${restId}/settings`)),
      get(ref(db, `restaurants/${restId}/info`))
    ]);

    const settings = settingsResult.status === "fulfilled" ? (settingsResult.value.val() || {}) : {};
    const info = infoResult.status === "fulfilled" ? (infoResult.value.val() || {}) : {};
    if (infoResult.status === "rejected") throw infoResult.reason;

    // window.currentGlobalRestName keeps its EXACT previous fallback
    // behavior (other, unrelated consumers already depend on it — cashier
    // receipts, systemAlert payloads, etc. — none of that is in this
    // task's scope). A separate, header-display-only value is used just
    // below to decide whether to show the "|  name" pair at all — an
    // empty/unknown name hides both rather than showing a literal
    // "Noma'lum Restoran" wedged between "Administrator" and "|".
    const restName = settings.restaurantName || info.name || t("unknown_restaurant", "Noma'lum Restoran");
    const restNameForHeader = settings.restaurantName || info.name || "";

    window.currentGlobalRestName = restName;
    window.currentGlobalLogoUrl = settings.restaurantLogoUrl || "";

    // Header: "Nesta ERP Administrator | <Restoran nomi>" — "Nesta ERP
    // Administrator" is already fully rendered by header.js's SHARED
    // renderHeader() call (#nestaHeaderBrand — reused as-is by every panel,
    // not touched here). Only the restaurant name + its "|" separator are
    // admin.html-specific siblings, filled in from window.currentGlobalRestName
    // — the SAME state this function already computed above; no second
    // Firebase query for the header specifically. This used to target
    // `.header h1` / `.brand h1` / `.logo` — none of which exist in admin.html's
    // actual DOM (a stale selector from before header.js existed), so this
    // silently never updated anything visible; that's the root cause of the
    // header staying stuck on its static default. Fixed to target the real
    // elements. Both stay hidden (not a dangling "|" with nothing after it)
    // until a real name is available — restaurant name is never hardcoded or
    // guessed.
    const restSepEl = document.getElementById("adminHeaderRestSep");
    const restNameEl = document.getElementById("adminHeaderRestName");
    if (restNameEl) {
      restNameEl.textContent = restNameForHeader;
      restNameEl.title = restNameForHeader; // to'liq nom uzun bo'lib, ellipsis bilan qisqarganda hover orqali ko'rinsin
      restNameEl.style.display = restNameForHeader ? "" : "none";
    }
    if (restSepEl) restSepEl.style.display = restNameForHeader ? "" : "none";

    document.title = restNameForHeader
      ? `${t("product_erp", "Nesta ERP")} | ${restNameForHeader}`
      : t("admin_document_title", "Nesta ERP — Admin");

  } catch (error) {
    console.error(t("rest_name_load_error", "Restoran nomini yuklashda xatolik:"), error);
  }
};

