window.saveMaxTable = async function () {
  const input = document.getElementById("maxTablesInput") || document.getElementById("maxTablesSettings");
  if (!input) return;

  const val = parseInt(input.value);

  if (isNaN(val) || val < 1) {
    alert(t("a_valid_number", "Iltimos, to'g'ri son kiriting!"));
    return;
  }

  const restId = localStorage.getItem("restaurantId");
  const database = window.db || (typeof db !== 'undefined' ? db : null);

  try {
    await update(ref(database, `restaurants/${restId}/settings`), {
      maxTable: val
    });

    alert(t("a_tables_saved", "Stollar soni saqlandi!"));

    // Eslatma: eskirgan renderTablesGrid() chaqiruvi shu yerdan olib
    // tashlandi — u "Stol qo'shish" tugmasisiz va yangi 8-status
    // ko'rinishisiz eski gridni chizib, #tablesGrid ustidan yozib yuborardi
    // (xuddi 10560-qator atrofidagi izohda tasvirlangan muammo kabi).
    // `restaurants/${restId}/settings/maxTable` yozuvi tables/ tugunini
    // o'zgartirmaydi, shuning uchun listenTablesRealtime() ichidagi onValue
    // listener bu yerda alohida qayta chizishni talab qilmaydi.
  } catch (error) {
    console.error(t("error_log", "Xato:"), error);
    alert(t("notify.error", "Saqlashda xatolik yuz berdi."));
  }
};

