// 💰 Taom narxi maydonlari (addPrice / editPrice): kiritilayotgan raqamga
// avtomatik minglik ajratgich (bo'shliq) qo'shadi — 10 emas 10 000 ko'rinsin.
(function bindMenuPriceFormatting() {
  function fmtThousands(v) {
    const digits = String(v || "").replace(/\D/g, "");
    if (!digits) return "";
    return digits.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  }
  [addPrice, editPriceInput].forEach((el) => {
    if (!el) return;
    el.addEventListener("input", function () {
      const raw = this.value.replace(/\D/g, "");
      this.value = fmtThousands(raw);
      const pos = this.value.length;
      this.setSelectionRange(pos, pos);
    });
  });
})();

