function escapeHtml(value = "") {
  return String(value)
    .replaceAll("&", "&amp;").replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;").replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

// ─── Payroll jadvali uchun: sonlarni "." bilan minglik ajratkichli formatlash ───
// Faqat Xodimlar oyligini hisoblash jadvalida ishlatiladi (dizayn/ranglarga tegilmaydi).
// Masalan: 50 -> "50.000", 3140000 -> "3.140.000", -30 -> "-30.000"
function formatPayrollDots(num) {
  const n = Number(num) || 0;
  const negative = n < 0;
  const intStr = Math.round(Math.abs(n)).toString();
  const withDots = intStr.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return (negative ? "-" : "") + withDots;
}

// Formatlangan matnli inputdan ("50.000") xom sonni ("50") qaytaradi.
function parsePayrollDots(str) {
  const cleaned = String(str ?? "").replace(/\./g, "").replace(/[^\d-]/g, "");
  const n = Number(cleaned);
  return isNaN(n) ? 0 : n;
}

// Matnli inputga teriladigan vaqtda jonli "." qo'yib boradi.
window.formatPayrollInputLive = function (inputEl) {
  const hasDigit = /\d/.test(inputEl.value);
  const raw = parsePayrollDots(inputEl.value);
  const negative = inputEl.value.trim().startsWith("-");
  inputEl.value = !hasDigit ? "" : formatPayrollDots(negative ? -Math.abs(raw) : raw);
};

// ─── Buyurtma raqamini formatlash: ORD-1 (restoran ichi) yoki DVR-1 (yetkazib berish) ───
// Ikki chaqiruv shakli qo'llab-quvvatlanadi:
//   formatOrderNumber(order)                — order obyektidan avtomatik aniqlaydi
//   formatOrderNumber(orderNumber, isDelivery) — xom raqam + boolean bilan
// Xom orderNumber mavjud bo'lmasa (masalan eski buyurtmalarda), null qaytaradi —
// chaqiruvchi tomon o'zining eski fallback'ini (masalan id.slice(-4)) ishlatishi kerak.
// DVR va ORD alohida hisoblagichlardan (meta/orderCounterOrd, meta/orderCounterDvr)
// olinadi — shu sabab ikkalasi ham 1 dan boshlanadi va bir-biriga aralashmaydi.
// Barcha panellarda (admin/chef/waiter/client) format bir xil bo'lishi shart.
function formatOrderNumber(orderOrNumber, isDeliveryFlag) {
  let num, prefix;
  if (orderOrNumber && typeof orderOrNumber === "object") {
    num = orderOrNumber.orderNumber;
    const type = normalizeOrderType(orderOrNumber);
    prefix = type === ORDER_TYPE.DELIVERY ? "DVR" : type === ORDER_TYPE.TAKEAWAY ? "Take" : "ORD";
  } else {
    num = orderOrNumber;
    prefix = isDeliveryFlag ? "DVR" : "ORD";
  }
  if (num === undefined || num === null || num === "") return null;
  return `${prefix}-${String(num)}`;
}
window.formatOrderNumber = formatOrderNumber;

function normalizeText(value = "") {
  return String(value).trim().toLowerCase();
}

// normalizePhone endi shared.js'dan import qilinadi (yagona manba — admin.js
// va waiter.js'da ikki xil mustaqil nusxa bo'lmasligi uchun). Chiqish bir xil
// (901234567/90 123 45 67/998901234567/+998901234567 → +998901234567),
// shared.js versiyasi shuningdek 12 xonadan ortiq raqamlarni ham to'g'irlaydi.

function normalizeCustomerMemoryList(value) {
  if (Array.isArray(value)) {
    return value
      .map(item => String(item || "").trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return value
      .split(/\r?\n|[,;]+/)
      .map(item => item.trim())
      .filter(Boolean);
  }

  return [];
}

function uniqueCustomerMemoryList(items = []) {
  const seen = new Set();
  return items.filter(item => {
    const value = String(item || "").trim();
    const key = value.toLowerCase();
    if (!value || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function buildCustomerProfilePhoneCache(customersObj = {}) {
  const cache = {};

  Object.entries(customersObj || {}).forEach(([id, profile]) => {
    const normalizedPhone = normalizePhone(profile?.phone || decodeURIComponent(id || ""));
    if (!normalizedPhone) return;

    cache[normalizedPhone] = {
      ...(profile || {}),
      phone: normalizedPhone,
      allergies: normalizeCustomerMemoryList(profile?.allergies),
      preferences: normalizeCustomerMemoryList(profile?.preferences)
    };
  });

  return cache;
}

function getCustomerProfileByPhone(phone = "") {
  const normalizedPhone = normalizePhone(phone);
  if (!normalizedPhone) return null;
  return window.customerProfilesByPhone?.[normalizedPhone] || null;
}

function getCustomerMemoryState(customer = {}, customerProfile = null) {
  const profile = customerProfile || getCustomerProfileByPhone(customer?.phone || customer?.customerPhone || "");
  const allergies = uniqueCustomerMemoryList([
    ...normalizeCustomerMemoryList(customer?.allergies),
    ...normalizeCustomerMemoryList(profile?.allergies)
  ]);
  const preferences = uniqueCustomerMemoryList([
    ...normalizeCustomerMemoryList(customer?.preferences),
    ...normalizeCustomerMemoryList(profile?.preferences)
  ]);

  return {
    allergies,
    preferences,
    summary: [
      allergies.length ? `${t("allergy", "Allergiya")}: ${allergies.join(", ")}` : "",
      preferences.length ? `${t("special_note", "Maxsus izoh")}: ${preferences.join(", ")}` : ""
    ].filter(Boolean).join(" | ")
  };
}

function renderCustomerMemoryInline(customer = {}, customerProfile = null) {
  const memory = getCustomerMemoryState(customer, customerProfile);
  if (!memory.summary) return "";

  return `
    <p style="margin-top:8px;">
      <span style="display:inline-flex; align-items:center; gap:6px; background:var(--admin-danger-bg); color:#b42318; padding:6px 10px; border-radius:999px; font-size:12px; font-weight:700; line-height:1.4;">
        ⚠️ ${t("allergy", "Allergiya")}/${t("special_note", "Izoh")}: ${escapeHtml(memory.summary)}
      </span>
    </p>
  `;
}

function isCountableVisit(order = {}) {
  const status = normalizeText(order.status || order.statusKey || "");
  return (
    order.payment?.paid === true ||
    order.tableClosed === true ||
    [
      "new", "yangi",
      "approved", "cooking", "ready", "closed",
      "tasdiqlandi", "tayyorlanmoqda", "tayyor", "yopildi"
    ].includes(status)
  );
}

function countCustomerVisitsByPhone(phone, ordersObj = {}, excludeOrderId = "") {
  const target = normalizePhone(phone);
  if (!target) return 0;

  let count = 0;

  Object.entries(ordersObj || {}).forEach(([id, order]) => {
    if (excludeOrderId && id === excludeOrderId) return;

    const orderPhone = normalizePhone(
      order.customerPhone ||
      order.phone ||
      order.clientPhone ||
      ""
    );

    if (!orderPhone) return;
    if (orderPhone !== target) return;
    if (!isCountableVisit(order)) return;

    count++;
  });

  return count;
}

function sumCustomerPaidTotalByPhone(phone, ordersObj = {}, includeCurrentOrder = null) {
  const target = normalizePhone(phone);
  if (!target) return 0;

  let total = 0;

  Object.values(ordersObj || {}).forEach(order => {
    const orderPhone = normalizePhone(
      order.customerPhone ||
      order.phone ||
      order.clientPhone ||
      ""
    );

    if (orderPhone !== target) return;
    if (!isCountableVisit(order)) return;

    total += Number(order.finalTotal || order.total || 0);
  });

  if (includeCurrentOrder) {
    total += Number(includeCurrentOrder.finalTotal || includeCurrentOrder.total || 0);
  }

  return total;
}

