// 🐛 FIX (item 12): avval brauzer/OS default locale bilan formatlanardi
// (currentDateLocale() e'tiborga olinmagan edi) — shu sabab audit jurnali
// sana/vaqt formati Admin paneldagi til tanlagichdan MUSTAQIL edi. Endi
// project bo'ylab allaqachon ishlatilayotgan currentDateLocale() (getLang()
// asosida) qayta ishlatiladi — yangi formatter ixtiro qilinmadi.
function formatDateTime(value) {
  if (!value) return uiEmpty();
  try { return new Date(value).toLocaleString(currentDateLocale()); }
  catch { return uiEmpty(); }
}

function formatRelativeTime(value) {
  if (!value) return uiEmpty();
  const diffMs = Date.now() - Number(value);
  const diffMin = Math.floor(diffMs / 60000);
  if (diffMin < 1) return t("notif_just_now") || "hozir";
  if (diffMin < 60) return `${diffMin} ${t("notif_minutes_ago_suffix") || "daqiqa oldin"}`;
  const diffHr = Math.floor(diffMin / 60);
  if (diffHr < 24) return `${diffHr} ${t("notif_hours_ago_suffix") || "soat oldin"}`;
  const diffDay = Math.floor(diffHr / 24);
  return `${diffDay} ${t("notif_days_ago_suffix") || "kun oldin"}`;
}

function getOrderTimestamp(order) {
  return Number(
    order?.updatedAt ||
    order?.createdAt ||
    order?.payment?.approvedAt ||
    order?.payment?.requestedAt ||
    0
  );
}

// Berilgan vaqtdan hozirgacha o'tgan vaqtni "Xs / Xd Ys / Xs Ym" ko'rinishida
// qaytaradi. Stol kartochkasidagi "Stol vaqti" qatori uchun ishlatiladi.
function formatElapsedSince(startTs) {
  const ts = Number(startTs || 0);
  if (!ts) return "—";
  const diffMs = Date.now() - ts;
  if (diffMs < 0) return "0 " + t("minutes_short", "daq");
  const totalMinutes = Math.floor(diffMs / 60000);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (hours <= 0) return `${minutes} ${t("minutes_short", "daq")}`;
  if (hours < 24) return `${hours} ${t("hours_short", "soat")} ${minutes} ${t("minutes_short", "daq")}`;
  const days = Math.floor(hours / 24);
  const remHours = hours % 24;
  return `${days} ${t("days_short", "kun")} ${remHours} ${t("hours_short", "soat")}`;
}

function getCustomerDisplayName(order = {}, profile = {}) {
  let name = profile.name || order.customerName || order.clientName || order.name;
  if (!name || String(name).trim() === "" || name === "undefined") {
    const phone = getCustomerPhone(order, profile);
    if (phone) {
      name = `${t("client_label", "Mijoz")} (${phone.slice(-4)})`;
    } else {
      name = `${t("table", "Stol")} ${order.table || "—"}`;
    }
  }

  return String(name).trim();
}

function getCustomerPhone(order = {}, profile = {}) {
  return profile.phone || order.customerPhone || order.phone || "";
}

function getLoyaltyLevel(totalSpent = 0, visits = 0) {
  if (visits >= 5) return "gold";
  if (visits >= 3) return "silver";
  return "bronze";
}

function getLoyaltyDiscountPercent(visits = 0) {
  if (visits >= 5) return 10;
  if (visits >= 3) return 5;
  return 0;
}

function buildFavoriteItems(map = {}, limit = 4) {
  return Object.entries(map)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([name]) => name);
}

function getReservationStatusActions(status) {
  const s = String(status || "pending").toLowerCase();

  if (s === "pending") {
    return [
      { label: t("confirm_btn"), status: "confirmed" },
      { label: t("cancel_btn"), status: "canceled" }
    ];
  }

  if (s === "confirmed") {
    return [
      { label: t("seated_btn"), status: "seated" },
      { label: t("no_show_btn"), status: "no_show" }
    ];
  }

  if (s === "seated") {
    return [
      { label: t("complete_btn"), status: "completed" }
    ];
  }

  return [];
}

function buildCustomerMapFromOrders(ordersObj = {}, customerProfiles = {}, users = {}) {
  const map = {};
  // Hoisted out of the orders loop below — was previously rebuilt from
  // scratch on every single order iteration (O(orders × customers) instead
  // of O(orders + customers)). Same result, computed once.
  const profileByNormalizedPhone = buildCustomerProfilePhoneCache(customerProfiles || {});

  Object.entries(ordersObj || {}).forEach(([orderId, order]) => {
    const phone = getCustomerPhone(order);
    const customerId = order.customerId || phone || `table_${order.table || "unknown"}`;

    // 🐛 FIX: buyurtmadagi telefon raqami har doim ham normalizatsiya
    // qilingan bo'lavermaydi — masalan waiter.js'da ofitsiant editClientPhone()
    // orqali raqamni qo'lda, hech qanday formatlashsiz kiritadi (bevosita
    // prompt() natijasi). customers/{restId} profilidagi yozuvlar esa har
    // doim normalizePhone() orqali o'tgan (applyCustomerDiscount va h.k.).
    // Natijada shu order asosidagi customerId (xom raqam) profildagi kalitga
    // (normallashtirilgan raqam) mos kelmay, admin CRM'da qo'ygan chegirma
    // ("discountPercent") shu mijoz kartasida umuman ko'rinmay qolardi —
    // saqlash muvaffaqiyatli bo'lsa ham (Firebase'ga to'g'ri yozilgan),
    // ro'yxat/profilni qayta chizishda topilmagani uchun 0% bo'lib ko'rinardi.
    // Shu yerda normallashtirilgan telefon bo'yicha profilni oldindan
    // qidirib, topilsa uning discountPercent/notes/isVip/loyaltyCard/
    // loyaltyPoints/cashbackBalance qiymatlarini boshlang'ich holatga
    // ko'chiramiz — customerId qanday formatda bo'lishidan qat'i nazar.
    const existingProfile = phone ? (profileByNormalizedPhone[normalizePhone(phone)] || null) : null;
    if (!map[customerId]) {
      map[customerId] = {
        id: customerId,
        name: getCustomerDisplayName(order),
        phone: phone || "",
        visits: 0, ordersCount: 0, totalSpent: 0,
        cashbackBalance: Number(existingProfile?.cashbackBalance || 0),
        promoCodesUsed: new Set(), favoriteItemsMap: {},
        recentOrders: [], lastVisit: 0, loyalty: "bronze",
        discountPercent: Number(existingProfile?.discountPercent ?? existingProfile?.personalDiscount ?? 0),
        // 🆕 QR bir martalik chegirma claimlari (backend/discountClaims/*) —
        // PERMANENT discountPercent'dan mutlaqo alohida maydon, ustidan
        // yozilmaydi (spec §9). Faqat ko'rsatish uchun — order calculation
        // client.js/waiter.js'da customers/{phone} yozuvining o'zidan
        // to'g'ridan-to'g'ri o'qiladi, bu yerga tegishli emas.
        oneTimeDiscounts: existingProfile?.oneTimeDiscounts || null,
        isVip: existingProfile?.isVip === true,
        loyaltyCard: existingProfile?.loyaltyCard || null,
        loyaltyPoints: Number(existingProfile?.loyaltyPoints || 0),
        notes: existingProfile?.notes || "",
        allergies: [],
        preferences: []
      };
    }

    const customer = map[customerId];
    // ordersCount — HAR bir order yozuvi (holatidan qat'i nazar); visits —
    // faqat "hisoblanadigan" (to'langan/tasdiqlangan) tashriflar. Ikkalasi
    // ham Customers moduli profilida alohida ko'rsatiladi (spec talabi).
    customer.ordersCount += 1;
    if (isCountableVisit(order)) {
      customer.visits += 1;
    }
    customer.totalSpent += Number(order.finalTotal || order.total || 0);
    customer.lastVisit = Math.max(customer.lastVisit, getOrderTimestamp(order));
    customer.allergies = uniqueCustomerMemoryList([
      ...customer.allergies,
      ...normalizeCustomerMemoryList(order.allergyNote)
    ]);
    customer.preferences = uniqueCustomerMemoryList([
      ...customer.preferences,
      ...normalizeCustomerMemoryList(order.preferenceNote)
    ]);

    if (order.promoCode) customer.promoCodesUsed.add(order.promoCode);

    Object.values(order.items || {}).forEach(item => {
      const menuItem = window.allMenu?.[item.menuId || item.id || item.itemId];
      const itemName = getTranslatedItemName(item, menuItem, getLang());
      customer.favoriteItemsMap[itemName] =
        (customer.favoriteItemsMap[itemName] || 0) + Number(item.qty || 0);
    });

    customer.recentOrders.push({
      orderId,
      orderNumber: order.orderNumber || orderId,
      isDelivery: !!(order.deliveryType === "delivery" || order.isDelivery || order.orderType === "delivery" || order.deliveryAddress),
      table: order.table || uiEmpty(),
      total: Number(order.finalTotal || order.total || 0),
      status: order.statusLabel || order.status || uiEmpty(),
      createdAt: getOrderTimestamp(order)
    });
  });

  Object.entries(customerProfiles || {}).forEach(([id, profile]) => {
    const key = profile.phone || id;
    if (!map[key]) {
      map[key] = {
        id: key, name: profile.name || uiEmpty(), phone: profile.phone || "",
        visits: Number(profile.visits || 0), ordersCount: Number(profile.ordersCount || profile.visits || 0),
        totalSpent: Number(profile.totalSpent || 0),
        cashbackBalance: Number(profile.cashbackBalance || 0),
        loyaltyPoints: Number(profile.loyaltyPoints || 0),
        promoCodesUsed: new Set(profile.promoCodesUsed || []),
        favoriteItemsMap: {}, recentOrders: [],
        lastVisit: Number(profile.lastVisit || 0), loyalty: profile.loyalty || "bronze",
        discountPercent: Number(profile.discountPercent || profile.personalDiscount || 0),
        isVip: profile.isVip === true, loyaltyCard: profile.loyaltyCard || null, notes: profile.notes || "",
        allergies: normalizeCustomerMemoryList(profile.allergies),
        preferences: normalizeCustomerMemoryList(profile.preferences)
      };
    } else {
      map[key].name = profile.name || map[key].name;
      map[key].cashbackBalance = Number(profile.cashbackBalance || map[key].cashbackBalance || 0);
      map[key].lastVisit = Math.max(Number(profile.lastVisit || 0), map[key].lastVisit || 0);
      // Customers profilidagi visits va totalSpent ni ham hisobga olish
      map[key].visits = Math.max(map[key].visits, Number(profile.visits || 0));
      map[key].ordersCount = Math.max(map[key].ordersCount, Number(profile.ordersCount || 0));
      map[key].totalSpent = Math.max(map[key].totalSpent, Number(profile.totalSpent || 0));
      map[key].loyaltyPoints = Math.max(map[key].loyaltyPoints || 0, Number(profile.loyaltyPoints || 0));
      // 🆕 Customers moduli: discountPercent/loyaltyCard/notes — admin qo'lda
      // belgilagan qiymatlar, mavjud bo'lsa har doim ustuvor. Hech qanday
      // status/tier tushunchasi yo'q — hamma mijoz teng.
      map[key].discountPercent = Number(profile.discountPercent ?? profile.personalDiscount ?? map[key].discountPercent ?? 0);
      map[key].isVip = profile.isVip === true || map[key].isVip === true;
      map[key].loyaltyCard = profile.loyaltyCard || map[key].loyaltyCard || null;
      map[key].notes = profile.notes || map[key].notes || "";
      (profile.promoCodesUsed || []).forEach(code => map[key].promoCodesUsed.add(code));
      map[key].allergies = uniqueCustomerMemoryList([
        ...normalizeCustomerMemoryList(map[key].allergies),
        ...normalizeCustomerMemoryList(profile.allergies)
      ]);
      map[key].preferences = uniqueCustomerMemoryList([
        ...normalizeCustomerMemoryList(map[key].preferences),
        ...normalizeCustomerMemoryList(profile.preferences)
      ]);
    }
  });

  Object.entries(users || {}).forEach(([id, user]) => {
    if (user.role !== "client") return;
    const key = user.phone || id;
    if (!map[key]) {
      map[key] = {
        id: key, name: user.name || uiEmpty(), phone: user.phone || "",
        visits: 0, totalSpent: 0,
        cashbackBalance: Number(user.cashbackBalance || 0),
        promoCodesUsed: new Set(), favoriteItemsMap: {},
        recentOrders: [], lastVisit: Number(user.lastVisit || 0), loyalty: "bronze",
        allergies: [],
        preferences: []
      };
    }
  });

  // 🐛 FIX (final authoritative pass): a single real customer can still end
  // up as more than one entry in `map` above — e.g. an early dine-in order
  // created a table_X-keyed entry before a phone was ever recorded, and a
  // later order for the same person is keyed by phone once the waiter added
  // it (editClientPhone doesn't retroactively relink earlier orders). Each
  // such duplicate is a SEPARATE object, so patching "the" customer's
  // discountPercent (in saveCustomerDiscount / the pass-1 seed above) only
  // ever reaches ONE of them — whichever one that code found. Depending on
  // which entry the admin clicked into (modal) vs. which one a given card
  // renders, they could show different values even though Firebase has one
  // consistent, correct number. Fixing this at the source instead of
  // guessing which entry is "the" displayed one: every entry that has a
  // resolvable phone gets its discountPercent forced to match the
  // customers/ profile record for that phone — the same source
  // saveCustomerDiscount() writes to and the modal already reads from — so
  // card, modal and any duplicate all agree, unconditionally.
  Object.values(map).forEach(customer => {
    if (!customer.phone) return;
    const profile = profileByNormalizedPhone[normalizePhone(customer.phone)];
    if (!profile) return;
    customer.discountPercent = Number(profile.discountPercent ?? profile.personalDiscount ?? 0);
  });

  return Object.values(map).map(customer => ({
    ...customer,
    favoriteItems: buildFavoriteItems(customer.favoriteItemsMap, 4),
    promoCodesUsed: Array.from(customer.promoCodesUsed),
    // 🆕 status==="vip" (yoki eski isVip=true yozuvlar) — avtomatik
    // bronze/silver/gold hisoblashdan ustun turadi (bu — Customers moduliga
    // aloqasi yo'q, alohida oldindan mavjud grantVipStatus/VIP-sovg'a tizimi;
    // Customers modulida umuman status/tier tushunchasi yo'q).
    loyalty: customer.isVip ? "vip" : getLoyaltyLevel(customer.totalSpent, customer.visits),
    allergies: uniqueCustomerMemoryList(customer.allergies),
    preferences: uniqueCustomerMemoryList(customer.preferences),
    recentOrders: customer.recentOrders
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, 5)
  })).sort((a, b) => b.totalSpent - a.totalSpent);
}

async function autoTranslate(text, targetLang) {
  try {
    const res = await fetch(
      `https://translate.googleapis.com/translate_a/single?client=gtx&sl=uz&tl=${targetLang}&dt=t&q=${encodeURIComponent(text)}`
    );
    if (!res.ok) throw new Error(t("translate_service_busy", "Tarjima xizmati band"));
    const data = await res.json();
    return data[0][0][0];
  } catch (e) {
    console.warn(t("translate_error_log"), e);
    return text;
  }
}

function getTranslatedItemName(item, menuItem = null, lang = getLang()) {
  if (menuItem?.name) {
    if (typeof menuItem.name === "object") {
      return menuItem.name[lang] || menuItem.name.uz || menuItem.name.ru || menuItem.name.en || uiEmpty();
    }
    return menuItem.name || uiEmpty();
  }
  if (item?.name) {
    if (typeof item.name === "object") {
      return item.name[lang] || item.name.uz || item.name.ru || item.name.en || uiEmpty();
    }
    return item.name || uiEmpty();
  }
  return uiEmpty();
}

// ── Global yordamchi: item.name (object yoki string) → ko'rinadigan nom ──────
// admin.html ichidagi inline scriptlar ham ishlatishi uchun window ga bind qilingan
window.getItemDisplayName = function (name, fallback) {
  fallback = fallback || t("food_label", "Taom");
  if (!name) return fallback;
  if (typeof name === "string") return name.trim() || fallback;
  if (typeof name === "object") {
    const lang = typeof getLang === "function" ? getLang() : "uz";
    return name[lang] || name.uz || name.ru || name.en || fallback;
  }
  return fallback;
};

function showToast(text, type = "success") {
  const toast = document.getElementById("toast");
  if (!toast) return;
  toast.textContent = text;
  toast.className = `toast show ${type}`;
  setTimeout(() => toast.classList.remove("show"), 3000);
}

