// 🔔 YANGI BUYURTMA OVOZLI BILDIRISHNOMA
// ==========================================
(function initOrderSoundSystem() {
  const _restId = localStorage.getItem("restaurantId");
  if (!_restId) return;

  window._afterAdminTenantReady(async () => {
    onValue(ref(db, `restaurants/${_restId}/settings/notificationsEnabled`), snap => {
      window._adminNotifEnabled = snap.exists() ? snap.val() : true;
      console.log("🔔 Ovozli bildirishnoma:", window._adminNotifEnabled ? "YOQILGAN" : "O'CHIRILGAN");
    });
  }).catch((error) => {
    console.error("Order sound readiness failed:", window.classifyAdminDataError(error).code);
  });
  if (window._adminNotifEnabled === undefined) {
    window._adminNotifEnabled = true;
  }
})();

// ── Shared, lazily-initialized Web Audio API context for every admin.js
// notification sound (new-order chime, peak-hours warning, production-
// planning loss alert). Console-error fix: each of those 3 sounds used to
// create ITS OWN fresh AudioContext on every single call — a brand-new
// context always starts "suspended" per browser autoplay policy until a
// user gesture has occurred somewhere on the page, and none of these call
// sites ever resumed one, hence "The AudioContext was not allowed to
// start." One shared context instead, created only on first actual use
// (never at page load) and resumed on the page's first real user gesture —
// after that one-time unlock (normal, unavoidable browser behavior on
// every site, not a regression), every existing sound keeps working
// exactly as before. Voice notifications themselves are unchanged.
let _sharedAudioCtx = null;
function _getSharedAudioCtx() {
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtx) return null;
  if (!_sharedAudioCtx) _sharedAudioCtx = new AudioCtx();
  if (_sharedAudioCtx.state === "suspended") _sharedAudioCtx.resume().catch(() => {});
  return _sharedAudioCtx;
}
(function _unlockSharedAudioOnFirstGesture() {
  const unlock = () => {
    _getSharedAudioCtx();
    ["pointerdown", "keydown", "touchstart"].forEach(evt => document.removeEventListener(evt, unlock));
  };
  ["pointerdown", "keydown", "touchstart"].forEach(evt => document.addEventListener(evt, unlock, { passive: true }));
})();

function playNewOrderSound() {
  if (!window._adminNotifEnabled) return;

  try {
    const ctx = _getSharedAudioCtx();
    if (!ctx) return;

    const notes = [
      { freq: 880, start: 0.0, dur: 0.18 },
      { freq: 660, start: 0.2, dur: 0.18 },
      { freq: 880, start: 0.42, dur: 0.25 }
    ];

    notes.forEach(({ freq, start, dur }) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.type = "sine";
      osc.frequency.setValueAtTime(freq, ctx.currentTime + start);

      gain.gain.setValueAtTime(0, ctx.currentTime + start);
      gain.gain.linearRampToValueAtTime(0.45, ctx.currentTime + start + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + start + dur);

      osc.start(ctx.currentTime + start);
      osc.stop(ctx.currentTime + start + dur + 0.05);
    });

    // (Shared AudioContext now — no longer closed after use; see
    // _getSharedAudioCtx() above, the other 2 notification sounds reuse it.)
  } catch (e) {
    console.warn("Ovoz chiqarishda xato:", e);
  }
}

/** Ovozli + vizual yangi buyurtma bildirishnomasi */
function notifyNewOrder(orderCount) {
  if (!window._adminNotifEnabled) return;

  playNewOrderSound();

  // Animatsiyali banner
  const banner = document.createElement("div");
  banner.id = "new-order-banner-" + Date.now();
  banner.style.cssText = `
    position: fixed; top: 20px; left: 50%; transform: translateX(-50%) translateY(-80px);
    background: linear-gradient(135deg, #16a34a, #15803d);
    color: white; padding: 14px 28px; border-radius: 14px;
    font-size: 15px; font-weight: 700; z-index: 99999;
    box-shadow: 0 8px 32px rgba(22,163,74,0.45);
    display: flex; align-items: center; gap: 10px;
    transition: transform 0.35s cubic-bezier(.175,.885,.32,1.275);
    white-space: nowrap;
  `;
  banner.innerHTML = `
    <span style="font-size:20px;animation:bell-shake 0.6s ease infinite alternate;">🔔</span>
    <span>${orderCount > 1 ? t("new_orders_count", "{count} ta yangi buyurtma!").replace("{count}", orderCount) : t("new_order_arrived", "Yangi buyurtma keldi!")}</span>
  `;

  if (!document.getElementById("bell-shake-style")) {
    const s = document.createElement("style");
    s.id = "bell-shake-style";
    s.textContent = `@keyframes bell-shake{0%{transform:rotate(-15deg)}100%{transform:rotate(15deg)}}`;
    document.head.appendChild(s);
  }

  document.body.appendChild(banner);
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      banner.style.transform = "translateX(-50%) translateY(0)";
    });
  });

  setTimeout(() => {
    banner.style.transform = "translateX(-50%) translateY(-80px)";
    setTimeout(() => banner.remove(), 400);
  }, 3500);
}

