window.toggleOrderCornerMenu = function (evt, id) {
  evt.stopPropagation();
  const menu = document.getElementById(`orderCornerMenu-${id}`);
  if (!menu) return;
  const isOpen = menu.style.display === "block";
  document.querySelectorAll("[id^='orderCornerMenu-']").forEach(m => m.style.display = "none");
  menu.style.display = isOpen ? "none" : "block";
};

document.addEventListener("click", () => {
  document.querySelectorAll("[id^='orderCornerMenu-']").forEach(m => m.style.display = "none");
});

// Maps an order-history record → receiptEngine.js's shared data shape.
// Replaces the previously hand-rolled table-based template — now the exact
// same thermal receipt design as kassa/waiter/client (receiptEngine.js).
function buildOrderReceiptData(order, id) {
  const orderNum = formatOrderNumber(order.orderNumber, order.isDelivery) || ("#" + id.slice(-4));
  const dateObj = new Date(order.createdAt || Date.now());
  const dateStr = dateObj.toLocaleDateString(currentDateLocale());
  const timeStr = dateObj.toLocaleTimeString(currentDateLocale(), { hour: "2-digit", minute: "2-digit" });
  const items = Object.values(order.items || {}).map(item => ({
    name: _resolveItemName(item),
    qty: item.qty || item.quantity || 1,
    price: Number(item.price || 0),
  }));

  const restName = window._cashierRestName || window.currentGlobalRestName || t("unknown_restaurant", "Noma'lum Restoran");
  // 🆕 Sozlamalar → Chop etish sozlamalari (window._printSettingsCache) — admin
  // paneldagi "Chekni ko'rish/qayta chop etish" ham waiter/kassa bilan bir xil
  // logotip/shtrix-kod/pastki matn qoidasiga bo'ysunadi (avval hech biri o'qilmasdi).
  const ps = window._printSettingsCache || {};
  const showLogo = ps.receiptLogo !== false; // default: yoqilgan
  const logoUrl = showLogo ? (window._cashierLogoUrl || window.currentGlobalLogoUrl || "") : "";
  const waiterName = order.waiterName || order.createdByName || "";

  const subtotal = Number(order.total || 0);
  const finalTotal = Number(order.finalTotal || order.total || 0);
  const discountPercent = Number(order.discountPercent || 0);
  const discountAmount = Number(order.discountAmount || (discountPercent > 0 ? (subtotal - finalTotal) : 0));

  // engineMethodLabel understands the raw firebaseKey ("Naqd"/"Click"/...)
  // written by kassa.js/waiter.js's paymentEngine, and falls back gracefully
  // for older orders that only ever had normalizePaymentMethod's lowercase
  // id ("cash"/"click"/"payme"/"uzum").
  const methodLabel = order.payment?.method
    ? engineMethodLabel(order.payment.method, t)
    : "";

  return {
    restaurantName: restName, logoUrl,
    date: dateStr, time: timeStr,
    receiptId: orderNum, orderNumber: order.orderNumber, orderId: id,
    table: order.table, waiterName,
    items, subtotal, discount: discountAmount, total: finalTotal,
    methodLabel,
    docTitle: t("receipt_thanks", "CHEK"),
    barcodeText: ps.receiptBarcode ? String(order.orderNumber || orderNum || "").trim() : "",
    footerText: ps.receiptFooter && String(ps.receiptFooter).trim() ? ps.receiptFooter : t("sa_rcpt_visit_again", "Yana tashrif buyuring!"),
  };
}
function _adminReceiptCopies() {
  return Number((window._printSettingsCache || {}).receiptCopies) || 1;
}
function _adminReceiptWidth() {
  return (window._printSettingsCache || {}).receiptPaperSize === "58mm" ? "58mm" : "80mm";
}

