// 🆕 Buyurtmalar KPI kartochkalari: Navbatda / Tayyorlanmoqda / Tayyor / O'rtacha tayyorlanish vaqti
function updateOrdersKpi(entries) {
  const queuedEl = document.getElementById("ordersKpiQueued");
  const preparingEl = document.getElementById("ordersKpiPreparing");
  const readyEl = document.getElementById("ordersKpiReady");
  const avgEl = document.getElementById("ordersKpiAvgTime");
  if (!queuedEl && !preparingEl && !readyEl && !avgEl) return;

  const QUEUED_STATUSES = ["yangi", "new", "queue", "order_created", "waiter", "tasdiqlandi", "approved", "kitchen_printer", "kitchen_display"];
  const PREPARING_STATUSES = ["tayyorlanmoqda", "cooking", "preparing"];
  const READY_STATUSES = ["tayyor", "ready"];

  let queued = 0, preparing = 0, ready = 0;
  const cookTimes = [];

  (entries || []).forEach(([, order]) => {
    const s = String(order.statusKey || order.status || "").trim().toLowerCase();
    if (QUEUED_STATUSES.includes(s)) queued++;
    else if (PREPARING_STATUSES.includes(s)) preparing++;
    else if (READY_STATUSES.includes(s)) ready++;

    if (order.readyAt && order.createdAt && order.readyAt > order.createdAt) {
      cookTimes.push(order.readyAt - order.createdAt);
    }
  });

  const avgMs = cookTimes.length ? cookTimes.reduce((a, b) => a + b, 0) / cookTimes.length : 0;
  const avgMin = avgMs ? Math.round(avgMs / 60000) : 0;

  if (queuedEl) queuedEl.textContent = queued;
  if (preparingEl) preparingEl.textContent = preparing;
  if (readyEl) readyEl.textContent = ready;
  if (avgEl) avgEl.textContent = avgMin ? `${avgMin} ${t("minutes_short", "daq")}` : "—";
}

function renderOrders(ordersObj) {
  const list = document.getElementById("ordersList");
  if (!list) return;

  try {
    // 🆕 Yagona buyurtma hayot-sikli (canonical pipeline):
    // Order Created → Kitchen Printer/Display → Preparing → Ready →
    // Picked Up → Served → Payment Pending → Paid → Completed
    // Eski status nomlari (yangi/tasdiqlandi/tayyorlanmoqda/tayyor/...) ham
    // shu bosqichlarga moslab tartiblanadi — orqaga qarab muvofiqlik saqlanadi.
    const priority = {
      // Order Created
      yangi: 1, new: 1, queue: 1, order_created: 1, waiter: 1,
      // Kitchen Printer / Kitchen Display
      tasdiqlandi: 2, approved: 2, kitchen_printer: 2, kitchen_display: 2,
      // Preparing
      tayyorlanmoqda: 3, cooking: 3, preparing: 3,
      // Ready
      tayyor: 4, ready: 4,
      // Picked Up
      picked_up: 5,
      // Served
      served: 6,
      // Payment Pending
      payment_pending: 7, cashier: 7, payment: 7,
      // Paid
      paid: 8,
      // Completed
      yopildi: 9, closed: 9, completed: 9
    };

    let filteredArr = applyOrderFilters(ordersObj);
    if (typeof applyChefFilter === 'function') {
      filteredArr = applyChefFilter(filteredArr);
    }

    if (typeof updateOrdersKpi === "function") updateOrdersKpi(filteredArr);

    let htmlContent = "";

    filteredArr
      .sort((a, b) => {
        const sa = String(a[1].statusKey || a[1].status || "").trim().toLowerCase();
        const sb = String(b[1].statusKey || b[1].status || "").trim().toLowerCase();

        if ((priority[sa] || 99) !== (priority[sb] || 99)) {
          return (priority[sa] || 99) - (priority[sb] || 99);
        }
        const ta = a[1].createdAt || 0;
        const tb = b[1].createdAt || 0;
        return tb - ta;
      })
      .forEach(([id, order]) => {
        if (typeof renderOrderCard === 'function') {
          htmlContent += renderOrderCard(id, order);
        }
      });

    list.innerHTML = htmlContent;
  } catch (e) {
    console.error(t("error_rendering_orders") || "renderOrders xatosi:", e);
    list.innerHTML = `<p style="color:red;">${t("error_rendering_orders") || "Xatolik yuz berdi"}</p>`;
  }
}

function applyOrderFilters(ordersObj) {
  const paymentStatus = filterPaymentStatus?.value || "all";
  const category = filterOrderCategory?.value || "all";
  const subcategory = filterOrderSubcategory?.value || "all";
  const paymentMethod = filterPaymentType?.value || "all";
  const stage = document.getElementById("filterOrderStage")?.value || "all";
  const searchQuery = (document.getElementById("orderSearchInput")?.value || "").trim().toLowerCase();
  const dateValue = document.getElementById("filterOrderDate")?.value || "";

  // 🆕 Kanonik pipeline bosqichlarini eski/yangi status nomlari bilan mos qilish
  const STAGE_STATUS_MAP = {
    order_created: ["yangi", "new", "queue", "order_created", "waiter"],
    kitchen_sent: ["approved", "tasdiqlandi", "kitchen_printer", "kitchen_display"],
    preparing: ["cooking", "tayyorlanmoqda", "preparing"],
    ready: ["ready", "tayyor"],
    picked_up: ["picked_up"],
    served: ["served"],
    payment_pending: ["payment_pending", "cashier", "payment"],
    paid: ["paid"],
    completed: ["closed", "yopildi", "completed"]
  };

  return Object.entries(ordersObj || {}).filter(([_, order]) => {
    if (paymentStatus !== "all") {
      const paid = order.payment?.paid === true;
      if (paymentStatus === "paid" && !paid) return false;
      if (paymentStatus === "unpaid" && paid) return false;
    }

    if (stage !== "all") {
      const s = String(order.statusKey || order.status || "").trim().toLowerCase();
      const allowedStatuses = STAGE_STATUS_MAP[stage] || [];
      if (!allowedStatuses.includes(s)) return false;
    }

    if (paymentMethod !== "all") {
      const method = normalizePaymentMethod(order.payment?.method);
      if (method !== paymentMethod) return false;
    }

    if (category !== "all" || subcategory !== "all") {
      const match = Object.entries(order.items || {}).some(([_, item]) => {
        const menuItem = window.allMenu?.[item.menuId || item.id || item.itemId];
        if (!menuItem) return false;
        if (category !== "all" && menuItem.category !== category) return false;
        if (subcategory !== "all" && menuItem.subcategory !== subcategory) return false;
        return true;
      });

      if (!match) return false;
    }

    if (dateValue) {
      const createdAt = order.createdAt || order.timestamp || order.date || 0;
      if (!createdAt) return false;
      const orderDate = new Date(createdAt);
      const y = orderDate.getFullYear();
      const m = String(orderDate.getMonth() + 1).padStart(2, "0");
      const d = String(orderDate.getDate()).padStart(2, "0");
      const orderDateStr = `${y}-${m}-${d}`;
      if (orderDateStr !== dateValue) return false;
    }

    if (searchQuery) {
      const idStr = String(_).toLowerCase();
      const tableStr = String(order.table ?? "").toLowerCase();
      const phone = String(
        order.clientPhone || order.customerPhone || order.phone || ""
      ).toLowerCase();
      const customerName = String(
        order.customerName || order.clientName || order.name || ""
      ).toLowerCase();
      const itemNames = Object.values(order.items || {})
        .map(item => {
          const n = item?.name;
          if (typeof n === "object") {
            return (n.uz || n.ru || n.en || "").toLowerCase();
          }
          return String(n || "").toLowerCase();
        })
        .join(" ");

      const haystack = `${idStr} ${tableStr} ${phone} ${customerName} ${itemNames}`;
      if (!haystack.includes(searchQuery)) return false;
    }

    return true;
  });
}

// ══════════════════════════════════════════════════════════
// 📤 Buyurtmalarni eksport qilish (Excel / CSV)
// ══════════════════════════════════════════════════════════
function _resolveItemName(item) {
  const n = item?.name;
  if (typeof n === "object") {
    return n?.[getLang?.()] || n.uz || n.ru || n.en || "";
  }
  return n || "";
}

function _buildOrdersExportRows() {
  const filteredArr = applyOrderFilters(window.allOrders || {});
  return filteredArr.map(([id, order]) => {
    const createdAt = order.createdAt || order.timestamp || order.date || 0;
    const dateStr = createdAt ? new Date(createdAt).toLocaleString() : "";
    const itemsStr = Object.values(order.items || {})
      .map(item => {
        const name = _resolveItemName(item);
        const qty = item?.qty || item?.quantity || 1;
        return `${name} x${qty}`;
      })
      .join(", ");
    const total = Number(order.finalTotal || order.total || 0);
    const paid = order.payment?.paid === true ? t("status_paid", "To'langan") : t("status_unpaid", "To'lanmagan");
    const method = normalizePaymentMethod(order.payment?.method) || "";
    const status = String(order.statusKey || order.status || "");
    const phone = order.clientPhone || order.customerPhone || order.phone || "";
    const customerName = order.customerName || order.clientName || order.name || "";
    // Ichki Firebase orderId ("-OzAh626q2rqT-pjmPr5") o'rniga foydalanuvchi
    // ko'radigan kanonik buyurtma raqami ("ORD-125") ko'rsatiladi — xuddi
    // shu formatOrderNumber() waiter/admin/kassa cheklarida ham ishlatiladi.
    // Eski orderlarda orderNumber umuman yozilmagan bo'lishi mumkin — faqat
    // o'shanda ichki id fallback sifatida ishlatiladi.
    const orderNumberStr = formatOrderNumber(order) || id;

    return {
      [t("order_number_label", "Buyurtma raqami")]: orderNumberStr,
      [t("date_label", "Sana")]: dateStr,
      [t("table_label", "Stol")]: order.table ?? "",
      [t("client", "Mijoz")]: customerName,
      [t("phone_label", "Telefon")]: phone,
      [t("menu_tab_foods", "Taomlar")]: itemsStr,
      [t("amount_label", "Summa")]: total,
      [t("payment_status", "To'lov holati")]: paid,
      [t("payment_type_label", "To'lov turi")]: method,
      [t("order_status_label", "Bosqich")]: status
    };
  });
}

window.exportOrders = (format = "excel") => {
  try {
    const rows = _buildOrdersExportRows();
    if (!rows.length) {
      alert(t("no_orders_to_export", "Eksport qilish uchun buyurtmalar topilmadi"));
      return;
    }

    const fileBase = buildExportFilename("buyurtmalar", new Date().toISOString().slice(0, 10));

    if (format === "csv") {
      // Ajratkich exportUtils.js'ning standart qiymatidan olinadi (";") —
      // boshqa barcha modul CSV eksportlari bilan bir xil (item 8/10).
      exportRowsToCsv({ rows, filename: fileBase });
    } else {
      if (typeof XLSX === "undefined") {
        console.error("XLSX kutubxonasi topilmadi");
        alert(t("export_lib_missing", "Excel eksport kutubxonasi yuklanmagan"));
        return;
      }
      exportRowsToExcel({
        rows,
        sheetName: t("orders", "Buyurtmalar"),
        filename: fileBase,
        currencyColumns: [t("amount_label", "Summa")],
        wrapColumns: [t("menu_tab_foods", "Taomlar")],
      });
    }

    document.getElementById("ordersExportMenu")?.classList.remove("open");
  } catch (e) {
    console.error("exportOrders xatosi:", e);
    alert(t("error_exporting_orders", "Eksport qilishda xatolik yuz berdi"));
  }
};

document.getElementById("ordersExportBtn")?.addEventListener("click", (e) => {
  e.stopPropagation();
  document.getElementById("ordersExportMenu")?.classList.toggle("open");
});

document.addEventListener("click", (e) => {
  const menu = document.getElementById("ordersExportMenu");
  const btn = document.getElementById("ordersExportBtn");
  if (menu && menu.classList.contains("open") && !menu.contains(e.target) && e.target !== btn) {
    menu.classList.remove("open");
  }
});

