// ── Taomlar jadvali uchun kategoriya filtrini to'ldiradi ──
function populateMenuCategoryFilter() {
  const sel = document.getElementById("menuFilterCategory");
  if (!sel) return;
  const prev = sel.value || "all";
  sel.innerHTML = `<option value="all" data-i18n="all_categories">${t("all_categories", "Kategoriya ▾")}</option>`;
  getAllCategories().forEach(cat => {
    sel.innerHTML += `<option value="${cat.id}">${cat.isCustom ? "⭐ " : ""}${cat.label}</option>`;
  });
  sel.value = [...sel.options].some(o => o.value === prev) ? prev : "all";
}

let menuFilterCategoryValue = "all";
let menuFilterStatusValue = "all";

function computeSoldQtyForMenuId(menuId) {
  let total = 0;
  const closed = ["yopildi", "bekor qilindi", "closed", "cancelled", "to'landi", "paid", "закрыто", "отменён", "оплачено", "canceled"];
  Object.values(window.allOrders || {}).forEach(order => {
    const st = String(order.status || order.statusKey || "").trim().toLowerCase();
    if (!closed.includes(st)) return;
    if (!order.items) return;
    Object.values(order.items).forEach(it => {
      const itId = it.menuId || it.id || it.itemId;
      if (itId === menuId) total += Number(it.qty || 0);
    });
  });
  return total;
}

function updateMenuStatCards() {
  const allItems = Object.values(window.allMenu || {}).filter(item => !item.isCombo);
  const total = allItems.length;
  const active = allItems.filter(item => item.active !== false).length;
  const inactive = total - active;
  const catCount = getAllCategories().length;

  const elTotal = document.getElementById("menuStatTotal");
  const elActive = document.getElementById("menuStatActive");
  const elInactive = document.getElementById("menuStatInactive");
  const elCats = document.getElementById("menuStatCategories");
  if (elTotal) elTotal.textContent = total.toLocaleString();
  if (elActive) elActive.textContent = active.toLocaleString();
  if (elInactive) elInactive.textContent = inactive.toLocaleString();
  if (elCats) elCats.textContent = catCount.toLocaleString();
}

function renderMenu() {
  if (!menuList) return;
  populateMenuCategoryFilter();
  updateMenuStatCards();

  const lang = getLang();
  let items = Object.entries(window.allMenu || {})
    .filter(([, item]) => !item.isCombo)
    .map(([id, item]) => ({ id, ...item }))
    .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));

  if (searchQuery) {
    items = items.filter(item => {
      const name = item.name?.[lang] || item.name?.uz || item.name?.ru || item.name?.en || "";
      return name.toLowerCase().includes(searchQuery.toLowerCase());
    });
  }

  if (menuFilterCategoryValue !== "all") {
    items = items.filter(item => item.category === menuFilterCategoryValue);
  }

  if (menuFilterStatusValue !== "all") {
    items = items.filter(item => {
      const isActive = item.active !== false; // default: faol
      return menuFilterStatusValue === "active" ? isActive : !isActive;
    });
  }

  menuList.innerHTML = items.length
    ? items.map(item => {
      const name = item.name?.[lang] || item.name?.uz || item.name?.ru || item.name?.en || uiEmpty();
      const categoryObj = findCategoryById(item.category);
      const catName = categoryObj ? categoryObj.label : item.category || uiEmpty();
      const subObj = categoryObj?.sub?.find(s => s.id === item.subcategory);
      const subName = subObj ? subObj.label : (item.subcategory ? t(item.subcategory, item.subcategory) : "—");
      const img = item.imgUrl?.trim() ? item.imgUrl : "img/no-image.png";

      const variantsList = item.variants ? Object.values(item.variants) : [];
      const priceText = variantsList.length
        ? (() => {
          const prices = variantsList.map(v => Number(v.price) || 0);
          const min = Math.min(...prices);
          const max = Math.max(...prices);
          return min === max
            ? `${min.toLocaleString()} ${t("currency")}`
            : `${min.toLocaleString()} – ${max.toLocaleString()} ${t("currency")}`;
        })()
        : `${(item.price ?? 0).toLocaleString()} ${t("currency")}`;

      const variantText = variantsList.length
        ? variantsList.map(v => escapeHtml(v.name)).join(", ")
        : "—";

      const soldQty = computeSoldQtyForMenuId(item.id);
      const isActive = item.active !== false;

      const estCost = _estimateMenuItemCost(item);
      const minSellPrice = variantsList.length
        ? Math.min(...variantsList.map(v => Number(v.price) || 0))
        : Number(item.price ?? 0);
      const isLoss = estCost > 0 && minSellPrice > 0 && estCost >= minSellPrice;
      const lossBadge = isLoss
        ? `<span title="${t("loss_warning_title", "Zarar: tannarx sotuv narxidan yuqori yoki teng")}" style="display:inline-flex;align-items:center;gap:3px;font-size:10px;font-weight:800;color:#fff;background:#dc2626;border-radius:5px;padding:1px 6px;margin-right:6px;vertical-align:middle;">⚠ ${t("loss_badge", "ZARAR")}</span>`
        : "";

      const badges = [
        item.isFeatured ? `<span title="${t("is_featured_label", "Mashhur")}" style="font-size:13px;">⭐</span>` : "",
        item.isNew ? `<span title="${t("is_new_label", "Yangi")}" style="font-size:11px;background:var(--admin-success-bg);color:#16a34a;border-radius:999px;padding:1px 7px;font-weight:700;">${t("badge_new_short", "YANGI")}</span>` : "",
      ].filter(Boolean).join(" ");

      const variantExtra = [
        item.prepTime ? `⏰ ${item.prepTime} ${t("minutes_short", "daq")}` : "",
        item.portionSize ? `🍽 ${escapeHtml(item.portionSize)}` : "",
      ].filter(Boolean).join(" · ");

      return `
            <tr class="menu-row" style="border-bottom:1px solid var(--border-color,#e2e8f0);">
              <td style="padding:10px 14px;">
                
                  <input type="checkbox" class="menu-check" value="${item.id}">
                </label>
              </td>
              <td style="padding:10px 14px;">
                <img src="${img}" alt="${name}" onerror="this.src='img/no-image.png'"
                  style="width:42px;height:42px;border-radius:10px;object-fit:cover;border:1px solid var(--border-color,#e2e8f0);">
              </td>
              <td style="padding:10px 14px;font-weight:600;color:var(--text-primary,#1e293b);">${lossBadge}${name}${badges ? ` ${badges}` : ""}</td>
              <td style="padding:10px 14px;color:var(--text-secondary,#64748b);">${catName}</td>
              <td style="padding:10px 14px;color:var(--text-secondary,#64748b);">${subName}</td>
              <td style="padding:10px 14px;text-align:right;font-weight:600;color:var(--text-primary,#1e293b);white-space:nowrap;">${priceText}</td>
              <td style="padding:10px 14px;color:var(--text-secondary,#64748b);font-size:13px;">${variantText}${variantExtra ? `<div style="margin-top:3px;font-size:11px;color:#94a3b8;white-space:nowrap;">${variantExtra}</div>` : ""}</td>
              <td style="padding:10px 14px;text-align:right;color:var(--text-secondary,#64748b);">${soldQty}</td>
              <td style="padding:10px 14px;text-align:center;">
                <span class="menu-status-toggle" data-id="${item.id}" data-active="${isActive}" title="${t("toggle_status_title", "Holatni almashtirish")}" style="
                    display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:5px 12px;
                    font-size:12px;font-weight:700;cursor:pointer;
                    background:${isActive ? "#dcfce7" : "#fee2e2"};color:${isActive ? "#16a34a" : "#dc2626"};
                  "><span style="width:6px;height:6px;border-radius:50%;background:${isActive ? "#16a34a" : "#dc2626"};display:inline-block;"></span>${isActive ? t("status_active", "Faol") : t("status_inactive", "Nofaol")}</span>
              </td>
              <td style="padding:10px 14px;text-align:center;white-space:nowrap;">
                <button class="view-btn" data-id="${item.id}" title="${t("view_btn", "Ko'rish")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:var(--text-secondary);">👁</button>
                <button class="edit-btn" data-id="${item.id}" title="${t("edit_btn", "Tahrirlash")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#f59e0b;">✏️</button>
                <button class="recipe-btn" data-id="${item.id}" data-name="${name.replace(/"/g, '&quot;')}" title="${t("recipe_btn", "Tarkibi (ombor)")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#3b82f6;">📄</button>
                <button class="menu-status-toggle" data-id="${item.id}" data-active="${isActive}" title="${t("toggle_status_title", "Faol/Nofaol")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#f97316;">🚫</button>
                <button class="delete-btn" data-id="${item.id}" title="${t("delete_btn", "O'chirish")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#dc2626;">🗑</button>
              </td>
            </tr>
          `;
    }).join("")
    : `<tr><td colspan="10" style="text-align:center;padding:24px;color:var(--text-secondary,#94a3b8);">${t("search_not_found")}</td></tr>`;
}

