let _menuActiveTab = "taomlar";

window.showMenuTab = function (tab) {
  _menuActiveTab = tab;

  document.querySelectorAll(".menu-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.menutab === tab);
  });

  let activePanel = null;
  document.querySelectorAll(".menu-tab-panel").forEach(panel => {
    const isActive = panel.dataset.menutabpanel === tab;
    panel.style.display = isActive ? "block" : "none";
    if (isActive) activePanel = panel;
  });

  // Tab har safar ko'rsatilganda o'sha panel ichidagi [data-i18n] / [data-i18n-placeholder]
  // elementlarini qayta tarjima qilamiz. Sahifa birinchi marta yuklanganda applyLang()
  // to'g'ri ishlagan bo'lsa ham, keyingi til almashtirishlarda yoki panel qayta
  // ko'rsatilganda bu ta'minlaydi — static th/placeholder xom key holida qolib ketmasin.
  if (activePanel && typeof t === "function") {
    activePanel.querySelectorAll("[data-i18n]").forEach(el => {
      const key = el.getAttribute("data-i18n");
      if (key) el.textContent = t(key, el.textContent);
    });
    activePanel.querySelectorAll("[data-i18n-placeholder]").forEach(el => {
      const key = el.getAttribute("data-i18n-placeholder");
      if (key) el.setAttribute("placeholder", t(key, el.getAttribute("placeholder") || ""));
    });
    activePanel.querySelectorAll("[data-i18n-title]").forEach(el => {
      const key = el.getAttribute("data-i18n-title");
      if (key) el.setAttribute("title", t(key, el.getAttribute("title") || ""));
    });
  }

  if (tab === "kategoriyalar") renderCategoriesList();
  if (tab === "modifierlar") renderModifiersList();
  if (tab === "ingredientlar") {
    if (!window._inventoryListenerStarted && typeof listenToInventory === "function") {
      listenToInventory();
      window._inventoryListenerStarted = true;
    }
    if (typeof window.renderMenuIngredientsList === "function") window.renderMenuIngredientsList();
  }
  if (tab === "qoshimchalar") renderExtrasList();
  if (tab === "combolar" && typeof window.renderMenuCombosList === "function") window.renderMenuCombosList();
  if (tab === "aksiyalar") { renderPromosList(); renderPromotionsList(); }
  if (tab === "analitika" && typeof window.renderMenuAnalytics === "function") window.renderMenuAnalytics();
};

// ── "Yangi taom" tugmasi — qo'shish blokini ochib, unga scroll qiladi ──
window.openAddFoodBlock = function () {
  if (!_menuAddFoodOpen) window.toggleAddFoodBlock();
  document.getElementById("menuAddFoodBlock")?.scrollIntoView({ behavior: "smooth", block: "start" });
  document.getElementById("foodNameInput")?.focus();
};

// ── "Taom qo'shish" bloki ochish/yopish (Taomlar tab ichida) ──
let _menuAddFoodOpen = false;
window.toggleAddFoodBlock = function () {
  _menuAddFoodOpen = !_menuAddFoodOpen;
  const content = document.getElementById("menuAddFoodContent");
  const icon = document.getElementById("menuAddFoodToggleIcon");
  const btn = document.getElementById("menuAddFoodToggleBtn");
  if (content) content.style.display = _menuAddFoodOpen ? "block" : "none";
  if (icon) icon.textContent = _menuAddFoodOpen ? "▲" : "▼";
  if (btn) btn.innerHTML = `<span id="menuAddFoodToggleIcon">${_menuAddFoodOpen ? "▲" : "▼"}</span> ${_menuAddFoodOpen ? t("close_btn", "Yopish") : t("open_btn", "Ochish")}`;
};

// ────────────────────────────────────────────────────────────
// 📂 KATEGORIYALAR TAB — mavjud kategoriya tizimini ro'yxat
//    ko'rinishida ko'rsatadi (add/edit modallari qayta ishlatiladi)
// ────────────────────────────────────────────────────────────
let catSearchQuery = "";
let modSearchQuery = "";
let extraSearchQuery = "";

function countFoodsInCategory(catId) {
  return Object.values(window.allMenu || {}).filter(item => item.category === catId).length;
}

// Qaysi kategoriyalar hozir "ochiq" (subkategoriyalari ko'rsatilgan) holatda ekanini saqlaydi
window._expandedCatIds = window._expandedCatIds || new Set();

// Bitta kategoriyaning subkategoriyalarini alohida jadval qatorlari (<tr>) sifatida chizadi
function renderCategorySubRow(cat) {
  const subs = cat.sub || [];

  if (!subs.length) {
    return `<tr class="cat-sub-row" data-catid-sub="${cat.id}">
        <td></td>
        <td></td>
        <td class="cat-cell-name">
          <span class="cat-sub-empty">${t("mx_no_subcategories", "Hali subkategoriya yo'q")}</span>
        </td>
        <td></td>
        <td></td>
        <td></td>
        <td>
          ${cat.isCustom ? `<button class="cat-sub-add-btn" data-catid="${cat.id}" title="${t('add_subcategory_btn', "Subkategoriya qo'shish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:1.5px dashed var(--border-color,#cbd5e1);background:transparent;color:var(--ds-accent,#6366f1);cursor:pointer;font-size:13px;"><i class="fa-solid fa-plus"></i></button>` : ""}
        </td>
      </tr>`;
  }

  const subRows = subs.map((sub, idx) => {
    const isLast = idx === subs.length - 1;
    return `<tr class="cat-sub-row" data-catid-sub="${cat.id}" data-subid="${sub.id}">
        <td></td>
        <td class="cat-cell-icon">↳</td>
        <td class="cat-cell-name">
          <span class="cat-name-text" title="${escapeHtml(sub.label)}">${escapeHtml(sub.label)}</span>
        </td>
        <td></td>
        <td></td>
        <td></td>
        <td>
          <div style="display:inline-flex;align-items:center;gap:4px;">
            ${cat.isCustom ? `<button class="cat-sub-delete-btn" data-catid="${cat.id}" data-subid="${sub.id}" title="${t('delete_btn', "O'chirish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-danger-bg);color:#e11d48;cursor:pointer;font-size:13px;"><i class="fa-solid fa-trash"></i></button>` : ""}
            ${isLast && cat.isCustom ? `<button class="cat-sub-add-btn" data-catid="${cat.id}" title="${t('add_subcategory_btn', "Subkategoriya qo'shish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:1.5px dashed var(--border-color,#cbd5e1);background:transparent;color:var(--ds-accent,#6366f1);cursor:pointer;font-size:13px;"><i class="fa-solid fa-plus"></i></button>` : ""}
          </div>
        </td>
      </tr>`;
  }).join("");

  return subRows;
}

function renderCategoriesList() {
  const wrap = document.getElementById("categoriesListWrap");
  if (!wrap) return;
  if (typeof updateMenuStatCards === "function") updateMenuStatCards();
  let cats = getAllCategories();

  if (catSearchQuery) {
    cats = cats.filter(cat => (cat.label || "").toLowerCase().includes(catSearchQuery.toLowerCase()));
  }

  wrap.innerHTML = cats.length ? cats.map(cat => {
    const foodCount = countFoodsInCategory(cat.id);
    // Har ikkala tur (statik va custom) ham endi haqiqiy active holatga ega:
    // statik kategoriyalar uchun staticCategoryOverrides, custom uchun
    // customCategories[id].active — ikkalasi ham getAllCategories() da
    // cat.active sifatida allaqachon hisoblab qo'yilgan.
    const isActive = cat.active !== false;
    const icon = cat.isCustom ? "⭐" : "📁";
    const isExpanded = window._expandedCatIds.has(cat.id);
    const subCount = (cat.sub || []).length;

    // ── Holat (status) cell — endi statik kategoriyalar uchun ham bosiladigan ──
    const statusCell = `<button class="cat-status-toggle" data-id="${cat.id}" data-static="${!cat.isCustom}" data-active="${isActive}" title="${t('mx_toggle_status_title', "Holatni almashtirish")}" style="
            display:inline-flex;align-items:center;gap:6px;
            border:none;border-radius:999px;padding:5px 14px;font-size:12px;font-weight:700;cursor:pointer;
            transition:background .15s,color .15s;
            background:${isActive ? "#dcfce7" : "#fee2e2"};
            color:${isActive ? "#15803d" : "#dc2626"};
          ">
            <span style="width:7px;height:7px;border-radius:50%;background:${isActive ? "#22c55e" : "#ef4444"};flex-shrink:0;"></span>
            ${isActive ? t("status_active", "Faol") : t("status_inactive", "Nofaol")}
          </button>`;

    // ── Taomlar soni — kliklanadigan badge (Nofaol kategoriyada bloklanadi) ──
    const foodBadge = foodCount > 0
      ? (isActive
          ? `<button class="cat-food-count-btn" data-catid="${cat.id}" title="${t("cat_view_foods_title", "Shu kategoriyadagi taomlarni ko'rish")}" style="
                display:inline-flex;align-items:center;gap:5px;
                background:var(--admin-info-bg);color:#3b82f6;border:1.5px solid #bfdbfe;
                border-radius:999px;padding:4px 12px;font-size:13px;font-weight:700;
                cursor:pointer;transition:background .15s,border-color .15s;
              ">
                <i class="fa-solid fa-utensils" style="font-size:10px;"></i>
                ${foodCount}
              </button>`
          : `<span title="${t('mx_category_inactive_hint', "Kategoriya Nofaol — taomlar vaqtincha ishlamaydi")}" style="
                display:inline-flex;align-items:center;gap:5px;
                background:var(--bg-hover);color:#94a3b8;border:1.5px solid var(--border);
                border-radius:999px;padding:4px 12px;font-size:13px;font-weight:700;
              ">
                <i class="fa-solid fa-utensils" style="font-size:10px;"></i>
                ${foodCount}
              </button>`)
      : `<span style="color:var(--text-secondary,#94a3b8);font-size:13px;">—</span>`;

    // ── Amal tugmalari (faqat ✏️ va 🗑️) ──
    const editBtn = cat.isCustom
      ? `<button class="cat-edit-btn" data-id="${cat.id}" data-label="${escapeHtml(cat.label)}" title="${t('edit_btn', "Tahrirlash")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-warning-bg);color:#ca8a04;cursor:pointer;font-size:13px;"><i class="fa-solid fa-pen"></i></button>`
      : `<button disabled title="${t('system_category_title', "Tizim kategoriyasi")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--bg-hover);color:#cbd5e1;cursor:not-allowed;font-size:13px;"><i class="fa-solid fa-pen"></i></button>`;

    const deleteBtn = cat.isCustom
      ? `<button class="cat-delete-btn" data-id="${cat.id}" title="${t('delete_btn', "O'chirish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-danger-bg);color:#e11d48;cursor:pointer;font-size:13px;"><i class="fa-solid fa-trash"></i></button>`
      : `<button disabled title="${t('system_category_delete_disabled_title', "Tizim kategoriyasini o'chirish mumkin emas")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--bg-hover);color:#cbd5e1;cursor:not-allowed;font-size:13px;"><i class="fa-solid fa-trash"></i></button>`;

    const expandBtn = `<button class="cat-expand-toggle${isExpanded ? " expanded" : ""}" data-id="${cat.id}"
        title="${t('mx_show_subcategories', "Subkategoriyalarni ko'rsatish")}${subCount ? ` (${subCount})` : ""}">
        <i class="fa-solid fa-chevron-right"></i>
      </button>`;

    const subCell = subCount > 0
      ? `<button class="cat-food-count-btn cat-expand-toggle-inline" data-id="${cat.id}" title="${t('mx_show_subcategories', "Subkategoriyalarni ko'rsatish")}" style="
            display:inline-flex;align-items:center;gap:5px;
            background:var(--admin-purple-bg);color:#6366f1;border:1.5px solid #c7d2fe;
            border-radius:999px;padding:4px 12px;font-size:13px;font-weight:700;
            cursor:pointer;transition:background .15s,border-color .15s;
          ">
            <i class="fa-solid fa-layer-group" style="font-size:10px;"></i>
            ${subCount}
          </button>`
      : `<span style="color:var(--text-secondary,#94a3b8);font-size:13px;">—</span>`;

    const mainRow = `<tr class="cat-list-row${isActive ? "" : " cat-list-row-inactive"}" data-catid="${cat.id}"${isActive ? "" : ` style="opacity:.55;"`}>
        <td class="cat-cell-expand">${expandBtn}</td>
        <td class="cat-cell-icon">${icon}</td>
        <td class="cat-cell-name">
          <span class="cat-name-text" title="${escapeHtml(cat.label)}">${escapeHtml(cat.label)}</span>
        </td>
        <td>${subCell}</td>
        <td>${foodBadge}</td>
        <td>${statusCell}</td>
        <td><div style="display:inline-flex;align-items:center;gap:4px;">${editBtn}${deleteBtn}</div></td>
      </tr>`;

    return isExpanded ? mainRow + renderCategorySubRow(cat) : mainRow;
  }).join("") : `<tr><td colspan="7" style="text-align:center;padding:32px;color:var(--text-secondary,#94a3b8);">
    <i class="fa-solid fa-folder-open" style="font-size:28px;margin-bottom:8px;display:block;opacity:.4;"></i>
    ${t("mx_no_categories", "Hali kategoriya yo'q")}
  </td></tr>`;
}

document.getElementById("catSearch")?.addEventListener("input", e => {
  catSearchQuery = e.target.value;
  renderCategoriesList();
});

document.getElementById("modSearch")?.addEventListener("input", e => {
  modSearchQuery = e.target.value;
  renderModifiersList();
});

document.getElementById("extraSearch")?.addEventListener("input", e => {
  extraSearchQuery = e.target.value;
  renderExtrasList();
});

// Enter tugmasi bilan kategoriya nomini saqlash
document.addEventListener("keydown", e => {
  if (e.key === "Enter" && document.activeElement?.id === "editCategoryNameInput") {
    window.saveEditCategory();
  }
  if (e.key === "Escape") {
    const editModal = document.getElementById("editCategoryModal");
    if (editModal && !editModal.classList.contains("hidden")) {
      window.closeEditCategoryModal();
    }
  }
});

document.addEventListener("click", e => {
  // ── Holat toggle ──
  if (e.target.closest(".cat-status-toggle")) {
    const btn = e.target.closest(".cat-status-toggle");
    const id = btn.dataset.id;
    const isStatic = btn.dataset.static === "true";
    const currentlyActive = btn.dataset.active === "true";
    window.toggleCategoryStatus(id, !currentlyActive, isStatic);
    return;
  }
  // ── Tahrirlash ──
  if (e.target.closest(".cat-edit-btn")) {
    const btn = e.target.closest(".cat-edit-btn");
    window.openEditCategoryModal(btn.dataset.id, btn.dataset.label);
    return;
  }
  // ── O'chirish ──
  if (e.target.closest(".cat-delete-btn")) {
    const btn = e.target.closest(".cat-delete-btn");
    window.deleteCustomCategory(btn.dataset.id);
    return;
  }
  // ── Taomlar soni bosilsa → Taomlar tabiga o'tib filter (faqat Faol kategoriyada) ──
  if (e.target.closest(".cat-food-count-btn")) {
    const btn = e.target.closest(".cat-food-count-btn");
    const cat = findCategoryById(btn.dataset.catid);
    if (cat && cat.active === false) return;
    window.jumpToFoodsByCategory(btn.dataset.catid);
    return;
  }
  // ── Subkategoriyalarni ochish/yopish (expand) ──
  if (e.target.closest(".cat-expand-toggle") || e.target.closest(".cat-expand-toggle-inline")) {
    const btn = e.target.closest(".cat-expand-toggle") || e.target.closest(".cat-expand-toggle-inline");
    const catId = btn.dataset.id;
    if (window._expandedCatIds.has(catId)) window._expandedCatIds.delete(catId);
    else window._expandedCatIds.add(catId);
    renderCategoriesList();
    return;
  }
  // ── Ro'yxatdan turib subkategoriya qo'shish ──
  if (e.target.closest(".cat-sub-add-btn")) {
    const btn = e.target.closest(".cat-sub-add-btn");
    window.openSubcategoryModal("list", btn.dataset.catid);
    return;
  }
  // ── Ro'yxatdan turib subkategoriyani o'chirish ──
  if (e.target.closest(".cat-sub-delete-btn")) {
    const btn = e.target.closest(".cat-sub-delete-btn");
    window.deleteCustomSubcategory(btn.dataset.catid, btn.dataset.subid);
    return;
  }
});

// catId: kategoriya ID'si
// active: true → Faol qilish, false → Nofaol qilish
// isStatic: true bo'lsa CATEGORY_DATA (shared.js) dagi tizim kategoriyasi —
//           Firebase'da alohida "categoryOverrides" yo'lida saqlanadi, chunki
//           statik kategoriyalarning o'zi "/categories" yo'lida yozilmagan.
//
// Muhim: taomning haqiqiy Faol/Nofaol holati "menu/{id}/active" maydonida
// saqlanadi (renderMenu va toggleMenu shu maydondan foydalanadi — bu butun
// tizim: buyurtma/oshxona/mijoz oqimi taomning ishlash-ishlamasligini shu
// yerdan biladi). Shu sababli kategoriya Nofaol qilinganda taomlarni ham
// aynan shu "active:false" holatiga o'tkazamiz — shunda kategoriya haqiqatan
// ham "ishlamaydi": uning taomlari boshqa joylarda (buyurtma, oshxona va h.k.)
// ham Nofaol sifatida ko'rinadi/bloklanadi.
window.toggleCategoryStatus = async function (catId, active, isStatic = false) {
  try {
    if (isStatic) {
      await update(ref(db, BASE_PATH + "/categoryOverrides/" + catId), { active });
      window.staticCategoryOverrides = window.staticCategoryOverrides || {};
      window.staticCategoryOverrides[catId] = { ...(window.staticCategoryOverrides[catId] || {}), active };
    } else {
      await update(ref(db, BASE_PATH + "/categories/" + catId), { active });
      if (window.customCategories?.[catId]) window.customCategories[catId].active = active;
    }

    await cascadeCategoryStatusToFoods(catId, active);

    renderCategoriesList();
    renderMenu?.();
    await crmAdvAudit(
      "menu",
      "status_change",
      catId,
      active
        ? t("audit_category_activated", "Kategoriya Faol qilindi")
        : t("audit_category_deactivated", "Kategoriya Nofaol qilindi"),
      { catId, active },
      active ? "info" : "warning"
    );
    showAdminNotification(active
      ? t("notify_category_active", "Kategoriya Faol qilindi")
      : t("notify_category_inactive", "Kategoriya Nofaol qilindi — taomlari vaqtincha ishlamaydi"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

// Kategoriya Nofaol/Faol qilinganda shu kategoriyadagi taomlarning haqiqiy
// "active" maydonini ham moslashtiradi (renderMenu/toggleMenu shu maydondan
// foydalanadi).
//
// — Nofaol qilinganda: hali Faol turgan har bir taom "active:false" qilinadi,
//   va o'sha taomga "disabledByCategory:true" belgisi qo'yiladi — bu shu
//   taom ALOHIDA emas, balki KATEGORIYASI orqali o'chirilganini bildiradi.
// — Faol qilinganda: faqat "disabledByCategory:true" belgisi turgan taomlar
//   qayta "active:true" qilinadi. Admin ilgari o'zi qo'lda Nofaol qilib
//   qo'ygan (disabledByCategory belgisisiz) taomlar esa tegilmay, Nofaol
//   holatida qoladi — kategoriya ularni "qaytarib yoqib" yubormaydi.
async function cascadeCategoryStatusToFoods(catId, categoryActive) {
  const foods = Object.entries(window.allMenu || {}).filter(([, item]) => item.category === catId);
  if (!foods.length) return;

  const updates = {};

  foods.forEach(([foodId, item]) => {
    if (!categoryActive) {
      // Faqat hozircha Faol turgan taomlarni o'chiramiz va ularni
      // "kategoriya sabab o'chdi" deb belgilaymiz.
      if (item.active !== false) {
        updates[`${BASE_PATH}/menu/${foodId}/active`] = false;
        updates[`${BASE_PATH}/menu/${foodId}/disabledByCategory`] = true;
        if (window.allMenu?.[foodId]) {
          window.allMenu[foodId].active = false;
          window.allMenu[foodId].disabledByCategory = true;
        }
      }
    } else {
      // Faqat shu belgi bilan o'chirilgan taomlarni qaytaramiz.
      if (item.disabledByCategory === true) {
        updates[`${BASE_PATH}/menu/${foodId}/active`] = true;
        updates[`${BASE_PATH}/menu/${foodId}/disabledByCategory`] = null;
        if (window.allMenu?.[foodId]) {
          window.allMenu[foodId].active = true;
          delete window.allMenu[foodId].disabledByCategory;
        }
      }
    }
  });

  if (!Object.keys(updates).length) return;

  try {
    await update(ref(db), updates);
  } catch (err) {
    console.error("cascadeCategoryStatusToFoods xato:", err);
  }
}

// Item 4.3/4.4 — kategoriyani o'chirishdan oldin unga biriktirilgan taomlar
// sonini hisoblaydi (mavjud "item.category === catId" mezoni —
// cascadeCategoryStatusToFoods() bilan bir xil, item 4.1: canonical source).
function _categoryDependentFoods(catId) {
  return Object.entries(window.allMenu || {}).filter(([, item]) => item.category === catId);
}

async function _actuallyDeleteCategory(catId) {
  await remove(ref(db, BASE_PATH + "/categories/" + catId));
  if (window.customCategories) delete window.customCategories[catId];
  await crmAdvAudit("menu", "delete", catId, t("audit_category_deleted", "Kategoriya o'chirildi"), {}, "warning");
  renderCategoriesList();
  showAdminNotification(t("notify_deleted_all", "O'chirildi"));
}

window.deleteCustomCategory = async function (catId) {
  try {
    const dependents = _categoryDependentFoods(catId);

    // 0 ta taom — oddiy, mavjud tasdiqlash bilan (item Test B).
    if (!dependents.length) {
      if (!confirm(t("confirm_delete_selected", "Ishonchingiz komilmi?"))) return;
      await _actuallyDeleteCategory(catId);
      return;
    }

    // Taomlar biriktirilgan — aniq ogohlantirish + "boshqa kategoriyaga
    // ko'chirish" majburiy variant (item 4.4 "eng xavfsiz variant").
    window._openCategoryDeleteWarningModal(catId, dependents);
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

// Item 4.3/4.4 — kategoriyaga biriktirilgan taomlar bilan nima qilishni
// tanlash oynasi. Standart va yagona "davom etish" yo'li — boshqa
// kategoriyaga ko'chirish (taomlar hech qachon "yo'qolib ketmaydi").
// "Kategoriyasiz qoldirish" alohida, kamroq ko'zga tashlanadigan variant
// sifatida ham beriladi (task shart qilib bermagan, lekin imkoniyat sifatida
// so'ralgan) — ikkalasi ham FAQAT tanlangandan keyin amalga oshadi.
window._openCategoryDeleteWarningModal = function (catId, dependents) {
  let modal = document.getElementById("catDeleteWarnModal");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "catDeleteWarnModal";
    modal.className = "modal";
    document.body.appendChild(modal);
  }

  // Item 4.8 — canonical source: getAllCategories()/findCategoryById()
  // (statik CATEGORY_DATA + custom kategoriyalar birga, joriy til bilan
  // avtomatik) — bu yerda alohida label hisoblash mantig'i qayta yozilmadi.
  const catLabel = findCategoryById(catId)?.label || catId;
  const otherCats = getAllCategories().filter(c => c.id !== catId);
  const optionsHtml = otherCats.map(c =>
    `<option value="${escapeHtml(c.id)}">${c.isCustom ? "⭐ " : ""}${escapeHtml(c.label)}</option>`
  ).join("");

  modal.innerHTML = `
    <div class="modal-content" style="max-width:440px;">
      <h3 style="margin-top:0;">⚠️ ${escapeHtml(catLabel)}</h3>
      <p>${t("cat_delete_warn_count", "Bu kategoriya {n} ta taomga biriktirilgan.").replace("{n}", dependents.length)}</p>
      <p style="color:var(--text-secondary);font-size:13px;">${t("cat_delete_warn_sub", "O'chirsangiz, taomlar kategoriyasiz qolishi mumkin.")}</p>
      ${otherCats.length ? `
        <label style="font-size:13px;font-weight:700;color:var(--text-secondary);display:block;margin:14px 0 6px;">${t("cat_delete_move_label", "Boshqa kategoriyaga ko'chirish")}</label>
        <select id="catDeleteTargetSelect" style="width:100%;">
          <option value="">${t("cat_delete_move_placeholder", "— Kategoriya tanlang —")}</option>
          ${optionsHtml}
        </select>
      ` : ""}
      <div class="modal-actions" style="margin-top:18px;display:flex;flex-direction:column;gap:8px;">
        ${otherCats.length ? `<button class="btn primary" onclick="window._resolveCategoryDelete('${escapeHtml(catId)}','move')">${t("cat_delete_move_btn", "Boshqa kategoriyaga ko'chirish")}</button>` : ""}
        <button class="btn" onclick="window._resolveCategoryDelete('${escapeHtml(catId)}','orphan')">${t("cat_delete_orphan_btn", "Kategoriyasiz qoldirish")}</button>
        <button class="btn" onclick="window.closeCategoryDeleteWarnModal()">${t("cancel_btn", "Bekor qilish")}</button>
      </div>
    </div>
  `;
  modal.classList.add("open");
};

window.closeCategoryDeleteWarnModal = function () {
  document.getElementById("catDeleteWarnModal")?.classList.remove("open");
};

window._resolveCategoryDelete = async function (catId, mode) {
  try {
    const dependents = _categoryDependentFoods(catId);
    let targetCatId = "";
    if (mode === "move") {
      targetCatId = document.getElementById("catDeleteTargetSelect")?.value || "";
      if (!targetCatId) {
        alert(t("cat_delete_move_required", "Ko'chirish uchun kategoriya tanlang"));
        return;
      }
    }

    // Item 4.5 — taomlarni ko'chirish subkategoriyani BUZMAYDI: subcategory
    // maydoni faqat targetCatId'da haqiqatan mavjud bo'lsa saqlanadi, aks
    // holda (eski kategoriyaga xos subkategoriya endi mos kelmasligi mumkin)
    // tozalanadi — noto'g'ri, "osilib qolgan" subkategoriya havolasi
    // qoldirilmaydi.
    if (dependents.length) {
      const updates = {};
      dependents.forEach(([foodId, item]) => {
        updates[`${BASE_PATH}/menu/${foodId}/category`] = mode === "move" ? targetCatId : "";
        if (mode === "move" && item.subCategory) {
          updates[`${BASE_PATH}/menu/${foodId}/subCategory`] = null;
        }
      });
      await update(ref(db), updates);
      dependents.forEach(([foodId]) => {
        if (window.allMenu?.[foodId]) {
          window.allMenu[foodId].category = mode === "move" ? targetCatId : "";
          if (mode === "move") delete window.allMenu[foodId].subCategory;
        }
      });
    }

    await _actuallyDeleteCategory(catId);
    window.closeCategoryDeleteWarnModal();
    if (typeof renderMenu === "function") renderMenu();
  } catch (err) {
    console.error("_resolveCategoryDelete error:", err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.deleteCustomSubcategory = async function (catId, subId) {
  if (!confirm(t("confirm_delete_selected", "Ishonchingiz komilmi?"))) return;
  try {
    await remove(ref(db, BASE_PATH + "/categories/" + catId + "/sub/" + subId));
    if (window.customCategories?.[catId]?.sub) delete window.customCategories[catId].sub[subId];
    await crmAdvAudit("menu", "delete", subId, t("audit_subcategory_deleted", "Subkategoriya o'chirildi"), { catId }, "warning");
    renderCategoriesList();
    renderSubcategories(subcategorySelect, categorySelect?.value || "", subcategorySelect?.value || "");
    renderSubcategories(editSubCategory, editCategory?.value || "", editSubCategory?.value || "");
    showAdminNotification(t("notify_deleted_all", "O'chirildi"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

