window.openEditCategoryModal = function (catId, currentLabel) {
  const modal = document.getElementById("editCategoryModal");
  const idInput = document.getElementById("editCategoryId");
  const nameInput = document.getElementById("editCategoryNameInput");
  if (!modal || !idInput || !nameInput) return;
  idInput.value = catId;
  nameInput.value = currentLabel || "";
  modal.classList.remove("hidden");
  setTimeout(() => nameInput.focus(), 50);
};

window.closeEditCategoryModal = function () {
  document.getElementById("editCategoryModal")?.classList.add("hidden");
};

window.saveEditCategory = async function () {
  const catId = document.getElementById("editCategoryId")?.value;
  const nameUz = document.getElementById("editCategoryNameInput")?.value.trim();
  if (!catId || !nameUz) { alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring")); return; }

  try {
    const nameRu = await autoTranslate(nameUz, "ru");
    const nameEn = await autoTranslate(nameUz, "en");

    await update(ref(db, BASE_PATH + "/categories/" + catId), {
      name: { uz: nameUz, ru: nameRu, en: nameEn }
    });

    if (window.customCategories?.[catId]) {
      window.customCategories[catId].name = { uz: nameUz, ru: nameRu, en: nameEn };
    }

    await crmAdvAudit("menu", "edit", catId, t("audit_category_renamed", "Kategoriya nomi o'zgartirildi"), { name: nameUz }, "info");

    window.closeEditCategoryModal();
    renderCategoriesList();
    renderCategories(categorySelect, categorySelect?.value || "");
    renderCategories(editCategory, editCategory?.value || "");
    showAdminNotification(t("category_updated_notification", "Kategoriya yangilandi ✅"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

