window.jumpToFoodsByCategory = function (catId) {
  // 1. Menyu bo'limiga o'tamiz
  const menuSection = document.querySelector('[data-section="menu"]') ||
    document.querySelector('.nav-link[href="#menu"]') ||
    document.querySelector('[onclick*="menu"]');
  if (menuSection) menuSection.click();

  // 2. "Taomlar" tabini faollashtirish
  setTimeout(() => {
    window.showMenuTab("taomlar");

    // 3. Kategoriya filterini o'rnatamiz
    const sel = document.getElementById("menuFilterCategory");
    if (sel) {
      sel.value = catId;
      menuFilterCategoryValue = catId;
    }

    // 4. Menyuni qayta chizamiz
    if (typeof renderMenu === "function") renderMenu();

    // 5. Taomlar bo'limiga scroll
    document.getElementById("menuTab-taomlar")?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, 150);
};

// ────────────────────────────────────────────────────────────
// ➕ MODIFIERLAR TAB — tanlash guruhlari (masalan: achchiqlik
//    darajasi), restaurants/{restId}/modifiers ostida saqlanadi
// ────────────────────────────────────────────────────────────
window.allModifiers = window.allModifiers || {};
let _modifierOptionRowId = 0;
let _modifierEditId = null;

function listenToModifiers() {
  onValue(ref(db, BASE_PATH + "/modifiers"), snap => {
    window.allModifiers = snap.val() || {};
    if (_menuActiveTab === "modifierlar") renderModifiersList();
  });
}

function renderModifiersList() {
  const wrap = document.getElementById("modifiersListWrap");
  if (!wrap) return;
  const lang = getLang();
  let items = Object.entries(window.allModifiers || {}).map(([id, m]) => ({ id, ...m }));

  if (modSearchQuery) {
    items = items.filter(mod => {
      const nm = mod.name?.[lang] || mod.name?.uz || "";
      return nm.toLowerCase().includes(modSearchQuery.toLowerCase());
    });
  }

  wrap.innerHTML = items.length ? items.map(mod => {
    const name = mod.name?.[lang] || mod.name?.uz || uiEmpty();
    const optCount = Object.keys(mod.options || {}).length;
    const isActive = mod.active !== false;

    // ── Tanlash (min-max) cell — "kamida:X ko'pi bilan:Y" formatida ──
    const minSel = Number.isFinite(mod.minSelect) ? mod.minSelect : (mod.required ? 1 : 0);
    const maxSel = Number.isFinite(mod.maxSelect) ? mod.maxSelect : Math.max(minSel, 1);
    const requiredCell = `<span style="font-size:13px;color:var(--text-primary,#1e293b);white-space:nowrap;">${minSel}–${maxSel} ${t("mx_pieces_short", "ta")}</span>`;

    // ── Holat (status) cell — kategoriyalar jadvali bilan bir xil uslub ──
    const statusCell = `<span style="display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 14px;font-size:12px;font-weight:700;background:${isActive ? "#dcfce7" : "#fee2e2"};color:${isActive ? "#15803d" : "#dc2626"};">
          <span style="width:7px;height:7px;border-radius:50%;background:${isActive ? "#22c55e" : "#ef4444"};flex-shrink:0;"></span>
          ${isActive ? t("status_active", "Faol") : t("status_inactive", "Nofaol")}
        </span>`;

    const editBtn = `<button onclick="window.openModifierModal('${mod.id}')" title="${t("edit_btn", "Tahrirlash")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-warning-bg);color:#ca8a04;cursor:pointer;font-size:13px;"><i class="fa-solid fa-pen"></i></button>`;
    const deleteBtn = `<button onclick="window.deleteModifier('${mod.id}')" title="${t("delete_btn", "O'chirish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-danger-bg);color:#e11d48;cursor:pointer;font-size:13px;"><i class="fa-solid fa-trash"></i></button>`;

    return `<tr class="mod-row" style="border-bottom:1px solid var(--border-color,#e2e8f0);" onmouseenter="this.style.background='var(--bg-body,#f8fafc)'" onmouseleave="this.style.background=''">
        <td style="padding:12px 14px;font-weight:600;color:var(--text-primary,#1e293b);font-size:14px;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(name)}</td>
        <td style="padding:12px 14px;text-align:center;color:var(--text-primary,#1e293b);">${optCount}</td>
        <td style="padding:12px 14px;text-align:center;">${requiredCell}</td>
        <td style="padding:12px 14px;text-align:center;">${statusCell}</td>
        <td style="padding:12px 14px;text-align:center;white-space:nowrap;"><div style="display:inline-flex;align-items:center;gap:4px;justify-content:center;">${editBtn}${deleteBtn}</div></td>
      </tr>`;
  }).join("") : `<tr><td colspan="5" style="text-align:center;padding:32px;color:var(--text-secondary,#94a3b8);">
    <i class="fa-solid fa-folder-open" style="font-size:28px;margin-bottom:8px;display:block;opacity:.4;"></i>
    ${t("mx_no_modifiers", "Hali modifier yo'q")}
  </td></tr>`;
}

window.addModifierOptionRow = function (name = "", price = 0) {
  const list = document.getElementById("modifierOptionsList");
  if (!list) return;
  const rowId = "modopt_" + (_modifierOptionRowId++);
  const row = document.createElement("div");
  row.className = "mx-modifier-option-row";
  row.id = rowId;
  row.innerHTML = `
    <input type="text" class="mx-mod-opt-name" placeholder="${t("modifier_option_name_placeholder", "Nomi (masalan: O'rtacha)")}" value="${escapeHtml(name)}">
    <input type="number" class="mx-mod-opt-price" placeholder="${t("modifier_option_price_placeholder", "Qo'shimcha narx")}" value="${Number(price) || 0}">
    <button type="button" class="variant-row .variant-remove-btn" onclick="document.getElementById('${rowId}').remove()" style="flex-shrink:0;width:32px;height:32px;border-radius:6px;border:none;background:var(--admin-danger-bg);color:#dc2626;cursor:pointer;">✕</button>
  `;
  list.appendChild(row);
};

window.openModifierModal = function (modId = null) {
  _modifierEditId = modId;
  const modal = document.getElementById("modifierModal");
  const nameInput = document.getElementById("modifierNameInput");
  const minInput = document.getElementById("modifierMinSelect");
  const maxInput = document.getElementById("modifierMaxSelect");
  const optList = document.getElementById("modifierOptionsList");
  if (optList) optList.innerHTML = "";

  if (modId) {
    const mod = window.allModifiers[modId];
    if (mod) {
      const lang = getLang();
      if (nameInput) nameInput.value = mod.name?.[lang] || mod.name?.uz || "";
      const minSel = Number.isFinite(mod.minSelect) ? mod.minSelect : (mod.required ? 1 : 0);
      const maxSel = Number.isFinite(mod.maxSelect) ? mod.maxSelect : Math.max(minSel, 1);
      if (minInput) minInput.value = minSel;
      if (maxInput) maxInput.value = maxSel;
      Object.values(mod.options || {}).forEach(o => window.addModifierOptionRow(o.name, o.price));
    }
  } else {
    if (nameInput) nameInput.value = "";
    if (minInput) minInput.value = 0;
    if (maxInput) maxInput.value = 1;
    window.addModifierOptionRow();
  }

  modal?.classList.remove("hidden");
};

window.closeModifierModal = function () {
  document.getElementById("modifierModal")?.classList.add("hidden");
  _modifierEditId = null;
};

window.saveModifier = async function () {
  const nameUz = document.getElementById("modifierNameInput")?.value.trim();
  if (!nameUz) { alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring")); return; }

  const optionRows = document.querySelectorAll("#modifierOptionsList .mx-modifier-option-row");
  const options = {};
  optionRows.forEach((row, idx) => {
    const oName = row.querySelector(".mx-mod-opt-name")?.value.trim();
    const oPrice = Number(row.querySelector(".mx-mod-opt-price")?.value) || 0;
    if (oName) options["opt_" + idx] = { name: oName, price: oPrice };
  });
  if (!Object.keys(options).length) { alert(t("alerts.fill_all", "Kamida bitta variant kiriting")); return; }

  const minSelect = Math.max(0, Number(document.getElementById("modifierMinSelect")?.value) || 0);
  const maxSelect = Math.max(0, Number(document.getElementById("modifierMaxSelect")?.value) || 0);
  const optionCount = Object.keys(options).length;

  if (maxSelect < 1) { alert(t("alerts.mod_max_min1", "Maksimal tanlash kamida 1 bo'lishi kerak")); return; }
  if (minSelect > maxSelect) { alert(t("alerts.mod_min_gt_max", "Minimal tanlash maksimaldan katta bo'lishi mumkin emas")); return; }
  if (maxSelect > optionCount) { alert(t("alerts.mod_max_gt_options", "Maksimal tanlash variantlar sonidan ko'p bo'lishi mumkin emas")); return; }

  try {
    const nameRu = await autoTranslate(nameUz, "ru");
    const nameEn = await autoTranslate(nameUz, "en");
    const id = _modifierEditId || ("mod_" + Date.now().toString());

    await set(ref(db, BASE_PATH + "/modifiers/" + id), {
      id,
      name: { uz: nameUz, ru: nameRu, en: nameEn },
      minSelect,
      maxSelect,
      required: minSelect >= 1, // eski kod bilan moslik uchun hisoblab chiqarilgan qiymat
      options,
      createdAt: window.allModifiers[id]?.createdAt || Date.now()
    });

    await crmAdvAudit("menu", _modifierEditId ? "update" : "create", id,
      _modifierEditId ? t("audit_modifier_updated", "Modifier yangilandi") : t("audit_modifier_created", "Yangi modifier qo'shildi"),
      { name: nameUz }, "info");

    window.closeModifierModal();
    showAdminNotification(t("notify.modifier_saved", "Modifier saqlandi ✅"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.deleteModifier = async function (modId) {
  if (!confirm(t("confirm_delete_selected", "Ishonchingiz komilmi?"))) return;
  try {
    await remove(ref(db, BASE_PATH + "/modifiers/" + modId));
    await crmAdvAudit("menu", "delete", modId, t("audit_modifier_deleted", "Modifier o'chirildi"), {}, "warning");
    showAdminNotification(t("notify_deleted_all", "O'chirildi"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

// ────────────────────────────────────────────────────────────
// 🥕 INGREDIENTLAR TAB (Menu bo'limi ichida) — Ombor bilan bog'langan
// Manba: window.allInventory (restaurants/{id}/inventory), Ombor bo'limining
// mavjud real-vaqtli listener'i orqali doim yangilanib turadi (mergeAndRender()).
// Bu yerda yangi ma'lumot bazasi YARATILMAYDI — faqat shu bir xil ombor
// yozuvlarini Menu bo'limi ichidan ham ko'rish/qo'shish/tahrirlash imkonini beradi.
// Har bir taomning "tarkibi" (retsept) mavjud openRecipeModal() orqali ochiladi —
// sotilganda ombordan avtomatik ayirish esa mavjud deductStock() funksiyasi
// (buyurtma to'langanda ishga tushadi) orqali allaqachon amalga oshiriladi.
// ────────────────────────────────────────────────────────────
let _miEditId = null;
let _miSearchQuery = "";

function _miFindMenuItemName(item) {
  const lang = typeof getLang === "function" ? getLang() : "uz";
  return typeof item.name === "object"
    ? (item.name?.[lang] || item.name?.uz || item.name?.ru || item.name?.en || "—")
    : (item.name || "—");
}

// Har bir ingredient qaysi taomlarda ishlatilishini window.allMenu dan hisoblab chiqamiz
function _miUsedInMap() {
  const map = {}; // ingId -> [taom nomi, ...]
  Object.values(window.allMenu || {}).forEach(item => {
    const recipe = Array.isArray(item.recipe) ? item.recipe : Object.values(item.recipe || {});
    recipe.forEach(ing => {
      if (!ing?.id) return;
      if (!map[ing.id]) map[ing.id] = [];
      map[ing.id].push(_miFindMenuItemName(item));
    });
  });
  return map;
}

window.renderMenuIngredientsList = function () {
  const tbody = document.getElementById("menuIngredientsListBody");
  if (!tbody) return;

  const searchInput = document.getElementById("miSearchInput");
  _miSearchQuery = searchInput ? searchInput.value.trim().toLowerCase() : _miSearchQuery;

  const usedIn = _miUsedInMap();
  let items = Object.entries(window.allInventory || {}).map(([id, ing]) => ({ id, ...ing }));

  if (_miSearchQuery) {
    items = items.filter(ing => String(ing.name || "").toLowerCase().includes(_miSearchQuery));
  }
  items.sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "uz"));

  if (!items.length) {
    tbody.innerHTML = `<tr><td colspan="6" style="text-align:center;padding:24px;color:var(--text-secondary,#94a3b8);">${t("menu_ing_empty", "Hali ingredient yo'q. \"Yangi ingredient\" tugmasi orqali qo'shing.")}</td></tr>`;
    return;
  }

  const UNITS = window.RECIPE_UNITS || [{ value: "gr", label: () => "gr" }];
  const unitLabelOf = (u) => {
    const found = UNITS.find(x => x.value === u);
    return found ? (typeof found.label === "function" ? found.label() : found.label) : (u || "gr");
  };

  tbody.innerHTML = items.map(ing => {
    const stockVal = parseFloat(ing.stock || 0);
    const minStockVal = parseFloat(ing.minStock || 0);
    const unit = ing.unit || "gr";
    const defaultThresholds = { kg: 1, l: 1, gr: 200, ml: 200, dona: 5 };
    const lowThreshold = minStockVal > 0 ? minStockVal : (defaultThresholds[unit] ?? 10);
    const color = stockVal <= 0 ? "#dc2626" : (stockVal <= lowThreshold ? "#d97706" : "#16a34a");
    const badgeBg = stockVal <= 0 ? "#fee2e2" : (stockVal <= lowThreshold ? "#fef9c3" : "#dcfce7");
    const statusText = stockVal <= 0 ? t("stock_empty", "Tugagan") : (stockVal <= lowThreshold ? t("stock_low", "Kam qoldi") : t("stock_enough", "Yetarli"));

    const usedList = usedIn[ing.id] || [];
    const usedText = usedList.length
      ? usedList.slice(0, 3).map(n => escapeHtml(n)).join(", ") + (usedList.length > 3 ? ` +${usedList.length - 3}` : "")
      : `<span style="color:#94a3b8;">${t("menu_ing_not_used", "Hech qaysi taomda yo'q")}</span>`;

    return `
      <tr class="mi-row" style="border-bottom:1px solid var(--border-color,#e2e8f0);">
        <td style="padding:10px 14px;font-weight:600;color:var(--text-primary,#1e293b);">${escapeHtml(ing.name || "—")}</td>
        <td style="padding:10px 14px;color:var(--text-secondary,#64748b);">${unitLabelOf(unit)}</td>
        <td style="padding:10px 14px;text-align:right;font-weight:700;color:${color};">${stockVal.toLocaleString()} ${unit}</td>
        <td style="padding:10px 14px;font-size:13px;color:var(--text-secondary,#64748b);">${usedText}</td>
        <td style="padding:10px 14px;text-align:center;">
          <span style="display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:4px 10px;font-size:12px;font-weight:700;background:${badgeBg};color:${color};">${statusText}</span>
        </td>
        <td style="padding:10px 14px;text-align:center;white-space:nowrap;">
          <button onclick="window.openMenuIngredientModal('${ing.id}')" title="${t("edit_btn", "Tahrirlash")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#f59e0b;">✏️</button>
          <button onclick="window.deleteIngredient('${ing.id}'); setTimeout(window.renderMenuIngredientsList, 300);" title="${t("delete_btn", "O'chirish")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#dc2626;">🗑</button>
        </td>
      </tr>`;
  }).join("");
};

// ── menuIngredientModal uchun: Jami summa ⇄ 1 birlik narxi (Miqdorga bog'liq) ──
window.syncMiPriceFields = function (changedField) {
  const stockInput = document.getElementById('miStockInput');
  const totalInput = document.getElementById('miTotalPriceInput');
  const unitInput = document.getElementById('miPriceInput');
  if (!stockInput || !totalInput || !unitInput) return;

  const stock = parseFloat(stockInput.value);
  if (!stock || stock <= 0) return;

  if (changedField === 'total') {
    const total = parseFloat(totalInput.value);
    if (!isNaN(total) && total >= 0) unitInput.value = Math.round((total / stock) * 100) / 100;
  } else if (changedField === 'unit') {
    const unit = parseFloat(unitInput.value);
    if (!isNaN(unit) && unit >= 0) totalInput.value = Math.round(unit * stock * 100) / 100;
  } else if (changedField === 'stock') {
    const total = parseFloat(totalInput.value);
    if (!isNaN(total) && total >= 0) {
      unitInput.value = Math.round((total / stock) * 100) / 100;
    } else {
      const unit = parseFloat(unitInput.value);
      if (!isNaN(unit) && unit >= 0) totalInput.value = Math.round(unit * stock * 100) / 100;
    }
  }
};

window.openMenuIngredientModal = function (ingId = null) {
  _miEditId = ingId;
  const modal = document.getElementById("menuIngredientModal");
  const title = document.getElementById("menuIngredientModalTitle");
  const nameInput = document.getElementById("miNameInput");
  const unitSelect = document.getElementById("miUnitSelect");
  const stockInput = document.getElementById("miStockInput");
  const priceInput = document.getElementById("miPriceInput");
  const totalPriceInput = document.getElementById("miTotalPriceInput");
  const datalist = document.getElementById("miNameDatalist");

  const UNITS = window.RECIPE_UNITS || [{ value: "gr", label: () => "gr" }];
  if (unitSelect) {
    unitSelect.innerHTML = UNITS.map(u => `<option value="${u.value}">${typeof u.label === "function" ? u.label() : u.label}</option>`).join("");
  }
  if (datalist) {
    datalist.innerHTML = (window.UZBEK_INGREDIENTS_LIST || []).map(n => `<option value="${escapeHtml(n)}">`).join("");
  }

  if (ingId) {
    const ing = window.allInventory?.[ingId];
    if (title) title.textContent = t("menu_ingredient_edit_title", "Ingredientni tahrirlash");
    if (nameInput) nameInput.value = ing?.name || "";
    if (unitSelect) unitSelect.value = ing?.unit || "gr";
    if (stockInput) stockInput.value = ing?.stock ?? 0;
    if (priceInput) priceInput.value = ing?.price || "";
    const stockVal = parseFloat(ing?.stock || 0);
    const priceVal = parseFloat(ing?.price || 0);
    if (totalPriceInput) totalPriceInput.value = (stockVal > 0 && priceVal > 0) ? Math.round(priceVal * stockVal * 100) / 100 : "";
  } else {
    if (title) title.textContent = t("menu_ingredient_add_title", "Yangi ingredient");
    if (nameInput) nameInput.value = "";
    if (unitSelect) unitSelect.value = "gr";
    if (stockInput) stockInput.value = 0;
    if (priceInput) priceInput.value = "";
    if (totalPriceInput) totalPriceInput.value = "";
  }

  modal?.classList.remove("hidden");
  nameInput?.focus();
};

window.closeMenuIngredientModal = function () {
  document.getElementById("menuIngredientModal")?.classList.add("hidden");
  _miEditId = null;
};

window.saveMenuIngredient = async function () {
  const name = document.getElementById("miNameInput")?.value.trim();
  const unit = document.getElementById("miUnitSelect")?.value || "gr";
  const stock = Number(document.getElementById("miStockInput")?.value) || 0;

  // Ikkala narx maydoni ham to'ldirilishi mumkin — 1 birlik narxi bo'sh bo'lsa,
  // jami summadan (agar bor bo'lsa) hisoblab olamiz.
  let price = Number(document.getElementById("miPriceInput")?.value);
  const totalPrice = Number(document.getElementById("miTotalPriceInput")?.value);
  if ((isNaN(price) || !price) && totalPrice && stock > 0) {
    price = totalPrice / stock;
  }
  if (isNaN(price) || !price) price = 0;

  if (!name) { alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring")); return; }
  if (stock < 0) { alert(t("menu_ing_stock_negative", "Zaxira manfiy bo'lishi mumkin emas")); return; }

  const restId = localStorage.getItem("restaurantId");
  if (!restId) return;

  try {
    let ingId = _miEditId;

    // Yangi qo'shishda: bir xil nomli ingredient allaqachon bor-yo'qligini tekshiramiz
    // (retsept orqali avtomatik yaratilgan bo'lishi mumkin — dublikat yaratmaslik uchun)
    if (!ingId) {
      const existing = Object.entries(window.allInventory || {})
        .find(([, ing]) => String(ing.name || "").trim().toLowerCase() === name.toLowerCase());
      if (existing) ingId = existing[0];
    }

    const data = { name, unit, stock, price, updatedAt: Date.now() };
    if (!ingId) {
      const newRef = push(ref(db, `restaurants/${restId}/inventory`));
      ingId = newRef.key;
      data.createdAt = Date.now();
      data.minStock = 0;
      data.addedFrom = "menu_ingredients_tab";
      await set(newRef, data);
    } else {
      await update(ref(db, `restaurants/${restId}/inventory/${ingId}`), data);
    }
    // ingredients yo'lini ham sinxronlashtiramiz (retsept moduli shu yerdan ham o'qiydi)
    await update(ref(db, `restaurants/${restId}/ingredients/${ingId}`), data);

    if (window.allInventory) window.allInventory[ingId] = { ...(window.allInventory[ingId] || {}), ...data };

    showAdminNotification(t("menu_ingredient_saved", "Ingredient saqlandi ✅"));
    window.closeMenuIngredientModal();
    window.renderMenuIngredientsList();
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

// ────────────────────────────────────────────────────────────
// 🎁 COMBO / SET TAB — bir nechta taomni bitta chegirmali paketga
// birlashtirish. Combo restaurants/{id}/menu/{id} ostida ODDIY taom
// sifatida saqlanadi (isCombo:true, comboItems:[{menuId,qty},...]) —
// shunda buyurtma/kassa/mijoz oqimi uni boshqa taomdan farqlamaydi.
// Sotilganda ombordan ayirish deductStock() ichidagi
// _expandRecipeForMenuId() orqali avtomatik amalga oshiriladi:
// combo tarkibidagi har bir taomning o'z retsepti bo'yicha ayriladi.
// ────────────────────────────────────────────────────────────
let _comboEditId = null;
let _comboItemRowId = 0;

function _comboGetMenuItemName(item) {
  const lang = typeof getLang === "function" ? getLang() : "uz";
  return typeof item?.name === "object"
    ? (item.name?.[lang] || item.name?.uz || item.name?.ru || item.name?.en || "—")
    : (item?.name || "—");
}

window.addComboItemRow = function (selectedMenuId = "", qty = 1) {
  const list = document.getElementById("comboItemsList");
  if (!list) return;
  const rowId = "combo_item_" + (_comboItemRowId++);

  // Combo o'z ichida combo bo'lolmaydi — tanlash ro'yxatidan boshqa combolarni chiqarib tashlaymiz
  const options = Object.entries(window.allMenu || {})
    .filter(([id, m]) => !m.isCombo && id !== _comboEditId)
    .map(([id, m]) => ({ id, name: _comboGetMenuItemName(m) }))
    .sort((a, b) => a.name.localeCompare(b.name, "uz"));

  const optionsHtml = `<option value="">${t("menu_combo_select_item", "— Taom tanlang —")}</option>` +
    options.map(o => `<option value="${o.id}"${o.id === selectedMenuId ? " selected" : ""}>${escapeHtml(o.name)}</option>`).join("");

  const row = document.createElement("div");
  row.className = "combo-item-row";
  row.id = rowId;
  row.style.cssText = "display:flex;gap:8px;align-items:center;";
  row.innerHTML = `
    <select class="combo-item-menu-select" style="flex:2;padding:8px;border:1px solid #cbd5e1;border-radius:6px;font-size:14px;" onchange="window._recalcComboPrice()">
      ${optionsHtml}
    </select>
    <input type="number" class="combo-item-qty-input" value="${qty}" min="1" step="1"
      style="width:70px;padding:8px;border:1px solid #cbd5e1;border-radius:6px;font-size:14px;" oninput="window._recalcComboPrice()">
    <button type="button" onclick="document.getElementById('${rowId}').remove(); window._recalcComboPrice();"
      style="padding:8px 12px;background:#ef4444;color:#fff;border:none;border-radius:6px;cursor:pointer;">✖</button>
  `;
  list.appendChild(row);
  window._recalcComboPrice();
};

// Tarkib narxlari yig'indisini hisoblab, tanlangan chegirma turiga qarab combo narxini chiqaradi
window._recalcComboPrice = function () {
  const rows = document.querySelectorAll("#comboItemsList .combo-item-row");
  let originalPrice = 0;
  rows.forEach(row => {
    const menuId = row.querySelector(".combo-item-menu-select")?.value;
    const qty = Number(row.querySelector(".combo-item-qty-input")?.value) || 0;
    const menuItem = menuId ? window.allMenu?.[menuId] : null;
    if (menuItem) originalPrice += Number(menuItem.price || 0) * qty;
  });

  const origEl = document.getElementById("comboOriginalPriceDisplay");
  if (origEl) origEl.textContent = Math.round(originalPrice).toLocaleString() + " " + t("currency", "so'm");

  const discType = document.querySelector('input[name="comboDiscountType"]:checked')?.value || "percent";
  const discValInput = document.getElementById("comboDiscountValueInput");
  const discVal = Number(discValInput?.value) || 0;

  let finalPrice;
  if (discType === "manual") {
    if (discValInput) discValInput.placeholder = t("menu_combo_manual_price_placeholder", "Combo narxini kiriting");
    finalPrice = discVal;
  } else if (discType === "amount") {
    if (discValInput) discValInput.placeholder = t("menu_combo_discount_amount_placeholder", "Masalan: 20000");
    finalPrice = Math.max(0, originalPrice - discVal);
  } else {
    if (discValInput) discValInput.placeholder = t("menu_combo_discount_value_placeholder", "Masalan: 15");
    finalPrice = Math.max(0, originalPrice - (originalPrice * discVal / 100));
  }

  const finalEl = document.getElementById("comboFinalPriceDisplay");
  if (finalEl) finalEl.textContent = Math.round(finalPrice).toLocaleString() + " " + t("currency", "so'm");
  return { originalPrice, finalPrice };
};

window.openComboModal = function (comboId = null) {
  _comboEditId = comboId;
  const modal = document.getElementById("comboModal");
  const title = document.getElementById("comboModalTitle");
  const nameInput = document.getElementById("comboNameInput");
  const imgInput = document.getElementById("comboImgUrlInput");
  const activeInput = document.getElementById("comboActiveInput");
  const discValInput = document.getElementById("comboDiscountValueInput");
  const itemsList = document.getElementById("comboItemsList");
  if (itemsList) itemsList.innerHTML = "";

  renderCategories(document.getElementById("comboCategorySelect"));

  if (comboId) {
    const combo = window.allMenu?.[comboId];
    const lang = typeof getLang === "function" ? getLang() : "uz";
    if (title) title.textContent = t("menu_combo_edit_title", "Comboni tahrirlash");
    if (nameInput) nameInput.value = combo?.name?.[lang] || combo?.name?.uz || "";
    if (imgInput) imgInput.value = combo?.imgUrl || "";
    if (activeInput) activeInput.checked = combo?.active !== false;

    const catSelect = document.getElementById("comboCategorySelect");
    if (catSelect && combo?.category) catSelect.value = combo.category;

    const comboItems = Array.isArray(combo?.comboItems) ? combo.comboItems : Object.values(combo?.comboItems || {});
    if (comboItems.length) {
      comboItems.forEach(ci => window.addComboItemRow(ci.menuId, ci.qty));
    } else {
      window.addComboItemRow();
    }

    // Chegirma turi va qiymatini saqlangan discountMeta'dan tiklaymiz (bo'lmasa manual sifatida asl narxni ko'rsatamiz)
    const dt = combo?.discountMeta?.type || "manual";
    const radio = document.querySelector(`input[name="comboDiscountType"][value="${dt}"]`);
    if (radio) radio.checked = true;
    if (discValInput) discValInput.value = dt === "manual" ? (combo?.price || 0) : (combo?.discountMeta?.value || 0);
  } else {
    if (title) title.textContent = t("menu_combo_add_title", "Yangi combo");
    if (nameInput) nameInput.value = "";
    if (imgInput) imgInput.value = "";
    if (activeInput) activeInput.checked = true;
    if (discValInput) discValInput.value = 0;
    const percentRadio = document.getElementById("comboDiscountTypePercent");
    if (percentRadio) percentRadio.checked = true;
    window.addComboItemRow();
  }

  window._recalcComboPrice();
  modal?.classList.remove("hidden");
};

window.closeComboModal = function () {
  document.getElementById("comboModal")?.classList.add("hidden");
  _comboEditId = null;
};

window.saveCombo = async function () {
  const nameUz = document.getElementById("comboNameInput")?.value.trim();
  const category = document.getElementById("comboCategorySelect")?.value;
  const imgUrlInput = document.getElementById("comboImgUrlInput")?.value.trim();
  const isActive = document.getElementById("comboActiveInput")?.checked !== false;

  if (!nameUz) { alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring")); return; }

  const rows = document.querySelectorAll("#comboItemsList .combo-item-row");
  const comboItems = [];
  rows.forEach(row => {
    const menuId = row.querySelector(".combo-item-menu-select")?.value;
    const qty = Number(row.querySelector(".combo-item-qty-input")?.value) || 0;
    if (menuId && qty > 0) comboItems.push({ menuId, qty });
  });

  if (!comboItems.length) { alert(t("menu_combo_needs_items", "Kamida bitta taom tanlang")); return; }

  const discType = document.querySelector('input[name="comboDiscountType"]:checked')?.value || "percent";
  const discVal = Number(document.getElementById("comboDiscountValueInput")?.value) || 0;
  const { originalPrice, finalPrice } = window._recalcComboPrice();

  if (finalPrice <= 0) { alert(t("menu_combo_price_invalid", "Combo narxi 0 dan katta bo'lishi kerak")); return; }

  const restId = localStorage.getItem("restaurantId");
  if (!restId) return;

  try {
    const nameRu = await autoTranslate(nameUz, "ru");
    const nameEn = await autoTranslate(nameUz, "en");
    const id = _comboEditId || ("combo_" + Date.now().toString());

    const comboData = {
      name: { uz: nameUz, ru: nameRu, en: nameEn },
      isCombo: true,
      comboItems,
      price: Math.round(finalPrice),
      originalPrice: Math.round(originalPrice),
      discountMeta: { type: discType, value: discVal },
      category: category || "",
      subcategory: "",
      imgUrl: imgUrlInput || "img/no-image.png",
      imgPath: "",
      active: isActive,
      recipe: [], // combo o'z retseptiga ega emas — tarkibi orqali hisoblanadi
      createdAt: window.allMenu?.[id]?.createdAt || Date.now()
    };

    await set(ref(db, `restaurants/${restId}/menu/${id}`), comboData);
    if (window.allMenu) window.allMenu[id] = comboData;

    await crmAdvAudit("menu", _comboEditId ? "update" : "create", id,
      _comboEditId ? t("audit_combo_updated", "Combo yangilandi") : t("audit_combo_created", "Yangi combo qo'shildi"),
      { name: nameUz }, "info");

    showAdminNotification(t("menu_combo_saved", "Combo saqlandi ✅"));
    window.closeComboModal();
    window.renderMenuCombosList();
    if (typeof renderMenu === "function") renderMenu(); // dashboard/stat kartalarni ham yangilash uchun
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.deleteCombo = async function (comboId) {
  if (!confirm(t("confirm_delete_selected", "Ishonchingiz komilmi?"))) return;
  const restId = localStorage.getItem("restaurantId");
  if (!restId) return;
  try {
    await remove(ref(db, `restaurants/${restId}/menu/${comboId}`));
    if (window.allMenu) delete window.allMenu[comboId];
    await crmAdvAudit("menu", "delete", comboId, t("audit_combo_deleted", "Combo o'chirildi"), {}, "warning");
    showAdminNotification(t("notify_deleted_all", "O'chirildi"));
    window.renderMenuCombosList();
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.renderMenuCombosList = function () {
  const tbody = document.getElementById("menuCombosListBody");
  if (!tbody) return;

  const combos = Object.entries(window.allMenu || {}).filter(([, item]) => item.isCombo);

  if (!combos.length) {
    tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;padding:24px;color:var(--text-secondary,#94a3b8);">${t("menu_combo_empty", "Hali combo yo'q. \"Yangi combo\" tugmasi orqali qo'shing.")}</td></tr>`;
    return;
  }

  const lang = typeof getLang === "function" ? getLang() : "uz";
  tbody.innerHTML = combos.map(([id, combo]) => {
    const name = combo.name?.[lang] || combo.name?.uz || "—";
    const comboItems = Array.isArray(combo.comboItems) ? combo.comboItems : Object.values(combo.comboItems || {});
    const contentsText = comboItems.map(ci => {
      const m = window.allMenu?.[ci.menuId];
      const itemName = m ? _comboGetMenuItemName(m) : t("menu_combo_item_deleted", "(o'chirilgan taom)");
      return `${ci.qty}× ${escapeHtml(itemName)}`;
    }).join(", ") || "—";

    const discMeta = combo.discountMeta || {};
    const discText = discMeta.type === "percent" ? `${discMeta.value}%`
      : discMeta.type === "amount" ? `${Number(discMeta.value).toLocaleString()} ${t("currency", "so'm")}`
      : t("menu_combo_manual_price", "Qo'lda narx");

    const isActive = combo.active !== false;
    const statusCell = `<span style="display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 14px;font-size:12px;font-weight:700;background:${isActive ? "#dcfce7" : "#fee2e2"};color:${isActive ? "#15803d" : "#dc2626"};">
        <span style="width:7px;height:7px;border-radius:50%;background:${isActive ? "#22c55e" : "#ef4444"};flex-shrink:0;"></span>
        ${isActive ? t("status_active", "Faol") : t("status_inactive", "Nofaol")}
      </span>`;

    return `<tr class="combo-row" style="border-bottom:1px solid var(--border-color,#e2e8f0);">
        <td style="padding:12px 14px;font-weight:600;color:var(--text-primary,#1e293b);">${escapeHtml(name)}</td>
        <td style="padding:12px 14px;font-size:13px;color:var(--text-secondary,#64748b);max-width:260px;">${contentsText}</td>
        <td style="padding:12px 14px;text-align:right;color:#94a3b8;text-decoration:line-through;">${Number(combo.originalPrice || 0).toLocaleString()}</td>
        <td style="padding:12px 14px;text-align:center;color:#d97706;font-weight:600;">${discText}</td>
        <td style="padding:12px 14px;text-align:right;font-weight:700;color:#16a34a;">${Number(combo.price || 0).toLocaleString()} ${t("currency", "so'm")}</td>
        <td style="padding:12px 14px;text-align:center;">${statusCell}</td>
        <td style="padding:12px 14px;text-align:center;white-space:nowrap;">
          <button onclick="window.openComboModal('${id}')" title="${t("edit_btn", "Tahrirlash")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#f59e0b;">✏️</button>
          <button onclick="window.deleteCombo('${id}')" title="${t("delete_btn", "O'chirish")}" style="background:none;border:none;cursor:pointer;font-size:15px;padding:4px 6px;color:#dc2626;">🗑</button>
        </td>
      </tr>`;
  }).join("");
};

// ────────────────────────────────────────────────────────────
// 🧀 QO'SHIMCHALAR TAB — qo'shimcha to'lovli ingredientlar,
//    restaurants/{restId}/extras ostida saqlanadi
// ────────────────────────────────────────────────────────────
window.allExtras = window.allExtras || {};
let _extraEditId = null;

function listenToExtras() {
  onValue(ref(db, BASE_PATH + "/extras"), snap => {
    window.allExtras = snap.val() || {};
    if (_menuActiveTab === "qoshimchalar") renderExtrasList();
  });
}

function renderExtrasList() {
  const wrap = document.getElementById("extrasListWrap");
  if (!wrap) return;
  const lang = getLang();
  let items = Object.entries(window.allExtras || {}).map(([id, e]) => ({ id, ...e }));

  if (extraSearchQuery) {
    items = items.filter(ex => {
      const nm = ex.name?.[lang] || ex.name?.uz || "";
      return nm.toLowerCase().includes(extraSearchQuery.toLowerCase());
    });
  }

  wrap.innerHTML = items.length ? items.map(ex => {
    const name = ex.name?.[lang] || ex.name?.uz || uiEmpty();
    const isActive = ex.active !== false;

    const statusCell = `<span style="display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 14px;font-size:12px;font-weight:700;background:${isActive ? "#dcfce7" : "#fee2e2"};color:${isActive ? "#15803d" : "#dc2626"};">
          <span style="width:7px;height:7px;border-radius:50%;background:${isActive ? "#22c55e" : "#ef4444"};flex-shrink:0;"></span>
          ${isActive ? t("status_active", "Faol") : t("status_inactive", "Nofaol")}
        </span>`;

    const editBtn = `<button onclick="window.openExtraModal('${ex.id}')" title="${t("edit_btn", "Tahrirlash")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-warning-bg);color:#ca8a04;cursor:pointer;font-size:13px;"><i class="fa-solid fa-pen"></i></button>`;
    const deleteBtn = `<button onclick="window.deleteExtra('${ex.id}')" title="${t("delete_btn", "O'chirish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-danger-bg);color:#e11d48;cursor:pointer;font-size:13px;"><i class="fa-solid fa-trash"></i></button>`;

    return `<tr class="extra-row" style="border-bottom:1px solid var(--border-color,#e2e8f0);" onmouseenter="this.style.background='var(--bg-body,#f8fafc)'" onmouseleave="this.style.background=''">
        <td style="padding:12px 14px;font-weight:600;color:var(--text-primary,#1e293b);font-size:14px;overflow:hidden;text-overflow:ellipsis;">${ex.icon ? `<span style="margin-right:6px;">${ex.icon}</span>` : ""}${escapeHtml(name)}</td>
        <td style="padding:12px 14px;text-align:center;color:var(--text-primary,#1e293b);">+${(Number(ex.price) || 0).toLocaleString()} ${t("currency")}</td>
        <td style="padding:12px 14px;text-align:center;">${statusCell}</td>
        <td style="padding:12px 14px;text-align:center;white-space:nowrap;"><div style="display:inline-flex;align-items:center;gap:4px;justify-content:center;">${editBtn}${deleteBtn}</div></td>
      </tr>`;
  }).join("") : `<tr><td colspan="4" style="text-align:center;padding:32px;color:var(--text-secondary,#94a3b8);">
    <i class="fa-solid fa-folder-open" style="font-size:28px;margin-bottom:8px;display:block;opacity:.4;"></i>
    ${t("mx_no_extras", "Hali qo'shimcha yo'q")}
  </td></tr>`;
}

const EXTRA_ICON_CHOICES = ["🧀", "🥓", "🍅", "🥚", "🌶️", "🥑", "🍄", "🧅", "🥒", "🍋", "🧂", "🍯", "🥩", "🍗", "🫒"];

window.openExtraIconPicker = function () {
  const current = document.getElementById("extraIconInput")?.value || "";
  const optionsHtml = EXTRA_ICON_CHOICES.map(ic =>
    `<button type="button" onclick="window.selectExtraIcon('${ic}')" style="font-size:22px;width:44px;height:44px;border-radius:10px;border:2px solid ${ic === current ? "var(--primary,#22c55e)" : "var(--border-color,#e2e8f0)"};background:var(--bg-body,#f8fafc);cursor:pointer;">${ic}</button>`
  ).join("");

  let picker = document.getElementById("extraIconPickerModal");
  if (!picker) {
    picker = document.createElement("div");
    picker.id = "extraIconPickerModal";
    picker.className = "modal";
    picker.style.zIndex = "10000";
    document.body.appendChild(picker);
  }
  picker.classList.remove("hidden");
  picker.innerHTML = `
    <div class="modal-content" style="max-width:340px;">
      <h3 data-i18n="choose_icon_title">Ikonka tanlash</h3>
      <div style="display:flex;flex-wrap:wrap;gap:8px;margin:12px 0;">${optionsHtml}</div>
      <div class="modal-actions">
        <button class="btn" onclick="document.getElementById('extraIconPickerModal').classList.add('hidden')" data-i18n="cancel_btn">Bekor qilish</button>
      </div>
    </div>`;
};

window.selectExtraIcon = function (icon) {
  const input = document.getElementById("extraIconInput");
  const preview = document.getElementById("extraIconPreview");
  if (input) input.value = icon;
  if (preview) preview.textContent = icon;
  document.getElementById("extraIconPickerModal")?.classList.add("hidden");
};

window.openExtraModal = function (exId = null) {
  _extraEditId = exId;
  const nameInput = document.getElementById("extraNameInput");
  const priceInput = document.getElementById("extraPriceInput");
  const iconInput = document.getElementById("extraIconInput");
  const iconPreview = document.getElementById("extraIconPreview");
  const activeInput = document.getElementById("extraActiveInput");

  if (exId) {
    const ex = window.allExtras[exId];
    if (ex) {
      const lang = getLang();
      if (nameInput) nameInput.value = ex.name?.[lang] || ex.name?.uz || "";
      if (priceInput) priceInput.value = ex.price || "";
      if (iconInput) iconInput.value = ex.icon || "";
      if (iconPreview) iconPreview.textContent = ex.icon || "🧀";
      if (activeInput) activeInput.checked = ex.active !== false;
    }
  } else {
    if (nameInput) nameInput.value = "";
    if (priceInput) priceInput.value = "";
    if (iconInput) iconInput.value = "";
    if (iconPreview) iconPreview.textContent = "🧀";
    if (activeInput) activeInput.checked = true;
  }

  document.getElementById("extraModal")?.classList.remove("hidden");
};

window.closeExtraModal = function () {
  document.getElementById("extraModal")?.classList.add("hidden");
  _extraEditId = null;
};

window.saveExtra = async function () {
  const nameUz = document.getElementById("extraNameInput")?.value.trim();
  const price = Number(document.getElementById("extraPriceInput")?.value) || 0;
  const icon = document.getElementById("extraIconInput")?.value || "";
  const active = document.getElementById("extraActiveInput")?.checked !== false;
  if (!nameUz) { alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring")); return; }

  try {
    const nameRu = await autoTranslate(nameUz, "ru");
    const nameEn = await autoTranslate(nameUz, "en");
    const id = _extraEditId || ("extra_" + Date.now().toString());

    await set(ref(db, BASE_PATH + "/extras/" + id), {
      id,
      name: { uz: nameUz, ru: nameRu, en: nameEn },
      price,
      icon,
      active,
      createdAt: window.allExtras[id]?.createdAt || Date.now()
    });

    await crmAdvAudit("menu", _extraEditId ? "update" : "create", id,
      _extraEditId ? t("audit_extra_updated", "Qo'shimcha yangilandi") : t("audit_extra_created", "Yangi qo'shimcha qo'shildi"),
      { name: nameUz, price }, "info");

    window.closeExtraModal();
    showAdminNotification(t("notify.extra_saved", "Qo'shimcha saqlandi ✅"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.deleteExtra = async function (exId) {
  if (!confirm(t("confirm_delete_selected", "Ishonchingiz komilmi?"))) return;
  try {
    await remove(ref(db, BASE_PATH + "/extras/" + exId));
    await crmAdvAudit("menu", "delete", exId, t("audit_extra_deleted", "Qo'shimcha o'chirildi"), {}, "warning");
    showAdminNotification(t("notify_deleted_all", "O'chirildi"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

// ────────────────────────────────────────────────────────────
// 🎯 AKSIYALAR TAB — promokod/chegirmalar. Mavjud
//    restaurants/{restId}/discounts manzilini qayta ishlatadi
//    (checkAndShowPromo / applyPromoCode shu yerdan o'qiydi)
// ────────────────────────────────────────────────────────────
window.allPromos = window.allPromos || {};
let _promoEditCode = null;

function listenToPromos() {
  onValue(ref(db, BASE_PATH + "/discounts"), snap => {
    window.allPromos = snap.val() || {};
    if (_menuActiveTab === "aksiyalar") renderPromosList();
  });
}

function formatDiscountLabel(p) {
  if (p.discountType === "amount" || (p.amount && !p.percent)) {
    return `${(Number(p.amount) || 0).toLocaleString()} ${t("currency")}`;
  }
  return `${Number(p.percent) || 0}%`;
}

function renderPromosList() {
  const wrap = document.getElementById("promosListWrap");
  if (!wrap) return;
  const items = Object.entries(window.allPromos || {}).map(([code, p]) => ({ code, ...p }));

  wrap.innerHTML = items.length ? `
    <div class="mx-crud-table-wrap">
      <table class="mx-crud-table">
        <thead>
          <tr>
            <th data-i18n="promo_col_code">Kod</th>
            <th data-i18n="promo_col_discount">Chegirma</th>
            <th data-i18n="promo_col_used">Ishlatilgan</th>
            <th data-i18n="promo_col_limit">Limit</th>
            <th data-i18n="promo_col_end_date">Tugash sanasi</th>
            <th data-i18n="promo_col_status">Holat</th>
            <th data-i18n="promo_col_actions">Amallar</th>
          </tr>
        </thead>
        <tbody>
          ${items.map(p => {
            const used = Number(p.usedCount) || 0;
            const max = Number(p.maxUses) || 0;
            const isActive = p.active !== false;
            const endDate = formatPromoDate(p.endDate) || "—";

            const statusCell = `<span style="display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 14px;font-size:12px;font-weight:700;background:${isActive ? "#dcfce7" : "#fee2e2"};color:${isActive ? "#15803d" : "#dc2626"};">
                  <span style="width:7px;height:7px;border-radius:50%;background:${isActive ? "#22c55e" : "#ef4444"};flex-shrink:0;"></span>
                  ${isActive ? t("status_active", "Faol") : t("status_inactive", "Nofaol")}
                </span>`;

            const viewBtn = `<button onclick="window.viewPromoDetails('${p.code}')" title="${t("view_btn", "Ko'rish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-info-bg);color:#2563eb;cursor:pointer;font-size:13px;"><i class="fa-solid fa-eye"></i></button>`;
            const editBtn = `<button onclick="window.togglePromoActive('${p.code}', ${isActive})" title="${isActive ? t("mx_deactivate", "To'xtatish") : t("mx_activate", "Faollashtirish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-warning-bg);color:#ca8a04;cursor:pointer;font-size:13px;"><i class="fa-solid ${isActive ? "fa-pause" : "fa-play"}"></i></button>`;
            const deleteBtn = `<button onclick="window.deletePromo('${p.code}')" title="${t("delete_btn", "O'chirish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-danger-bg);color:#e11d48;cursor:pointer;font-size:13px;"><i class="fa-solid fa-trash"></i></button>`;

            return `<tr style="border-bottom:1px solid var(--border-color,#e2e8f0);" onmouseenter="this.style.background='var(--bg-body,#f8fafc)'" onmouseleave="this.style.background=''">
                <td style="padding:12px 14px;"><span class="mx-promo-code-chip">${escapeHtml(p.code)}</span></td>
                <td style="padding:12px 14px;text-align:center;font-weight:600;color:var(--text-primary,#1e293b);">${formatDiscountLabel(p)}</td>
                <td style="padding:12px 14px;text-align:center;color:var(--text-primary,#1e293b);">${used}</td>
                <td style="padding:12px 14px;text-align:center;color:var(--text-primary,#1e293b);">${max || "∞"}</td>
                <td style="padding:12px 14px;text-align:center;color:var(--text-secondary,#64748b);white-space:nowrap;">${endDate}</td>
                <td style="padding:12px 14px;text-align:center;">${statusCell}</td>
                <td style="padding:12px 14px;text-align:center;white-space:nowrap;"><div style="display:inline-flex;align-items:center;gap:4px;justify-content:center;">${viewBtn}${editBtn}${deleteBtn}</div></td>
              </tr>`;
          }).join("")}
        </tbody>
      </table>
    </div>` : `<div class="mx-crud-empty">🎟️ ${t("mx_no_promos", "Hali promokod yo'q")}</div>`;
}

window.viewPromoDetails = function (code) {
  const p = window.allPromos?.[code];
  if (!p) return;
  const used = Number(p.usedCount) || 0;
  const max = Number(p.maxUses) || 0;
  const minOrder = Number(p.minOrder) || 0;
  const lines = [
    `${t("promo_code_label", "Promokod")}: ${p.code}`,
    `${t("promo_col_discount", "Chegirma")}: ${formatDiscountLabel(p)}`,
    `${t("mx_uses_label", "Ishlatilgan")}: ${used}/${max || "∞"}`,
    minOrder ? `${t("promo_min_order_label", "Minimal buyurtma")}: ${minOrder.toLocaleString()} ${t("currency")}` : null,
    (p.startDate || p.endDate) ? `${t("promo_period_label", "Muddat")}: ${formatPromoDate(p.startDate) || "…"} – ${formatPromoDate(p.endDate) || "…"}` : null,
    `${t("promo_col_status", "Holat")}: ${p.active === false ? t("status_inactive", "Nofaol") : t("status_active", "Faol")}`
  ].filter(Boolean);
  alert(lines.join("\n"));
};


window.onPromoCodeTypeChange = function () {
  const isAmount = document.getElementById("promoTypeAmount")?.checked;
  const percentInput = document.getElementById("promoPercentInput");
  if (!percentInput) return;
  if (isAmount) {
    percentInput.removeAttribute("max");
  } else {
    percentInput.setAttribute("max", "100");
  }
};

window.openPromoModal = function () {
  document.getElementById("promoCodeInput").value = "";
  document.getElementById("promoPercentInput").value = "";
  document.getElementById("promoMaxUsesInput").value = "";
  document.getElementById("promoMinOrderInput").value = "";
  document.getElementById("promoStartDateInput").value = "";
  document.getElementById("promoEndDateInput").value = "";
  const percentRadio = document.getElementById("promoTypePercent");
  if (percentRadio) percentRadio.checked = true;
  const activeInput = document.getElementById("promoActiveInput");
  if (activeInput) activeInput.checked = true;
  window.onPromoCodeTypeChange();
  document.getElementById("promoModal")?.classList.remove("hidden");
};

window.closePromoModal = function () {
  document.getElementById("promoModal")?.classList.add("hidden");
};

window.savePromo = async function () {
  const code = document.getElementById("promoCodeInput")?.value.trim().toUpperCase();
  const discountType = document.getElementById("promoTypeAmount")?.checked ? "amount" : "percent";
  const value = Number(document.getElementById("promoPercentInput")?.value);
  const maxUses = Number(document.getElementById("promoMaxUsesInput")?.value) || 0;
  const minOrder = Number(document.getElementById("promoMinOrderInput")?.value) || 0;
  const startDate = document.getElementById("promoStartDateInput")?.value || "";
  const endDate = document.getElementById("promoEndDateInput")?.value || "";
  const active = document.getElementById("promoActiveInput")?.checked !== false;

  if (!code || !value || (discountType === "percent" && (value < 1 || value > 100))) {
    alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring"));
    return;
  }

  try {
    await set(ref(db, BASE_PATH + "/discounts/" + code), {
      code,
      discountType,
      percent: discountType === "percent" ? value : null,
      amount: discountType === "amount" ? value : null,
      maxUses,
      minOrder,
      startDate,
      endDate,
      usedCount: window.allPromos[code]?.usedCount || 0,
      active,
      createdAt: window.allPromos[code]?.createdAt || Date.now()
    });

    await crmAdvAudit("menu", "create", code, t("audit_promo_created", "Yangi promokod qo'shildi"), { code, value }, "info");

    window.closePromoModal();
    showAdminNotification(t("notify.promo_saved", "Promokod saqlandi ✅"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.togglePromoActive = async function (code, makeActive) {
  // Optimistik yangilash — Firebase javobini kutmasdan darhol
  // lokal holatni va tugma ikonkasini almashtiramiz, shu bilan
  // pause/play holati kechikmasdan ko'rinadi.
  if (window.allPromos[code]) {
    window.allPromos[code].active = makeActive;
  }
  renderPromosList();

  try {
    await update(ref(db, BASE_PATH + "/discounts/" + code), { active: makeActive });
    await crmAdvAudit("menu", "update", code,
      makeActive ? t("audit_promo_activated", "Promokod faollashtirildi") : t("audit_promo_deactivated", "Promokod to'xtatildi"),
      { code }, "info");
    showAdminNotification(makeActive
      ? t("notify.promo_activated", "Promokod faollashtirildi ✅")
      : t("notify.promo_deactivated", "Promokod to'xtatildi ⏸️"));
  } catch (err) {
    console.error(err);
    // Xatolik bo'lsa lokal holatni qaytaramiz
    if (window.allPromos[code]) {
      window.allPromos[code].active = !makeActive;
    }
    renderPromosList();
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.deletePromo = async function (code) {
  if (!confirm(t("confirm_delete_selected", "Ishonchingiz komilmi?"))) return;
  try {
    await remove(ref(db, BASE_PATH + "/discounts/" + code));
    await crmAdvAudit("menu", "delete", code, t("audit_promo_deleted", "Aksiya o'chirildi"), {}, "warning");
    showAdminNotification(t("notify_deleted_all", "O'chirildi"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

// ────────────────────────────────────────────────────────────
// 🎯 YANGI AKSIYALAR TIZIMI — target-asosli aksiyalar
//    (taom / kategoriya / butun restoran bo'yicha chegirma)
//    restaurants/{restId}/promotions manzilida saqlanadi.
//    Eski promokod tizimi (discounts) alohida ishlaydi.
// ────────────────────────────────────────────────────────────
window.allPromotions = window.allPromotions || {};
let _promotionEditId = null;
let promotionSearchQuery = "";

function listenToPromotions() {
  onValue(ref(db, BASE_PATH + "/promotions"), snap => {
    window.allPromotions = snap.val() || {};
    if (_menuActiveTab === "aksiyalar") renderPromotionsList();
  });
}

window.onPromotionSearch = function (val) {
  promotionSearchQuery = val || "";
  renderPromotionsList();
};

function formatPromoDate(dateStr) {
  if (!dateStr) return "";
  const parts = dateStr.split("-");
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
}

function getPromotionScopeLabel(promo) {
  const lang = getLang();
  if (promo.scope === "all") return t("promo_scope_all", "Butun restoran");
  if (promo.scope === "category") {
    const cat = findCategoryById(promo.targetId);
    return cat ? cat.label : (t("promo_scope_category", "Kategoriya"));
  }
  if (promo.scope === "item") {
    const item = window.allMenu?.[promo.targetId];
    const name = item ? (getItemDisplayName ? getItemDisplayName(item.name, promo.targetId) : (item.name?.[lang] || item.name?.uz)) : null;
    return name || t("promo_scope_item", "Taom");
  }
  return "";
}

function renderPromotionsList() {
  const wrap = document.getElementById("promotionsListWrap");
  if (!wrap) return;
  let items = Object.entries(window.allPromotions || {}).map(([id, p]) => ({ id, ...p }));

  if (promotionSearchQuery) {
    items = items.filter(p => (p.name || "").toLowerCase().includes(promotionSearchQuery.toLowerCase()));
  }

  wrap.innerHTML = items.length ? `<div class="promotion-cards-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px;">${items.map(p => {
    const isActive = p.active !== false;
    const discountLabel = p.discountType === "amount"
      ? `-${(Number(p.value) || 0).toLocaleString()} ${t("currency")}`
      : `-${Number(p.value) || 0}%`;
    const period = (p.startDate || p.endDate)
      ? `${formatPromoDate(p.startDate) || "…"} → ${formatPromoDate(p.endDate) || "…"}`
      : "—";

    const statusCell = `<span style="display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 14px;font-size:12px;font-weight:700;background:${isActive ? "#dcfce7" : "#fee2e2"};color:${isActive ? "#15803d" : "#dc2626"};">
          <span style="width:7px;height:7px;border-radius:50%;background:${isActive ? "#22c55e" : "#ef4444"};flex-shrink:0;"></span>
          ${isActive ? t("status_active", "Faol") : t("status_inactive", "Nofaol")}
        </span>`;

    const editBtn = `<button onclick="window.openPromotionModal('${p.id}')" title="${t("edit_btn", "Tahrirlash")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-warning-bg);color:#ca8a04;cursor:pointer;font-size:13px;"><i class="fa-solid fa-pen"></i></button>`;
    const deleteBtn = `<button onclick="window.deletePromotion('${p.id}')" title="${t("delete_btn", "O'chirish")}" style="display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;border:none;background:var(--admin-danger-bg);color:#e11d48;cursor:pointer;font-size:13px;"><i class="fa-solid fa-trash"></i></button>`;

    return `<div class="promotion-card" style="background:var(--bg-card,#fff);border:1px solid var(--border-color,#e2e8f0);border-radius:16px;padding:18px;display:flex;flex-direction:column;gap:8px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
          <div style="font-weight:700;font-size:15px;color:var(--text-primary,#1e293b);display:flex;align-items:center;gap:6px;">🔥 ${escapeHtml(p.name || "")}</div>
          <div style="display:flex;gap:4px;">${editBtn}${deleteBtn}</div>
        </div>
        <div style="font-size:26px;font-weight:800;color:#dc2626;line-height:1;">${discountLabel}</div>
        <div style="font-size:13px;color:var(--text-secondary,#64748b);">${escapeHtml(getPromotionScopeLabel(p))}</div>
        <div style="font-size:12px;color:var(--text-secondary,#94a3b8);white-space:nowrap;">${period}</div>
        <div style="margin-top:4px;">${statusCell}</div>
      </div>`;
  }).join("")}</div>` : `<div style="text-align:center;padding:32px;color:var(--text-secondary,#94a3b8);">
    <i class="fa-solid fa-bullseye" style="font-size:28px;margin-bottom:8px;display:block;opacity:.4;"></i>
    ${t("mx_no_promotions", "Hali aksiya yo'q")}
  </div>`;
}

window.onPromotionTypeChange = function () {
  const isAmount = document.getElementById("promotionTypeAmount")?.checked;
  const valueInput = document.getElementById("promotionValueInput");
  if (!valueInput) return;
  if (isAmount) {
    valueInput.removeAttribute("max");
  } else {
    valueInput.setAttribute("max", "100");
  }
};

window.onPromotionScopeChange = function () {
  const scope = document.getElementById("promotionScopeSelect")?.value;
  const wrap = document.getElementById("promotionTargetWrap");
  const select = document.getElementById("promotionTargetSelect");
  if (!wrap || !select) return;

  if (scope === "all") {
    wrap.style.display = "none";
    return;
  }
  wrap.style.display = "block";

  const lang = getLang();
  if (scope === "category") {
    select.innerHTML = getAllCategories().map(cat =>
      `<option value="${cat.id}">${cat.isCustom ? "⭐ " : ""}${escapeHtml(cat.label)}</option>`
    ).join("");
  } else {
    select.innerHTML = Object.entries(window.allMenu || {}).map(([id, item]) => {
      const name = getItemDisplayName ? getItemDisplayName(item.name, id) : (item.name?.[lang] || item.name?.uz || id);
      return `<option value="${id}">${escapeHtml(name)}</option>`;
    }).join("");
  }
};

window.openPromotionModal = function (promoId = null) {
  _promotionEditId = promoId;
  const nameInput = document.getElementById("promotionNameInput");
  const valueInput = document.getElementById("promotionValueInput");
  const scopeSelect = document.getElementById("promotionScopeSelect");
  const startInput = document.getElementById("promotionStartDateInput");
  const endInput = document.getElementById("promotionEndDateInput");
  const activeInput = document.getElementById("promotionActiveInput");
  const percentRadio = document.getElementById("promotionTypePercent");
  const amountRadio = document.getElementById("promotionTypeAmount");

  if (promoId) {
    const p = window.allPromotions[promoId];
    if (p) {
      if (nameInput) nameInput.value = p.name || "";
      if (valueInput) valueInput.value = p.value ?? "";
      if (scopeSelect) scopeSelect.value = p.scope || "item";
      if (startInput) startInput.value = p.startDate || "";
      if (endInput) endInput.value = p.endDate || "";
      if (activeInput) activeInput.checked = p.active !== false;
      if (percentRadio && amountRadio) {
        if (p.discountType === "amount") { amountRadio.checked = true; } else { percentRadio.checked = true; }
      }
      window.onPromotionTypeChange();
      window.onPromotionScopeChange();
      const targetSelect = document.getElementById("promotionTargetSelect");
      if (targetSelect && p.targetId) targetSelect.value = p.targetId;
    }
  } else {
    if (nameInput) nameInput.value = "";
    if (valueInput) valueInput.value = "";
    if (scopeSelect) scopeSelect.value = "item";
    if (startInput) startInput.value = "";
    if (endInput) endInput.value = "";
    if (activeInput) activeInput.checked = true;
    if (percentRadio) percentRadio.checked = true;
    window.onPromotionTypeChange();
    window.onPromotionScopeChange();
  }

  document.getElementById("promotionModal")?.classList.remove("hidden");
};

window.closePromotionModal = function () {
  document.getElementById("promotionModal")?.classList.add("hidden");
  _promotionEditId = null;
};

window.savePromotion = async function () {
  const name = document.getElementById("promotionNameInput")?.value.trim();
  const discountType = document.getElementById("promotionTypeAmount")?.checked ? "amount" : "percent";
  const value = Number(document.getElementById("promotionValueInput")?.value) || 0;
  const scope = document.getElementById("promotionScopeSelect")?.value || "item";
  const targetId = scope === "all" ? null : (document.getElementById("promotionTargetSelect")?.value || null);
  const startDate = document.getElementById("promotionStartDateInput")?.value || "";
  const endDate = document.getElementById("promotionEndDateInput")?.value || "";
  const active = document.getElementById("promotionActiveInput")?.checked !== false;

  if (!name || !value || (discountType === "percent" && (value < 1 || value > 100))) {
    alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring"));
    return;
  }
  if (scope !== "all" && !targetId) {
    alert(t("alerts.fill_all", "Barcha maydonlarni to'ldiring"));
    return;
  }

  try {
    const id = _promotionEditId || ("promo_" + Date.now().toString());
    await set(ref(db, BASE_PATH + "/promotions/" + id), {
      id,
      name,
      discountType,
      value,
      scope,
      targetId,
      startDate,
      endDate,
      active,
      createdAt: window.allPromotions[id]?.createdAt || Date.now()
    });

    await crmAdvAudit("menu", _promotionEditId ? "update" : "create", id,
      _promotionEditId ? t("audit_promotion_updated", "Aksiya yangilandi") : t("audit_promotion_created", "Yangi aksiya qo'shildi"),
      { name, value, scope }, "info");

    window.closePromotionModal();
    showAdminNotification(t("notify.promotion_saved", "Aksiya saqlandi ✅"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

window.deletePromotion = async function (promoId) {
  if (!confirm(t("confirm_delete_selected", "Ishonchingiz komilmi?"))) return;
  try {
    await remove(ref(db, BASE_PATH + "/promotions/" + promoId));
    await crmAdvAudit("menu", "delete", promoId, t("audit_promotion_deleted", "Aksiya o'chirildi"), {}, "warning");
    showAdminNotification(t("notify_deleted_all", "O'chirildi"));
  } catch (err) {
    console.error(err);
    alert(t("notify.error", "Xatolik yuz berdi"));
  }
};

// Modifierlar / Qo'shimchalar / Aksiyalar uchun real-time listenerlarni
// bir marta ishga tushiramiz (renderMenu chaqirilganda emas, sahifa
// yuklanganda — chunki boshqa joylarda ham (masalan buyurtma formasida)
// bu ma'lumotlar kerak bo'lishi mumkin)
if (!window._mxTabListenersStarted) {
  listenToModifiers();
  listenToExtras();
  listenToPromos();
  listenToPromotions();
  window._mxTabListenersStarted = true;
}

window.deleteSelectedMenus = async function () {
  // 🩹 Audit fix: RBAC tekshiruvi yo'q edi.
  if (typeof window.canDelete === "function" && !window.canDelete("menu")) {
    return showAdminNotification(t("rbac_no_permission", "Sizda bu amal uchun ruxsat yo'q"), "error");
  }
  const checks = document.querySelectorAll(".menu-check:checked");
  if (!checks.length) { alert(t("confirm_select_first")); return; }
  if (!confirm(t("confirm_delete_selected"))) return;
  for (const ch of checks) {
    const snap = await get(ref(db, BASE_PATH + "/menu/" + ch.value));
    if (snap.exists() && snap.val().imgPath) {
      await deleteObject(storageRef(storage, snap.val().imgPath)).catch(() => { });
    }
    await remove(ref(db, BASE_PATH + "/menu/" + ch.value));
  }
  showAdminNotification(t("notify_deleted_selected"));
};

window.deleteAllMenus = async function () {
  // 🩹 Audit fix: RBAC tekshiruvi yo'q edi.
  if (typeof window.canDelete === "function" && !window.canDelete("menu")) {
    return showAdminNotification(t("rbac_no_permission", "Sizda bu amal uchun ruxsat yo'q"), "error");
  }
  if (!confirm(t("confirm_delete_all_1"))) return;
  if (!confirm(t("confirm_delete_all_2"))) return;
  const snap = await get(ref(db, BASE_PATH + "/menu"));
  if (!snap.exists()) return;
  const data = snap.val();
  for (const id in data) {
    if (data[id].imgPath) await deleteObject(storageRef(storage, data[id].imgPath)).catch(() => { });
  }
  await remove(ref(db, BASE_PATH + "/menu"));
  showAdminNotification(t("notify_deleted_all"), "error");
};

function listenMenu() {
  if (window._menuListenerStarted) return;
  window._menuListenerStarted = true;
  onValue(ref(db, BASE_PATH + "/menu"), snap => {
    window.allMenu = snap.val() || {};
    renderMenu();
  });
}

window.toggleMenu = async function (id, active) {
  await update(ref(db, BASE_PATH + "/menu/" + id), { active });
};

document.getElementById("menuSearch")?.addEventListener("input", e => {
  searchQuery = e.target.value.toLowerCase();
  renderMenu();
});

document.addEventListener("click", e => {
  if (e.target.classList.contains("edit-btn")) editMenu(e.target.dataset.id);
  if (e.target.classList.contains("delete-btn")) deleteMenu(e.target.dataset.id);
  if (e.target.classList.contains("view-btn")) window.openMenuViewModal(e.target.dataset.id);
  if (e.target.classList.contains("duplicate-btn")) window.duplicateMenu(e.target.dataset.id);

  if (e.target.classList.contains("recipe-btn")) {
    const id = e.target.dataset.id;
    const name = e.target.dataset.name;
    window.openRecipeModal(id, name);
  }

  if (e.target.classList.contains("menu-status-toggle")) {
    const id = e.target.dataset.id;
    const currentlyActive = e.target.dataset.active === "true";
    window.toggleMenu(id, !currentlyActive);
  }
});

window.duplicateMenu = async function (id) {
  const snap = await get(ref(db, BASE_PATH + "/menu/" + id));
  if (!snap.exists()) return alert(t("alerts.not_found"));
  const item = snap.val();
  const copy = { ...item, createdAt: Date.now() };
  if (copy.name) {
    copy.name = {
      uz: (copy.name.uz || "") + " (nusxa)",
      ru: (copy.name.ru || "") + " (копия)",
      en: (copy.name.en || "") + " (copy)"
    };
  }
  const newRef = push(ref(db, BASE_PATH + "/menu"));
  await set(newRef, copy);
  showAdminNotification(t("notify_duplicated", "Nusxa yaratildi"));
};

let cashierListenerBound = false;

function ensureCashierListener() {
  if (cashierListenerBound) return;
  cashierListenerBound = true;
  listenCashier();
}

function listenCashier() {
  const restId = localStorage.getItem("restaurantId");

  // Cashier orders ro'yxatini qayta render qiluvchi funksiya
  function renderCashierOrders(orders) {
    const list = document.getElementById("cashierList");
    if (!list) return;

    const svcPct = Number(window._cashierServiceFee || 0);
    const svcMinOrder = Number(window._cashierServiceFeeMinOrder || 0);
    let htmlContent = "";

    Object.entries(orders)
      .filter(([_, o]) => o.payment?.requested && !o.payment?.paid)
      .sort((a, b) => {
        const ta = a[1].payment?.requestedAt || a[1].updatedAt || a[1].createdAt || 0;
        const tb = b[1].payment?.requestedAt || b[1].updatedAt || b[1].createdAt || 0;
        return tb - ta;
      })
      .forEach(([id, o]) => {
        const baseTotal = Number(o.total || 0);
        // Обслуга faqat svcMinOrder dan oshganda qo'shiladi (0 bo'lsa — doim qo'shiladi)
        const applyService = svcPct > 0 && (svcMinOrder === 0 || baseTotal >= svcMinOrder);
        const svcAmount = applyService ? Math.round(baseTotal * svcPct / 100) : 0;
        // Agar allaqachon finalTotal yozilgan bo'lsa — uni ishlatamiz, aks holda hisob
        const grandTotal = Number(o.finalTotal || (baseTotal + svcAmount));
        const cur = t("currency");

        const svcRow = applyService ? `
          <div style="display:flex; justify-content:space-between; font-size:13px;
               padding:6px 0; border-top:1px dashed var(--border); color:#92400e;">
            <span>🧾 ${t("obsluga_title") || "Обслуга"} (${svcPct}%)</span>
            <b>+${svcAmount.toLocaleString()} ${cur}</b>
          </div>` : "";

        const totalRow = applyService ? `
          <div style="display:flex; justify-content:space-between; font-size:15px;
               font-weight:800; padding:8px 0; border-top:2px solid var(--border); margin-top:2px;
               color:#15803d;">
            <span>${t("grand_total") || "Jami to'lov"}</span>
            <span>${grandTotal.toLocaleString()} ${cur}</span>
          </div>` : "";

        // Chek tepasidagi logo va telefon
        const receiptLogoUrl = window._cashierLogoUrl || "";
        const receiptPhone = window._cashierContactPhone || "";
        const receiptRestName = window._cashierRestName || "";

        const receiptHeaderHtml = (receiptLogoUrl || receiptPhone || receiptRestName) ? `
          <div style="text-align:center; padding-bottom:10px; margin-bottom:10px; border-bottom:2px dashed var(--border);">
            ${receiptLogoUrl ? `<img src="${receiptLogoUrl}" alt="${t("cashier_receipt_logo_alt", "Restoran logotipi")}" style="height:56px; width:56px; object-fit:contain; border-radius:10px; margin-bottom:6px; display:block; margin-left:auto; margin-right:auto;">` : ""}
            ${receiptRestName ? `<div style="font-weight:800; font-size:15px; color:var(--text-primary); margin-bottom:2px;">${receiptRestName}</div>` : ""}
            ${receiptPhone ? `<div style="font-size:13px; color:var(--text-secondary);">📞 ${receiptPhone}</div>` : ""}
          </div>
        ` : "";

        htmlContent += `
            <div class="cash-card">
              ${receiptHeaderHtml}
              <h4>🧾 ${formatOrderNumber(o) || o.orderNumber}</h4>
              <p>${t("table")}: <b>${o.table}</b></p>
              <div class="cash-items">
                ${Object.values(o.items || {}).map(i => {
          const menuItem = window.allMenu?.[i.id || i.menuId || i.itemId];
          const itemName = getTranslatedItemName(i, menuItem, getLang());
          return `<div class="cash-item">
                    <img src="${i.img || 'img/food.png'}" alt="${t("order_image_alt")}">
                    <span>${itemName} × ${i.qty}</span>
                    <b>${(i.price * i.qty).toLocaleString()} ${cur}</b>
                  </div>`;
        }).join("")}
              </div>
              <!-- Narx taqsimoti -->
              <div style="padding:4px 0;">
                <p class="cash-total" style="margin-bottom:4px;">
                  ${t("total_label")}: <b>${baseTotal.toLocaleString()} ${cur}</b>
                </p>
                ${svcRow}
                ${totalRow}
              </div>
              <div style="margin-top:10px; text-align:center; font-size:12px; font-weight:700; color:var(--admin-warning-text); background:var(--admin-warning-bg); border:1px solid #fde68a; border-radius:8px; padding:8px;">
                ⏳ ${t("cashier_waiting_waiter_or_client", "To'lov kutilmoqda — ofitsiant yoki mijoz tomonidan yopiladi")}
              </div>
            </div>
          `;
      });

    list.innerHTML = htmlContent;
  }

  // Oxirgi kelgan orders ma'lumotini saqlab turamiz
  // (settings o'zgarganda orders listi qayta render bo'lishi uchun)
  let _cachedOrders = null;

  // 1) AVVAL settings ni bir marta yuklash (race condition oldini olish)
  get(ref(db, BASE_PATH + "/settings")).then(settSnap => {
    const sett = settSnap.val() || {};
    window._cashierServiceFee = Number(sett.serviceFee || 0);
    window._cashierServiceFeeMinOrder = Number(sett.serviceFeeMinOrder || 0);
    window._cashierLogoUrl = sett.restaurantLogoUrl || "";
    window._cashierContactPhone = sett.contactPhone || "";
    window._cashierRestName = sett.restaurantName || window.currentGlobalRestName || "";

    // 2) Settings tayyor bo'lgandan KEYIN orders tinglashni boshlash
    onValue(ref(db, BASE_PATH + "/orders"), snap => {
      _cachedOrders = snap.val() || {};
      renderCashierOrders(_cachedOrders);
    });
  }).catch(() => {
    // get() xato bersa ham orders tinglashni boshlaymiz (fallback)
    onValue(ref(db, BASE_PATH + "/orders"), snap => {
      _cachedOrders = snap.val() || {};
      renderCashierOrders(_cachedOrders);
    });
  });

  // 3) Settings real-time o'zgarganda (admin % ni saqlasa) — orders qayta render
  onValue(ref(db, BASE_PATH + "/settings"), settSnap => {
    const sett = settSnap.val() || {};
    window._cashierServiceFee = Number(sett.serviceFee || 0);
    window._cashierServiceFeeMinOrder = Number(sett.serviceFeeMinOrder || 0);
    window._cashierLogoUrl = sett.restaurantLogoUrl || "";
    window._cashierContactPhone = sett.contactPhone || "";
    window._cashierRestName = sett.restaurantName || window.currentGlobalRestName || "";
    // Agar orders allaqachon yuklangan bo'lsa — yangi % bilan qayta render
    if (_cachedOrders !== null) {
      renderCashierOrders(_cachedOrders);
    }
  });
}

async function checkAndShowPromo(orderId, phone) {
  if (!phone) return null;

  const normalizedInputPhone = normalizePhone(phone);

  const discountsSnap = await get(ref(db, `${BASE_PATH}/discounts`));
  const discounts = discountsSnap.val() || {};

  const activePromo = Object.values(discounts).find(d =>
    normalizePhone(d.ownerPhone || "") === normalizedInputPhone && d.used === false && d.active !== false
  );

  if (activePromo) {
    const promoBtn = document.getElementById(`promo-btn-${orderId}`);
    if (promoBtn) {
      promoBtn.style.display = "block";
      promoBtn.innerHTML = `🎁 ${t("promo_available_msg", "Sizda {percent}% promokod bor! (Qo'llash)").replace("{percent}", activePromo.percent)}`;
      promoBtn.onclick = () => applyPromoCode(orderId, activePromo);
    }
  }
}

window.applyPromoCode = async function (orderId, promo) {
  // Xavfsizlik uchun: promokod hozir "to'xtatilgan" (active=false)
  // holatda bo'lsa, tugma bosilgan payt eski bo'lsa ham qo'llanmasin.
  const liveSnap = await get(ref(db, `${BASE_PATH}/discounts/${promo.code}`));
  const liveData = liveSnap.val() || {};
  if (liveData.active === false) {
    alert(t("promo_inactive_error", "Bu promokod hozir faol emas"));
    return;
  }

  const orderSnap = await get(ref(db, `${BASE_PATH}/orders/${orderId}`));
  if (!orderSnap.exists()) return;

  const order = orderSnap.val();
  const currentTotal = Number(order.total || 0);
  const discountAmount = (currentTotal * promo.percent) / 100;
  const newTotal = currentTotal - discountAmount;

  // usedCount ni oshiramiz, maxUses ga yetsa used=true qilamiz
  const promoSnap = await get(ref(db, `${BASE_PATH}/discounts/${promo.code}`));
  const promoData = promoSnap.val() || {};
  const newUsedCount = (Number(promoData.usedCount) || 0) + 1;
  const maxUses = Number(promoData.maxUses) || 1;
  const nowUsed = newUsedCount >= maxUses;

  await update(ref(db, `${BASE_PATH}/orders/${orderId}`), {
    total: newTotal,
    originalTotal: currentTotal,
    appliedPromo: promo.code,
    discountAmount: discountAmount,
    discountPercent: promo.percent
  });

  await update(ref(db, `${BASE_PATH}/discounts/${promo.code}`), {
    usedCount: newUsedCount,
    used: nowUsed
  });

  showAdminNotification(`✅ ${t("promo_applied_success", "Promokod qo'llanildi:")} -${discountAmount.toLocaleString()} ${t("currency")}`);
};

window.approvePayment = async function (orderId, svcAmount, grandTotal) {
  const now = Date.now();
  try {
    const orderSnap = await get(ref(db, BASE_PATH + "/orders/" + orderId));
    if (!orderSnap.exists()) return;
    const order = orderSnap.val();

    // Production Security Fix Pass, Phase 4 (verification pass — payment
    // idempotency, completing the "Transactions" requirement). approvePayment
    // is a THIRD independent "mark order paid" path alongside kassa.js/
    // waiter.js's writeUnifiedPayment() (paymentEngine.js, already made
    // atomic in Phase 2) — this one had no guard at all against a double-
    // click/double-invocation, or against racing writeUnifiedPayment on the
    // same order. Both now claim the same orders/{id}/payment/paid leaf via
    // runTransaction, so whichever call actually lands first wins and every
    // other concurrent caller (from either path) aborts here instead of
    // double-processing (double inventory deduction, double KPI credit,
    // overwritten payment metadata).
    const paidClaimRef = ref(db, `${BASE_PATH}/orders/${orderId}/payment/paid`);
    const paidClaim = await runTransaction(paidClaimRef, (current) => {
      if (current === true) return; // abort — already paid (by us or a racing caller)
      return true;
    });
    if (!paidClaim.committed || paidClaim.snapshot.val() !== true) {
      showAdminNotification(t("order_already_paid", "Bu buyurtma allaqachon to'langan"), "error");
      return;
    }

    // Обслуга: svcAmount/grandTotal HTML dan keladi; agar yo'q bo'lsa settings dan hisoblaymiz
    const svcPct = Number(window._cashierServiceFee || 0);
    const svcMinOrder = Number(window._cashierServiceFeeMinOrder || 0);
    const baseTotal = Number(order.total || 0);
    // Chegara: svcMinOrder 0 bo'lsa doim qo'shiladi, aks holda faqat chegara summadan oshganda
    const applyService = svcPct > 0 && (svcMinOrder === 0 || baseTotal >= svcMinOrder);
    const computedSvc = applyService ? Math.round(baseTotal * svcPct / 100) : 0;
    const finalSvc = applyService ? (Number(svcAmount) || computedSvc) : 0;
    const finalTotal = Number(grandTotal) || (baseTotal + computedSvc);

    const updates = {
      [`orders/${orderId}/payment/paid`]: true,
      [`orders/${orderId}/payment/approvedAt`]: now,
      [`orders/${orderId}/status`]: ORDER_STATUS_V2.COMPLETED.key,
      [`orders/${orderId}/statusKey`]: ORDER_STATUS_V2.COMPLETED.key,
      [`orders/${orderId}/statusV2`]: ORDER_STATUS_V2.COMPLETED.key,
      [`orders/${orderId}/statusLabel`]: t("status_paid", "To'landi"),
      [`orders/${orderId}/updatedAt`]: now,
      [`orders/${orderId}/finalTotal`]: finalTotal,
      [`orders/${orderId}/serviceFeeAmount`]: finalSvc,
      [`orders/${orderId}/serviceFeePercent`]: svcPct,
      // Cashier → Payment → Completed: uchala bosqich ham shu bir lahzada sodir bo'ladi
      // (kassir tasdiqlash tugmasini bosgan payt), lekin statusHistory'da alohida
      // bosqich sifatida qayd etiladi — arxitektura zanjiri to'liq ko'rinishi uchun.
      [`orders/${orderId}/statusHistory/${ORDER_STATUS_V2.CASHIER.key}`]: now,
      [`orders/${orderId}/statusHistory/${ORDER_STATUS_V2.PAYMENT.key}`]: now,
      [`orders/${orderId}/statusHistory/${ORDER_STATUS_V2.COMPLETED.key}`]: now
    };

    if (!order.inventoryDeducted) {
      if (typeof window.deductOrderInventory === "function") {
        await window.deductOrderInventory(orderId);
      } else if (typeof deductStock === "function") {
        await deductStock(order.items);
        updates[`orders/${orderId}/inventoryDeducted`] = true;
      }
    }

    // 🥩 Yarim-fabrikat ombori: buyurtmadagi har bir taom uchun, agar uning
    // retseptida yarim-fabrikat ingredienti bo'lsa, mos miqdorda kamaytiramiz.
    if (typeof window._deductSemiFinishedOnSale === "function" && order.items) {
      for (const item of Object.values(order.items)) {
        if (item?.id) {
          await window._deductSemiFinishedOnSale(item.id, item.qty || 1);
        }
      }
    }

    if (order.table) {
      const tableKey = getTableKey(order.table);
      // 🆕 To'lov qabul qilingani stol holatida ham aks etadi ("To'landi").
      // orderId ataylab bu yerda tozalanmaydi — closeCheckAndFreeTable()
      // kassir/admin "chekni yopish" tugmasini bosganda, stolni haqiqatda
      // bo'shatganda tozalaydi. Shu bilan waiter.js hali "to'landi, lekin
      // hali yopilmagan" stolni to'g'ri ko'rsatib turadi.
      updates[`tables/${tableKey}/status`] = "paid";
      updates[`tables/${tableKey}/busy`] = true;
      updates[`tables/${tableKey}/updatedAt`] = now;
      updates[`tables/${tableKey}/paidAt`] = now;
    }

    await update(ref(db, BASE_PATH), updates);

    if (typeof syncCustomerProfileFromOrder === "function") {
      await syncCustomerProfileFromOrder(orderId, order, window.allOrders);
    }

    // finalTotal yozilgandan KEYIN KPI hisoblash (обслуга qo'shilgan summa bo'yicha)
    if (typeof window.calculateStaffKPI === "function") {
      await window.calculateStaffKPI(orderId);
    }

    await crmAdvAudit("orders", "payment_finish", orderId, t("audit_payment_approved_admin"), { paidAt: now }, "info");
    showAdminNotification("✅ " + t("payment_approved_cleaning", "To'lov tasdiqlandi. Stol 'Tozalanmoqda' holatiga o'tkazildi!"));

    if (order.appliedPromo) {
      await update(ref(db, `${BASE_PATH}/discounts/${order.appliedPromo}`), {
        used: true,
        usedAt: now,
        usedByOrder: orderId
      });

      if (typeof trackCouponRedemption === "function") {
        await trackCouponRedemption({
          customerId: order.customerPhone || order.clientPhone,
          couponCode: order.appliedPromo,
          orderId: orderId,
          discountAmount: order.discountAmount
        });
      }
    }

  } catch (error) {
    console.error(t("payment_approve_error_log", "⛔ To'lovni tasdiqlashda xatolik:"), error);
    showAdminNotification(t("notify_error", "Xatolik yuz berdi"), "error");
  }
};

// ─── Davomad hisoboti HTML blokini inject qilish ────────────────────────────
function _ensureAttendanceReportHTML() {
  // Agar allaqachon inject qilingan bo'lsa — qayta qilmaymiz
  if (document.getElementById("attendanceReportBlock")) return;

  // Qo'shish joyini topamiz: "Xodimlar boshqaruvi" bo'limidagi "Davomat" tabi
  const reportSection = document.getElementById("attendanceTab");
  if (!reportSection) return;

  const block = document.createElement("div");
  block.id = "attendanceReportBlock";
  block.style.cssText = "margin-top:24px;";
  block.innerHTML = `
<div style="background:var(--bg-card);border-radius:16px;box-shadow:0 2px 10px rgba(0,0,0,.07);padding:20px;margin-bottom:20px;">
  <!-- Sarlavha -->
  <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:18px;">
    <div style="display:flex;align-items:center;gap:10px;">
      <span style="font-size:22px;">📅</span>
      <div>
        <div style="font-size:17px;font-weight:800;color:var(--text-primary);">${t("attendance_report_title", "Davomad hisoboti (jadval)")}</div>
        <div style="font-size:12px;color:#94a3b8;">${t("attendance_report_subtitle", "Keldi / Kechikdi / Kelmadi — vaqti bilan")}</div>
      </div>
    </div>

    <!-- Filtrlar -->
    <div style="display:flex;flex-wrap:wrap;align-items:center;gap:8px;">
      <select id="attRepMode"
        style="border:1.5px solid var(--border);border-radius:9px;padding:8px 12px;font-size:13px;font-weight:600;color:#334155;background:var(--bg-hover);outline:none;cursor:pointer;"
        onchange="window._onAttRepModeChange()">
        <option value="week">${t("period_this_week", "Joriy hafta")}</option>
        <option value="month">${t("period_this_month", "Joriy oy")}</option>
        <option value="year">${t("period_this_year", "Joriy yil")}</option>
        <option value="range">${t("period_date_range", "Sana oralig'i")}</option>
      </select>

      <span id="attRepRangeInputs" style="display:none;display:flex;align-items:center;gap:6px;">
        <input type="date" id="attRepFrom"
          style="border:1.5px solid var(--border);border-radius:9px;padding:7px 10px;font-size:13px;color:#334155;outline:none;"
          onchange="window.renderAttendanceReport()">
        <span style="color:#94a3b8;font-size:13px;">—</span>
        <input type="date" id="attRepTo"
          style="border:1.5px solid var(--border);border-radius:9px;padding:7px 10px;font-size:13px;color:#334155;outline:none;"
          onchange="window.renderAttendanceReport()">
      </span>

      <button onclick="window.renderAttendanceReport()"
        style="background:#6366f1;color:#fff;border:none;border-radius:9px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer;">
        <span class="refresh-emoji">🔄</span> ${t("refresh_btn", "Yangilash")}
      </button>
    </div>
  </div>

  <!-- Jadval joyi -->
  <div id="attendanceReportContainer">
    <div style="text-align:center;color:#94a3b8;padding:24px;">⏳ ${t("loading", "Yuklanmoqda...")}</div>
  </div>
</div>`;

  reportSection.appendChild(block);

  // Mode o'zgarganda range inputlarini ko'rsatamiz/yashiramiz
  window._onAttRepModeChange = function () {
    const mode = document.getElementById("attRepMode")?.value;
    const inputs = document.getElementById("attRepRangeInputs");
    if (inputs) inputs.style.display = mode === "range" ? "flex" : "none";
    if (mode !== "range") window.renderAttendanceReport();
  };
}

function loadSectionData(id) {
  if (id === "promocodes") loadPromocodesPanel();
  if (id === "reservations") loadReservations();
  if (id === "customers" && typeof loadCustomersModule === "function") loadCustomersModule();
  if (id === "feedback") loadFeedbacks();
  if (id === "notifications") loadNotifications();
  if (id === "roles") loadRoles();
  if (id === "settings") {
    loadSettings();
    loadTerminalSettings();
    if (typeof window.loadPrintSettings === "function") window.loadPrintSettings();
    if (typeof window._initMaintenanceCenter === "function") window._initMaintenanceCenter();
    if (typeof window.loadAiImportSettings === "function") window.loadAiImportSettings();
  }
  if (id === "audit_log") loadAuditLog();
  if (id === "ai-import" && typeof window.initAiImportSection === "function") window.initAiImportSection();
  // Tables grid: #tablesGrid rendering/styling is fully owned by
  // listenTablesRealtime() below (it builds a nested #tablesCardsGrid with
  // the .tables-grid class) — this used to ALSO force #tablesGrid itself to
  // inline display:grid on every section switch, which fought that nested
  // structure (turning the outer wrapper into a 2-item grid of its own —
  // header + cards-wrapper — instead of a plain block wrapper). Removed as
  // dead/conflicting; nothing else here needs #tablesGrid re-styled on nav.
  if (id === "cashier") ensureCashierListener();

  // Staff bolimi: oshpaz va ofitsiant reytinglarini yangilash
  if (id === "staff") {
    if (typeof window.updateChefKPIs === "function") window.updateChefKPIs();
    if (typeof window.updateWaiterKPIs === "function") window.updateWaiterKPIs();

    // 🍳 Oshpaz qo'shish formasiga kategoriya checkboxlarini inject qilish
    setTimeout(() => {
      const container = document.getElementById("chefCategoryContainer");
      if (container && typeof window.renderChefCategoryCheckboxes === "function") {
        window.renderChefCategoryCheckboxes("chefCategoryContainer", []);
      }
      // 👑 Bosh oshpaz checkboxini inject qilish (agar HTML da yo'q bo'lsa)
      if (!document.getElementById("chefIsHeadChef")) {
        const parentContainer = document.getElementById("chefCategoryContainer")?.parentElement;
        if (parentContainer) {
          const headChefWrap = document.createElement("div");
          headChefWrap.id = "chefHeadChefWrap";
          headChefWrap.style.cssText = "margin-top:12px;padding:10px 14px;background:var(--admin-warning-bg);border:1.5px solid #fbbf24;border-radius:10px;";
          headChefWrap.innerHTML = `
            <label style="display:flex;align-items:center;gap:10px;cursor:pointer;user-select:none;">
              <input type="checkbox" id="chefIsHeadChef" style="accent-color:#f59e0b;width:18px;height:18px;">
              <div>
                <div style="font-size:14px;font-weight:700;color:#92400e;">👑 ${t("head_chef_label", "Bosh oshpaz")}</div>
                <div style="font-size:11px;color:#b45309;margin-top:2px;">${t("head_chef_hint", "Fast-food kategoriyasida 2+ oshpaz bo'lsa, buyurtma bosh oshpazga boradi")}</div>
              </div>
            </label>`;
          parentContainer.appendChild(headChefWrap);
        }
      }
    }, 100);
  }

  // Dashboard: real vaqt statistikasini yangilash
  if (id === "dashboard") {
    if (typeof updateRealTimeStats === "function") updateRealTimeStats();
    // Sof foyda qatori uchun harajatlar tinglovchisini ham shu yerda ishga tushiramiz
    // (aks holda admin "Harajatlar" bo'limiga kirmaguncha "Sof foyda" ko'rinmaydi)
    if (typeof window._initExpenses === "function") window._initExpenses();
    if (typeof window._initSystemHealth === "function") window._initSystemHealth();
  }

  // Sistem health bolimi: to'liq tekshiruvni ishga tushirish
  if (id === "system-health") {
    if (typeof window._initSystemHealth === "function") window._initSystemHealth();
    // _initSystemHealth allaqachon birinchi marta hamma tekshiruvlarni (shu jumladan
    // DB hajmi) bajaradi; bo'limga qayta kirilganda yangi ma'lumot uchun refresh qilamiz
    if (window._shSystemHealthEverOpened && typeof window._refreshSystemHealth === "function") {
      window._refreshSystemHealth();
    }
    window._shSystemHealthEverOpened = true;
  }

  // Menu bolimi: menyuni qayta render qilish
  if (id === "menu") {
    if (typeof renderMenu === "function") renderMenu();
    // Statistikani ham yuklash
    setTimeout(() => {
      if (typeof window.renderMenuStats === "function") window.renderMenuStats();
    }, 300);
    // Joriy faol tabni ham qayta chizamiz (Kategoriyalar/Modifierlar/
    // Qo'shimchalar/Aksiyalar tablarida bo'lsa, bo'sh qolib ketmasin)
    if (typeof window.showMenuTab === "function" && typeof _menuActiveTab !== "undefined") {
      window.showMenuTab(_menuActiveTab);
    }
  }

  // Report bolimi: moliya hisobotlarini yangilash
  if (id === "report") {
    if (typeof window.renderStaffFinance === "function") window.renderStaffFinance();
    if (typeof window.renderSalaryReport === "function") window.renderSalaryReport();
    if (typeof window.renderAttendanceReport === "function") window.renderAttendanceReport();
    // Hisobot bo'limi ochilishi bilan avtomatik yuklaymiz
    setTimeout(() => {
      // Agar sana tanlanmagan bo'lsa — joriy oyni tanlaymiz
      const dateMode = document.getElementById("dateMode");
      if (dateMode && dateMode.value === "range") {
        const from = document.getElementById("reportFrom");
        const to = document.getElementById("reportTo");
        if (!from?.value || !to?.value) {
          dateMode.value = "month";
        }
      }
      if (typeof window.generateRangeReport === "function") window.generateRangeReport();
    }, 200);
  }

  // Buyurtmalar bolimi: filtrlangan royxatni korsatish
  if (id === "orders") {
    if (typeof renderOrders === "function") renderOrders(window.allOrders || {});
  }

  // Ombor bolimi: inventarizatsiyani yuklash
  if (id === "warehouse") {
    if (!window._inventoryListenerStarted) {
      listenToInventory();
      window._inventoryListenerStarted = true;
    }
  }

  // Smart Production Planner: ombor + yarim-fabrikat listenerlarini ishga tushiramiz
  if (id === "production-planner") {
    if (!window._inventoryListenerStarted) {
      listenToInventory();
      window._inventoryListenerStarted = true;
    }
    if (typeof window.listenSemiFinished === "function" && !window._sfpListenerStarted) {
      window._sfpListenerStarted = true;
      window.listenSemiFinished();
    }
    if (typeof window.initProductionPlanner === "function") window.initProductionPlanner();
  }

  // Moliya bolimi: ish haqi hisoblash + harajatlar
  if (id === "finance") {
    if (typeof window.calculateSalaries === "function") window.calculateSalaries();
    if (typeof window.renderSalaryReport === "function") window.renderSalaryReport();
    if (typeof window._initExpenses === "function") window._initExpenses();
  }

  if (id === "courier") {
    if (typeof window._initCourierMonitor === "function") window._initCourierMonitor();
  }

  if (id === "kitchen-monitor") {
    if (typeof window._initKitchenMonitor === "function") window._initKitchenMonitor();
  }

  if (id === "pos-monitoring") {
    if (typeof window._initPosMonitoring === "function") window._initPosMonitoring();
  }

  if (id === "approval-center") {
    if (typeof window._initApprovalCenter === "function") window._initApprovalCenter();
  }
}

// ==========================================
// 🟢 SIDEBAR ACTIVE-STATE — YAGONA MANBA
// ==========================================
// Oldin sidebar'dagi "active" (yashil) klass FAQAT admin.html ichida
// "Bosh sahifa" havolasiga statik yozib qo'yilgan edi va uni HECH QAYERDA
// boshqa linkka ko'chiradigan kod yo'q edi (faqat bitta joyda — pastroqda,
// til almashtirilganda — o'qib olinardi, lekin yozilmasdi). Natijada qaysi
// bo'lim ochilishidan qat'i nazar sidebar'da doim "Bosh sahifa" yashil
// bo'lib qolardi. Endi bitta shu funksiya — window.showSection() haqiqatda
// bo'lim almashtirgan har safar (klik, hash o'zgarishi, bildirishnoma
// havolasi, dashboard kartochkasi, RBAC-yo'naltirish — BARCHASI faqat
// showSection() orqali o'tadi) — sidebar'dagi active linkni shu bilan
// birga, bitta joydan yangilaydi. Ichki sub-tablar (Sozlamalar/Moliya/
// Ombor ichidagi tablar) alohida showSection chaqirmaydi — ular faqat
// bo'lim ICHIDAGI elementlarni almashtiradi — shuning uchun ota-modul
// active holatda avtomatik qoladi, alohida ishlov shart emas.
function setActiveSidebarNav(id) {
    const links = document.querySelectorAll(".sidebar-nav a[href]");
    let matched = null;
    links.forEach(link => {
        const linkId = (link.getAttribute("href") || "").replace("#", "");
        if (linkId === id && !matched) matched = link;
        link.classList.remove("active");
    });
    if (matched) matched.classList.add("active");
}
window.setActiveSidebarNav = setActiveSidebarNav;

// ==========================================
// 🔄 BO'LIMLARNI (SAHIFALARNI) ALMASHTIRISH
// ==========================================
window.showSection = function (id) {
    if (typeof isPlanFeatureBlocked === "function" &&
        isPlanFeatureBlocked(id)) return;

    if (typeof isModuleBlocked === "function" &&
        isModuleBlocked(id)) return;

    if (
        id === "courier" &&
        window._serviceTypes &&
        window._serviceTypes.delivery === false
    ) return;

    if (
        id !== "rbac-403" &&
        window._isRbacBlocked &&
        window._isRbacBlocked(id)
    ) {
        return window.showSection("rbac-403");
    }

    // Scoped to <main> — every real admin panel (dashboard, orders, staff, ...)
    // lives inside <main class="content"> (see admin.html's DIV.layout > MAIN.content
    // wrapper). This used to be scoped the same way; it was temporarily widened to
    // a document-wide "section, .admin-section, .dashboard-section" as a workaround
    // for #staff (and everything after it in source order) getting parsed outside
    // <main> entirely, due to a stray extra </div> inside #customers's filter-bar
    // markup that closed the page's outer layout wrapper early (fixed in admin.html).
    // Restored to the scoped selector now that the real DOM bug is fixed — this is
    // safer going forward (won't silently start hiding/showing an unrelated
    // <section> if one is ever added inside a modal/widget outside <main>).
    const sections = document.querySelectorAll(
        "main section, main .admin-section, .dashboard-section"
    );

    let found = false;

    sections.forEach(sec => {
        const isActive = sec.id === id;

        if (isActive) {
            sec.style.display = "block";
            sec.classList.add("active-section");
            found = true;
        } else {
            sec.style.display = "none";
            sec.classList.remove("active-section");
        }
    });

    if (found) {
    setActiveSidebarNav(id);

    if (typeof loadSectionData === "function") {
        loadSectionData(id);
    }

    const target = document.getElementById(id);

    if (target) {
        requestAnimationFrame(() => {
            target.scrollIntoView({
                behavior: "auto",
                block: "start"
            });
        });
    }
}
};

// ==========================================
// 📊 Dashboard kartochkalaridan Buyurtmalar bo'limiga bosqich filtri bilan o'tish
// (Kassa bo'limi olib tashlangandan keyin shu o'rniga ishlatiladi)
// ==========================================
window.goToOrdersFiltered = function (stage) {
  window.showSection("orders");
  const sel = document.getElementById("filterOrderStage");
  if (sel) {
    sel.value = stage;
    sel.dispatchEvent(new Event("change"));
  }
};

// Sahifa yuklanishidan oldin bosib ketilgan nav-click larni bajarish
if (typeof window._flushShowSection === "function") {
  window._flushShowSection(window.showSection);
}

document.querySelectorAll(".sidebar-nav a, .nav-link").forEach(link => {
  link.addEventListener("click", e => {
    e.preventDefault();
    showSection(link.getAttribute("href").replace("#", ""));
  });
});

function listenPaymentNotifications() {
  onValue(ref(db, BASE_PATH + "/orders"), snap => {
    const orders = snap.val() || {};

    Object.entries(orders).forEach(([orderId, o]) => {
      if (o.payment?.paid && !o.payment?.adminNotified) {
        showAdminNotification(
          `💰 ${t("table")} ${o.table} — ${Number(o.total || 0).toLocaleString()} ${t("currency")}`
        );

        update(ref(db, BASE_PATH + "/orders/" + orderId + "/payment"), {
          adminNotified: true
        });
      }
    });
  });
}

window.deleteAllOrdersAndFreeTables = async function () {
  if (!confirm(t("alerts.confirm_delete_all_orders_1"))) return;
  if (!confirm(t("alerts.confirm_delete_all_orders_2"))) return;
  try {
    await set(ref(db, BASE_PATH + "/orders"), null);
    const tablesSnap = await get(ref(db, BASE_PATH + "/tables"));
    if (tablesSnap.exists()) {
      const updates = {};
      Object.keys(tablesSnap.val()).forEach(n => {
        updates[`tables/${n}/busy`] = false;
        updates[`tables/${n}/orderId`] = null;
        updates[`tables/${n}/status`] = "free";
        updates[`tables/${n}/closedByAdmin`] = false;
      });
      await update(ref(db, BASE_PATH), updates);
    }
    window.allOrders = {};
    renderOrders({});
    showAdminNotification(t("alerts.orders_deleted_all"), "error");
  } catch (e) {
    console.error(e);
    showAdminNotification(t("notify.error"), "error");
  }
};

function renderOrderFilters() {
  const payment = document.getElementById("filterPaymentStatus");
  const category = document.getElementById("filterOrderCategory");
  const subcategory = document.getElementById("filterOrderSubcategory");

  if (payment) {
    payment.innerHTML = `
    <option value="all">${t("orders_payment_all")}</option>
    <option value="paid">${t("orders_payment_paid")}</option>
    <option value="unpaid">${t("orders_payment_unpaid")}</option>
  `;
  }
  if (category) {
    category.innerHTML = `<option value="all">${t("all_categories")}</option>`;
    getAllCategories().forEach(cat => {
      category.innerHTML += `<option value="${cat.id}">${cat.isCustom ? "⭐ " : ""}${cat.label}</option>`;
    });
  }
  if (subcategory) {
    subcategory.innerHTML = `<option value="all">${t("all_subcategories")}</option>`;
  }
}

// ==========================================
// 🍳 OSHPAZ KATEGORIYALARI — CATEGORY_DATA + custom kategoriyalardan dinamik
// ==========================================

/**
 * Menyudagi real kategoriyalar ro'yxatini qaytaradi.
 * CATEGORY_DATA (shared.js) + Firebase custom kategoriyalardan o'qiladi.
 * + oxirida "general" (hamma taomlar) opsiyasi qo'shiladi.
 */
window.getChefCategoryOptions = function () {
  const cats = getAllKitchenStations().map(st => ({
    value: st.id,
    label: () => st.label
  }));
  // "Umumiy" — kategoriyasiz hamma buyurtmalar
  cats.push({
    value: "general",
    label: () => t("chef_cat_general", "🍽️ Umumiy (hamma taomlar)")
  });
  return cats;
};

// ==========================================
// 🍳 OSHPAZ KATEGORIYASI UI INJEKTsIYASI
// ==========================================
window.renderChefCategoryCheckboxes = function (containerId, selectedValues = []) {
  const container = document.getElementById(containerId);
  if (!container) return;

  const options = window.getChefCategoryOptions();
  container.innerHTML = options.map(cat => {
    const checked = selectedValues.includes(cat.value) ? "checked" : "";
    const label = typeof cat.label === "function" ? cat.label() : cat.label;
    return `
      <label style="display:inline-flex; align-items:center; gap:6px; margin:4px 8px 4px 0;
        padding:5px 10px; background:var(--bg-hover); border:1.5px solid var(--border); border-radius:8px;
        cursor:pointer; font-size:13px; user-select:none;">
        <input type="checkbox" name="chefCategory" value="${cat.value}" ${checked}
          style="accent-color:#6366f1; width:15px; height:15px;">
        ${label}
      </label>
    `;
  }).join("");
};

// ══════════════════════════════════════════════════════
// 💰 MAOSH HISOBLASH USULI — faqat xodim yaratishda tanlanadi.
// Yaratilgandan keyin bu rejim o'zgarmaydi (admin panelidan olib tashlandi).
// ══════════════════════════════════════════════════════
// i18n fix: was a `const` array with t() baked in at module-load time
// (module top-level runs once, before any language switch could ever
// re-run it) — if this modal is opened for the first time AFTER switching
// language, the picker still showed the very first page-load's language.
// Turned into a function so every render call re-reads t() in the
// CURRENT language, matching the labelKey/fallback pattern used elsewhere
// (e.g. ATTENDANCE_ROLE_META/getAttendanceRoleMeta()).
function _getSalaryModeOpts() {
  return [
    { val: "fixed", icon: "💼", label: t("salary_mode_fixed", "Oylik"), clr: "#6366f1", bg: "var(--admin-purple-bg)" },
    { val: "kpi", icon: "🎯", label: t("salary_mode_kpi", "KPI"), clr: "#0891b2", bg: "var(--admin-info-bg)" },
    { val: "percent", icon: "📊", label: t("salary_mode_percent", "Foiz"), clr: "#d97706", bg: "var(--admin-warning-bg)" },
    { val: "ball", icon: "🏆", label: t("salary_mode_ball", "Ball"), clr: "#16a34a", bg: "var(--admin-success-bg)" }
  ];
}

function renderSalaryModePicker(containerId, keyPrefix, defaultMode = "fixed") {
  const container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = `
    <div class="smode-wrap">
      <div class="smode-label">${t("smode_label", "Hisoblash usuli")}:</div>
      <div class="smode-btns" id="${keyPrefix}-smode-btns">
        ${_getSalaryModeOpts().map(opt => `
          <div class="smode-opt${opt.val === defaultMode ? " selected" : ""}"
               style="--smode-clr:${opt.clr}; --smode-bg:${opt.bg};"
               data-mode="${opt.val}"
               onclick="window._selectSalaryMode('${keyPrefix}', '${opt.val}')">
            ${opt.icon} ${opt.label}
          </div>`).join("")}
      </div>
      <input type="hidden" id="${keyPrefix}-smode-value" value="${defaultMode}">

      <div class="smode-input-row" id="${keyPrefix}-smode-row-fixed" style="${defaultMode !== "fixed" && defaultMode !== "kpi" ? "display:none;" : ""}">
        <label>${t("monthly_salary_label", "Oylik maosh (so'm)")}:</label>
        <input type="number" id="${keyPrefix}-smode-fixed" value="0" min="0">
      </div>
      <div class="smode-input-row" id="${keyPrefix}-smode-row-kpi" style="${defaultMode !== "kpi" ? "display:none;" : ""}">
        <label>${t("kpi_percent_label", "Boshlang'ich KPI (%)")}:</label>
        <input type="number" id="${keyPrefix}-smode-kpi" value="100" min="0" max="100">
      </div>
      <div class="smode-input-row" id="${keyPrefix}-smode-row-comm" style="${defaultMode !== "percent" ? "display:none;" : ""}">
        <label>${t("percent_per_order_label", "Har bir buyurtmadan foiz (%)")}:</label>
        <input type="number" id="${keyPrefix}-smode-comm" value="0" min="0" max="100" step="0.5">
      </div>
      <div class="smode-input-row" id="${keyPrefix}-smode-row-ball" style="${defaultMode !== "ball" ? "display:none;" : ""}">
        <label>${t("ball_rate_label", "1 ball = necha so'm")}:</label>
        <input type="number" id="${keyPrefix}-smode-ball" value="0" min="0">
      </div>
    </div>
  `;
}

window._selectSalaryMode = function (keyPrefix, mode) {
  document.getElementById(`${keyPrefix}-smode-value`).value = mode;
  document.querySelectorAll(`#${keyPrefix}-smode-btns .smode-opt`).forEach(el => {
    el.classList.toggle("selected", el.dataset.mode === mode);
  });
  const show = id => { const el = document.getElementById(id); if (el) el.style.display = ""; };
  const hide = id => { const el = document.getElementById(id); if (el) el.style.display = "none"; };
  hide(`${keyPrefix}-smode-row-fixed`); hide(`${keyPrefix}-smode-row-kpi`); hide(`${keyPrefix}-smode-row-comm`); hide(`${keyPrefix}-smode-row-ball`);
  if (mode === "fixed") show(`${keyPrefix}-smode-row-fixed`);
  if (mode === "kpi") { show(`${keyPrefix}-smode-row-fixed`); show(`${keyPrefix}-smode-row-kpi`); }
  if (mode === "percent") show(`${keyPrefix}-smode-row-comm`);
  if (mode === "ball") show(`${keyPrefix}-smode-row-ball`);
};

function readSalaryModeFields(keyPrefix) {
  const mode = document.getElementById(`${keyPrefix}-smode-value`)?.value || "fixed";
  return {
    salaryMode: mode,
    fixedSalary: Number(document.getElementById(`${keyPrefix}-smode-fixed`)?.value) || 0,
    kpiPercent: Number(document.getElementById(`${keyPrefix}-smode-kpi`)?.value ?? 100) || 0,
    commissionPercent: Number(document.getElementById(`${keyPrefix}-smode-comm`)?.value) || 0,
    ballRate: Number(document.getElementById(`${keyPrefix}-smode-ball`)?.value) || 0
  };
}

// ── Moliya → Ish haqi: har bir xodim uchun alohida hisoblash usuli ──
window.populateStaffSalaryModeSelect = function () {
  const select = document.getElementById("payrollSmodeStaffSelect");
  if (!select) return;
  const prevValue = select.value;
  const users = window.allUsers || {};
  const options = Object.entries(users)
    .filter(([, u]) => u.role === "chef" || u.role === "waiter")
    .sort((a, b) => (a[1].name || "").localeCompare(b[1].name || ""));

  select.innerHTML = `<option value="">${t("select_staff_placeholder", "Xodimni tanlang...")}</option>` +
    options.map(([id, u]) => {
      const roleIcon = u.role === "chef" ? "👨‍🍳" : "🧑‍🍳";
      return `<option value="${escapeHtml(id)}">${roleIcon} ${escapeHtml(u.name || t("unknown_label", "Noma'lum"))}</option>`;
    }).join("");

  if (prevValue && users[prevValue]) select.value = prevValue;
};

window.loadStaffSalaryMode = function (staffId) {
  const pickerBox = document.getElementById("payrollSmodePicker");
  const saveBtn = document.getElementById("payrollSmodeSaveBtn");
  if (!pickerBox || !saveBtn) return;

  if (!staffId) {
    pickerBox.style.display = "none";
    saveBtn.style.display = "none";
    pickerBox.innerHTML = "";
    return;
  }

  const user = (window.allUsers || {})[staffId];
  if (!user) return;

  pickerBox.style.display = "";
  saveBtn.style.display = "";
  renderSalaryModePicker("payrollSmodePicker", "payrollSmode", user.salaryMode || "fixed");

  const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };
  setVal("payrollSmode-smode-fixed", user.fixedSalary || 0);
  setVal("payrollSmode-smode-kpi", user.kpiPercent ?? 100);
  setVal("payrollSmode-smode-comm", user.commissionPercent || 0);
  setVal("payrollSmode-smode-ball", user.ballRate || 0);
};

window.saveStaffSalaryMode = async function () {
  const staffId = document.getElementById("payrollSmodeStaffSelect")?.value;
  if (!staffId) return;

  const smode = readSalaryModeFields("payrollSmode");
  try {
    await update(ref(db, BASE_PATH + "/users/" + staffId), {
      salaryMode: smode.salaryMode,
      fixedSalary: smode.fixedSalary,
      kpiPercent: smode.kpiPercent,
      commissionPercent: smode.commissionPercent,
      ballRate: smode.ballRate
    });
    if (typeof showToast === "function") showToast(t("payment_success", "✅ Saqlandi!"), "success");
    else alert(t("payment_success", "✅ Saqlandi!"));
  } catch (e) {
    console.error("Staff salary mode save error:", e);
  }
};

// ══════════════════════════════════════════════════════
// Parol ko'rsatish/yashirish va avtomatik generatsiya
// (Xodim qo'shish formalari: chef / waiter / cashier uchun umumiy)
// ══════════════════════════════════════════════════════
window.togglePwVisibility = function (inputId, btnEl) {
  const input = document.getElementById(inputId);
  if (!input) return;
  const icon = btnEl?.querySelector("i");
  if (input.type === "password") {
    input.type = "text";
    input.classList.add("pw-revealed");
    if (icon) { icon.classList.remove("fa-eye"); icon.classList.add("fa-eye-slash"); }
  } else {
    input.type = "password";
    input.classList.remove("pw-revealed");
    if (icon) { icon.classList.remove("fa-eye-slash"); icon.classList.add("fa-eye"); }
  }
};

// Xodim paroli — 4 xonali sondan oshmasin (min "1000", max "9999")
function _genStrongPassword() {
  return String(Math.floor(1000 + Math.random() * 9000));
}

// ── Shu restoran ichida band bo'lgan PIN kodlar to'plamini bir marta o'qiydi ──
// [_isPinCodeTaken PERMISSION_DENIED root-cause fix]: this used to do ONE
// bulk get(ref(db, CREDS_PATH)) — a read of the WHOLE credentials/$restId
// node. database.rules.json only grants ".read" at the LEAF
// credentials/$restId/$userId/password path, never at $restId or $userId
// above it — Firebase Rules do not let a parent-level read borrow a
// descendant's grant, so that bulk read was PERMISSION_DENIED for every
// session, including a fully legitimate owner/admin (live-verified: 401 for
// an admin session that successfully reads the exact same data one leaf at a
// time). Not a View-As-specific bug — a structural one. Fixed by reading
// each active staff member's password leaf individually (the one shape the
// rules actually permit — the same one editStaff() already uses
// successfully), in parallel, and ONLY when this session's role can read
// them at all (checked once, up front — no doomed requests, no
// Permission-denied storm). Returns null (not an empty Set) when this
// session isn't authorized to check, so callers can tell "verified: no
// staff has this PIN" apart from "couldn't verify, don't know."
async function _fetchTakenPinsSet(excludeUserId = null) {
  // PostgreSQL owns credential uniqueness and checks it atomically inside
  // the canonical staff transaction. Never inspect Firebase credentials in
  // postgres mode.
  if ((await resolveClientDataBackend()) === "postgres") return null;
  if (!(await _hasCredentialAccess())) return null;
  try {
    const usersSnap = await get(ref(db, BASE_PATH + "/users"));
    if (!usersSnap.exists()) return new Set();
    const activeUids = Object.entries(usersSnap.val())
      .filter(([uid, u]) => !(excludeUserId && uid === excludeUserId) && u.active !== false) // bloklangan/faol bo'lmagan xodim kodini qayta berish mumkin
      .map(([uid]) => uid);
    const pins = await Promise.all(activeUids.map(uid =>
      get(ref(db, CREDS_PATH + "/" + uid + "/password"))
        .then(snap => String(snap.val() ?? "").trim())
        .catch(() => "") // bitta xodim yozuvi o'qilmasa ham, qolganlarini bloklab qo'ymaymiz
    ));
    return new Set(pins.filter(Boolean));
  } catch (err) {
    console.error("_fetchTakenPinsSet error:", err);
    return new Set(); // tarmoq xatosida bloklab qo'ymaslik uchun ehtiyotkorlik bilan bo'sh to'plam
  }
}

// ── Shu restoran ichida PIN kod band emasligini tekshirish ──
// excludeUserId: tahrirlashda o'zining joriy kodini "band" deb hisoblamaslik uchun
async function _isPinCodeTaken(pin, excludeUserId = null) {
  if (!pin) return false;
  const taken = await _fetchTakenPinsSet(excludeUserId);
  if (taken === null) {
    // Bu sessiya credential'larni tekshira olmaydi (masalan owner/admin
    // bo'lmagan View-As sessiyasi) — HECH QANDAY so'rov yubormasdan xavfsiz
    // o'tkazib yuboramiz. Bloklamaymiz: agar shu sessiya haqiqatan parolni
    // SAQLASHGA harakat qilsa, xuddi shu qoida (owner/admin) yozishni ham
    // mustaqil ravishda rad etadi — shu yerda tekshiruvni o'tkazib yuborish
    // bu himoyani chetlab o'tishga olib kelmaydi.
    console.log("[PIN-CHECK-DIAG] Current session lacks credential access — skipping PIN uniqueness check (no request sent).");
    return false;
  }
  return taken.has(String(pin).trim());
}

// ── Bo'sh (band bo'lmagan) 4 xonali PIN kod avtomatik generatsiya qilish ──
// Taken-PIN to'plami loop BOSHLANISHIDAN OLDIN bir marta o'qiladi (avval har
// bir urinishda _isPinCodeTaken() qayta o'qirdi — 30 tagacha urinish = 30
// marta bir xil ma'lumotni qayta o'qish, ortiqcha Firebase so'rovlari).
async function _genUniqueStaffPassword(maxAttempts = 30) {
  const taken = await _fetchTakenPinsSet(null);
  if (taken === null) {
    console.log("[PIN-CHECK-DIAG] Current session lacks credential access — generating a PIN without a uniqueness guarantee.");
    return _genStrongPassword();
  }
  for (let i = 0; i < maxAttempts; i++) {
    const candidate = _genStrongPassword();
    if (!taken.has(candidate)) return candidate;
  }
  // Juda kam ehtimol, lekin baribir band bo'lmagan kod topilmasa — vaqt belgisiga asoslangan fallback
  return String(1000 + (Date.now() % 9000));
}

window.generateStaffPassword = function (inputId) {
  const input = document.getElementById(inputId);
  if (!input) return;
  // Xodim paroli — 4 xonali sondan oshmasin (max "9999")
  input.value = String(Math.floor(1000 + Math.random() * 9000));
  input.maxLength = 4;
  // Generatsiyadan so'ng parolni ko'rinadigan qilib qo'yamiz — nusxa olish oson bo'lishi uchun
  input.type = "text";
  input.classList.add("pw-revealed");
  const wrap = input.closest(".pw-field-wrap");
  const icon = wrap?.querySelector(".pw-eye-btn i");
  if (icon) { icon.classList.remove("fa-eye"); icon.classList.add("fa-eye-slash"); }
};

// [CREATE-STAFF compensation fix] Two independent writes make up "a new
// staff member": credentials/$restId/$id/password (credential) and
// restaurants/$restId/users/$id (the visible record). There is no single
// Firebase transaction across those two top-level paths from the client, so
// a failure between them could previously leave a half-created employee —
// most concerningly a WRITTEN credential with NO matching user record if the
// second write failed (the credential write succeeding first was already
// required, since login iterates restaurants/$restId/users and would never
// even look up a credential with no matching entry there — so this can't be
// exploited as a "phantom login", but it's still real orphaned data an
// admin would have no way to see or clean up). Shared by every "add new
// staff" flow (addChef/addWaiter/addCashier/addCourier/saveNewStaff) so the
// same compensation applies everywhere identically, not copy-pasted 5 times.
async function _staffApi(path, { method = "GET", body } = {}) {
  const user = auth?.currentUser;
  if (!user) {
    const err = new Error("AUTH_REQUIRED");
    err.status = 401;
    err.code = "AUTH_REQUIRED";
    throw err;
  }
  let tokenResult;
  try {
    tokenResult = await user.getIdTokenResult(true);
  } catch {
    const err = new Error("TENANT_FORBIDDEN");
    err.status = 403;
    err.code = "TENANT_FORBIDDEN";
    throw err;
  }
  const claims = tokenResult?.claims || {};
  const claimRestId = claims.restId ?? claims.restaurantId ?? null;
  if (claimRestId !== currentRestaurantId) {
    const err = new Error("TENANT_FORBIDDEN");
    err.status = 403;
    err.code = "TENANT_FORBIDDEN";
    throw err;
  }
  const token = tokenResult.token;
  const separator = path.includes("?") ? "&" : "?";
  const response = await fetch(`${path}${separator}restId=${encodeURIComponent(currentRestaurantId)}`, {
    method,
    headers: {
      Authorization: `Bearer ${token}`,
      ...(body === undefined ? {} : { "Content-Type": "application/json" }),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    const classified = window.classifyAdminDataError({ status: response.status, code: payload?.error });
    const err = new Error(classified.code);
    err.status = classified.status;
    err.code = classified.code;
    throw err;
  }
  return payload;
}

async function _writeNewStaffCredentialAndRecord(id, password, userData) {
  if ((await resolveClientDataBackend()) === "postgres") {
    return _staffApi("/api/staff", {
      method: "POST",
      body: { ...userData, password },
    });
  }
  await set(ref(db, CREDS_PATH + "/" + id + "/password"), password);
  try {
    await set(ref(db, BASE_PATH + "/users/" + id), userData);
  } catch (userWriteErr) {
    // Compensate: remove the now-orphaned credential rather than leaving a
    // password on record for an employee that was never actually created.
    // Best-effort — if this ALSO fails, the original error is still what's
    // reported; a dangling credential with no matching user is inert (never
    // reachable via login, which only iterates real user records) rather
    // than a security gap, so failing to compensate here doesn't get hidden
    // behind a false "success", it's just not worse than the original error.
    try {
      await remove(ref(db, CREDS_PATH + "/" + id + "/password"));
    } catch (cleanupErr) {
      console.error("[CREATE-STAFF] Orphaned credential cleanup also failed:", cleanupErr?.code || cleanupErr?.message);
    }
    throw userWriteErr;
  }
  return { id, ...userData };
}

window.addChef = async function () {
  const name = document.getElementById("chefName")?.value?.trim();
  const passwordInput = document.getElementById("chefPassword")?.value?.trim();

  if (!name) {
    alert(t("enter_chef_name"));
    return;
  }

  // ── Tarif bo'yicha oshpazlar soni limitini tekshirish ──
  const chefLimitCheck = await window.checkStaffRoleLimit(currentRestaurantId, "chef", "maxChefs");
  if (!chefLimitCheck.ok) {
    alert(
      t("chef_limit_reached", "⛔ Tarifingiz bo'yicha oshpazlar soni limiti tugagan!") +
      `\n${t("chef_limit_current", "Joriy")}: ${chefLimitCheck.current} / ${chefLimitCheck.limit}\n` +
      t("chef_limit_upgrade_hint", "Ko'proq oshpaz qo'shish uchun tarifni yangilang.")
    );
    return;
  }

  // ── Oshpaz kategoriyalarini olish ──
  const categoryCheckboxes = document.querySelectorAll("#chefCategoryContainer input[name='chefCategory']:checked");
  const chefCategories = Array.from(categoryCheckboxes).map(cb => cb.value);

  // ── Oshpazning oshxona bo'limi (kitchenStation) ──
  const kitchenStation = document.getElementById("chefKitchenStation")?.value || "";

  // ── Bosh oshpaz (isHeadChef) belgisi ──
  const isHeadChef = document.getElementById("chefIsHeadChef")?.checked === true;

  // ── Qo'lda kiritilgan PIN kod band emasligini tekshirish ──
  if (passwordInput) {
    if (await _isPinCodeTaken(passwordInput)) {
      showAdminNotification(t("staff_pin_taken", "⛔ Bu PIN kod boshqa xodimda band! Boshqa kod tanlang."), "error");
      return;
    }
  }

  const password = passwordInput || await _genUniqueStaffPassword();
  const id = "chef_" + Date.now();

  // ── Agar bosh oshpaz belgilansa: avvalgi bosh oshpazdan belgini olamiz ──
  if (isHeadChef) {
    const usersSnap = await get(ref(db, BASE_PATH + "/users"));
    if (usersSnap.exists()) {
      const staffWriteMode = await resolveClientDataBackend();
      const removeHeadOps = [];
      Object.entries(usersSnap.val()).forEach(([uid, u]) => {
        if (u.role === "chef" && u.isHeadChef === true) {
          removeHeadOps.push(
            staffWriteMode === "postgres"
              ? _staffApi(`/api/staff/${encodeURIComponent(uid)}`, { method: "PATCH", body: { isHeadChef: false } })
              : update(ref(db, BASE_PATH + "/users/" + uid), { isHeadChef: false })
          );
        }
      });
      await Promise.all(removeHeadOps);
    }
  }

  try {
    const smode = readSalaryModeFields("chef");
    // P0-2 residual-gap fix: password written to CREDS_PATH, not embedded
    // in the users/ record — see CREDS_PATH's definition above.
    //
    // [CREATE-STAFF PERMISSION_DENIED root-cause fix] this used to
    // set(ref(db, CREDS_PATH + "/" + id), { password }) — a set() on the
    // PARENT credentials/$restId/$userId node. database.rules.json only
    // grants ".write" at the LEAF credentials/$restId/$userId/password path,
    // never at $userId itself — same structural gap already found (and
    // fixed) for _isPinCodeTaken()'s old bulk READ a few passes back, this
    // time on the WRITE side, for every "add new staff" flow. A set() on a
    // node with no ".write" of its own (and none at any ancestor) is denied
    // regardless of role — confirmed not role/View-As-specific. Fixed by
    // writing the LEAF directly (_writeNewStaffCredentialAndRecord, above —
    // also compensates by removing the credential if the user-record write
    // that follows it fails, so a failed create never leaves an orphaned
    // password behind).
    await _writeNewStaffCredentialAndRecord(id, password, {
      name,
      role: "chef",
      active: true,
      chefCategories: chefCategories.length > 0 ? chefCategories : ["general"],
      kitchenStation,
      isHeadChef: isHeadChef,
      salaryMode: smode.salaryMode,
      fixedSalary: smode.fixedSalary,
      kpiPercent: smode.kpiPercent,
      commissionPercent: smode.commissionPercent,
      ballRate: smode.ballRate,
      createdAt: Date.now()
    });

    const categoryLabels = (window.getChefCategoryOptions ? window.getChefCategoryOptions() : [])
      .filter(c => (chefCategories.length > 0 ? chefCategories : ["general"]).includes(c.value))
      .map(c => typeof c.label === "function" ? c.label() : c.label)
      .join(", ");

    const stationLabel = kitchenStation
      ? (getAllKitchenStations().find(s => s.id === kitchenStation)?.label || kitchenStation)
      : t("no_kitchen_station", "Belgilanmagan");

    const headLabel = isHeadChef ? ` 👑 ${t("head_chef_label", "Bosh oshpaz")}` : "";

    showAdminNotification(
      `👨‍🍳 ${t("chef_added")}${headLabel}\n${t("name_label")}: ${name}\n${t("password_label")}: ${password}\n🍳 ${t("chef_categories_label", "Kategoriyalar")}: ${categoryLabels}\n🔪 ${t("kitchen_station_label", "Bo'lim")}: ${stationLabel}\n(${t("save_password_note")})`,
      "success"
    );

    document.getElementById("chefName").value = "";
    document.getElementById("chefPassword").value = "";
    const headChefEl = document.getElementById("chefIsHeadChef");
    if (headChefEl) headChefEl.checked = false;
    renderKitchenStationSelect(document.getElementById("chefKitchenStation"), "");

    // Checkboxlarni tozalash
    const chefContainer = document.getElementById("chefCategoryContainer");
    if (chefContainer) {
      chefContainer.querySelectorAll("input[name='chefCategory']").forEach(cb => { cb.checked = false; });
    }
  } catch (err) {
    console.error(err);
    showAdminNotification(t("error_occurred"), "error");
  }
};

