window.saveNewTable = async function () {
  const numInput = document.getElementById("__addTableNum");
  const countInput = document.getElementById("__addTableCount");
  const capacityInput = document.getElementById("__addTableCapacity");
  const activeInput = document.getElementById("__addTableActive");

  let tableNum = parseInt(numInput?.value || 0);
  let tableCount = Math.max(1, parseInt(countInput?.value || 1) || 1);
  let tableCapacity = parseInt(capacityInput?.value || 0) || null;
  let isActive = activeInput ? !!activeInput.checked : true;
  // 🆕 Xizmat narxi — aniq summa (foiz emas), bo'sh/0/manfiy → 0.
  const serviceAmountVal = Math.max(0, Number(document.getElementById("__addTableServiceAmount")?.value || 0)) || 0;
  const customIconVal = document.getElementById("__addTableTypeCustomIcon")?.value?.trim() || "";

  // Tur: standart ro'yxatdan yoki admin kiritgan yangi nom
  let tableType = window.resolveTableType("__selectedTableType", "__addTableTypeCustom");
  if (tableType === null) {
    showAdminNotification(t("table_type_name_required", "Yangi tur nomini kiriting!"), "error");
    return;
  }

  if (!tableNum || tableNum < 1) {
    showAdminNotification(t("table_number_required", "Stol raqamini kiriting!"), "error");
    return;
  }
  if (!tableType) tableType = "oddiy";

  const restId = localStorage.getItem("restaurantId");
  const normalizedType = tableType.toLowerCase();

  // ── Tarif bo'yicha stollar soni limitini tekshirish ──
  const existingTablesCount = Object.keys(window.allTables || {}).length;
  const projectedTotal = existingTablesCount + tableCount;
  const tableLimitCheck = await window.checkNumericPlanLimit(restId, "maxTables", projectedTotal);
  if (!tableLimitCheck.ok) {
    const remaining = Math.max(0, tableLimitCheck.limit - existingTablesCount);
    showAdminNotification(
      t("table_limit_reached_error", "⛔ Tarifingiz bo'yicha stollar soni limiti tugagan! Joriy: {current}, Limit: {limit}. Yana faqat {remaining} ta stol qo'sha olasiz.")
        .replace("{current}", existingTablesCount).replace("{limit}", tableLimitCheck.limit).replace("{remaining}", remaining),
      "error"
    );
    return;
  }

  const added = [];
  const skipped = [];

  try {
    for (let i = 0; i < tableCount; i++) {
      const num = tableNum + i;
      const key = `table_${num}`;

      // Bunday stol raqami mavjudmi tekshiramiz
      const existing = window.allTables?.[key];
      if (existing) {
        skipped.push(num);
        continue;
      }

      await set(ref(db, `${BASE_PATH}/tables/${key}`), {
        number: num,
        tableType: normalizedType,
        capacity: tableCapacity,
        active: isActive,
        status: "free",
        tableServiceAmount: serviceAmountVal,
        createdAt: Date.now()
      });

      // Keyingi iteratsiyada dublikat tekshiruvi to'g'ri ishlashi uchun
      // lokal ro'yxatni ham yangilab qo'yamiz
      window.allTables = window.allTables || {};
      window.allTables[key] = { number: num, tableType: normalizedType, capacity: tableCapacity, active: isActive, status: "free", tableServiceAmount: serviceAmountVal };

      added.push(num);
    }

    if (added.length > 0) {
      const label = added.length === 1
        ? t("table_added_label_single", "Stol №{num}").replace("{num}", added[0])
        : t("table_added_label_multi", "{count} ta stol (№{first}–№{last})").replace("{count}", added.length).replace("{first}", added[0]).replace("{last}", added[added.length - 1]);

      if (typeof window.logSystemAction === "function") {
        await window.logSystemAction("update", t("audit_table_added", "➕ {label} qo'shildi (tur: {type})").replace("{label}", label).replace("{type}", tableType));
      }
    }

    // 🆕 Custom tur uchun ikon berilgan bo'lsa — bir marta, yagona
    // canonical manbaga (getTableTypeMeta() shu yerdan o'qiydi) yoziladi.
    if (added.length > 0 && customIconVal) {
      await update(ref(db, `${BASE_PATH}/settings/customTableTypeIcons`), {
        [normalizedType]: customIconVal
      });
    }

    if (added.length > 0 && skipped.length === 0) {
      showAdminNotification(
        added.length === 1
          ? t("table_added_success_single", "✅ Stol №{num} ({type}) qo'shildi!").replace("{num}", added[0]).replace("{type}", tableType)
          : t("table_added_success_multi", "✅ {count} ta stol qo'shildi (№{first}–№{last})!").replace("{count}", added.length).replace("{first}", added[0]).replace("{last}", added[added.length - 1]),
        "success"
      );
    } else if (added.length > 0 && skipped.length > 0) {
      showAdminNotification(
        t("table_added_partial_success", "✅ {count} ta stol qo'shildi. ⚠️ Mavjud bo'lgani uchun o'tkazib yuborildi: №{skipped}")
          .replace("{count}", added.length).replace("{skipped}", skipped.join(", №")),
        "warning"
      );
    } else {
      showAdminNotification(t("tables_all_exist_error", "Barcha stol raqamlari (№{numbers}) allaqachon mavjud!").replace("{numbers}", skipped.join(", №")), "error");
      return;
    }

    document.getElementById("__addTableModal")?.remove();
  } catch (err) {
    console.error("Stol qo'shishda xato:", err);
    showAdminNotification(t("notify_error", "Xatolik yuz berdi"), "error");
  }
};

