// ─── CRM ─────────────────────────────────────────────────
async function loadCRM() {
  const statsEl = document.getElementById("crmStats");
  const listEl = document.getElementById("customerList");
  if (!statsEl || !listEl) return;
  try {
    const [ordersSnap, customersSnap, usersSnap] = await Promise.all([
      get(ref(db, BASE_PATH + "/orders")), get(ref(db, BASE_PATH + "/customers")), get(ref(db, BASE_PATH + "/users"))
    ]);
    window.customerProfilesByPhone = buildCustomerProfilePhoneCache(customersSnap.val() || {});
    crmState.customers = buildCustomerMapFromOrders(
      ordersSnap.val() || {}, customersSnap.val() || {}, usersSnap.val() || {}
    );
    crmState.filtered = [...crmState.customers];
    injectCRMPhoneLookupPanel();
    renderCRMStats();
    renderCustomerList();
    const searchInput = document.getElementById("customerSearch");
    if (searchInput && !searchInput.dataset.bound) {
      searchInput.dataset.bound = "1";
      searchInput.addEventListener("input", filterCustomers);
    }
  } catch (err) {
    console.error(t("crm_load_error_log"), err);
    showAdminNotification(t("crm_load_error"), "error");
  }
}

// ══════════════════════════════════════════════════════
// 👥 CUSTOMERS MODULE — top-level nav (RBAC module "customers")
// Reuses buildCustomerMapFromOrders() (same merged orders+customers/+users
// source loadCRM() already uses) — no new Firebase listeners, one-off get()
// reads on section open only. Anonymous (phone-less) customers are dropped
// here — per spec they're never identifiable/trackable.
// ══════════════════════════════════════════════════════
window._custModuleState = { all: [], filtered: [] };

// 🩹 Root-cause fix (Sozlamalar → Mijozlar chegirmasi "yonib-o'chish"):
// saveCustomerDiscount() darhol to'g'ri qiymatni optimistic patch bilan
// ko'rsatgach, ORQA FONDA to'liq re-sync uchun shu funksiyani chaqiradi —
// lekin bu funksiya har doim (fon rejimida ham) gridni "Yuklanmoqda..."
// spinneriga almashtirib qo'yardi, keyin Firebase round-trip tugagach qayta
// chizardi. Bir zumlik "0%/bo'sh" ko'rinish shu yerdan — ma'lumot noto'g'ri
// emas, faqat orqa fon sinxronizatsiyasi keraksiz ravishda ko'rinadigan
// spinner bilan UI'ni "yangilab" qo'yardi. `silent=true` — bo'lim birinchi
// marta ochilgandagi haqiqiy yuklanish holatini o'zgartirmaydi, faqat
// keyingi fon-sinxronizatsiya chaqiruvlari (Saqlashdan keyingi) uchun.
async function loadCustomersModule(silent = false) {
  const gridEl = document.getElementById("custListGrid");
  if (!gridEl) return;
  if (!silent) gridEl.innerHTML = `<div class="cust-empty-state">${t("loading", "Yuklanmoqda...")}</div>`;
  if (typeof window._authRuleDiag === "function") await window._authRuleDiag("loadCustomersModule", BASE_PATH + "/customers");
  try {
    const [ordersSnap, customersSnap, usersSnap] = await Promise.all([
      get(ref(db, BASE_PATH + "/orders")), get(ref(db, BASE_PATH + "/customers")), get(ref(db, BASE_PATH + "/users"))
    ]);
    window._custModuleState.all = buildCustomerMapFromOrders(
      ordersSnap.val() || {}, customersSnap.val() || {}, usersSnap.val() || {}
    ).filter(c => c.phone);
    window._custModuleState.filtered = [...window._custModuleState.all];
    renderCustomerStatsRow(window._custModuleState.all);
    window.filterCustomersModule();
    // Fon-sinxronizatsiya butunlay yangi obyektlar bilan _custModuleState'ni
    // qayta quradi — ochiq turgan profil modali (agar bo'lsa) ham shu yangi
    // obyektdan qayta chizilishi kerak, aks holda modal eski (patch qilingan,
    // lekin endi eskirgan referens) obyektni ko'rsatishda davom etadi.
    if (silent && window._custProfileCurrentId) _refreshOpenCustomerProfile();
  } catch (err) {
    console.error("loadCustomersModule error:", err);
    if (!silent) gridEl.innerHTML = `<div class="cust-empty-state">${t("customers_load_error", "Mijozlarni yuklashda xatolik")}</div>`;
  }
}

function renderCustomerStatsRow(customers) {
  const el = document.getElementById("custStatsRow");
  if (!el) return;
  const now = Date.now(), DAY = 86400000;
  const total = customers.length;
  // "Yangi" — birinchi (yagona) tashrifi so'nggi 30 kun ichida bo'lganlar
  // (buildCustomerMapFromOrders customer.createdAt bermaydi, shu sababli
  // eng yaqin ishonchli proksi — visits<=1 va lastVisit yaqinda).
  const newCustomers = customers.filter(c => c.visits <= 1 && c.lastVisit >= now - 30 * DAY).length;
  const returning = customers.filter(c => c.visits > 1).length;
  const totalVisits = customers.reduce((s, c) => s + Number(c.visits || 0), 0);
  const totalSpent = customers.reduce((s, c) => s + Number(c.totalSpent || 0), 0);
  const totalPoints = customers.reduce((s, c) => s + Number(c.loyaltyPoints || 0), 0);
  const avgVisits = total ? (totalVisits / total) : 0;
  const avgCheck = totalVisits ? (totalSpent / totalVisits) : 0;
  const ltv = total ? (totalSpent / total) : 0;

  const topSpenders = [...customers].sort((a, b) => b.totalSpent - a.totalSpent).slice(0, 5);
  const mostActive = [...customers].sort((a, b) => b.visits - a.visits).slice(0, 5);

  const miniList = (list, valueFn) => list.length
    ? list.map(c => `<div style="display:flex;justify-content:space-between;font-size:12.5px;padding:4px 0;">
        <span style="cursor:pointer;color:var(--text-secondary);" onclick="window.openCustomerProfile('${escapeHtml(c.id)}')">${escapeHtml(c.name || c.phone)}</span>
        <b>${valueFn(c)}</b></div>`).join("")
    : `<div style="font-size:12px;color:var(--text-muted);">${t("customers_no_data", "Ma'lumot yo'q")}</div>`;

  el.innerHTML = `
    <div class="cust-stat-card"><div class="cust-stat-label">${t("customers_stat_new", "Yangi mijozlar")}</div><div class="cust-stat-value">${newCustomers}</div></div>
    <div class="cust-stat-card"><div class="cust-stat-label">${t("customers_stat_returning", "Qaytgan mijozlar")}</div><div class="cust-stat-value">${returning}</div></div>
    <div class="cust-stat-card"><div class="cust-stat-label">${t("customers_stat_ltv", "LTV")}</div><div class="cust-stat-value">${formatMoney(ltv)}</div></div>
  `;
}

function renderCustomerListGrid(customers) {
  const el = document.getElementById("custListGrid");
  if (!el) return;
  if (!customers.length) {
    el.innerHTML = `<div class="cust-empty-state">🔍 ${t("customers_empty", "Mijozlar topilmadi")}</div>`;
    return;
  }
  el.innerHTML = customers.map(c => {
    const initial = (c.name || c.phone || "?").trim().charAt(0).toUpperCase();
    // 🆕 QR bir martalik chegirma — faqat status==="available" claimlar
    // (ishlatilgan/tugagan claimlar bu yerda ko'rinmaydi, spec §21).
    const bestOneTime = Object.values(c.oneTimeDiscounts || {})
      .filter(v => v.status === "available")
      .sort((a, b) => Number(b.percent || 0) - Number(a.percent || 0))[0] || null;
    return `
    <div class="cust-card" onclick="window.openCustomerProfile('${escapeHtml(c.id)}')">
      <div class="cust-card-top">
        <div class="cust-avatar">${escapeHtml(initial)}</div>
        <div style="min-width:0;">
          <div class="cust-card-name">${escapeHtml(c.name || t("unknown_customer", "Noma'lum mijoz"))}</div>
          <div class="cust-card-phone">${escapeHtml(c.phone)}</div>
        </div>
      </div>
      <div class="cust-card-meta">
        <span>💰 <b>${Number(c.discountPercent || 0)}%</b></span>
        <span>🔁 <b>${c.visits}</b> ${t("customers_visits_short", "tashrif")}</span>
        <span>🛒 <b>${c.ordersCount ?? c.visits}</b> ${t("customers_orders_short", "buyurtma")}</span>
        <span>💵 <b>${formatMoney(c.totalSpent)}</b></span>
      </div>
      ${bestOneTime ? `<div class="cust-card-meta" style="margin-top:4px;">
        <span style="color:#16a34a;">🎁 <b>${Number(bestOneTime.percent)}%</b> — ${t("remaining_uses_label", "Qolgan foydalanish")}: ${Number(bestOneTime.usageLimit || 1) - Number(bestOneTime.usageCount || 0)}/${Number(bestOneTime.usageLimit || 1)}</span>
      </div>` : ""}
    </div>`;
  }).join("");
}

window.filterCustomersModule = function () {
  const all = window._custModuleState.all || [];
  const q = (document.getElementById("custSearchInput")?.value || "").trim().toLowerCase();
  const dMin = document.getElementById("custFilterDiscountMin")?.value;
  const dMax = document.getElementById("custFilterDiscountMax")?.value;
  const vMin = document.getElementById("custFilterVisitsMin")?.value;
  const vMax = document.getElementById("custFilterVisitsMax")?.value;
  const sMin = document.getElementById("custFilterSpentMin")?.value;
  const sMax = document.getElementById("custFilterSpentMax")?.value;
  const lastVisit = document.getElementById("custFilterLastVisit")?.value || "";
  const now = Date.now(), DAY = 86400000;

  const filtered = all.filter(c => {
    if (q && !(String(c.name || "").toLowerCase().includes(q) || String(c.phone || "").toLowerCase().includes(q))) return false;
    if (dMin !== "" && dMin != null && Number(c.discountPercent || 0) < Number(dMin)) return false;
    if (dMax !== "" && dMax != null && Number(c.discountPercent || 0) > Number(dMax)) return false;
    if (vMin !== "" && vMin != null && Number(c.visits || 0) < Number(vMin)) return false;
    if (vMax !== "" && vMax != null && Number(c.visits || 0) > Number(vMax)) return false;
    if (sMin !== "" && sMin != null && Number(c.totalSpent || 0) < Number(sMin)) return false;
    if (sMax !== "" && sMax != null && Number(c.totalSpent || 0) > Number(sMax)) return false;
    if (lastVisit === "365+") { if (!(c.lastVisit && c.lastVisit < now - 365 * DAY)) return false; }
    else if (lastVisit) { if (!(c.lastVisit && c.lastVisit >= now - Number(lastVisit) * DAY)) return false; }
    return true;
  });

  window._custModuleState.filtered = filtered;
  renderCustomerListGrid(filtered);
};

// ── Customer profile modal ──────────────────────────────────────────────
// 🆕 QR/usage-limited bir martalik mijoz chegirmasi — customer profil
// panelida (spec §4/§10/§12). "available" claim (usageCount < usageLimit) —
// aktiv chegirma + "Qolgan foydalanish: N/M" sifatida; "exhausted" claim —
// pastda alohida "Chegirma tarixi"da "M/M ishlatildi ✅ Tugagan" sifatida
// (audit uchun qoladi, lekin aktiv badge sifatida ENDI ko'rinmaydi — spec
// §4/§10/§21ning aynan o'zi).
function _renderOneTimeDiscountsSection(c, canGrant) {
  const entries = Object.entries(c.oneTimeDiscounts || {});
  const available = entries.filter(([, v]) => v.status === "available").sort((a, b) => Number(b[1].percent || 0) - Number(a[1].percent || 0));
  const exhausted = entries.filter(([, v]) => v.status === "exhausted").sort((a, b) => Number(b[1].claimedAt || 0) - Number(a[1].claimedAt || 0)).slice(0, 5);

  const availableHtml = available.map(([, v]) => {
    const limit = Number(v.usageLimit || 1);
    const used = Number(v.usageCount || 0);
    return `
    <div style="display:flex;justify-content:space-between;align-items:center;background:#f0fdf4;border:1.5px solid #86efac;border-radius:10px;padding:8px 12px;margin-bottom:6px;font-size:13px;">
      <span>🎁 <b style="color:#16a34a;">${Number(v.percent)}%</b></span>
      <span>${t("remaining_uses_label", "Qolgan foydalanish")}: <b>${limit - used}/${limit}</b></span>
    </div>`;
  }).join("");

  const exhaustedHtml = exhausted.length ? `
    <div style="font-size:12px;color:var(--text-muted);margin:8px 0 4px;">${t("discount_history_label", "Chegirma tarixi")}</div>
    ${exhausted.map(([, v]) => {
      const limit = Number(v.usageLimit || 1);
      return `
      <div style="display:flex;justify-content:space-between;align-items:center;font-size:12.5px;padding:4px 0;color:var(--text-secondary);">
        <span>🎁 ${Number(v.percent)}% — ${limit}/${limit} ${t("discount_used_label", "ishlatilgan")} ✅ ${t("discount_exhausted_label", "Tugagan")}</span>
      </div>`;
    }).join("")}
  ` : "";

}

window.grantOneTimeDiscountUi = async function (phone) {
  const pct = Number(document.getElementById("custGrantPercent")?.value || 0);
  const usageLimit = Number(document.getElementById("custGrantUsageLimit")?.value || 0);
  if (!(pct > 0) || pct > 100) { alert(t("customers_discount_range_error", "Chegirma 0 dan 100 gacha bo'lishi kerak")); return; }
  if (!Number.isFinite(usageLimit) || usageLimit <= 0) { alert(t("customers_usage_limit_error", "Foydalanish soni 1 yoki undan katta bo'lishi kerak")); return; }
  try {
    const result = await discountClaimsClient.grant(currentRestaurantId, phone, pct, usageLimit);
    if (!result.ok) { showAdminNotification(t("qr_discount_claim_failed", "Chegirmani saqlashda xatolik yuz berdi"), "error"); return; }
    showAdminNotification(t("qr_discount_saved", "Chegirma saqlandi"), "success");
    _refreshOpenCustomerProfile();
  } catch (err) {
    console.error("grantOneTimeDiscountUi error:", err);
    showAdminNotification(t("qr_discount_claim_failed", "Chegirmani saqlashda xatolik yuz berdi"), "error");
  }
};

