window.saveCustomerDiscount = async function (phone) {
  const input = document.getElementById("custDiscountInput");
  const pct = Number(input?.value || 0);
  if (pct < 0 || pct > 100) { alert(t("customers_discount_range_error", "Chegirma 0 dan 100 gacha bo'lishi kerak")); return; }
  try {
    // Firebase update() to'liq bajarilguncha (await) hech qanday muvaffaqiyat
    // xabari ko'rsatilmaydi — agar update() reject bo'lsa, quyidagi catch
    // blokiga tushadi va faqat xatolik xabari chiqadi, "saqlandi" emas.
    await applyCustomerDiscount(phone, { discountPercent: pct });

    // Optimistic local patch — server'dan to'liq qayta o'qishni (quyidagi
    // loadCustomersModule()) kutmasdan, modal va kartani DARHOL yangi
    // qiymat bilan yangilaydi. normalizePhone bilan solishtiriladi, chunki
    // ro'yxatdagi ba'zi mijoz yozuvlari (buyurtmadan kelgan, hali
    // formatlanmagan raqam bilan) va profildagi (har doim normallashtirilgan)
    // xom ko'rinishi farq qilishi mumkin — buildCustomerMapFromOrders'dagi
    // tuzatish bilan bir xil solishtirish mantig'i.
    const normalizedTarget = normalizePhone(phone);
    (window._custModuleState?.all || []).forEach(c => {
      if (normalizePhone(c.phone) === normalizedTarget) c.discountPercent = pct;
    });
    (window._custModuleState?.filtered || []).forEach(c => {
      if (normalizePhone(c.phone) === normalizedTarget) c.discountPercent = pct;
    });
    renderCustomerListGrid(window._custModuleState?.filtered || []);
    _refreshOpenCustomerProfile();

    // 🩹 Root-cause fix — "modalda 3%, cardda 0% qolib ketadi": bu loyihada
    // customer ma'lumotlari IKKI ALOHIDA joyda saqlanadi — "Mijozlar" moduli
    // (_custModuleState, yuqorida allaqachon patch qilinadi) va eski
    // "CRM/Loyalty" bo'limi (crmState, listenCustomersRealtime()dagi
    // real-time listener orqali, lekin FAQAT "loyalty" bo'limi active bo'lsa
    // yangilanadi — "Mijozlar" ko'rinib turganda bu listener crmState'ga
    // tegmaydi). Agar admin ko'rib turgan card aslida crmState'dan
    // renderlansa, u ushbu Saqlash bosilgunga qadar hech qachon yangilanmas
    // edi. Xuddi shu optimistic patch shu yerda ham qo'llaniladi — ikkinchi
    // Firebase o'qish/listener yaratilmaydi, faqat mavjud xotiradagi holat.
    (window.crmState?.customers || []).forEach(c => {
      if (normalizePhone(c.phone) === normalizedTarget) c.discountPercent = pct;
    });
    (window.crmState?.filtered || []).forEach(c => {
      if (normalizePhone(c.phone) === normalizedTarget) c.discountPercent = pct;
    });
    if (document.getElementById("customerList") && typeof renderCustomerList === "function") {
      renderCustomerList();
    }

    showAdminNotification(t("customers_discount_saved", "Chegirma saqlandi"), "success");

    // Server bilan to'liq sinxronlash — fon rejimida, UI allaqachon yangi
    // qiymatni ko'rsatib turibdi, shuning uchun buni kutish shart emas.
    // silent=true — gridni "Yuklanmoqda..." spinneriga almashtirmaydi (item 1.2).
    loadCustomersModule(true).catch(err => console.error("post-save reload error:", err));
  } catch (err) {
    console.error("saveCustomerDiscount error:", err);
    showAdminNotification(t("error_occurred", "Xatolik"), "error");
  }
};

