// ── Timeline: buyurtmalar + bronlar + status/chegirma tarixi (bitta martalik
// o'qish, profil ochilganda — doimiy listener emas) ──
async function _loadCustomerTimeline(c, myOrders) {
  const box = document.getElementById("custTimelineBox");
  if (!box) return;
  const restId = localStorage.getItem("restaurantId");
  const items = [];

  myOrders.forEach(o => {
    const type = normalizeOrderType(o);
    const cls = type === ORDER_TYPE.DELIVERY ? "tl-delivery" : "tl-order";
    const icon = type === ORDER_TYPE.DELIVERY ? "🛵" : type === ORDER_TYPE.TAKEAWAY ? "🥡" : "🍽";
    const paidTag = o.payment?.paid ? ` · ✅ ${t("payment_status_paid", "To'landi")}` : "";
    items.push({
      time: o.createdAt || o.paidAt || 0, cls,
      desc: `${icon} ${t("orders_list", "Buyurtma")} #${o.orderNumber || ""} — ${formatMoney(o.finalTotal || o.total || 0)}${paidTag}`
    });
  });

  try {
    const [resvSnap, logsSnap] = await Promise.all([
      get(ref(db, `restaurants/${restId}/reservations`)),
      get(ref(db, `restaurants/${restId}/activityLogs`)),
    ]);
    Object.values(resvSnap.val() || {}).forEach(r => {
      if (normalizePhone(r.phone || "") !== c.phone) return;
      items.push({
        time: r.createdAt || new Date(`${r.date}T${r.time || "00:00"}`).getTime() || 0,
        cls: "tl-reservation",
        desc: `📅 ${t("reservations_title", "Bron")}: ${r.date} ${r.time || ""} · ${r.guests || ""} ${t("notif_guests_label", "kishi")} (${r.status || "pending"})`
      });
    });
    Object.values(logsSnap.val() || {}).forEach(l => {
      if (l.module !== "customers" || (l.target || l.targetId) !== c.phone) return;
      items.push({ time: l.timestamp || l.time || l.createdAt || 0, cls: "tl-discount", desc: `💳 ${l.description || ""}` });
    });
  } catch (_e) { /* bron/audit o'qib bo'lmasa ham buyurtma tarixini ko'rsatamiz */ }

  items.sort((a, b) => b.time - a.time);
  box.innerHTML = items.length
    ? items.slice(0, 40).map(it => `
      <div class="cust-timeline-item ${it.cls}">
        <div class="cust-timeline-time">${it.time ? new Date(it.time).toLocaleString(currentDateLocale()) : ""}</div>
        <div class="cust-timeline-desc">${it.desc}</div>
      </div>`).join("")
    : `<div class="cust-timeline-item">${t("customers_no_history", "Tarix mavjud emas")}</div>`;
}

const loyaltySyncInFlight = new Set();

/* =========================
   MIJOZ TASHRIFLARINI SANASH 
========================= */
async function applyAutoLoyaltyToOrder(orderId, order, ordersObj = {}) {
  const phone = normalizePhone(order.customerPhone || order.phone || order.clientPhone || "");
  if (!phone) return;
  if (order.payment?.paid) return;

  const previousVisits = countCustomerVisitsByPhone(phone, ordersObj, orderId);
  const currentVisitNumber = previousVisits + 1;
  const loyaltyLevel = getLoyaltyLevel(0, currentVisitNumber);

  const discountPercent = getLoyaltyDiscountPercent(previousVisits);

  const customerName = order.customerName || order.clientName || order.name || `${t("table")} ${order.table || uiEmpty()}`;

  const updates = {
    customerId: phone,
    customerPhone: phone,
    customerName,
    loyaltyLevel,
    loyaltyVisits: currentVisitNumber,
    loyaltyAutoApplied: true,
    updatedAt: Date.now()
  };

  if (discountPercent > 0 && !order.discountApplied) {
    const currentTotal = Number(order.total || 0);
    const discountAmount = (currentTotal * discountPercent) / 100;
    const newTotal = currentTotal - discountAmount;

    updates.originalTotal = currentTotal;
    updates.total = newTotal;
    updates.discountPercent = discountPercent;
    updates.discountApplied = true;

    showAdminNotification(`🎉 ${t("client_label", "Mijoz")} (${phone}) ${discountPercent}% ${t("discount_received", "chegirma oldi! Yangi narx:")} ${newTotal}`);
  }

  await update(ref(db, `${BASE_PATH}/orders/${orderId}`), updates);
}

window.cancelOrder = async function (orderId) {
  if (!orderId) return;

  const confirmCancel = confirm(
    t("confirm_cancel_order", "Buyurtmani bekor qilmoqchimisiz?")
  );

  if (!confirmCancel) return;

  try {
    const orderRef = ref(db, `${BASE_PATH}/orders/${orderId}`);

    const orderSnap = await get(orderRef);

    if (!orderSnap.exists()) {
      showAdminNotification(
        t("order_not_found", "Buyurtma topilmadi"),
        "error"
      );
      return;
    }

    const order = orderSnap.val();

    // Production Security Fix Pass, Phase 3 (cancellation consistency),
    // completed here (Phase 4 verification pass — the original guard had a
    // real gap): checking order.payment?.paid from the plain get() above and
    // only THEN writing status via a separate update() left a TOCTOU window —
    // writeUnifiedPayment's own atomic claim (paymentEngine.js) could
    // complete in between, and this check would never see it, landing on
    // exactly the payment.paid:true + status:"canceled" contradiction this
    // guard exists to prevent. Replaced with a single runTransaction on
    // orders/{id}/status so "is this order already paid/terminal" and the
    // cancel write happen atomically — no window for a concurrent payment to
    // slip through. (status and payment.paid are always written together by
    // writeUnifiedPayment's multi-path update, so checking status alone here
    // is equivalent to checking paid.)
    const statusRef = ref(db, `${BASE_PATH}/orders/${orderId}/status`);
    const cancelClaim = await runTransaction(statusRef, (current) => {
      const terminal = current === "to'landi" || current === "paid" || current === "canceled";
      if (terminal) return; // abort — already paid or already cancelled
      return "canceled";
    });
    if (!cancelClaim.committed || cancelClaim.snapshot.val() !== "canceled") {
      showAdminNotification(
        t("cancel_paid_order_blocked", "To'langan buyurtmani bekor qilib bo'lmaydi — avval qaytarish (refund) amalga oshiring."),
        "error"
      );
      return;
    }

    if (order.table) {
      await update(
        ref(db, `${BASE_PATH}/tables/${getTableKey(order.table)}`),
        {
          status: "free",
          busy: false,
          orderId: null
        }
      );
    }

    // status itself was already set atomically by the runTransaction claim
    // above — this only fills in the remaining metadata fields.
    await update(orderRef, {
      statusKey: "canceled",
      statusLabel: "canceled",
      canceledAt: Date.now(),
      canceledBy: currentUserId || "admin"
    });

    // Ingredients already deducted for this order (it reached kitchen/ready
    // before being cancelled) — restore them instead of letting stock
    // silently and permanently shrink. No-ops safely if nothing was ever
    // deducted (restoreOrderInventory checks inventoryDeducted itself).
    if (order.inventoryDeducted === true && typeof window.restoreOrderInventory === "function") {
      await window.restoreOrderInventory(orderId);
    }

    // Courier sync: a delivery order can already have a live
    // courierAssignments/{id} record (see assignOrderToCourier) that
    // courier.js reads independently of orders/{id} — nothing previously
    // touched that record on cancel, so a courier's app kept showing an
    // active delivery for an order that no longer existed. Mark every
    // matching, not-yet-delivered assignment cancelled so courier.js (which
    // already listens to courierAssignments live) reflects it immediately.
    try {
      const assignQuery = query(ref(db, `${BASE_PATH}/courierAssignments`), orderByChild("orderId"), equalTo(orderId));
      const assignSnap = await get(assignQuery);
      if (assignSnap.exists()) {
        const updates = {};
        assignSnap.forEach((child) => {
          const status = child.val()?.status;
          if (status !== "delivered" && status !== "completed" && status !== "cancelled") {
            updates[`${child.key}/status`] = "cancelled";
            updates[`${child.key}/cancelledAt`] = Date.now();
          }
        });
        if (Object.keys(updates).length) {
          await update(ref(db, `${BASE_PATH}/courierAssignments`), updates);
        }
      }
    } catch (courierSyncErr) {
      // Non-fatal — the order cancellation itself already succeeded above;
      // a courier-sync hiccup shouldn't be reported as the cancel failing.
      console.error("cancelOrder courier sync xato:", courierSyncErr);
    }

    if (typeof window.createOrderTimelineEvent === "function") {
      await window.createOrderTimelineEvent(
        orderId,
        "order_canceled",
        {
          canceledBy: currentUserId || "admin"
        }
      );
    }

    if (typeof crmAdvAudit === "function") {
      await crmAdvAudit(
        "orders",
        "cancel",
        orderId,
        t("audit_order_canceled", "Buyurtma bekor qilindi"),
        {},
        "warning"
      );
    }

    showAdminNotification(
      t("order_canceled_success", "Buyurtma bekor qilindi"),
      "success"
    );

  } catch (error) {
    console.error("Cancel order error:", error);

    showAdminNotification(
      t("notify.error", "Xatolik yuz berdi"),
      "error"
    );
  }
};

async function syncCustomerProfileFromOrder(orderId, order, ordersObj = {}) {
  const phone = normalizePhone(
    order.customerPhone ||
    order.phone ||
    order.clientPhone ||
    ""
  );

  if (!phone) return;

  // Har doim fresh ma'lumot olish — allOrders eskirgan bo'lishi mumkin
  const restId = localStorage.getItem("restaurantId");
  let freshOrders = ordersObj;
  try {
    const freshSnap = await get(ref(db, `restaurants/${restId}/orders`));
    if (freshSnap.exists()) freshOrders = freshSnap.val();
  } catch (e) { /* fallback to passed ordersObj */ }

  const paidVisits = countCustomerVisitsByPhone(phone, freshOrders);
  const totalSpentFresh = sumCustomerPaidTotalByPhone(phone, freshOrders);
  const discountPercent = getLoyaltyDiscountPercent(paidVisits);
  const totalSpent = totalSpentFresh;

  // Alohida, oldindan mavjud grantVipStatus tizimi (isVip=true) bergan
  // mijozga har safar to'lov qilinganda avtomatik bronze/silver/gold
  // hisoblash uni ustidan yozib qo'ymasligi kerak — avval joriy isVip'ni
  // o'qib olamiz (Customers moduliga aloqasi yo'q — u yerda status yo'q).
  let loyaltyLevel = getLoyaltyLevel(totalSpentFresh, paidVisits);
  try {
    const curSnap = await get(ref(db, `${BASE_PATH}/customers/${crmAdvSafeKey(phone)}/isVip`));
    if (curSnap.exists() && curSnap.val() === true) loyaltyLevel = "vip";
  } catch (_e) { /* isVip o'qib bo'lmasa, oddiy avtomatik hisoblash bilan davom etamiz */ }

  await update(ref(db, `${BASE_PATH}/customers/${crmAdvSafeKey(phone)}`), {
    id: phone,
    phone,
    name: order.customerName || order.clientName || order.name || "",
    visits: paidVisits,
    loyalty: loyaltyLevel,
    loyaltyDiscountPercent: discountPercent,
    cashbackBalance: Number(order.cashbackBalance || 0),
    totalSpent,
    lastVisit: Date.now(),
    updatedAt: Date.now()
  });
}

function renderCRMStats() {
  const el = document.getElementById("crmStats");
  if (!el) return;
  const customers = Array.isArray(crmState.filtered) ? crmState.filtered : crmState.customers;
  const totalCustomers = customers.length;
  const vipMembers = customers.filter(c => c.loyalty === "vip").length;
  const returning = customers.filter(c => c.visits > 1).length;
  const avgSpend = totalCustomers
    ? customers.reduce((sum, c) => sum + Number(c.totalSpent || 0), 0) / totalCustomers : 0;
  const topVip = [...crmState.customers]
    .filter(c => c.loyalty === "vip").slice(0, 3)
    .map(c => `${escapeHtml(c.name)} (${formatMoney(c.totalSpent)})`).join("<br>") || uiEmpty();
  el.innerHTML = `
    <div class="stats-grid">
      <div class="stat-card"><h4>${t("crm_total_customers")}</h4><b>${totalCustomers}</b></div>
      <div class="stat-card"><h4>${t("crm_vip_customers")}</h4><b>${vipMembers}</b></div>
      <div class="stat-card"><h4>${t("crm_returning_customers")}</h4><b>${returning}</b></div>
      <div class="stat-card"><h4>${t("crm_avg_spend")}</h4><b>${formatMoney(avgSpend)}</b></div>
    </div>
  `;
}

function filterCustomers() {
  const q = normalizeText(document.getElementById("customerSearch")?.value || "");
  crmState.filtered = crmState.customers.filter(c =>
    normalizeText(c.name).includes(q) || normalizeText(c.phone).includes(q)
  );
  renderCRMStats();
  renderCustomerList();
}

