window.updatePrice = async function (id) {
  const restId = localStorage.getItem("restaurantId");
  if (!restId) return;

  const valInput = document.getElementById(`ing-price-val-${id}`);
  const newPrice = parseFloat(valInput ? valInput.value : NaN);

  if (isNaN(newPrice) || newPrice < 0) { alert(t("invalid_amount", "Noto'g'ri miqdor!")); return; }

  const ing = window.allInventory?.[id];
  const stock = parseFloat(ing?.stock || 0);
  const newTotal = stock > 0 ? Math.round(newPrice * stock * 100) / 100 : 0;

  try {
    await update(ref(db, `restaurants/${restId}/inventory/${id}`), { price: newPrice, totalPrice: newTotal });
    await update(ref(db, `restaurants/${restId}/ingredients/${id}`), { price: newPrice, totalPrice: newTotal });
    window.hidePriceInput(id);
    if (typeof showAdminNotification === "function") {
      showAdminNotification(`✅ ${t("ing_price_label", "Narxi")} ${t("updated", "yangilandi")}: ${newPrice.toLocaleString()}`, "success");
    }
    if (typeof window._recalcRecipeCost === "function") window._recalcRecipeCost();
  } catch (err) {
    alert(t("notify.error", "Xatolik yuz berdi") + ": " + err.message);
  }
};

window.updateTotalPrice = async function (id) {
  const restId = localStorage.getItem("restaurantId");
  if (!restId) return;

  const totalInput = document.getElementById(`ing-total-price-val-${id}`);
  const newTotal = parseFloat(totalInput ? totalInput.value : NaN);

  if (isNaN(newTotal) || newTotal < 0) { alert(t("invalid_amount", "Noto'g'ri miqdor!")); return; }

  const ing = window.allInventory?.[id];
  const stock = parseFloat(ing?.stock || 0);
  const newPrice = stock > 0 ? Math.round((newTotal / stock) * 100) / 100 : 0;

  try {
    await update(ref(db, `restaurants/${restId}/inventory/${id}`), { totalPrice: newTotal, price: newPrice });
    await update(ref(db, `restaurants/${restId}/ingredients/${id}`), { totalPrice: newTotal, price: newPrice });
    window.hideTotalPriceInput(id);
    if (typeof showAdminNotification === "function") {
      showAdminNotification(`✅ ${t("ing_total_price_label", "Jami summa")} ${t("updated", "yangilandi")}: ${newTotal.toLocaleString()}`, "success");
    }
    if (typeof window._recalcRecipeCost === "function") window._recalcRecipeCost();
  } catch (err) {
    alert(t("notify.error", "Xatolik yuz berdi") + ": " + err.message);
  }
};

