window._switchPromoTab = function (tab) {
  const activePanel = document.getElementById("promo-panel-active");
  const usedPanel = document.getElementById("promo-panel-used");
  const activeBtn = document.getElementById("promo-tab-active");
  const usedBtn = document.getElementById("promo-tab-used");
  if (!activePanel || !usedPanel || !activeBtn || !usedBtn) return;

  if (tab === "active") {
    activePanel.style.display = "";
    usedPanel.style.display = "none";
    activeBtn.style.color = "#4f46e5";
    activeBtn.style.borderBottom = "2px solid #4f46e5";
    activeBtn.style.marginBottom = "-2px";
    usedBtn.style.color = "#6b7280";
    usedBtn.style.borderBottom = "none";
    usedBtn.style.marginBottom = "0";
  } else {
    activePanel.style.display = "none";
    usedPanel.style.display = "";
    usedBtn.style.color = "#4f46e5";
    usedBtn.style.borderBottom = "2px solid #4f46e5";
    usedBtn.style.marginBottom = "-2px";
    activeBtn.style.color = "#6b7280";
    activeBtn.style.borderBottom = "none";
    activeBtn.style.marginBottom = "0";
  }
};

window.openCreatePromoModal = function () {
  const modal = document.getElementById("createPromoModal");
  if (modal) {
    modal.style.display = "flex";
    document.getElementById("newPromoCode").value = "";
    document.getElementById("newPromoPercent").value = "";
    document.getElementById("newPromoMaxUses").value = "1";
  }
};

window.closeCreatePromoModal = function () {
  const modal = document.getElementById("createPromoModal");
  if (modal) modal.style.display = "none";
};

window.saveNewPromo = async function () {
  const codeInput = document.getElementById("newPromoCode")?.value.trim().toUpperCase();
  const percentVal = Number(document.getElementById("newPromoPercent")?.value || 0);
  const maxUsesVal = Number(document.getElementById("newPromoMaxUses")?.value || 1);

  if (!percentVal || percentVal <= 0 || percentVal > 100) {
    alert(t("alerts_invalid_promo_percent", "Chegirma foizini 1–100 oralig'ida kiriting!"));
    return;
  }

  const code = codeInput || `PROMO${percentVal}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

  // Duplicate tekshirish
  const existing = await get(ref(db, `${BASE_PATH}/discounts/${code}`));
  if (existing.exists()) {
    alert(t("promo_duplicate_error", "Bu kod allaqachon mavjud! Boshqa kod kiriting."));
    return;
  }

  await set(ref(db, `${BASE_PATH}/discounts/${code}`), {
    code,
    percent: percentVal,
    used: false,
    usedCount: 0,
    maxUses: maxUsesVal,
    createdAt: Date.now(),
    createdBy: "admin"
  });

  showAdminNotification(`✅ ${t("promo_created_success", "Promokod yaratildi:").replace("{code}", code).replace("{percent}", percentVal)} ${code} — ${percentVal}%`);
  window.closeCreatePromoModal();
  window.loadPromocodesPanel();
};

window.deactivatePromo = async function (code) {
  if (!confirm(t("promo_deactivate_confirm", `"${code}" promokodini o'chirishni tasdiqlaysizmi?`).replace("{code}", code))) return;

  await update(ref(db, `${BASE_PATH}/discounts/${code}`), {
    used: true,
    deactivatedAt: Date.now(),
    deactivatedBy: "admin"
  });

  showAdminNotification(`✅ ${t("promo_deactivated", "Promokod o'chirildi:")}: ${code}`, "warning");
  window.loadPromocodesPanel();
};

let _reservationNoShowTimerStarted = false;

// 🩹 Audit fix: loadReservations() used to fetch reservations via a
// one-time get() every time the "Bronlar" tab was opened — a reservation
// created/edited by the waiter panel (which has its own live listener)
// while admin had this tab open would not appear until the admin left and
// reopened the tab. Kept live now by the single onValue() listener started
// once in init() (see _reservationsListenerStarted below) — see the
// Production Security Fix Pass, Phase 3 comment further down in this
// function for why this no longer starts its own second listener.
async function loadReservations() {
  const listEl = document.getElementById("reservationList");
  const statsEl = document.getElementById("reservationStats");
  const formEl = document.getElementById("reservationForm");
  const filtersEl = document.getElementById("reservationFilters");
  if (!listEl || !statsEl || !formEl || !filtersEl) return;
  try {
    // ⏰ Avtomatik "No Show" nazoratchisi: bir marta ishga tushiriladi,
    // keyin har daqiqada o'zi qayta tekshiradi (reservationState.list
    // "Bronlar" bo'limi qayta ochilganda yangi ma'lumot bilan yangilanadi).
    if (!_reservationNoShowTimerStarted) {
      _reservationNoShowTimerStarted = true;
      window.autoCheckReservations(); // darhol bir marta tekshirish
      setInterval(() => window.autoCheckReservations(), 60000);
    }

    formEl.innerHTML = `
    <div class="resv-modal-overlay" id="reservationModalOverlay">
      <div class="resv-modal">
        <div class="resv-modal-header">
          <h3 id="reservationModalTitle">${t("create_reservation_btn", "Yangi bron")}</h3>
          <button type="button" class="resv-modal-close" onclick="window.closeReservationModal()">✕</button>
        </div>
        <div class="form-grid">
          <input id="resGuestName" type="text" placeholder="${t("reservation_guest_name")}">
          <input id="resPhone" type="text" placeholder="${t("customer_phone")}">
          <input id="resDate" type="date" onchange="window._resvRefreshTableAvailability()">
          <input id="resTime" type="time" onchange="window._resvRefreshTableAvailability()">
          <input id="resGuests" type="number" min="1" placeholder="${t("guest_count")}">
          <div class="resv-table-field">
            <select id="resTable" onchange="window._resvRefreshTableAvailability()"></select>
            <div id="resTableAvailability" class="resv-table-availability"></div>
          </div>
          <input id="resSpecial" type="text" placeholder="${t("special_request_label")}">
          <select id="resStatus" style="display:none;">
            <option value="pending">${t("reservation_status_pending")}</option>
            <option value="confirmed">${t("reservation_status_confirmed")}</option>
            <option value="seated">${t("reservation_status_seated")}</option>
            <option value="completed">${t("reservation_status_completed")}</option>
            <option value="no_show">${t("reservation_status_no_show")}</option>
            <option value="canceled">${t("reservation_status_canceled")}</option>
          </select>
        </div>
        <input type="hidden" id="resEditId" value="">
        <div class="resv-modal-footer">
          <button type="button" class="btn" onclick="window.closeReservationModal()">${t("cancel_btn", "Bekor qilish")}</button>
          <button type="button" class="btn primary" id="reservationModalSaveBtn" onclick="createReservation()">${t("create_reservation_btn")}</button>
        </div>
      </div>
    </div>
  `;
    filtersEl.innerHTML = `
    <div class="resv-filter-bar">
      <div class="resv-filter-search">
        <input id="reservationSearchFilter" type="text" placeholder="${t("resv_search_placeholder", "Mehmon ismi yoki telefon")}" oninput="renderReservationList()">
      </div>
      <select id="reservationStatusFilter" onchange="renderReservationList()">
        <option value="all">${t("all_items", "Holati")}</option>
        <option value="pending">${t("reservation_status_pending")}</option>
        <option value="confirmed">${t("reservation_status_confirmed")}</option>
        <option value="seated">${t("reservation_status_seated")}</option>
        <option value="completed">${t("reservation_status_completed")}</option>
        <option value="no_show">${t("reservation_status_no_show")}</option>
        <option value="canceled">${t("reservation_status_canceled")}</option>
      </select>
      <select id="reservationTableFilter" onchange="renderReservationList()">
        <option value="all">${t("resv_filter_table", "Stol")}</option>
      </select>
      
      <button type="button" class="btn primary resv-new-btn" onclick="window.openReservationModal()">➕ ${t("resv_new_btn", "Yangi bron")}</button>
    </div>
  `;

    // Form/filters HTML above is built once per tab-open. The data itself
    // is kept live by the single onValue(BASE_PATH + "/reservations")
    // listener started once in init() below (Production Security Fix
    // Pass, Phase 3 — this used to be a SECOND, independent listener on the
    // exact same path, doubling reads/callback work for every reservation
    // change for as long as an admin session was open; the init() listener
    // already updates reservationState.list AND calls
    // renderReservationList() when the section is on screen, so opening
    // this tab just needs to render once immediately with whatever's
    // already loaded — no separate subscription needed).
    renderReservationListNow();

    function renderReservationListNow() {
      const tableFilterEl = document.getElementById("reservationTableFilter");
      if (tableFilterEl) {
        const selectedVal = tableFilterEl.value;
        const opts = Array.from(new Set(reservationState.list.map(r => r.tableNumber).filter(Boolean)))
          .sort((a, b) => Number(a) - Number(b))
          .map(tbl => `<option value="${escapeHtml(String(tbl))}">${escapeHtml(String(tbl))}</option>`).join("");
        tableFilterEl.innerHTML = `<option value="all">${t("resv_filter_table", "Stol")}</option>${opts}`;
        // Preserve the admin's current filter selection across live updates
        // (still valid if that table still has a reservation, else falls
        // back to "all" instead of silently resetting to the first option).
        if (Array.from(tableFilterEl.options).some(o => o.value === selectedVal)) {
          tableFilterEl.value = selectedVal;
        }
      }

      renderReservationStats();
      renderReservationList();
      if (typeof _resvView !== "undefined" && _resvView === "calendar" && typeof renderReservationCalendar === "function") {
        renderReservationCalendar();
      }
      if (typeof updateRealTimeStats === "function") updateRealTimeStats();
    }
  } catch (err) {
    console.error(t("reservations_load_error_log"), err);
    showAdminNotification(t("reservations_load_error"), "error");
  }
}

