function getRoleModules(role) {
  const tpl = ROLE_TEMPLATES[role];
  if (tpl && Array.isArray(tpl.modules)) return tpl.modules;
  return [];
}

let currentRoleUserId = null;

/** Restoranning custom (owner tomonidan yaratilgan) rollarini Firebase'dan yuklaydi */
async function loadCustomRoles() {
  try {
    const snap = await get(ref(db, `${BASE_PATH}/customRoles`));
    window._customRoles = snap.val() || {};
  } catch (e) {
    window._customRoles = {};
  }
  return window._customRoles;
}

/**
 * actions ni har bir modulga "translyatsiya" qiladi: { view: true } uslubidagi
 * yagona (flat) ruxsat ro'yxatini { moduleId: [action,...] } ob'ektiga aylantiradi.
 * backend/rbac.js dagi bir xil nomli funksiya bilan sinxron bo'lishi shart.
 */
function broadcastFlatActionsToModules(flatActions, modules) {
  const result = {};
  (modules || []).forEach(moduleId => {
    result[moduleId] = Array.isArray(flatActions) ? [...flatActions] : [];
  });
  return result;
}

/** Rol uchun to'liq permission ob'ekt (modules/actions/stats) qaytaradi: avval customRoles, keyin ROLE_TEMPLATES.
 * `actions` endi har doim { moduleId: [action,...] } shaklida (modulga xos ruxsatlar) —
 * eski, tekis (flat) massiv sifatida saqlangan customRoles hali ham o'qiladi (orqaga
 * moslik), lekin yangi saqlashlar har bir modul uchun alohida amallar bilan yoziladi. */
function resolveRoleConfig(role) {
  const custom = (window._customRoles || {})[role];
  if (custom) {
    const modules = Array.isArray(custom.modules) ? custom.modules : [];
    const actions = Array.isArray(custom.actions)
      ? broadcastFlatActionsToModules(custom.actions, modules) // eski (flat) format — orqaga moslik
      : (custom.actions && typeof custom.actions === "object" ? custom.actions : {});
    const stats = [];
    if (custom.special?.finance) stats.push("revenue", "profit", "debts_total");
    if (custom.special?.report) stats.push("orders_count", "avg_check");
    return {
      label: custom.name || role,
      modules,
      actions,
      stats: Array.from(new Set(stats)),
      isCustom: true
    };
  }
  const tpl = ROLE_TEMPLATES[role];
  if (tpl) {
    const actions = broadcastFlatActionsToModules(tpl.actions, tpl.modules);
    // moduleActions — ixtiyoriy, faqat ba'zi shablonlarda bor: rolning umumiy
    // (flat) actions ro'yxatidan farqli, aynan bitta modul uchun torroq/kengroq
    // ruxsat kerak bo'lganda (masalan Customers moduli: Manager "edit+discount"
    // ola oladi-yu, boshqa modullarida hali ham faqat "view+export" bo'lib
    // qoladi). Faqat shu modulni ustidan yozadi — boshqa modullar broadcast
    // qilingan flat actions bilan qoladi, hech narsa buzilmaydi.
    if (tpl.moduleActions) Object.assign(actions, tpl.moduleActions);
    return { ...tpl, actions, isCustom: false };
  }
  return { label: role, modules: [], actions: {}, stats: [], isCustom: false };
}

async function loadRoles() {
  const statsEl = document.getElementById("rolesStats");
  const tableEl = document.getElementById("rolesUsersTable");
  const templatesEl = document.getElementById("rolesTemplates");
  const searchEl = document.getElementById("rolesSearch");

  if (!statsEl || !tableEl || !templatesEl) return;

  await loadCustomRoles();
  await loadDisabledRoles();

  const snap = await get(ref(db, BASE_PATH + "/users"));
  const users = Object.entries(snap.val() || {}).map(([id, u]) => {
    const role = u.role || "waiter";
    const cfg = resolveRoleConfig(role);
    return {
      id,
      name: u.name || uiEmpty(),
      position: u.position || "",
      role,
      active: u.active !== false,
      modules: Array.isArray(u.modules) ? u.modules : cfg.modules,
      actions: (u.actions && typeof u.actions === "object") ? u.actions : cfg.actions,
      stats: Array.isArray(u.stats) ? u.stats : cfg.stats,
      isCustomOverride: Array.isArray(u.modules) || (u.actions && typeof u.actions === "object") || Array.isArray(u.stats)
    };
  });

  window.rolesLoadedUsers = users;

  renderRolesStats(users);
  renderRolesTemplates();
  renderRolesTable(users);
  // "Rollar" sub-tabidagi maxsus (custom) rollar jadvali — mavjud rol-builder IIFE ichida aniqlangan
  if (typeof window.rbLoadCustomRoles === "function") window.rbLoadCustomRoles();

  if (searchEl && !searchEl.dataset.bound) {
    searchEl.dataset.bound = "1";
    searchEl.addEventListener("input", () => {
      const q = normalizeText(searchEl.value);
      const filtered = (window.rolesLoadedUsers || []).filter(u =>
        normalizeText(u.name).includes(q) ||
        normalizeText(u.position || "").includes(q) ||
        normalizeText(t("role_" + u.role) || u.role).includes(q)
      );
      renderRolesTable(filtered);
    });
  }
}

function startNotificationsAutoRefresh() {
  if (window.__notificationsInterval) clearInterval(window.__notificationsInterval);

  window.__notificationsInterval = setInterval(() => {
    const section = document.getElementById("notifications");
    if (section && section.style.display !== "none") {
      loadNotifications();
    }
  }, 5000);
}

function renderRolesStats(users) {
  const statsEl = document.getElementById("rolesStats");
  if (!statsEl) return;

  const total = users.length;
  const owners = users.filter(u => u.role === "owner").length;
  const active = users.filter(u => u.active).length;
  const custom = users.filter(u => u.isCustomOverride).length;

  statsEl.innerHTML = `
      <div class="stats-grid">
        <div class="stat-card"><h4>${t("roles_total_users")}</h4><b>${total}</b></div>
        <div class="stat-card"><h4>${t("roles_admin_count")}</h4><b>${owners}</b></div>
        <div class="stat-card"><h4>${t("status_active")}</h4><b>${active}</b></div>
        <div class="stat-card"><h4>${t("roles_custom_permissions")}</h4><b>${custom}</b></div>
      </div>
    `;
}

