/* =========================
   🗂️ SOZLAMALAR — TASHQI TAB SWITCHING
   settings-general / settings-services / settings-payments /
   settings-terminal-print / settings-kitchen-monitor
   Terminal, Chop etish va Oshxona monitori paneliga birinchi marta
   kirilganda tegishli yuklovchi funksiyalar (agar mavjud bo'lsa)
   chaqiriladi — shu bilan ma'lumot doim yangi bo'ladi.
========================= */
// 🔗 Webhook bazaviy manzili — restoran/tenant ID asosida noyob URL
function PAYMENT_WEBHOOK_BASE() {
  return `https://api.nestacrm.uz/${currentRestaurantId || "your-restaurant"}`;
}

// 📋 Webhook URL ni buferga nusxalash
window._copyWebhookUrl = function (fieldId) {
  const input = document.getElementById(fieldId);
  if (!input) return;
  input.select();
  input.setSelectionRange(0, 99999);
  const finish = () => showToast?.(t("webhook_url_copied", "Webhook URL nusxalandi"), "success");
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(input.value).then(finish).catch(() => {
      document.execCommand("copy");
      finish();
    });
  } else {
    document.execCommand("copy");
    finish();
  }
};

// 👁 API kalit maydonlarini ko'rsatish/yashirish (Merchant ID, Service ID, Secret Key)
window._toggleKeyVisibility = function (fieldId, btn) {
  const input = document.getElementById(fieldId);
  if (!input) return;
  const isHidden = input.type === "password";
  input.type = isHidden ? "text" : "password";
  if (btn) {
    btn.innerText = isHidden ? "🙈" : "👁";
    btn.title = isHidden ? t("hide_label", "Yashirish") : t("show_label", "Ko'rsatish");
  }
};

// 🟢🟡🔴 To'lov provayder holatini aniqlash (sinxron, tarmoqqa murojaat qilmasdan)
// Natija: "connected" | "unconfigured" | "error"
// - unconfigured: yoqilgan, lekin kalit maydonlari umuman to'ldirilmagan
// - error: yoqilgan, ba'zi maydonlar to'ldirilgan, lekin format/talab noto'g'ri
//   (Merchant ID formati, Click uchun Service ID, Secret Key uzunligi — _testSinglePaymentProvider bilan bir xil qoidalar)
// - connected: yoqilgan va barcha maydonlar to'g'ri to'ldirilgan
function _computePaymentProviderStatus(provider) {
  const fields = PAYMENT_FIELD_MAP[provider];
  if (!fields) return null;

  const enabled = document.getElementById(`${provider}Enabled`)?.checked ?? true;
  if (!enabled) return "unconfigured";

  const merchantId = document.getElementById(fields.merchantId)?.value?.trim() || "";
  const secretKey = document.getElementById(fields.secretKey)?.value?.trim() || "";
  const serviceId = fields.serviceId ? (document.getElementById(fields.serviceId)?.value?.trim() || "") : null;

  const nothingFilled = !merchantId && !secretKey && (fields.serviceId ? !serviceId : true);
  if (nothingFilled) return "unconfigured";

  if (!merchantId) return "error";
  const merchantValid = (() => {
    if (provider === "payme") return /^[a-f0-9]{16,}$/i.test(merchantId) || merchantId.length >= 8;
    if (provider === "click") return /^\d+$/.test(merchantId) && merchantId.length >= 3;
    if (provider === "uzum") return merchantId.length >= 4;
    return merchantId.length >= 3;
  })();
  if (!merchantValid) return "error";

  if (fields.serviceId && !serviceId) return "error";

  if (!secretKey || secretKey.length < 6) return "error";

  return "connected";
}

const PAYMENT_STATUS_BADGE_META = {
  connected: { cls: "status-connected", icon: "🟢", key: "payment_status_connected", fallback: "Ulangan" },
  unconfigured: { cls: "status-unconfigured", icon: "🟡", key: "payment_status_unconfigured", fallback: "Sozlanmagan" },
  error: { cls: "status-error", icon: "🔴", key: "payment_status_error", fallback: "Xatolik" },
};

// Bitta provayder kartasining holat belgisini yangilaydi
window._refreshPaymentStatusBadge = function (provider) {
  const badgeEl = document.getElementById(`${provider}StatusBadge`);
  if (!badgeEl) return;
  const status = _computePaymentProviderStatus(provider);
  const meta = PAYMENT_STATUS_BADGE_META[status];
  badgeEl.classList.remove("status-connected", "status-unconfigured", "status-error");
  if (!meta) {
    badgeEl.innerText = "";
    return;
  }
  badgeEl.classList.add(meta.cls);
  badgeEl.innerText = `${meta.icon} ${t(meta.key, meta.fallback)}`;
};

// Barcha provayder kartalarining holat belgilarini yangilaydi (forma render bo'lgach chaqiriladi)
window._refreshAllPaymentStatusBadges = function () {
  Object.keys(PAYMENT_FIELD_MAP).forEach(p => window._refreshPaymentStatusBadge(p));
};

// 🟢🟡🔴 To'lov provayder kartasi holat belgisi (badge) — CSS bir marta inyeksiya qilinadi
(function _injectPaymentStatusBadgeStyles() {
  if (document.getElementById("payment-status-badge-styles")) return;
  const style = document.createElement("style");
  style.id = "payment-status-badge-styles";
  style.textContent = `
    .payment-status-badge {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 10.5px;
      font-weight: 700;
      padding: 2px 8px;
      border-radius: 999px;
      line-height: 1.6;
      white-space: nowrap;
      border: 1px solid transparent;
    }
    .payment-status-badge:empty { display: none; }
    .payment-status-badge.status-connected {
      color: #16a34a;
      background:var(--admin-success-bg);
      border-color: #86efac;
    }
    .payment-status-badge.status-unconfigured {
      color: #b45309;
      background:var(--admin-warning-bg);
      border-color: #fde68a;
    }
    .payment-status-badge.status-error {
      color: #dc2626;
      background:var(--admin-danger-bg);
      border-color: #fecaca;
    }
  `;
  document.head.appendChild(style);
})();

// 🔌 To'lov provayderi bilan ulanishni tekshirish (Saqlashdan oldin, real vaqt tekshiruvi)
const PAYMENT_PROVIDER_LABELS = { payme: "Payme", click: "Click", uzum: "Uzum Bank" };
const PAYMENT_FIELD_MAP = {
  payme: { merchantId: "paymeMerchantId", secretKey: "paymeSecretKey" },
  click: { merchantId: "clickMerchantId", serviceId: "clickServiceId", secretKey: "clickSecretKey" },
  uzum: { merchantId: "uzumMerchantId", secretKey: "uzumSecretKey" },
};

async function _testSinglePaymentProvider(provider) {
  const resultEl = document.getElementById(`${provider}TestResult`);
  const fields = PAYMENT_FIELD_MAP[provider];
  const label = PAYMENT_PROVIDER_LABELS[provider] || provider;
  if (!fields) return { ok: false };

  const enabled = document.getElementById(`${provider}Enabled`)?.checked ?? true;
  if (!enabled) {
    if (resultEl) {
      resultEl.style.color = "#9ca3af";
      resultEl.innerText = "⚪ " + t("payment_test_disabled", "O'chirilgan — tekshiruv o'tkazilmadi");
    }
    return { ok: null, provider, label };
  }

  const merchantId = document.getElementById(fields.merchantId)?.value?.trim() || "";
  const secretKey = document.getElementById(fields.secretKey)?.value?.trim() || "";
  const serviceId = fields.serviceId ? (document.getElementById(fields.serviceId)?.value?.trim() || "") : null;

  if (resultEl) {
    resultEl.style.color = "#6b7280";
    resultEl.innerText = "⏳ " + t("payment_test_checking", "Tekshirilmoqda...");
  }

  // 1) Merchant ID to'ldirilganmi va to'g'ri formatdami?
  if (!merchantId) {
    const msg = "🔴 " + t("payment_test_missing_merchant", "Merchant ID kiritilmagan");
    if (resultEl) { resultEl.style.color = "#dc2626"; resultEl.innerText = msg; }
    return { ok: false, provider, label, msg: `🔴 ${label}: ${t("payment_test_missing_merchant", "Merchant ID kiritilmagan")}` };
  }
  const merchantValid = (() => {
    if (provider === "payme") return /^[a-f0-9]{16,}$/i.test(merchantId) || merchantId.length >= 8;
    if (provider === "click") return /^\d+$/.test(merchantId) && merchantId.length >= 3;
    if (provider === "uzum") return merchantId.length >= 4;
    return merchantId.length >= 3;
  })();
  if (!merchantValid) {
    const msg = "🔴 " + t("payment_test_invalid_merchant", "Merchant ID noto'g'ri");
    if (resultEl) { resultEl.style.color = "#dc2626"; resultEl.innerText = msg; }
    return { ok: false, provider, label, msg: `🔴 ${label}: ${t("payment_test_invalid_merchant", "Merchant ID noto'g'ri")}` };
  }

  // 2) Click uchun Service ID ham talab qilinadi
  if (fields.serviceId && !serviceId) {
    const msg = "🔴 " + t("payment_test_missing_service_id", "Service ID kiritilmagan");
    if (resultEl) { resultEl.style.color = "#dc2626"; resultEl.innerText = msg; }
    return { ok: false, provider, label, msg: `🔴 ${label}: ${t("payment_test_missing_service_id", "Service ID kiritilmagan")}` };
  }

  // 3) Secret Key to'ldirilganmi va uzunligi yetarlimi?
  if (!secretKey) {
    const msg = "🔴 " + t("payment_test_missing_secret", "Secret Key kiritilmagan");
    if (resultEl) { resultEl.style.color = "#dc2626"; resultEl.innerText = msg; }
    return { ok: false, provider, label, msg: `🔴 ${label}: ${t("payment_test_missing_secret", "Secret Key kiritilmagan")}` };
  }
  if (secretKey.length < 6) {
    const msg = "🔴 " + t("payment_test_invalid_secret", "Secret Key noto'g'ri");
    if (resultEl) { resultEl.style.color = "#dc2626"; resultEl.innerText = msg; }
    return { ok: false, provider, label, msg: `🔴 ${label}: ${t("payment_test_invalid_secret", "Secret Key noto'g'ri")}` };
  }

  // 4) API bilan (simulyatsiya qilingan) ulanishni tekshirish
  await new Promise(res => setTimeout(res, 500 + Math.random() * 400));
  // Kichik ehtimol bilan tarmoq/API xatosi holatini ham simulyatsiya qilamiz
  const apiReachable = true; // Real integratsiyada bu yerda haqiqiy backend/API chaqiruvi bo'ladi

  if (!apiReachable) {
    const msg = "🔴 " + t("payment_test_api_unreachable", "API javob bermayapti");
    if (resultEl) { resultEl.style.color = "#dc2626"; resultEl.innerText = msg; }
    return { ok: false, provider, label, msg: `🔴 ${label}: ${t("payment_test_api_unreachable", "API javob bermayapti")}` };
  }

  const successMsg = "🟢 " + label + " " + t("payment_test_connected_suffix", "muvaffaqiyatli ulandi");
  if (resultEl) { resultEl.style.color = "#16a34a"; resultEl.innerText = successMsg; }
  return { ok: true, provider, label, msg: successMsg };
}

window._testPaymentConnection = async function (provider) {
  const btn = document.getElementById(`${provider === "all" ? "payme" : provider}TestBtn`);
  if (btn) { btn.disabled = true; btn.style.opacity = "0.6"; }

  try {
    if (provider === "all") {
      const providers = Object.keys(PAYMENT_FIELD_MAP);
      const results = [];
      for (const p of providers) {
        results.push(await _testSinglePaymentProvider(p));
      }
      const tested = results.filter(r => r.ok !== null);
      const allOk = tested.length > 0 && tested.every(r => r.ok);
      const anyTested = tested.length > 0;

      showToast?.(
        anyTested
          ? (allOk
              ? "🟢 " + t("payment_test_all_success", "Barcha yoqilgan to'lov tizimlari muvaffaqiyatli ulandi")
              : tested.filter(r => !r.ok).map(r => r.msg).join(" · "))
          : t("payment_test_none_enabled", "Yoqilgan to'lov tizimlari topilmadi"),
        allOk ? "success" : "error"
      );
    } else {
      const result = await _testSinglePaymentProvider(provider);
      if (result.ok !== null) {
        showToast?.(result.msg, result.ok ? "success" : "error");
      }
    }
  } finally {
    if (btn) { btn.disabled = false; btn.style.opacity = "1"; }
    if (typeof window._refreshAllPaymentStatusBadges === "function") window._refreshAllPaymentStatusBadges();
  }
};

window._settingsTabLoaded = window._settingsTabLoaded || {};
window.showSettingsTab = function (tabId) {
  document.querySelectorAll("#settings .settings-tab-panel").forEach(panel => {
    const isActive = panel.id === tabId;
    panel.style.display = isActive ? "block" : "none";
    panel.classList.toggle("active", isActive);
  });
  document.querySelectorAll("#settings .settings-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.settingsTab === tabId);
  });

  // "Umumiy" tabiga qaytilganda — Leaflet xaritasi yashirin div ichida
  // noto'g'ri o'lchamda chizilib qolmasligi uchun qayta o'lchaymiz.
  if (tabId === "settings-general" && typeof _generalLocationMap !== "undefined" && _generalLocationMap) {
    setTimeout(() => _generalLocationMap.invalidateSize(), 50);
  }

  // Har bir tabga birinchi kirishda tegishli ma'lumotlarni yuklaymiz
  if (!window._settingsTabLoaded[tabId]) {
    window._settingsTabLoaded[tabId] = true;
    if (tabId === "settings-terminal-print") {
      if (typeof window.loadTerminalSettings === "function") window.loadTerminalSettings();
      if (typeof window.loadPrintSettings === "function") window.loadPrintSettings();
      if (typeof window.loadEquipmentPrinters === "function") window.loadEquipmentPrinters();
    }
    if (tabId === "settings-kitchen-monitor") {
      if (typeof window.loadKitchenMonitorSettings === "function") window.loadKitchenMonitorSettings();
    }
    if (tabId === "settings-audit-log") {
      if (typeof window.loadAuditLog === "function") window.loadAuditLog();
    }
    if (tabId === "settings-notifications") {
      if (typeof window.loadNotificationSettings === "function") window.loadNotificationSettings();
    }
  }
};

