/* =========================
   🌗 DARK / LIGHT THEME TOGGLE
   Persisted to localStorage, applied via <html data-theme="...">
========================= */
(function initTheme() {
  try {
    const saved = localStorage.getItem("app_theme");
    if (saved === "dark") {
      document.documentElement.setAttribute("data-theme", "dark");
    }
  } catch { /* localStorage unavailable — default to light */ }
})();

window.toggleTheme = function () {
  const html = document.documentElement;
  const isDark = html.getAttribute("data-theme") === "dark";
  if (isDark) {
    html.removeAttribute("data-theme");
    try { localStorage.setItem("app_theme", "light"); } catch {}
  } else {
    html.setAttribute("data-theme", "dark");
    try { localStorage.setItem("app_theme", "dark"); } catch {}
  }
};

/* =========================
   🎨 DESIGN SYSTEM — theme mode (light/dark/system) + accent color
   Kengaytma: yuqoridagi toggleTheme() bilan bir xil localStorage
   kaliti ("app_theme") va data-theme atributidan foydalanadi, faqat
   uchinchi qiymat — "system" — qo'shiladi. Eski toggleTheme() ishlab
   turaveradi (light↔dark), bu yerda ustiga window.setThemeMode() va
   window.setAccentColor() qo'shiladi.
========================= */
window.setThemeMode = function (mode) {
  // mode: "light" | "dark" | "system"
  const html = document.documentElement;
  if (mode === "light") {
    html.removeAttribute("data-theme");
  } else {
    html.setAttribute("data-theme", mode);
  }
  try { localStorage.setItem("app_theme", mode); } catch {}
};

window.getThemeMode = function () {
  try { return localStorage.getItem("app_theme") || "light"; } catch { return "light"; }
};

window.setAccentColor = function (accent) {
  // accent: "indigo" (default, removes attribute) | "emerald" | "amber" | "rose" | "sky"
  const html = document.documentElement;
  if (!accent || accent === "indigo") {
    html.removeAttribute("data-accent");
  } else {
    html.setAttribute("data-accent", accent);
  }
  try { localStorage.setItem("app_accent", accent || "indigo"); } catch {}
};

window.getAccentColor = function () {
  try { return localStorage.getItem("app_accent") || "indigo"; } catch { return "indigo"; }
};

// Sahifa yuklanganda saqlangan mode/accent'ni qayta tiklash
(function initDesignSystem() {
  try {
    const savedMode = localStorage.getItem("app_theme");
    if (savedMode === "system") {
      document.documentElement.setAttribute("data-theme", "system");
    }
    const savedAccent = localStorage.getItem("app_accent");
    if (savedAccent && savedAccent !== "indigo") {
      document.documentElement.setAttribute("data-accent", savedAccent);
    }
  } catch { /* localStorage unavailable — defaults apply */ }
})();

/* =========================
   ADMIN SIDEBAR FOOTERNI YANGILASH
========================= */
function updateAdminFooter(hours, phone) {
  const wHours = hours || "09:00 – 22:00";
  const wPhone = phone || "+998 90 123 45 67";

  // Eski .support-footer tuzilmasi
  const adminFooter = document.querySelector('.support-footer');
  if (adminFooter) {
    adminFooter.innerHTML = `
      <div class="support-footer-item">
        <span>${t("support_working_hours", "Ish vaqti")}</span>
        <b>${wHours}</b>
      </div>
      <div class="support-footer-item">
        <span>${t("support_contact", "Aloqa")}</span>
        <b>${wPhone}</b>
      </div>
    `;
  }

  // Yangi .chef-footer tuzilmasi uchun maxsus elementlar
  const chefFooterWorkHours = document.getElementById("clientFooterWorkHours");
  const chefFooterPhone = document.getElementById("clientFooterPhone");
  if (chefFooterWorkHours) chefFooterWorkHours.textContent = wHours;
  if (chefFooterPhone) chefFooterPhone.textContent = wPhone;
}

// ==========================================
