// ==========================================
// 🧑‍🍳 QO'LDA REJIM: admin buyurtmani ofitsiantga tayinlaydi
// ==========================================
window.assignWaiterManually = async function (orderId, waiterId) {
  if (!waiterId) {
    alert(t("select_waiter_first", "Iltimos, avval ofitsiantni tanlang!"));
    return;
  }
  try {
    const userSnap = await get(ref(db, `${BASE_PATH}/users/${waiterId}`));
    const waiterName = userSnap.exists() ? (userSnap.val().name || "") : "";

    await update(ref(db, `${BASE_PATH}/orders/${orderId}`), {
      waiterId,
      waiterName,
      waiterAssignedAt: Date.now(),
      waiterAssignedVia: "manual"
    });

    showAdminNotification(t("waiter_assigned_success", "✅ Ofitsiant biriktirildi!"));
  } catch (err) {
    console.error(t("waiter_assign_error_log", "Ofitsiant biriktirishda xato:"), err);
    alert(t("error_occurred", "Xatolik yuz berdi!"));
  }
};

// ══════════════════════════════════════════════════════
// 🛵 Buyurtmani kuryerga tayinlash
// Yaratadi: restaurants/{id}/courierAssignments/{assignmentId}
//   { courierId, orderId, orderNumber, address, customerPhone,
//     total, note, status:"assigned", assignedAt }
// Bu yozuv courier.js tomonidan real-vaqtda o'qiladi (courierId
// bo'yicha filtrlanadi) va admin.js dagi Kuryer monitoring bo'limi
// ham shu yo'ldan statistikani hisoblaydi — shuning uchun bitta
// yozuv orqali ikkala tomon ham avtomatik yangilanadi.
// ══════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════
// 🛵 Buyurtmani "yetkazib berish" turi sifatida belgilash
// Buyurtma yaratish oynasida hozircha bunday tanlov yo'q, shuning
// uchun admin (yoki kassir) tayyor buyurtmani shu tugma orqali
// qo'lda "delivery" deb belgilashi mumkin — shundan keyin isDeliveryOrder
// true bo'lib, kuryerga tayinlash bloki darhol ko'rinadi.
// ══════════════════════════════════════════════════════
window.markOrderAsDelivery = async function (orderId) {
  try {
    await update(ref(db, `${BASE_PATH}/orders/${orderId}`), {
      isDelivery: true,
      deliveryType: "delivery",
      orderType: ORDER_TYPE.DELIVERY
    });
    showAdminNotification(`🛵 ${t("order_marked_delivery", "Buyurtma yetkazib berishga belgilandi")}`, "success");
  } catch (err) {
    console.error("markOrderAsDelivery error:", err);
    alert(t("error_occurred", "Xatolik yuz berdi!"));
  }
};

window.assignOrderToCourier = async function (orderId, courierId) {
  if (!courierId) {
    alert(t("select_courier_first", "Iltimos, avval kuryerni tanlang!"));
    return;
  }
  try {
    const [orderSnap, courierSnap] = await Promise.all([
      get(ref(db, `${BASE_PATH}/orders/${orderId}`)),
      get(ref(db, `${BASE_PATH}/users/${courierId}`))
    ]);

    if (!orderSnap.exists()) {
      alert(t("order_not_found", "Buyurtma topilmadi!"));
      return;
    }

    const order = orderSnap.val();
    const courierName = courierSnap.exists() ? (courierSnap.val().name || "") : "";
    const now = Date.now();

    const assignRef = push(ref(db, `${BASE_PATH}/courierAssignments`));
    const assignmentId = assignRef.key;

    const addressRaw = order.deliveryAddress || order.address || "";
    const address = formatDeliveryAddress(addressRaw) || (typeof addressRaw === "string" ? addressRaw : "");
    const customerPhone = order.customerPhone || order.clientPhone || order.phone || "";
    const customerName = order.customerName || "";
    const total = Number(order.finalTotal || order.total || 0);
    // 🛵 To'lov usuli: ofitsiant buyurtma yaratganda tanlagan holat —
    // mijoz oldindan karta bilan to'lagan bo'lsa "paid:true" bo'ladi,
    // aks holda kuryer yetkazgandan keyin naqt yig'ib olishi kerak.
    const paymentMethod = order.deliveryPaymentMethod || "cash_on_delivery";
    const isPrepaid = paymentMethod === "prepaid_card" && order.payment?.paid === true;
    // Xarita/navigatsiya uchun mo'ljal koordinatasi (courierMapView shuni o'qiydi)
    const destination = (typeof addressRaw === "object" && typeof addressRaw.lat === "number" && typeof addressRaw.lng === "number")
      ? { lat: addressRaw.lat, lng: addressRaw.lng }
      : null;

    await set(assignRef, {
      courierId,
      orderId,
      orderNumber: order.orderNumber || "",
      customerName,
      address,
      ...(destination ? { destination } : {}),
      customerPhone,
      total,
      paymentMethod,
      isPrepaid,
      note: order.deliveryNote || order.note || "",
      status: "assigned",
      assignedAt: now
    });

    await update(ref(db, `${BASE_PATH}/orders/${orderId}`), {
      courierId,
      courierName,
      courierAssignmentId: assignmentId,
      courierAssignedAt: now
    });

    // Kuryer holatini ham "yetkazmoqda" deb yangilaymiz — bu tayinlash
    // paytidayoq admin monitoringda ko'rinadi, kuryer o'zi "Olib ketdim"
    // tugmasini bosgach ham courier.js xuddi shu statusni tasdiqlaydi.
    await update(ref(db, `${BASE_PATH}/couriers/${courierId}`), {
      status: "on_delivery"
    });

    showAdminNotification(`🛵 ${t("courier_assigned_success", "Kuryerga tayinlandi!")} (${courierName})`, "success");
  } catch (err) {
    console.error("assignOrderToCourier error:", err);
    alert(t("error_occurred", "Xatolik yuz berdi!"));
  }
};

window.saveSettings = async function () {
  const restId = localStorage.getItem("restaurantId");

  // Mavjud logotip URL ni saqlab qolish
  let existingLogoUrl = "";
  try {
    const database = window.db || (typeof db !== 'undefined' ? db : null);
    if (database) {
      const existingSnap = await get(ref(database, `restaurants/${restId}/settings/restaurantLogoUrl`));
      if (existingSnap.exists()) {
        existingLogoUrl = existingSnap.val() || "";
      }
    }
  } catch (_) { }

  // ── SECTION 5: Yetkazib berish sozlamalarini tekshirish (validatsiya) ──
  const _dEnabled = !!document.getElementById("deliveryEnabled")?.checked;
  const _dProvider = document.getElementById("deliveryProvider")?.value || "yandex_go";
  const _dLat = document.getElementById("deliveryOriginLat")?.value;
  const _dLng = document.getElementById("deliveryOriginLng")?.value;
  const _dAreaMode = document.querySelector('input[name="deliveryAreaMode"]:checked')?.value || "unlimited";
  const _dAreaRadius = Number(document.getElementById("deliveryAreaRadiusKm")?.value || 0);
  const _dApiKey = document.getElementById("yandexGoApiKey")?.value?.trim() || "";
  const _dBaseFee = Number(document.getElementById("deliveryBaseFee")?.value || 0);
  const _dPerKmFee = Number(document.getElementById("deliveryPerKmFee")?.value || 0);
  const _dFreeThreshold = Number(document.getElementById("deliveryFreeThreshold")?.value || 0);
  const _dMaxDistance = Number(document.getElementById("deliveryMaxDistanceKm")?.value || 0);

  if (_dEnabled) {
    // Lat/Lng "0", undefined, null yoki NaN — barchasi xaritada hali belgi
    // qo'yilmagan deb hisoblanadi (0/0 — "Null Island" — sun'iy default,
    // haqiqiy restoran manzili emas), shu bilan birga haqiqiy geografik
    // diapazondan (-90..90 / -180..180) tashqariga chiqishi ham rad etiladi.
    const _dLatNum = Number(_dLat);
    const _dLngNum = Number(_dLng);
    const _dLocationValid = _dLat !== undefined && _dLat !== null && _dLat !== "" &&
      _dLng !== undefined && _dLng !== null && _dLng !== "" &&
      Number.isFinite(_dLatNum) && Number.isFinite(_dLngNum) &&
      _dLatNum !== 0 && _dLngNum !== 0 &&
      _dLatNum >= -90 && _dLatNum <= 90 && _dLngNum >= -180 && _dLngNum <= 180;
    if (!_dLocationValid) {
      alert(t("delivery_validation_location", "Restoran manzilini xaritada aniq belgilang!"));
      return;
    }
    if (_dProvider === "yandex_go" && !_dApiKey) {
      alert(t("delivery_validation_api", "Yandex Go uchun avval API kalitini kiriting!"));
      return;
    }
  }
  if (_dAreaMode === "radius" && !(_dAreaRadius > 0)) {
    alert(t("delivery_validation_radius", "Radius 0 dan katta bo'lishi kerak!"));
    return;
  }
  if ([_dBaseFee, _dPerKmFee, _dFreeThreshold, _dMaxDistance, _dAreaRadius].some(n => n < 0)) {
    alert(t("delivery_validation_negative", "Narx va masofa qiymatlari manfiy bo'lishi mumkin emas!"));
    return;
  }

  const data = {
    restaurantName: document.getElementById("restaurantName")?.value?.trim() || "",
    workingHours: document.getElementById("workingHours")?.value?.trim() || "",
    contactPhone: document.getElementById("contactPhone")?.value?.trim() || "",
    // 🆕 YAGONA STAFF FOOTER — on/off toggle'lar + ixtiyoriy matn. Qiymatlar
    // (ish vaqti/telefon) yuqoridagi workingHours/contactPhone'ning O'ZI —
    // bu yerda takrorlanmaydi.
    footerSettings: {
      showWorkingHours: document.getElementById("footerShowWorkingHours")?.checked !== false,
      showPhone: document.getElementById("footerShowPhone")?.checked !== false,
      customText: document.getElementById("footerCustomText")?.value?.trim() || ""
    },
    serviceFee: Number(document.getElementById("serviceFee")?.value || 0),
    serviceFeeMinOrder: Number(document.getElementById("serviceFeeMinOrder")?.value || 0),
    minOrderAmount: Number(document.getElementById("minOrderAmount")?.value || 0),
    fastFee: Number(document.getElementById("fastFee")?.value || 5),
    fastOrderMinusMinutes: Number(document.getElementById("fastMinusMins")?.value || 10),
    normalOrderBaseTime: Number(document.getElementById("normalTime")?.value || 30),
    fastOrderMinAmount: Number(document.getElementById("fastMinAmount")?.value || 80000),
    fastOrderActive: !!document.getElementById("fastOrderActive")?.checked,
    paymeEnabled: !!document.getElementById("paymeEnabled")?.checked,
    paymeMerchantId: document.getElementById("paymeMerchantId")?.value?.trim() || "",
    paymeSecretKey: document.getElementById("paymeSecretKey")?.value?.trim() || "",
    clickEnabled: !!document.getElementById("clickEnabled")?.checked,
    clickMerchantId: document.getElementById("clickMerchantId")?.value?.trim() || "",
    clickServiceId: document.getElementById("clickServiceId")?.value?.trim() || "",
    clickSecretKey: document.getElementById("clickSecretKey")?.value?.trim() || "",
    uzumEnabled: !!document.getElementById("uzumEnabled")?.checked,
    uzumMerchantId: document.getElementById("uzumMerchantId")?.value?.trim() || "",
    uzumSecretKey: document.getElementById("uzumSecretKey")?.value?.trim() || "",
    maxTable: Number(document.getElementById("maxTablesSettings")?.value || 0),
    billingMode: document.querySelector('input[name="billingMode"]:checked')?.value || "client_only",
    defaultLanguage: document.getElementById("defaultLanguage")?.value || "uz",
    vipDefaults: {
      discountPct: Number(document.getElementById("vipDefaultPercent")?.value || 10),
      orderCount: Number(document.getElementById("vipDefaultOrders")?.value || 3)
    },
    serviceTypes: {
      dineIn: !!document.getElementById("serviceTypeDineIn")?.checked,
      delivery: !!document.getElementById("serviceTypeDelivery")?.checked,
      takeaway: !!document.getElementById("serviceTypeTakeaway")?.checked
    },
    deliverySettings: {
      enabled: _dEnabled,
      provider: _dProvider,
      assignmentMode: document.getElementById("deliveryAssignmentMode")?.value || "manual",
      telegramChatId: document.getElementById("deliveryTelegramChatId")?.value?.trim() || "",
      pricingMode: document.getElementById("deliveryPricingMode")?.value || "fixed",
      baseFee: _dBaseFee,
      perKmFee: _dPerKmFee,
      freeDeliveryThreshold: _dFreeThreshold,
      minOrderAmount: Number(document.getElementById("deliveryMinOrderAmount")?.value || 0),
      defaultEtaMinutes: Number(document.getElementById("deliveryDefaultEta")?.value || 45),
      maxDeliveryDistanceKm: _dMaxDistance,
      restaurantLocation: {
        lat: _dLat ? Number(_dLat) : null,
        lng: _dLng ? Number(_dLng) : null
      },
      restaurantAddress: document.getElementById("deliveryOriginAddress")?.value?.trim() || "",
      areaMode: _dAreaMode,
      areaRadiusKm: _dAreaRadius,
      yandexGo: {
        apiKey: _dApiKey,
        clientId: document.getElementById("yandexGoClientId")?.value?.trim() || "",
        environment: document.getElementById("yandexGoEnvironment")?.value || "sandbox"
      }
    },
    autoDiscount: {
      enabled: !!document.getElementById("autoDiscountEnabled")?.checked,
      minAmount: Number(document.getElementById("autoDiscountMinAmount")?.value || 0),
      pct: Number(document.getElementById("autoDiscountPct")?.value || 0)
    },
    paymentAcceptor: document.querySelector('input[name="paymentAcceptor"]:checked')?.value || "kassir",
    updatedAt: Date.now()
  };

  // Logotip URL ni saqlab qolish (agar mavjud bo'lsa)
  if (existingLogoUrl) {
    data.restaurantLogoUrl = existingLogoUrl;
  }

  await update(ref(db, BASE_PATH + "/settings"), data);
  showAdminNotification(t("settings_saved_success") || "Sozlamalar saqlandi!");

  // Header real-time fix: if the admin just changed the restaurant name in
  // this very save, the header (Nesta ERP Administrator | <name>) should
  // reflect it immediately, not wait for some unrelated re-trigger (RBAC
  // change, language switch, next reload). Reuses the existing function/
  // state exactly as loaded above — no extra Firebase read beyond what this
  // save already did.
  if (typeof window.loadRestaurantNameForHeader === "function") {
    window.loadRestaurantNameForHeader();
  }

  if (typeof window.applyServiceTypeGating === "function") {
    window.applyServiceTypeGating(data.serviceTypes);
  }

  if (typeof updateAdminFooter === "function") {
    updateAdminFooter(data.workingHours, data.contactPhone);
  }

  // Admin header logotipini ham yangilash
  const finalLogoUrl = data.restaurantLogoUrl || existingLogoUrl;
  if (finalLogoUrl && typeof window.applyRestaurantLogo === "function") {
    window.applyRestaurantLogo(finalLogoUrl);
  }

  if (typeof loadRestaurantNameForHeader === "function") {
    loadRestaurantNameForHeader();
  }

  if (typeof window.logSystemAction === "function") {
    await window.logSystemAction("update", t("settings_updated_log", "⚙️ Restoran asosiy sozlamalari yangilandi."));
  }
};

