function getBusyTablesIds(orders) {
  if (!orders) return [];
  const busyIds = [];
  const _closedStatuses = [ORDER_STATUS_V2.COMPLETED.key, ORDER_STATUS_V2.CANCELLED.key, "paid", "to'landi", "completed", "yopildi", "closed", "cancelled", "bekor qilindi"];
  Object.values(orders).forEach(order => {
    const _st = String(order.status || order.statusKey || "").toLowerCase();
    if (!_closedStatuses.includes(_st) && order.table) {
      const tableNum = String(order.table).replace(/\D/g, '');
      if (tableNum && !busyIds.includes(tableNum)) {
        busyIds.push(tableNum);
      }
    }
  });
  return busyIds;
}

