/* =========================
   CHAT SYSTEM INITIALIZATION
   Admin: E'lonlar (yozadi) + SuperAdmin + har bir Kassir/Ofitsiant bilan
   alohida chat, xodimlar ko'p bo'lsa — rol bo'yicha guruh chat.
   Chef bilan chat yo'q; Kassir↔Ofitsiant kabi xodimlararo chat yo'q.
========================= */
async function getAdminChatOptions(userId, restaurantId) {
  // Clean-exit fix: same reasoning as checkPermissions() above — this only
  // ever runs from initAdminChat() (init() -> post-auth-gate) now, but a
  // permission_denied here used to propagate as an unhandled rejection to
  // whatever awaits getChatOptions() in chat-system.js instead of a clean,
  // logged "no options" result.
  let snap;
  try {
    snap = await get(ref(db, `restaurants/${restaurantId}/users`));
  } catch (err) {
    console.error("[getAdminChatOptions] Admin access denied yoki xato — bo'sh ro'yxat qaytarildi:", err.code || err.message);
    return [];
  }
  const users = snap.val() || {};

  const cashiers = Object.entries(users)
    .filter(([, u]) => u.role === "cashier" && u.active !== false)
    .map(([id, u]) => ({ ...u, id }));
  const waiters = Object.entries(users)
    .filter(([, u]) => u.role === "waiter" && u.active !== false)
    .map(([id, u]) => ({ ...u, id }));

  const options = [
    { icon: "📢", label: t("chat_announcements", "E'lonlar"), type: "announcement" },
    { icon: "👤", label: t("chat_with_superadmin", "SuperAdmin"), type: "superadmin" }
  ];

  if (cashiers.length > 1) {
    options.push({ icon: "📢", label: t("chat_with_cashiers_group", "Barcha kassirlar (Guruh)"), type: "group_cashier" });
  }
  cashiers.forEach(cashier => {
    options.push({ icon: "💵", label: cashier.name || t("role_cashier", "Kassir"), type: "single_cashier", targetId: cashier.id });
  });

  if (waiters.length > 1) {
    options.push({ icon: "📢", label: t("chat_with_waiters_group", "Barcha ofitsiantlar (Guruh)"), type: "group_waiter" });
  }
  waiters.forEach(waiter => {
    options.push({ icon: "🧑‍🍳", label: waiter.name || t("role_waiter", "Ofitsiant"), type: "single_waiter", targetId: waiter.id });
  });

  return options;
}

async function getAdminChatId(option) {
  if (option.type === "superadmin") return "superadmin";
  if (option.type === "group_cashier") return "cashier_group";
  if (option.type === "single_cashier") return `admin_cashier_${option.targetId}`;
  if (option.type === "group_waiter") return "waiter_group";
  if (option.type === "single_waiter") return `admin_waiter_${option.targetId}`;

  return null;
}

function initAdminChat() {
  if (!window.initChatSystem) {
    console.error("❌ window.initChatSystem topilmadi!");
    return;
  }

  window.initChatSystem({
    currentRestaurantId,
    currentUserId,
    currentRole: "admin",
    db,
    getChatOptions: getAdminChatOptions,
    getChatId: getAdminChatId
  }).catch(err => {
    console.error("❌ Chat init error:", err);
    console.error("Stack trace:", err.stack);
  });
}

