  _i18nRelabelStep("renderSupplierList", () => { if (typeof renderSupplierList === "function") renderSupplierList(); });
  _i18nRelabelStep("_renderFinance", () => { if (typeof _renderFinance === "function") _renderFinance(); });
  _i18nRelabelStep("_renderStaff", () => { if (typeof _renderStaff === "function") _renderStaff(); });
  // 🐛 Audit topilmasi: "_renderStaff" (yuqorida) — Hisobot → Personal
  // tabidagi STATISTIKA funksiyasi, nomi o'xshash bo'lsa-da, Xodimlar
  // ("Ism/Rol/Amallar") jadvaliga umuman aloqasi yo'q. Xodimlar jadvalining
