  // o'qishisiz qayta chiziladi — va har biri o'zining konteyner elementi
  // DOM'da yo'qligida (`if (!el) return`) darhol chiqib ketadi, shuning
  // uchun boshqa bo'lim ochiq bo'lsa ham xavfsiz, hech narsa qilmaydi.
  // ══════════════════════════════════════════════════════════════════
  _i18nRelabelStep("renderCategoriesList", () => { if (typeof renderCategoriesList === "function") renderCategoriesList(); });
  _i18nRelabelStep("renderModifiersList", () => { if (typeof renderModifiersList === "function") renderModifiersList(); });
