/* ═══════════════════════════════════════════════════════
   📊 MENYU STATISTIKASI — Eng ko'p sotilgan taomlar
═══════════════════════════════════════════════════════ */

let _menuStatsChart = null;
let _menuStatsChartType = "bar";
let _menuStatsOpen = true;

window.setStatsChartType = function (type) {
  _menuStatsChartType = type;
  // Button styles
  ["bar", "pie", "doughnut"].forEach(t => {
    const btn = document.getElementById("statsBtnBar".replace("Bar", t.charAt(0).toUpperCase() + t.slice(1)));
    if (btn) {
      btn.style.background = t === type ? "#22c55e" : "var(--bg-body,#f8fafc)";
      btn.style.color = t === type ? "#fff" : "var(--text-primary,#1e293b)";
      btn.style.borderColor = t === type ? "#22c55e" : "var(--border-color,#e2e8f0)";
    }
  });
  const btnBar = document.getElementById("statsBtnBar");
  const btnPie = document.getElementById("statsBtnPie");
  const btnDoughnut = document.getElementById("statsBtnDoughnut");
  [btnBar, btnPie, btnDoughnut].forEach(b => {
    if (!b) return;
    b.style.background = "var(--bg-body,#f8fafc)";
    b.style.color = "var(--text-primary,#1e293b)";
    b.style.borderColor = "var(--border-color,#e2e8f0)";
  });
  const activeBtn = document.getElementById("statsBtn" + type.charAt(0).toUpperCase() + type.slice(1));
  if (activeBtn) {
    activeBtn.style.background = "#22c55e";
    activeBtn.style.color = "#fff";
    activeBtn.style.borderColor = "#22c55e";
  }
  window.renderMenuStats();
};

window.toggleMenuStats = function () {
  _menuStatsOpen = !_menuStatsOpen;
  const content = document.getElementById("menuStatsContent");
  const icon = document.getElementById("menuStatsToggleIcon");
  const btn = document.getElementById("menuStatsToggleBtn");
  if (content) content.style.display = _menuStatsOpen ? "block" : "none";
  if (icon) icon.textContent = _menuStatsOpen ? "▲" : "▼";
  if (btn) btn.innerHTML = `<span id="menuStatsToggleIcon">${_menuStatsOpen ? "▲" : "▼"}</span> ${_menuStatsOpen ? t("close_btn", "Yopish") : t("view_btn", "Ko'rsatish")}`;
};

window.restaurantFeatures = [];

onValue(ref(db, `restaurants/${currentRestaurantId}/subscription/features`), (snap) => {
  if (snap.exists()) {
    window.restaurantFeatures = snap.val() || [];
    console.log(t("loaded_features", "Faol funksiyalar:"), window.restaurantFeatures);
  } else {
    window.restaurantFeatures = [];
  }
});

window.checkFeatureAccess = function (featureKey, actionCallback) {
  if (window.restaurantFeatures.includes('all') || window.restaurantFeatures.includes(featureKey)) {
    if (typeof actionCallback === "function") actionCallback();
    return true;
  } else {
    const modal = document.getElementById("upgradePlanModal");
    if (modal) {
      modal.style.display = "flex";
      modal.classList.remove("hidden");
    }
    return false;
  }
};

window.closeUpgradeModal = function () {
  const modal = document.getElementById("upgradePlanModal");
  if (modal) {
    modal.style.display = "none";
    modal.classList.add("hidden");
  }
};

window.renderMenuStats = function () {
  const periodEl = document.getElementById("statsFilterPeriod");
  const topEl = document.getElementById("statsFilterTop");
  const metricEl = document.getElementById("statsFilterMetric");
  const fromEl = document.getElementById("statsDateFrom");
  const toEl = document.getElementById("statsDateTo");
  const customDiv = document.getElementById("statsCustomRange");

  const period = periodEl?.value || "week";
  const topN = Number(topEl?.value || 10);
  const metric = metricEl?.value || "qty";
  if (customDiv) customDiv.style.display = period === "custom" ? "flex" : "none";

  const loader = document.getElementById("menuStatsChartLoader");
  if (loader) loader.style.display = "flex";

  const now = Date.now();
  const MS_DAY = 86400000;
  let fromTs = 0;
  let toTs = now;

  if (period === "today") {
    const d = new Date(); d.setHours(0, 0, 0, 0);
    fromTs = d.getTime();
  } else if (period === "week") {
    fromTs = now - 7 * MS_DAY;
  } else if (period === "month") {
    fromTs = now - 30 * MS_DAY;
  } else if (period === "custom") {
    if (fromEl?.value) fromTs = new Date(fromEl.value).getTime();
    if (toEl?.value) toTs = new Date(toEl.value).getTime() + MS_DAY - 1;
  }

  // Filter orders
  const allOrders = window.allOrders || {};
  const filtered = Object.values(allOrders).filter(order => {
    const closed = ["yopildi", "bekor qilindi", "closed", "cancelled", "to'landi", "paid", "закрыто", "отменён", "оплачено", "canceled"];
    const st = String(order.status || order.statusKey || "").trim().toLowerCase();
    if (!closed.includes(st)) return false;
    const ts = Number(order.createdAt || order.timestamp || order.time || 0);
    if (period !== "all" && (ts < fromTs || ts > toTs)) return false;
    return true;
  });

  // Aggregate
  const stats = {};
  filtered.forEach(order => {
    if (!order.items) return;
    Object.values(order.items).forEach(item => {
      const lang = typeof getLang === "function" ? getLang() : "uz";
      const name = typeof item.name === "object"
        ? item.name?.[lang] || item.name?.uz || item.name?.ru || item.name?.en || "—"
        : item.name || "—";
      const qty = Number(item.qty || 0);
      const sum = Number(item.price || 0) * qty;
      if (!stats[name]) stats[name] = { name, qty: 0, sum: 0 };
      stats[name].qty += qty;
      stats[name].sum += sum;
    });
  });

  const sorted = Object.values(stats)
    .sort((a, b) => b[metric] - a[metric])
    .slice(0, topN);

  // Update meta
  const metaEl = document.getElementById("menuStatsMeta");
  if (metaEl) {
    const periodLabels = {
      all: t("stats_all_time", "Barcha vaqt"),
      today: t("today_label", "Bugun"),
      week: t("stats_last_7_days", "Oxirgi 7 kun"),
      month: t("stats_last_30_days", "Oxirgi 30 kun"),
      custom: t("stats_custom_range", "Tanlangan davr")
    };
    metaEl.textContent = `${periodLabels[period] || ""} • ${filtered.length} ${t("orders_count_suffix", "ta buyurtma")} • ${Object.keys(stats).length} ${t("food_types_suffix", "xil taom")}`;
  }

  // Render table
  const tbody = document.getElementById("menuStatsTableBody");
  if (tbody) {
    if (!sorted.length) {
      tbody.innerHTML = `<tr><td colspan="4" style="text-align:center;padding:24px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`;
    } else {
      const medals = ["🥇", "🥈", "🥉"];
      tbody.innerHTML = sorted.map((item, i) => {
        const bar = sorted[0][metric] > 0
          ? Math.round((item[metric] / sorted[0][metric]) * 100) : 0;
        return `<tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:9px 10px;font-weight:700;color:var(--text-secondary);">${medals[i] || (i + 1)}</td>
          <td style="padding:9px 10px;">
            <div style="font-weight:600;color:var(--text-primary,#1e293b);margin-bottom:3px;">${item.name}</div>
            <div style="height:4px;background:var(--bg-hover);border-radius:99px;overflow:hidden;">
              <div style="height:100%;width:${bar}%;background:linear-gradient(90deg,#22c55e,#16a34a);border-radius:99px;transition:width .4s;"></div>
            </div>
          </td>
          <td style="padding:9px 10px;text-align:right;font-weight:700;color:var(--text-primary);">${item.qty.toLocaleString()}</td>
          <td style="padding:9px 10px;text-align:right;color:#16a34a;font-weight:600;">${item.sum.toLocaleString()} ${t("currency", "so'm")}</td>
        </tr>`;
      }).join("");
    }
  }

  // Summary cards
  const summaryEl = document.getElementById("menuStatsSummary");
  if (summaryEl && sorted.length) {
    const totalQty = Object.values(stats).reduce((s, i) => s + i.qty, 0);
    const totalSum = Object.values(stats).reduce((s, i) => s + i.sum, 0);
    const topItem = sorted[0];
    summaryEl.innerHTML = `
      <div style="flex:1;min-width:140px;background:linear-gradient(135deg,#f0fdf4,#dcfce7);border:1px solid #bbf7d0;border-radius:12px;padding:12px 16px;">
        <div style="font-size:11px;color:#16a34a;font-weight:600;text-transform:uppercase;letter-spacing:.5px;">${t("stats_total_sold", "Jami sotilgan")}</div>
        <div style="font-size:22px;font-weight:800;color:#15803d;margin-top:2px;">${totalQty.toLocaleString()} ${t("qty_col_label", "dona")}</div>
      </div>
      <div style="flex:1;min-width:140px;background:linear-gradient(135deg,#eff6ff,#dbeafe);border:1px solid #bfdbfe;border-radius:12px;padding:12px 16px;">
        <div style="font-size:11px;color:#3b82f6;font-weight:600;text-transform:uppercase;letter-spacing:.5px;">${t("stats_total_revenue", "Jami tushum")}</div>
        <div style="font-size:22px;font-weight:800;color:#1d4ed8;margin-top:2px;">${totalSum.toLocaleString()} ${t("currency", "so'm")}</div>
      </div>
      <div style="flex:1;min-width:140px;background:linear-gradient(135deg,#fffbeb,#fef9c3);border:1px solid #fde68a;border-radius:12px;padding:12px 16px;">
        <div style="font-size:11px;color:#d97706;font-weight:600;text-transform:uppercase;letter-spacing:.5px;">🥇 ${t("stats_leader_food", "Lider taom")}</div>
        <div style="font-size:15px;font-weight:800;color:#92400e;margin-top:2px;">${topItem.name}</div>
        <div style="font-size:11px;color:#b45309;margin-top:1px;">${topItem.qty} ${t("qty_col_label", "dona")} · ${topItem.sum.toLocaleString()} ${t("currency", "so'm")}</div>
      </div>
    `;
  }

  // Render chart
  const ctx = document.getElementById("menuTopFoodsChart");
  if (!ctx) { if (loader) loader.style.display = "none"; return; }
  if (_menuStatsChart) _menuStatsChart.destroy();

  if (!sorted.length) {
    if (loader) loader.style.display = "none";
    return;
  }

  const COLORS = [
    "#22c55e", "#3b82f6", "#f59e0b", "#ef4444", "#8b5cf6",
    "#06b6d4", "#ec4899", "#84cc16", "#f97316", "#6366f1",
    "#14b8a6", "#a855f7", "#0ea5e9", "#eab308", "#10b981",
    "#fb923c", "#e879f9", "#4ade80", "#60a5fa", "#fbbf24"
  ];

  const labels = sorted.map(i => i.name);
  const dataVals = sorted.map(i => i[metric]);
  const label = metric === "qty" ? t("stats_metric_qty", "Sotilgan (dona)") : t("stats_metric_sum", "Tushum (so'm)");

  const isBar = _menuStatsChartType === "bar";

  _menuStatsChart = new Chart(ctx, {
    type: _menuStatsChartType,
    data: {
      labels,
      datasets: [{
        label,
        data: dataVals,
        backgroundColor: isBar
          ? COLORS.slice(0, sorted.length).map(c => c + "CC")
          : COLORS.slice(0, sorted.length),
        borderColor: isBar
          ? COLORS.slice(0, sorted.length)
          : "#fff",
        borderWidth: isBar ? 1 : 2,
        borderRadius: isBar ? 8 : 0,
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          display: !isBar,
          position: "bottom",
          labels: { font: { size: 11 }, padding: 10, boxWidth: 12 }
        },
        tooltip: {
          callbacks: {
            label: ctx => metric === "qty"
              ? ` ${ctx.raw.toLocaleString()} ${t("qty_col_label", "dona")}`
              : ` ${ctx.raw.toLocaleString()} ${t("currency", "so'm")}`
          }
        }
      },
      scales: isBar ? {
        y: {
          beginAtZero: true,
          grid: { color: "rgba(0,0,0,0.05)" },
          ticks: {
            callback: v => metric === "qty" ? v : v.toLocaleString(),
            font: { size: 11 }
          }
        },
        x: {
          grid: { display: false },
          ticks: {
            font: { size: 11 },
            maxRotation: 35,
            callback: function (val, idx) {
              const lbl = this.getLabelForValue(idx);
              return lbl.length > 14 ? lbl.slice(0, 14) + "…" : lbl;
            }
          }
        }
      } : {}
    }
  });

  if (loader) loader.style.display = "none";
};

// ==========================================
// 🍽️ TAOMLAR ANALITIKASI (Menu Analytics)
// Manba: window.allOrders (yopilgan buyurtmalar) + window.allMenu (taom kartochkalari)
// ==========================================
let _maCategoryChart = null;
let _maHourlyChart = null;

window.renderMenuAnalytics = function () {
  const periodEl = document.getElementById("maFilterPeriod");
  const fromEl = document.getElementById("maDateFrom");
  const toEl = document.getElementById("maDateTo");
  const customDiv = document.getElementById("maCustomRange");

  const period = periodEl?.value || "week";
  if (customDiv) customDiv.style.display = period === "custom" ? "flex" : "none";

  const now = Date.now();
  const MS_DAY = 86400000;
  let fromTs = 0;
  let toTs = now;

  if (period === "today") {
    const d = new Date(); d.setHours(0, 0, 0, 0);
    fromTs = d.getTime();
  } else if (period === "week") {
    fromTs = now - 7 * MS_DAY;
  } else if (period === "month") {
    fromTs = now - 30 * MS_DAY;
  } else if (period === "custom") {
    if (fromEl?.value) fromTs = new Date(fromEl.value).getTime();
    if (toEl?.value) toTs = new Date(toEl.value).getTime() + MS_DAY - 1;
  }

  const closedStatuses = ["yopildi", "bekor qilindi", "closed", "cancelled", "to'landi", "paid", "закрыто", "отменён", "оплачено", "canceled"];
  const allOrders = window.allOrders || {};
  const filtered = Object.values(allOrders).filter(order => {
    const st = String(order.status || order.statusKey || "").trim().toLowerCase();
    if (!closedStatuses.includes(st)) return false;
    const ts = Number(order.createdAt || order.timestamp || order.time || 0);
    if (period !== "all" && (ts < fromTs || ts > toTs)) return false;
    return true;
  });

  const lang = typeof getLang === "function" ? getLang() : "uz";
  const getItemName = (item) => typeof item.name === "object"
    ? item.name?.[lang] || item.name?.uz || item.name?.ru || item.name?.en || "—"
    : item.name || "—";

  // ── Har bir taom bo'yicha statistika yig'ish ──
  const menuIndex = window.allMenu || {};
  const stats = {};   // name -> { name, qty, sum, category, costSum }
  const hourly = new Array(24).fill(0);

  filtered.forEach(order => {
    const ts = Number(order.createdAt || order.timestamp || order.time || 0);
    if (ts) {
      const hour = new Date(ts).getHours();
      hourly[hour] += 1;
    }
    if (!order.items) return;
    Object.values(order.items).forEach(item => {
      const name = getItemName(item);
      const qty = Number(item.qty || 0);
      const price = Number(item.price || 0);
      const sum = price * qty;

      let category = item.category;
      let unitCost = Number(item.costSnapshot || 0);
      if (!category || !unitCost) {
        const menuItem = Object.values(menuIndex).find(m => getItemName(m) === name) || null;
        if (!category) category = menuItem?.category || "boshqa";
        if (!unitCost) unitCost = Number(menuItem?.foodCost || 0);
      }

      if (!stats[name]) stats[name] = { name, qty: 0, sum: 0, category, costSum: 0 };
      stats[name].qty += qty;
      stats[name].sum += sum;
      stats[name].costSum += unitCost * qty;
    });
  });

  const statList = Object.values(stats);

  // ── Meta ──
  const metaEl = document.getElementById("maMeta");
  if (metaEl) {
    const periodLabels = {
      all: t("stats_all_time", "Barcha vaqt"),
      today: t("today_label", "Bugun"),
      week: t("stats_last_7_days", "Oxirgi 7 kun"),
      month: t("stats_last_30_days", "Oxirgi 30 kun"),
      custom: t("stats_custom_range", "Tanlangan davr")
    };
    metaEl.textContent = `${periodLabels[period] || ""} • ${filtered.length} ${t("orders_count_suffix", "ta buyurtma")} • ${statList.length} ${t("food_types_suffix", "xil taom")}`;
  }

  // ── 1) Eng ko'p sotilgan (TOP 5 by qty) ──
  const topSelling = [...statList].sort((a, b) => b.qty - a.qty).slice(0, 5);
  const topBody = document.getElementById("maTopSellingBody");
  if (topBody) {
    topBody.innerHTML = !topSelling.length
      ? `<tr><td colspan="3" style="text-align:center;padding:20px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`
      : topSelling.map((it, i) => `
        <tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:8px 10px;font-weight:600;">${["🥇","🥈","🥉"][i] || (i+1)} ${it.name}</td>
          <td style="padding:8px 10px;text-align:right;font-weight:700;">${it.qty.toLocaleString()}</td>
          <td style="padding:8px 10px;text-align:right;color:#16a34a;font-weight:600;">${it.sum.toLocaleString()} ${t("currency", "so'm")}</td>
        </tr>`).join("");
  }
  const topInsightEl = document.getElementById("maTopSellingInsight");
  if (topInsightEl) {
    topInsightEl.textContent = topSelling.length
      ? `💡 ${t("ma_top_insight_prefix", "Trendda")}: "${topSelling[0].name}" — ${t("ma_top_insight_suffix", "shu taomni ko'proq reklama qiling yoki aksiyaga qo'shing.")}`
      : "";
  }

  // ── 2) Eng kam sotilgan (BOTTOM 5 by qty, qty > 0) ──
  const lowSelling = [...statList].filter(s => s.qty > 0).sort((a, b) => a.qty - b.qty).slice(0, 5);
  const lowBody = document.getElementById("maLowSellingBody");
  if (lowBody) {
    lowBody.innerHTML = !lowSelling.length
      ? `<tr><td colspan="2" style="text-align:center;padding:20px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`
      : lowSelling.map(it => `
        <tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:8px 10px;">${it.name}</td>
          <td style="padding:8px 10px;text-align:right;font-weight:700;color:#dc2626;">${it.qty.toLocaleString()}</td>
        </tr>`).join("");
  }
  const lowInsightEl = document.getElementById("maLowSellingInsight");
  if (lowInsightEl) {
    lowInsightEl.textContent = lowSelling.length
      ? `⚠️ ${t("ma_low_insight", "Ushbu taomlarni menyudan olib tashlash yoki narxini qayta ko'rib chiqish kerakmi?")}`
      : "";
  }

  // ── 3) Kategoriya bo'yicha savdo (pie) ──
  const catSums = {};
  statList.forEach(it => {
    const catObj = typeof findCategoryById === "function" ? findCategoryById(it.category) : null;
    const catLabel = catObj ? catObj.label : (it.category || t("ma_uncategorized", "Boshqa"));
    catSums[catLabel] = (catSums[catLabel] || 0) + it.sum;
  });
  const catLabels = Object.keys(catSums);
  const catValues = Object.values(catSums);
  const catCtx = document.getElementById("maCategoryPieChart");
  if (catCtx && typeof Chart !== "undefined") {
    if (_maCategoryChart) _maCategoryChart.destroy();
    const COLORS = ["#22c55e", "#3b82f6", "#f59e0b", "#ef4444", "#8b5cf6", "#06b6d4", "#ec4899", "#84cc16", "#f97316", "#6366f1"];
    if (catLabels.length) {
      _maCategoryChart = new Chart(catCtx, {
        type: "pie",
        data: {
          labels: catLabels,
          datasets: [{
            data: catValues,
            backgroundColor: COLORS.slice(0, catLabels.length),
            borderColor: "#fff",
            borderWidth: 2
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { position: "bottom", labels: { font: { size: 11 }, padding: 10, boxWidth: 12 } },
            tooltip: {
              callbacks: {
                label: ctx => {
                  const total = catValues.reduce((a, b) => a + b, 0);
                  const pct = total ? Math.round((ctx.raw / total) * 100) : 0;
                  return ` ${ctx.label}: ${ctx.raw.toLocaleString()} ${t("currency", "so'm")} (${pct}%)`;
                }
              }
            }
          }
        }
      });
    }
  }

  // ── 4) Foyda bo'yicha TOP (profit = sum - costSum), TOP 6 ──
  const profitCalc = [...statList]
    .map(it => ({ ...it, profit: it.sum - it.costSum, unitPrice: it.qty ? it.sum / it.qty : 0, unitCost: it.qty ? it.costSum / it.qty : 0 }));
  const profitTop = [...profitCalc].sort((a, b) => b.profit - a.profit).slice(0, 6);
  const profitBody = document.getElementById("maProfitTopBody");
  if (profitBody) {
    profitBody.innerHTML = !profitTop.length
      ? `<tr><td colspan="4" style="text-align:center;padding:20px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`
      : profitTop.map(it => `
        <tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:7px 8px;">${it.name}</td>
          <td style="padding:7px 8px;text-align:right;">${Math.round(it.unitPrice).toLocaleString()}</td>
          <td style="padding:7px 8px;text-align:right;color:#94a3b8;">${Math.round(it.unitCost).toLocaleString()}</td>
          <td style="padding:7px 8px;text-align:right;font-weight:700;color:#16a34a;">${Math.round(it.profit).toLocaleString()}</td>
        </tr>`).join("");
  }

  // ── 4b) Eng kam foyda (BOTTOM 6 by profit, qty > 0 bo'lganlar orasidan) ──
  const profitLow = [...profitCalc].filter(it => it.qty > 0).sort((a, b) => a.profit - b.profit).slice(0, 6);
  const profitLowBody = document.getElementById("maProfitLowBody");
  if (profitLowBody) {
    profitLowBody.innerHTML = !profitLow.length
      ? `<tr><td colspan="4" style="text-align:center;padding:20px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`
      : profitLow.map(it => `
        <tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:7px 8px;">${it.name}</td>
          <td style="padding:7px 8px;text-align:right;">${Math.round(it.unitPrice).toLocaleString()}</td>
          <td style="padding:7px 8px;text-align:right;color:#94a3b8;">${Math.round(it.unitCost).toLocaleString()}</td>
          <td style="padding:7px 8px;text-align:right;font-weight:700;color:${it.profit < 0 ? "#dc2626" : "#b45309"};">${Math.round(it.profit).toLocaleString()}</td>
        </tr>`).join("");
  }

  // ── 5) Soatlar bo'yicha sotuv (buyurtmalar soni har soatda) ──
  const hourCtx = document.getElementById("maHourlyChart");
  if (hourCtx && typeof Chart !== "undefined") {
    if (_maHourlyChart) _maHourlyChart.destroy();
    _maHourlyChart = new Chart(hourCtx, {
      type: "bar",
      data: {
        labels: hourly.map((_, h) => `${String(h).padStart(2, "0")}:00`),
        datasets: [{
          label: t("ma_hourly_orders_label", "Buyurtmalar soni"),
          data: hourly,
          backgroundColor: "#3b82f6CC",
          borderColor: "#3b82f6",
          borderWidth: 1,
          borderRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          y: { beginAtZero: true, ticks: { precision: 0, font: { size: 11 } }, grid: { color: "rgba(0,0,0,0.05)" } },
          x: { grid: { display: false }, ticks: { font: { size: 10 } } }
        }
      }
    });
  }
  const peakHour = hourly.indexOf(Math.max(...hourly));
  const hourlyInsightEl = document.getElementById("maHourlyInsight");
  if (hourlyInsightEl) {
    hourlyInsightEl.textContent = Math.max(...hourly) > 0
      ? `⏰ ${t("ma_peak_hour_prefix", "Eng gavjum soat")}: ${String(peakHour).padStart(2, "0")}:00 — ${t("ma_peak_hour_suffix", "shu vaqtda xodimlarni ko'proq band qiling.")}`
      : "";
  }

  // ── 6) Hech sotilmagan taomlar (faol menyudagi, lekin statList'da yo'q yoki qty=0) ──
  const soldNames = new Set(statList.filter(s => s.qty > 0).map(s => s.name));
  const zeroSalesItems = Object.values(menuIndex).filter(m => {
    if (m.active === false) return false;
    const nm = getItemName(m);
    return !soldNames.has(nm);
  });
  const zeroSalesWrap = document.getElementById("maZeroSalesList");
  if (zeroSalesWrap) {
    zeroSalesWrap.innerHTML = !zeroSalesItems.length
      ? `<p style="font-size:13px;color:#16a34a;margin:0;">✅ ${t("ma_zero_sales_none", "Barcha faol taomlar tanlangan davrda sotilgan.")}</p>`
      : zeroSalesItems.map(m => `<span style="display:inline-flex;align-items:center;background:var(--admin-danger-bg);color:#b91c1c;border:1px solid #fecaca;border-radius:999px;padding:5px 12px;font-size:12.5px;font-weight:600;">${escapeHtml(getItemName(m))}</span>`).join("");
  }

  // ── 7) O'sish / Pasayish % — joriy davrni avvalgi teng uzunlikdagi davr bilan solishtirish ──
  const growthWrap = document.getElementById("maGrowthCards");
  if (growthWrap) {
    if (period === "all") {
      growthWrap.innerHTML = `<p style="font-size:13px;color:#94a3b8;margin:0;">ℹ️ ${t("ma_growth_all_time_note", "\"Barcha vaqt\" tanlanganda solishtirish mumkin emas — aniq davr tanlang.")}</p>`;
    } else {
      const rangeLen = toTs - fromTs;
      const prevFrom = fromTs - rangeLen;
      const prevTo = fromTs - 1;
      const prevFiltered = Object.values(allOrders).filter(order => {
        const st = String(order.status || order.statusKey || "").trim().toLowerCase();
        if (!closedStatuses.includes(st)) return false;
        const ts = Number(order.createdAt || order.timestamp || order.time || 0);
        return ts >= prevFrom && ts <= prevTo;
      });
      let prevRevenue = 0, prevOrderCount = prevFiltered.length;
      prevFiltered.forEach(order => {
        Object.values(order.items || {}).forEach(item => {
          prevRevenue += Number(item.price || 0) * Number(item.qty || 0);
        });
      });
      const curRevenue = statList.reduce((a, s) => a + s.sum, 0);
      const curOrderCount = filtered.length;

      const pct = (cur, prev) => prev > 0 ? ((cur - prev) / prev) * 100 : (cur > 0 ? 100 : 0);
      const revenuePct = pct(curRevenue, prevRevenue);
      const orderPct = pct(curOrderCount, prevOrderCount);

      const growthCard = (label, curVal, pctVal, isMoney) => {
        const up = pctVal >= 0;
        const displayVal = isMoney ? `${Math.round(curVal).toLocaleString()} ${t("currency", "so'm")}` : curVal.toLocaleString();
        return `<div style="border:1px solid var(--border-color,#e2e8f0);border-radius:12px;padding:12px 14px;">
          <div style="font-size:11.5px;color:#94a3b8;margin-bottom:4px;">${label}</div>
          <div style="font-size:16px;font-weight:700;color:var(--text-primary,#1e293b);">${displayVal}</div>
          <div style="font-size:12.5px;font-weight:700;margin-top:4px;color:${up ? "#16a34a" : "#dc2626"};">${up ? "▲" : "▼"} ${Math.abs(pctVal).toFixed(1)}%</div>
        </div>`;
      };
      growthWrap.innerHTML =
        growthCard(t("ma_growth_revenue_label", "Tushum"), curRevenue, revenuePct, true) +
        growthCard(t("ma_growth_orders_label", "Buyurtmalar"), curOrderCount, orderPct, false);
    }
  }

  // ── 8) Oxirgi 30 kun TOP 10 (davr filtridan mustaqil, doim so'nggi 30 kun) ──
  const thirtyDaysAgo = now - 30 * MS_DAY;
  const stats30 = {};
  Object.values(allOrders).forEach(order => {
    const st = String(order.status || order.statusKey || "").trim().toLowerCase();
    if (!closedStatuses.includes(st)) return;
    const ts = Number(order.createdAt || order.timestamp || order.time || 0);
    if (ts < thirtyDaysAgo || ts > now) return;
    Object.values(order.items || {}).forEach(item => {
      const name = getItemName(item);
      const qty = Number(item.qty || 0);
      const sum = Number(item.price || 0) * qty;
      if (!stats30[name]) stats30[name] = { name, qty: 0, sum: 0 };
      stats30[name].qty += qty;
      stats30[name].sum += sum;
    });
  });
  const top10ThirtyDays = Object.values(stats30).sort((a, b) => b.qty - a.qty).slice(0, 10);
  const top10Body = document.getElementById("maTop10ThirtyDaysBody");
  if (top10Body) {
    top10Body.innerHTML = !top10ThirtyDays.length
      ? `<tr><td colspan="4" style="text-align:center;padding:20px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`
      : top10ThirtyDays.map((it, i) => `
        <tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:8px 10px;font-weight:700;color:#94a3b8;">${i + 1}</td>
          <td style="padding:8px 10px;font-weight:600;">${it.name}</td>
          <td style="padding:8px 10px;text-align:right;font-weight:700;">${it.qty.toLocaleString()}</td>
          <td style="padding:8px 10px;text-align:right;color:#16a34a;font-weight:600;">${it.sum.toLocaleString()} ${t("currency", "so'm")}</td>
        </tr>`).join("");
  }

  // ── 9) Kategoriya bo'yicha tushum (jadval — pie chart yonida raqamli ko'rinish) ──
  const totalCatRevenue = catValues.reduce((a, b) => a + b, 0);
  const catRevenueRows = catLabels.map((label, i) => ({ label, value: catValues[i] })).sort((a, b) => b.value - a.value);
  const catRevenueBody = document.getElementById("maCategoryRevenueBody");
  if (catRevenueBody) {
    catRevenueBody.innerHTML = !catRevenueRows.length
      ? `<tr><td colspan="3" style="text-align:center;padding:20px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`
      : catRevenueRows.map(row => {
        const share = totalCatRevenue ? (row.value / totalCatRevenue) * 100 : 0;
        return `<tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:8px 10px;font-weight:600;">${escapeHtml(row.label)}</td>
          <td style="padding:8px 10px;text-align:right;color:#16a34a;font-weight:600;">${Math.round(row.value).toLocaleString()} ${t("currency", "so'm")}</td>
          <td style="padding:8px 10px;text-align:right;color:var(--text-secondary);">${share.toFixed(1)}%</td>
        </tr>`;
      }).join("");
  }

  // ── 10) Taomlar ABC tahlili (Pareto: A=80%, B=keyingi 15%, C=qolgan 5% kümülativ tushum) ──
  const abcSorted = [...statList].filter(s => s.sum > 0).sort((a, b) => b.sum - a.sum);
  const totalAbcRevenue = abcSorted.reduce((a, s) => a + s.sum, 0);
  let cumSum = 0;
  const abcRows = abcSorted.map(it => {
    cumSum += it.sum;
    const cumShare = totalAbcRevenue ? (cumSum / totalAbcRevenue) * 100 : 0;
    const cls = cumShare <= 80 ? "A" : cumShare <= 95 ? "B" : "C";
    return { ...it, cumShare, cls };
  });
  const abcCounts = { A: 0, B: 0, C: 0 };
  abcRows.forEach(r => abcCounts[r.cls]++);
  const abcSummaryWrap = document.getElementById("maAbcSummary");
  if (abcSummaryWrap) {
    const abcColors = { A: "#16a34a", B: "#d97706", C: "#dc2626" };
    const abcBg = { A: "#f0fdf4", B: "#fffbeb", C: "#fef2f2" };
    abcSummaryWrap.innerHTML = ["A", "B", "C"].map(cls => `
      <div style="flex:1;min-width:100px;background:${abcBg[cls]};border:1px solid ${abcColors[cls]}33;border-radius:10px;padding:10px 14px;text-align:center;">
        <div style="font-size:18px;font-weight:800;color:${abcColors[cls]};">${cls}</div>
        <div style="font-size:12px;color:var(--text-secondary);">${abcCounts[cls]} ${t("ma_abc_items_suffix", "ta taom")}</div>
      </div>`).join("");
  }
  const abcBody = document.getElementById("maAbcBody");
  if (abcBody) {
    const abcColors = { A: "#16a34a", B: "#d97706", C: "#dc2626" };
    const abcBg = { A: "#dcfce7", B: "#fef3c7", C: "#fee2e2" };
    abcBody.innerHTML = !abcRows.length
      ? `<tr><td colspan="4" style="text-align:center;padding:20px;color:#94a3b8;">📭 ${t("no_data", "Ma'lumot topilmadi")}</td></tr>`
      : abcRows.map(it => `
        <tr style="border-bottom:1px solid var(--border-color,#f1f5f9);">
          <td style="padding:8px 10px;">${escapeHtml(it.name)}</td>
          <td style="padding:8px 10px;text-align:right;color:#16a34a;font-weight:600;">${Math.round(it.sum).toLocaleString()} ${t("currency", "so'm")}</td>
          <td style="padding:8px 10px;text-align:right;color:var(--text-secondary);">${it.cumShare.toFixed(1)}%</td>
          <td style="padding:8px 10px;text-align:center;"><span style="display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:6px;background:${abcBg[it.cls]};color:${abcColors[it.cls]};font-weight:800;font-size:12px;">${it.cls}</span></td>
        </tr>`).join("");
  }
};

// ==========================================
// 🕐 XODIMLAR DAVOMADI — DASHBOARD KARTOCHKALARI
// Firebase: restaurants/{restId}/attendance/{YYYY-MM-DD}/{userId}
//           { checkIn, checkOut, status: "keldi"|"kechikdi"|"kelmadi" }
// ==========================================


// ==========================================
// 📅 DAVOMAT DASHBOARD — ADMIN (v2)
// Holat mantiqı: onlineAt vs workStart asosida
//   "keldi"    — vaqtida yoki erta keldi
//   "kechikdi" — kech keldi (onlineAt > workStart + lateMins)
//   "kelmadi"  — bugun hech qachon kelmadi
// Filtr: har bir summary card burchagidagi kalenda ikonasi
// ==========================================
(function initAttendanceDashboard() {

  // ── Utility ─────────────────────────────────────────────────────────────────
  function todayDateStr() {
    return new Date().toISOString().slice(0, 10);
  }

  function tsToHHMM(ts) {
    if (!ts) return "—";
    const d = new Date(Number(ts));
    return d.getHours().toString().padStart(2, "0") + ":" +
      d.getMinutes().toString().padStart(2, "0");
  }

  // ── State ────────────────────────────────────────────────────────────────────
  let _attendanceDate = todayDateStr();
  let _workStartTs = 0;   // bugungi ish boshlanish vaqti (ms)
  let _lateMins = 15;  // kechikish chegarasi (daqiqa)
  let _activeFilter = null; // "keldi" | "kechikdi" | "kelmadi" | null (hammasi)
  let _lastAttObj = {};   // so'nggi attendance snapshot (filter uchun)
  let _lastUsersObj = {};   // so'nggi users snapshot (filter uchun)

  // ── Settings dan ish boshlanish vaqtini yuklash ──────────────────────────────
  function loadWorkStartFromSettings(db, restId, dateStr) {
    if (!db || !restId) return Promise.resolve();
    return get(ref(db, `restaurants/${restId}/settings`)).then(snap => {
      if (!snap.exists()) return;
      const s = snap.val();
      const raw = s.workingHours || s.workStartTime || s.workStart || "";
      if (!raw) return;
      const part = String(raw).split(/\s*[-–]\s*/)[0].trim();
      const [h, m] = part.split(":").map(Number);
      if (isNaN(h)) return;
      const targetDate = dateStr ? new Date(dateStr) : new Date();
      targetDate.setHours(h, m || 0, 0, 0);
      _workStartTs = targetDate.getTime();
      _lateMins = Number(s.attendanceLateMins || 15);
    }).catch(() => { });
  }

  // ── Bir xodim uchun holat hisoblash ──────────────────────────────────────────
  // Firebase'da yozilgan maydonlar: onlineAt (birinchi kirish), status ("present"/"offline")
  // Biz workStart ga nisbatan "keldi" / "kechikdi" / "kelmadi" chiqaramiz
  function calcStatus(rec) {
    if (!rec) return "kelmadi";

    // onlineAt yozilgan bo'lsa — xodim bugun kamida bir marta kirib kelgan
    const arrivalTs = rec.onlineAt || rec.checkIn || 0;
    if (!arrivalTs) return "kelmadi";

    // Ish boshlanish ma'lum bo'lsa — kechikishni tekshiramiz
    if (_workStartTs) {
      const deadline = _workStartTs + _lateMins * 60 * 1000;
      return Number(arrivalTs) <= deadline ? "keldi" : "kechikdi";
    }

    // workStart noma'lum bo'lsa — kelgan deb hisoblaymiz
    return "keldi";
  }

  // ── Badge styles ─────────────────────────────────────────────────────────────
  const BADGE = {
    keldi: { icon: "✅", label: t("att_status_came", "Keldi"), bg: "var(--admin-success-bg)", color: "#15803d", border: "#86efac", grad: "135deg,#dcfce7,#bbf7d0" },
    kechikdi: { icon: "⏰", label: t("att_status_late", "Kechikdi"), bg: "var(--admin-warning-bg)", color: "#92400e", border: "#fcd34d", grad: "135deg,#fef9c3,#fde68a" },
    kelmadi: { icon: "❌", label: t("att_status_absent", "Kelmadi"), bg: "var(--admin-danger-bg)", color: "#b91c1c", border: "#f87171", grad: "135deg,#fee2e2,#fecaca" }
  };

  // i18n fix: BADGE.label above is computed once, when this IIFE runs at
  // page load — a plain `const`, not a function, so switching language
  // never re-evaluated it (unlike PO_STATUSES/UNIT_LABELS in the Purchase
  // module, which already had this exact recompute+rerender hook). Mutate
  // the SAME object's .label in place (not reassign BADGE) so every closure
  // holding a reference to it — renderAttendanceCards()'s `BADGE[status]`
  // lookups — automatically sees the fresh text without any other change.
  function _recomputeAttendanceBadges() {
    BADGE.keldi.label = t("att_status_came", "Keldi");
    BADGE.kechikdi.label = t("att_status_late", "Kechikdi");
    BADGE.kelmadi.label = t("att_status_absent", "Kelmadi");
  }

  // getAttendanceRoleMeta — global funksiya, pastga qarang (ROLE_ICONS yonida)

  // ── Kalenda SVG icon ─────────────────────────────────────────────────────────
  function calIcon(stroke) {
    return `<svg width="14" height="14" viewBox="0 0 24 24" fill="none"
      stroke="${stroke}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <rect x="3" y="4" width="18" height="18" rx="2" ry="2"/>
      <line x1="16" y1="2" x2="16" y2="6"/>
      <line x1="8" y1="2" x2="8" y2="6"/>
      <line x1="3" y1="10" x2="21" y2="10"/>
    </svg>`;
  }

  // ── Summary kartochkalarini render qilish ────────────────────────────────────
  function renderSummaryCards(attendanceObj, usersObj) {
    let came = 0, late = 0, absent = 0;

    // So'nggi snapshot'larni saqlab qo'yamiz (filter uchun kerak)
    _lastAttObj = attendanceObj || {};
    _lastUsersObj = usersObj || {};

    Object.entries(usersObj || {}).forEach(([uid, user]) => {
      // faqat aktiv, admin/client emas
      if (!user.active) return;
      if (user.role === "admin" || user.role === "client") return;

      const rec = (attendanceObj || {})[uid];
      const st = calcStatus(rec);
      if (st === "keldi") came++;
      else if (st === "kechikdi") late++;
      else absent++;
    });

    const el = {
      came: document.getElementById("attendanceCameCount"),
      late: document.getElementById("attendanceLateCount"),
      absent: document.getElementById("attendanceAbsentCount"),
      label: document.getElementById("attendanceDateLabel")
    };

    if (el.came) el.came.textContent = came;
    if (el.late) el.late.textContent = late;
    if (el.absent) el.absent.textContent = absent;

    // Sana labelini yangilash
    if (el.label) {
      const isToday = _attendanceDate === todayDateStr();
      el.label.textContent = isToday ? t("today_label", "Bugun") : _attendanceDate;
    }
  }

  // ── Xodim kartochkalarini render qilish ──────────────────────────────────────
  function renderAttendanceCards(attendanceObj, usersObj, filterStatus) {
    const container = document.getElementById("attendanceCardsContainer");
    if (!container) return;

    const staffList = Object.entries(usersObj || {})
      .filter(([, u]) => u.active && u.role !== "admin" && u.role !== "client")
      .sort((a, b) => {
        const order = { owner: 0, manager: 1, head_chef: 2, chef: 3, waiter: 4, cashier: 5, delivery_manager: 6, courier: 6, inventory_manager: 7, finance: 8, crm: 9, hr: 10 };
        return (order[a[1].role] ?? 9) - (order[b[1].role] ?? 9);
      });

    if (!staffList.length) {
      container.innerHTML = `
        <div style="grid-column:1/-1;text-align:center;padding:32px;color:#94a3b8;font-size:14px;">
          👥 ${t("no_staff_found", "Hech qanday xodim topilmadi")}
        </div>`;
      return;
    }

    // Filter qo'llash
    const filtered = filterStatus
      ? staffList.filter(([uid]) => {
        const rec = (attendanceObj || {})[uid];
        return calcStatus(rec) === filterStatus;
      })
      : staffList;

    if (!filtered.length) {
      const b = BADGE[filterStatus] || BADGE["kelmadi"];
      container.innerHTML = `
        <div style="grid-column:1/-1;text-align:center;padding:32px;color:#94a3b8;font-size:14px;">
          ${b.icon} ${t("att_no_staff_with_status", "Bu sanada {status} xodim yo'q").replace("{status}", `<strong style="color:${b.color}">${b.label.toLowerCase()}</strong>`)}
        </div>`;
      return;
    }

    container.innerHTML = filtered.map(([uid, user]) => {
      const rec = (attendanceObj || {})[uid];
      const status = calcStatus(rec);
      const b = BADGE[status] || BADGE["kelmadi"];

      // Kelgan/ketgan vaqt — onlineAt yoki checkIn
      const arrTs = rec?.onlineAt || rec?.checkIn;
      const depTs = rec?.offlineAt || rec?.checkOut;
      const arrStr = arrTs ? tsToHHMM(arrTs) : "—";
      const depStr = depTs ? tsToHHMM(depTs) : (status === "kelmadi" ? "—" : t("att_still_working", "Ishda"));

      // Kechikish miqdori (agar kechikdi bo'lsa)
      let lateLabel = "";
      if (status === "kechikdi" && _workStartTs && arrTs) {
        const diffMin = Math.max(0, Math.round((Number(arrTs) - _workStartTs) / 60000));
        if (diffMin > 0) {
          const h = Math.floor(diffMin / 60);
          const m = diffMin % 60;
          if (h > 0 && m > 0) lateLabel = t("att_late_hm", "+{h} soat {m} daqiqa kech").replace("{h}", h).replace("{m}", m);
          else if (h > 0) lateLabel = t("att_late_h", "+{h} soat kech").replace("{h}", h);
          else lateLabel = t("att_late_m", "+{m} daqiqa kech").replace("{m}", m);
        }
      }

      const roleMeta = getAttendanceRoleMeta(user.role);
      const roleIcon = roleMeta.icon;
      const roleLabel = roleMeta.label;
      const initial = (user.name || "?").charAt(0).toUpperCase();

      // avatar rang — rolega qarab
      const avatarGrad = roleMeta.gradient;

      return `
        <div style="
          background:var(--bg-card); border-radius:14px; padding:16px 18px;
          box-shadow:0 2px 8px rgba(0,0,0,0.07); border:1px solid var(--border-light);
          display:flex; flex-direction:column; gap:10px;
          transition:box-shadow .2s;
        ">
          <!-- Sarlavha: avatar + ism + badge -->
          <div style="display:flex; align-items:center; gap:12px;">
            <div style="
              width:42px; height:42px; border-radius:50%;
              background:${avatarGrad}; color:#fff;
              display:flex; align-items:center; justify-content:center;
              font-size:18px; font-weight:800; flex-shrink:0;
            ">${initial}</div>
            <div style="flex:1; min-width:0;">
              <div style="font-size:15px; font-weight:700; color:var(--text-primary);
                white-space:nowrap; overflow:hidden; text-overflow:ellipsis;"
              >${user.name || t("unknown_label", "Noma'lum")}</div>
              <div style="font-size:11px; color:var(--text-secondary); margin-top:1px;">${roleIcon} ${roleLabel}</div>
            </div>
            <span style="
              background:${b.bg}; color:${b.color};
              font-size:12px; font-weight:700; padding:4px 10px;
              border-radius:20px; white-space:nowrap; flex-shrink:0;
            ">${b.icon} ${b.label}</span>
          </div>

          <!-- Vaqtlar: Kirdi / Chiqdi -->
          <div style="display:grid; grid-template-columns:1fr 1fr; gap:8px;">
            <div style="background:var(--bg-hover); border-radius:10px; padding:8px 12px; text-align:center;">
              <div style="font-size:10px; color:#94a3b8; font-weight:600;
                text-transform:uppercase; letter-spacing:.4px;">${t("att_checkin_label", "Kirdi")}</div>
              <div style="font-size:16px; font-weight:800; color:var(--text-primary); margin-top:2px;">${arrStr}</div>
              ${lateLabel ? `<div style="font-size:10px; color:#b45309; margin-top:1px;">${lateLabel}</div>` : ""}
            </div>
            <div style="background:var(--bg-hover); border-radius:10px; padding:8px 12px; text-align:center;">
              <div style="font-size:10px; color:#94a3b8; font-weight:600;
                text-transform:uppercase; letter-spacing:.4px;">${t("att_checkout_label", "Chiqdi")}</div>
              <div style="font-size:${depTs ? "16px" : "13px"}; font-weight:${depTs ? "800" : "500"};
                color:${depTs ? "#1e293b" : "#94a3b8"}; margin-top:2px;">${depStr}</div>
            </div>
          </div>
        </div>
      `;
    }).join("");
  }

  // ── Firebase'dan berilgan sanadagi davomadni yuklash (realtime) ──────────────
  function loadAttendanceForDate(dateStr) {
    const restId = localStorage.getItem("restaurantId");
    const dbRef = window.db;
    if (!restId || !dbRef) {
      // db hali tayyor emas — qayta urinish
      setTimeout(() => loadAttendanceForDate(dateStr), 300);
      return;
    }

    // Avvalgi listenerni o'chirish (darhol — eski sana/eski work-start bilan qayta render bo'lib ketmasligi uchun)
    if (window._attendanceUnsubscribe) {
      try { window._attendanceUnsubscribe(); } catch (_) { }
    }

    // Tanlangan sanaga mos ish boshlanish vaqtini avval to'liq yuklab olamiz,
    // FAQAT shundan keyin attendance listenerini ulaymiz — aks holda birinchi
    // render "_workStartTs" hali 0 bo'lgan holatda ishga tushib, hamma xodim
    // "Keldi" deb chiqib ketardi (kechikish tekshiruvi ishlamay qolardi).
    loadWorkStartFromSettings(dbRef, restId, dateStr).then(() => {
      window._attendanceUnsubscribe = onValue(
        ref(dbRef, `restaurants/${restId}/attendance/${dateStr}`),
        snap => {
          const attObj = snap.val() || {};
          // allUsers hali to'lmagan bo'lsa — biroz kutib qayta chaqiramiz
          if (!window.allUsers || !Object.keys(window.allUsers).length) {
            setTimeout(() => {
              renderSummaryCards(attObj, window.allUsers || {});
              renderAttendanceCards(attObj, window.allUsers || {}, _activeFilter);
            }, 800);
          }
          renderSummaryCards(attObj, window.allUsers || {});
          renderAttendanceCards(attObj, window.allUsers || {}, _activeFilter);
        },
        () => { }
      );
    });
  }

  // ── Sana o'zgarganda ─────────────────────────────────────────────────────────
  function onDateChange(newDate) {
    _attendanceDate = newDate || todayDateStr();
    _activeFilter = null;          // sana o'zgarsa filterni tozalash
    _updateFilterCardStyles();       // card ko'rinishini yangilash
    loadAttendanceForDate(_attendanceDate);
  }

  // ── Status filtrini yoqish/o'chirish ─────────────────────────────────────────
  window.toggleAttendanceFilter = function (status) {
    // Agar xuddi shu filter bosilgan bo'lsa — bekor qilish (toggle)
    _activeFilter = (_activeFilter === status) ? null : status;
    _updateFilterCardStyles();
    renderAttendanceCards(_lastAttObj, _lastUsersObj, _activeFilter);
  };

  // ── Staff tab (oshpaz/ofitsiant/kassir/hammasi) almashganda davomatni shunga mos qayta chizish ──
  window.onStaffTabRoleChange = function () {
    renderSummaryCards(_lastAttObj, _lastUsersObj);
    renderAttendanceCards(_lastAttObj, _lastUsersObj, _activeFilter);
  };

  // ── Til o'zgarganda (i18n.js dagi onLangChange orqali) tashqaridan
  // chaqirish uchun global hook — BADGE.label larni qayta hisoblab,
  // hozir ekranda ko'rinib turgan kartochka/summary'ni allaqachon
  // keshlangan _lastAttObj/_lastUsersObj asosida (yangi Firebase
  // so'rovisiz) qayta chizadi. ──
  window._recomputeAttendanceI18n = function () {
    _recomputeAttendanceBadges();
    renderSummaryCards(_lastAttObj, _lastUsersObj);
    renderAttendanceCards(_lastAttObj, _lastUsersObj, _activeFilter);
  };

  // ── Aktiv card ga vizual chegara ko'rsatish ───────────────────────────────────
  function _updateFilterCardStyles() {
    const ids = { keldi: "attSumCard_keldi", kechikdi: "attSumCard_kechikdi", kelmadi: "attSumCard_kelmadi" };
    Object.entries(ids).forEach(([key, id]) => {
      const el = document.getElementById(id);
      if (!el) return;
      if (_activeFilter === key) {
        el.style.outline = "3px solid currentColor";
        el.style.outlineOffset = "2px";
        el.style.boxShadow = "0 4px 16px rgba(0,0,0,0.15)";
        el.style.transform = "scale(1.02)";
      } else {
        el.style.outline = "";
        el.style.outlineOffset = "";
        el.style.boxShadow = "";
        el.style.transform = _activeFilter ? "scale(0.97)" : "";
      }
    });
  }

  // ── Global handler'lar (HTML onclick uchun) ───────────────────────────────────
  window.openAttendanceDatePicker = function () {
    const picker = document.getElementById("attendanceDatePicker");
    if (!picker) return;
    picker.value = _attendanceDate;
    // showPicker() — zamonaviy brauzerlar uchun (Chrome 99+, Firefox 101+)
    if (typeof picker.showPicker === "function") {
      try { picker.showPicker(); return; } catch (_) { }
    }
    // Fallback: vaqtincha ko'rsatib click qilish
    picker.style.opacity = "1";
    picker.style.width = "100%";
    picker.style.height = "100%";
    picker.style.pointerEvents = "auto";
    picker.focus();
    picker.click();
    setTimeout(() => {
      picker.style.opacity = "0";
      picker.style.width = "1px";
      picker.style.height = "1px";
      picker.style.pointerEvents = "none";
    }, 200);
  };

  window.onAttendanceDateChange = function (val) {
    if (val) onDateChange(val);
  };

  // ── Firebase modullarini global'ga chiqarish (eski kod bilan moslik uchun) ────
  function exposeFirebaseModules() {
    // onValue, ref, get endi to'g'ridan-to'g'ri scope'dan ishlatiladi
    window.__fbModules = { onValue, ref, get };
  }

  // ── allUsers o'zgarganda summary'ni qayta hisoblash ──────────────────────────
  function refreshAttendanceOnUserChange() {
    const restId = localStorage.getItem("restaurantId");
    if (!restId || !window.db) {
      setTimeout(refreshAttendanceOnUserChange, 400);
      return;
    }

    onValue(
      ref(window.db, `restaurants/${restId}/users`),
      () => {
        get(ref(window.db, `restaurants/${restId}/attendance/${_attendanceDate}`))
          .then(snap2 => {
            renderSummaryCards(snap2.val() || {}, window.allUsers || {});
            renderAttendanceCards(snap2.val() || {}, window.allUsers || {}, _activeFilter);
          })
          .catch(() => { });
      },
      () => { }
    );
  }

  function injectAttendanceSection(onReady) {
    const staffSection = document.getElementById("staff");
    if (!staffSection) {
      setTimeout(() => injectAttendanceSection(onReady), 200);
      return;
    }
    // Davomat endi alohida tab (#attendanceTab) ichida ko'rinadi, avvalgi
    // kabi barcha tablarda doim ko'rinadigan statik blok emas.
    const attendanceTabEl = document.getElementById("attendanceTab");
    if (!attendanceTabEl) {
      setTimeout(() => injectAttendanceSection(onReady), 200);
      return;
    }
    if (!window._staffActiveRole) {
      const activeTabBtn = staffSection.querySelector(".staff-tabs .tab-btn.active");
      window._staffActiveRole = activeTabBtn?.dataset.role || "employee";
    }
    if (document.getElementById("attendanceDashboardSection")) {
      if (onReady) onReady();
      return;
    }

    const section = document.createElement("div");
    section.id = "attendanceDashboardSection";
    section.style.cssText = "margin-top:0;margin-bottom:28px;padding-bottom:0;";

    section.innerHTML = `
      <style>
        #attendanceDashboardSection { font-family: inherit; }
        #attendanceDashboardSection .att-section-title {
          font-size: 15px;
          font-weight: 800;
          color:var(--text-primary);
          margin-bottom: 12px;
          display: flex;
          align-items: center;
          gap: 8px;
        }
        #attendanceCardsContainer {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
          gap: 14px;
        }
        @media (max-width: 480px) {
          #attendanceCardsContainer { grid-template-columns: 1fr; }
        }
      </style>

      <div class="att-section-title">📅 ${t("attendance_section_title", "Bugungi davomat")}</div>

      <input
        type="date"
        id="attendanceDatePicker"
        style="position:absolute;top:0;left:0;opacity:0;width:1px;height:1px;pointer-events:none;"
        onchange="window.onAttendanceDateChange(this.value)"
      />

      <!-- XODIM KARTOCHKALARI -->
      <div id="attendanceCardsContainer">
        <div style="grid-column:1/-1;text-align:center;padding:20px;color:#94a3b8;">
          ⏳ ${t("loading", "Yuklanmoqda...")}
        </div>
      </div>
    `;

    attendanceTabEl.appendChild(section);
    if (onReady) onReady();
  }

  // "Davomat" tabi ochilganda chaqiriladi (showStaffTab orqali) — sana va
  // xodimlar ro'yxati o'zgargan bo'lishi mumkin, shu sabab qayta yuklaymiz.
  window.onStaffAttendanceTabOpen = function () {
    if (typeof _ensureAttendanceReportHTML === "function") _ensureAttendanceReportHTML();
    if (typeof window.renderAttendanceReport === "function") window.renderAttendanceReport();
    injectAttendanceSection(() => {
      loadAttendanceForDate(_attendanceDate);
    });
  };

  function boot() {
    exposeFirebaseModules();
    injectAttendanceSection(() => {
      loadAttendanceForDate(_attendanceDate);
      refreshAttendanceOnUserChange();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

// ══════════════════════════════════════════════════════════════
//  menu-import.js  —  CSV / Excel menyu import moduli
//  Nesta ERP admin.js ga qo'shimcha blok sifatida qo'shiladi
//  Bog'liqliklar: SheetJS (CDN), admin.js'dagi db, BASE_PATH,
//                 findCategoryById, autoTranslate, t(), showAdminNotification
// ══════════════════════════════════════════════════════════════

// ── 1. SheetJS CDN yuklash (birinchi marta chaqirilganda) ──────
async function loadSheetJS() {
  if (window.XLSX) return;
  await new Promise((res, rej) => {
    const s = document.createElement("script");
    // xlsx-js-style: cell-level styling (.s) qo'llab-quvvatlaydi
    s.src = "https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/dist/xlsx.bundle.js";
    s.onload = res;
    s.onerror = () => rej(new Error("SheetJS yuklanmadi"));
    document.head.appendChild(s);
  });
}

// ── 2. Faylni o'qib, massivga aylantirish ─────────────────────
async function parseUploadedFile(file) {
  await loadSheetJS();
  const buf = await file.arrayBuffer();
  const wb = XLSX.read(new Uint8Array(buf), { type: "array" });
  const ws = wb.Sheets[wb.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(ws, { defval: "" });
  return rows;
}

// CSV qabul qilish uchun fallback (SheetJS CSV ham o'qiydi, lekin sof CSV uchun zapas)
async function parseCsvFile(file) {
  const text = await file.text();
  const lines = text.split(/\r?\n/).filter(l => l.trim());
  if (!lines.length) return [];

  // Ajratuvchi: ; yoki ,
  const sep = lines[0].includes(";") ? ";" : ",";
  const headers = lines[0].split(sep).map(h => h.trim().replace(/^"+|"+$/g, ""));

  return lines.slice(1).map(line => {
    const vals = line.split(sep);
    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = (vals[i] ?? "").trim().replace(/^"+|"+$/g, "");
    });
    return obj;
  });
}

// ── 3. Qatorni Nesta ERP formatiga o'tkazish ────────────────────
// Kutilayotgan ustunlar (katta-kichik harfsiz, bo'sh joy muhim emas):
//   nom | name | nomi       → name.uz
//   narx | price | taom_narxi → price
//   kategoriya | category   → category  (ID yoki nom)
//   subkategoriya | subcategory → subcategory
//   tayyorlanish | prep_time → prepTime (daqiqa)
//   rasm | img | imgUrl     → imgUrl
function normalizeHeader(h = "") {
  return h.toLowerCase().replace(/[\s_\-]/g, "");
}

const HEADER_MAP = {
  nom: "nameUz",
  name: "nameUz",
  nomi: "nameUz",
  taomismi: "nameUz",
  narx: "price",
  price: "price",
  taomnarxi: "price",
  narxi: "price",
  kategoriya: "category",
  category: "category",
  cat: "category",
  subkategoriya: "subcategory",
  subcategory: "subcategory",
  sub: "subcategory",
  tayyorlanish: "prepTime",
  preptime: "prepTime",
  vaqt: "prepTime",
  rasm: "imgUrl",
  img: "imgUrl",
  imgurl: "imgUrl",
  photo: "imgUrl",
  tavsif: "desc",
  description: "desc",
  desc: "desc",
};

function mapRow(rawRow) {
  const out = {};
  for (const [rawKey, val] of Object.entries(rawRow)) {
    const norm = normalizeHeader(rawKey);
    const mappedKey = HEADER_MAP[norm];
    if (mappedKey) out[mappedKey] = String(val ?? "").trim();
  }
  return out;
}

// ── 4. Kategoriyani topish yoki birinchi mavjudini olish ─────────
function resolveCategoryId(categoryInput) {
  if (!categoryInput) return "";

  const all = typeof getAllMergedCategories === "function"
    ? getAllMergedCategories()
    : (window._allCategories || []);

  // Avval exact ID match
  const byId = all.find(c => c.id === categoryInput);
  if (byId) return byId.id;

  // Ism bo'yicha qidirish (uz/ru/en)
  const lower = categoryInput.toLowerCase();
  const byName = all.find(c =>
    (c.label || "").toLowerCase() === lower ||
    (c.labelRu || "").toLowerCase() === lower
  );
  return byName ? byName.id : categoryInput; // noma'lum bo'lsa saqlab qo'yamiz
}

function resolveSubcategoryId(catId, subInput) {
  if (!subInput) return "";
  const catObj = typeof findCategoryById === "function"
    ? findCategoryById(catId)
    : null;
  if (!catObj?.sub) return subInput;

  const lower = subInput.toLowerCase();
  const found = catObj.sub.find(s =>
    s.id === subInput ||
    (s.label || "").toLowerCase() === lower
  );
  return found ? found.id : subInput;
}

// ── 5. Preview jadvalini ko'rsatish ───────────────────────────────
let _importRows = [];          // parsed + mapped rows
let _importConfirmed = false;

function openImportModal(rows) {
  _importRows = rows;
  _importConfirmed = false;

  // Modal mavjud bo'lmasa – yaratamiz
  let modal = document.getElementById("csvImportModal");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "csvImportModal";
    modal.innerHTML = _buildModalHTML();
    document.body.appendChild(modal);
    _attachModalEvents(modal);
  } else {
    // ichini yangilaymiz
    modal.querySelector(".ci-body").innerHTML = _buildTableHTML(rows);
    modal.querySelector(".ci-footer-info").textContent = _footerInfo(rows);
  }

  modal.style.display = "flex";
  document.body.style.overflow = "hidden";
}

function _footerInfo(rows) {
  const ok = rows.filter(r => !r._error).length;
  const err = rows.filter(r => r._error).length;
  return t("import_footer_info", "Jami: {total} qator   ✅ Yuklash mumkin: {ok}   ⚠️ Xatolik: {err}")
    .replace("{total}", rows.length).replace("{ok}", ok).replace("{err}", err);
}

function _buildModalHTML() {
  return `
<div class="ci-overlay"></div>
<div class="ci-dialog">
  <div class="ci-header">
    <div class="ci-title">
      <svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
        <path d="M9 17H7A5 5 0 0 1 7 7h2"/><path d="M15 7h2a5 5 0 1 1 0 10h-2"/>
        <line x1="8" y1="12" x2="16" y2="12"/>
      </svg>
      ${t("menu_import_modal_title", "Menyu import — CSV / Excel")}
    </div>
    <button class="ci-close" id="csvImportClose">✕</button>
  </div>

  <div class="ci-body">
    ${_buildTableHTML(_importRows)}
  </div>

  <div class="ci-footer">
    <span class="ci-footer-info">${_footerInfo(_importRows)}</span>
    <div class="ci-footer-btns">
      <button class="ci-btn ci-btn-cancel" id="csvImportCancel">${t("cancel_btn", "Bekor qilish")}</button>
      <button class="ci-btn ci-btn-confirm" id="csvImportConfirm">
        <span class="ci-btn-icon">⬆</span> ${t("upload_to_firebase_btn", "Firebasega yuklash")}
      </button>
    </div>
  </div>
</div>
${_buildModalStyles()}`;
}

function _buildTableHTML(rows) {
  if (!rows.length) {
    return `<div class="ci-empty">
      <svg width="48" height="48" fill="none" stroke="#888" stroke-width="1.5" viewBox="0 0 24 24">
        <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/>
        <line x1="12" y1="16" x2="12.01" y2="16"/>
      </svg>
      <p>${t("csv_file_empty_or_invalid", "Fayl bo'sh yoki ustunlar noto'g'ri.")}</p>
      <small>${t("import_expected_columns", "Kutilgan ustunlar")}: <b>nom, narx, kategoriya, subkategoriya, tayyorlanish, rasm</b></small>
    </div>`;
  }

  const rowsHtml = rows.map((r, i) => {
    const hasErr = !!r._error;
    const catObj = typeof findCategoryById === "function" && r.category
      ? findCategoryById(r.category) : null;
    const catLabel = catObj ? catObj.label : (r.category || "—");
    const subObj = catObj?.sub?.find(s => s.id === r.subcategory);
    const subLabel = subObj ? subObj.label : (r.subcategory || "—");

    return `
<tr class="${hasErr ? "ci-row-error" : "ci-row-ok"}" title="${hasErr ? "⚠ " + r._error : ""}">
  <td class="ci-num">${i + 1}</td>
  <td class="ci-name">
    ${hasErr
        ? `<span class="ci-error-badge">⚠</span>`
        : `<span class="ci-ok-badge">✓</span>`
      }
    ${escapeHtmlLocal(r.nameUz || "—")}
  </td>
  <td class="ci-price">${r.price ? Number(r.price).toLocaleString() + " UZS" : "—"}</td>
  <td class="ci-cat">${escapeHtmlLocal(catLabel)}</td>
  <td class="ci-sub">${escapeHtmlLocal(subLabel)}</td>
  <td class="ci-prep">${r.prepTime ? r.prepTime + " " + t("minute_short", "daq") : "30 " + t("minute_short", "daq")}</td>
  <td class="ci-img">
    ${r.imgUrl
        ? `<img src="${escapeHtmlLocal(r.imgUrl)}" onerror="this.style.display='none'" loading="lazy">`
        : `<span class="ci-no-img">—</span>`
      }
  </td>
</tr>`;
  }).join("");

  return `
<div class="ci-scroll">
  <table class="ci-table">
    <thead>
      <tr>
        <th>#</th>
        <th>${t("name_label", "Nomi")}</th>
        <th>${t("price", "Narxi")}</th>
        <th>${t("category", "Kategoriya")}</th>
        <th>${t("subcategory", "Subkategoriya")}</th>
        <th>${t("time_label", "Vaqt")}</th>
        <th>${t("image_label", "Rasm")}</th>
      </tr>
    </thead>
    <tbody>${rowsHtml}</tbody>
  </table>
</div>`;
}

function escapeHtmlLocal(v = "") {
  return String(v)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function _attachModalEvents(modal) {
  const closeModal = () => {
    modal.style.display = "none";
    document.body.style.overflow = "";
  };

  modal.querySelector("#csvImportClose")?.addEventListener("click", closeModal);
  modal.querySelector("#csvImportCancel")?.addEventListener("click", closeModal);
  modal.querySelector(".ci-overlay")?.addEventListener("click", closeModal);

  modal.querySelector("#csvImportConfirm")?.addEventListener("click", async () => {
    await runImportToFirebase(_importRows, modal);
  });
}

// ── 6. Firebasega yozish ──────────────────────────────────────────
async function runImportToFirebase(rows, modal) {
  const validRows = rows.filter(r => !r._error);
  if (!validRows.length) {
    showAdminNotification?.(`⚠ ${t("import_no_valid_rows", "Yuklash uchun to'g'ri qator yo'q")}`, "error");
    return;
  }

  const confirmBtn = modal?.querySelector("#csvImportConfirm");
  if (confirmBtn) {
    confirmBtn.disabled = true;
    confirmBtn.innerHTML = `<span class="ci-spinner"></span> ${t("loading", "Yuklanmoqda...")}`;
  }

  let success = 0, fail = 0;
  for (const row of validRows) {
    try {
      const id = Date.now().toString() + "_" + Math.random().toString(36).slice(2, 6);
      const nameUz = row.nameUz;
      const nameRu = typeof autoTranslate === "function" ? await autoTranslate(nameUz, "ru") : nameUz;
      const nameEn = typeof autoTranslate === "function" ? await autoTranslate(nameUz, "en") : nameUz;

      const payload = {
        name: { uz: nameUz, ru: nameRu, en: nameEn },
        price: Number(row.price) || 0,
        category: row.category || "",
        subcategory: row.subcategory || "",
        prepTime: Number(row.prepTime) || 30,
        imgUrl: row.imgUrl || "img/no-image.png",
        imgPath: "",
        active: true,
        createdAt: Date.now(),
        importedAt: Date.now(),
      };

      await set(ref(db, BASE_PATH + "/menu/" + id), payload);
      success++;
    } catch (e) {
      console.error("Import row error:", e);
      fail++;
    }
  }

  if (confirmBtn) {
    confirmBtn.disabled = false;
    confirmBtn.innerHTML = `<span class="ci-btn-icon">✓</span> ${t("finished_label", "Tugadi")}`;
  }

  const msg = t("import_success_count", "✅ {count} ta mahsulot yuklandi").replace("{count}", success)
    + (fail ? " | " + t("import_fail_count", "⚠ {count} ta xato").replace("{count}", fail) : "");
  showAdminNotification?.(msg, fail ? "warning" : "success");

  setTimeout(() => {
    modal.style.display = "none";
    document.body.style.overflow = "";
  }, 1500);
}

// ── 7. Asosiy kirish nuqtasi: fayl input handler ──────────────────
async function handleMenuImportFile(file) {
  if (!file) return;

  const ext = file.name.split(".").pop().toLowerCase();
  let rawRows = [];

  try {
    if (ext === "csv") {
      rawRows = await parseCsvFile(file);
    } else if (["xlsx", "xls", "ods"].includes(ext)) {
      rawRows = await parseUploadedFile(file);
    } else {
      alert(t("alert_only_csv_xlsx", "Faqat CSV, XLSX, XLS formatlar qabul qilinadi."));
      return;
    }
  } catch (e) {
    alert(t("file_read_error", "Fayl o'qishda xato: ") + e.message);
    return;
  }

  if (!rawRows.length) {
    showAdminNotification?.(`⚠ ${t("file_empty_label", "Fayl bo'sh")}`, "error");
    return;
  }

  // Map + validate
  const mapped = rawRows
    .map(mapRow)
    .filter(r => Object.keys(r).length > 0)
    .map(r => {
      // Kategoriya ID ga aylantirish
      r.category = resolveCategoryId(r.category);
      r.subcategory = resolveSubcategoryId(r.category, r.subcategory);

      // Validatsiya
      if (!r.nameUz) r._error = t("import_err_name_empty", "Nomi bo'sh");
      else if (!r.price || isNaN(Number(r.price))) r._error = t("import_err_price_invalid", "Narxi noto'g'ri");
      else if (!r.category) r._error = t("import_err_no_category", "Kategoriya yo'q");

      return r;
    });

  openImportModal(mapped);
}

// ── 8. Tugma + input yaratish (bitta call bilan ishga tushadi) ───
function injectImportButton(containerSelector = "#menuSection") {
  if (document.getElementById("menuImportBtn")) return; // allaqachon bor

  const container = document.querySelector(containerSelector)
    || document.querySelector(".menu-header")
    || document.querySelector('[data-section="menu"]')
    || document.body;

  // Yashirin input
  const fileInput = document.createElement("input");
  fileInput.type = "file";
  fileInput.id = "menuImportFileInput";
  fileInput.accept = ".csv,.xlsx,.xls,.ods";
  fileInput.style.display = "none";
  fileInput.addEventListener("change", e => {
    if (e.target.files[0]) {
      handleMenuImportFile(e.target.files[0]);
      e.target.value = "";    // keyingi yuklashga tayyor
    }
  });
  document.body.appendChild(fileInput);

 
}

// ── 9. Namuna fayl yuklab olish (template) ───────────────────────
