  function _renderCustomers() {
    const customers = window.allCustomers || window.crmState?.customers || [];
    const from = new Date(document.getElementById("reportFrom")?.value || 0);
    const to = new Date(document.getElementById("reportTo")?.value || Date.now());
    to.setHours(23, 59, 59, 999);

    const vip = customers.filter(c => c.vip || c.isVip);
    const newCust = customers.filter(c => {
      const d = new Date(c.createdAt || c.registeredAt || 0);
      return d >= from && d <= to;
    });

    // Orders per customer
    const orders = Object.values(window.allOrders || {});
    const custOrders = {};
    const custRevenue = {};
    orders.forEach(o => {
      const phone = o.customerPhone || o.phone || "";
      if (!phone) return;
      custOrders[phone] = (custOrders[phone] || 0) + 1;
      custRevenue[phone] = (custRevenue[phone] || 0) + Number(o.totalPrice || o.total || 0);
    });
    const returning = customers.filter(c => (custOrders[c.phone] || 0) > 1);

    const totalOrders = orders.length;
    const totalRevenue = orders.reduce((sum, o) => sum + Number(o.totalPrice || o.total || 0), 0);
    const avgCheck = totalOrders > 0 ? Math.round(totalRevenue / totalOrders) : 0;

    setText("rptCustTotal", fmt(customers.length));
    setText("rptCustNew", fmt(newCust.length));
    setText("rptCustTotalOrders", fmt(totalOrders));
    setText("rptCustAvgCheck", Number(avgCheck).toLocaleString(currentDateLocale()));

    // Customer growth chart
    window._rptCustGrowthData = { customers, orders };
    window.rptCustGrowthMode = function (mode) {
      // Toggle button styles
      const dayBtn   = document.getElementById("rptCustGrowthDay");
      const monthBtn = document.getElementById("rptCustGrowthMonth");
      if (dayBtn && monthBtn) {
        const activeStyle   = "padding:4px 12px;border-radius:20px;border:1.5px solid #1a56db;background:#1a56db;color:#fff;font-size:12px;font-weight:600;cursor:pointer;";
        const inactiveStyle = "padding:4px 12px;border-radius:20px;border:1.5px solid var(--border);background:var(--bg-card);color:var(--text-muted);font-size:12px;font-weight:600;cursor:pointer;";
        dayBtn.style.cssText   = mode === "day"   ? activeStyle : inactiveStyle;
        monthBtn.style.cssText = mode === "month" ? activeStyle : inactiveStyle;
      }
      const { customers: custs, orders: ords } = window._rptCustGrowthData || {};
      const canvas = document.getElementById("rptCustGrowthChart");
      if (!canvas) return;

      // Build time buckets
      const buckets = {};
      const now = new Date();
      const periodDays = mode === "day" ? 14 : 6; // last 14 days or 6 months

      if (mode === "day") {
        for (let i = periodDays - 1; i >= 0; i--) {
          const d = new Date(now); d.setDate(now.getDate() - i);
          const key = d.toLocaleDateString(currentDateLocale(), { day: "2-digit", month: "2-digit" });
          buckets[key] = 0;
        }
        (custs || []).forEach(c => {
          const d = new Date(c.createdAt || c.registeredAt || 0);
          const key = d.toLocaleDateString(currentDateLocale(), { day: "2-digit", month: "2-digit" });
          if (key in buckets) buckets[key]++;
        });
      } else {
        for (let i = periodDays - 1; i >= 0; i--) {
          const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
          const key = d.toLocaleDateString(currentDateLocale(), { month: "short", year: "2-digit" });
          buckets[key] = 0;
        }
        (custs || []).forEach(c => {
          const d = new Date(c.createdAt || c.registeredAt || 0);
          const key = d.toLocaleDateString(currentDateLocale(), { month: "short", year: "2-digit" });
          if (key in buckets) buckets[key]++;
        });
      }

      const labels = Object.keys(buckets);
      const data   = Object.values(buckets);

      // Cumulative running total for "growth" feel
      const cumData = [];
      let running = (custs || []).filter(c => {
        const d = new Date(c.createdAt || c.registeredAt || 0);
        return isNaN(d) || d < new Date(now.getFullYear(), now.getMonth() - periodDays + 1, 1);
      }).length;
      data.forEach(v => { running += v; cumData.push(running); });

      // Destroy old chart if exists
      if (window._rptCustGrowthChart instanceof Chart) {
        window._rptCustGrowthChart.destroy();
      }

      window._rptCustGrowthChart = new Chart(canvas.getContext("2d"), {
        type: "line",
        data: {
          labels,
          datasets: [{
            label: t("crm_total_customers", "Mijozlar soni"),
            data: cumData,
            fill: true,
            tension: 0.4,
            borderColor: "#1a56db",
            backgroundColor: "rgba(26,86,219,0.08)",
            pointBackgroundColor: "#1a56db",
            pointRadius: 4,
            pointHoverRadius: 6,
            borderWidth: 2.5
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              callbacks: {
                label: ctx => ` ${ctx.parsed.y} ${t("crm_total_customers_suffix", "ta mijoz")}`
              }
            }
          },
          scales: {
            x: {
              grid: { color: "#f3f4f6" },
              ticks: { font: { size: 11 }, color: "#9ca3af" }
            },
            y: {
              beginAtZero: true,
              grid: { color: "#f3f4f6" },
              ticks: {
                font: { size: 11 }, color: "#9ca3af",
                stepSize: 1,
                callback: v => Number.isInteger(v) ? v : null
              }
            }
          }
        }
      });
    };

    // Initial render — day mode
    setTimeout(() => window.rptCustGrowthMode("day"), 0);
  }

