  window.showStaffSalesBreakdown = function (userId) {
    const data = (window._rptStaffSalesData || {})[userId];
    if (!data) return;
    const fmtSum = n => Number(n || 0).toLocaleString() + " " + t("currency", "so'm");
    const avgCheck = data.ordersCount > 0 ? Math.round(data.sale / data.ordersCount) : 0;

    const payoutPercent = data.payoutPercent || 0;
    const payoutAmount = data.payoutAmount || 0;
    const payoutBasisLabel = data.usesSalesCommission
      ? t("rpt_payout_basis_sales", "Sotuvdan foiz")
      : t("rpt_payout_basis_fee", "Xizmat haqidan foiz");

    const overlay = document.createElement("div");
    overlay.id = "staffSalesBreakdownOverlay";
    overlay.style.cssText = "position:fixed; inset:0; background:rgba(0,0,0,.45); z-index:99999; display:flex; align-items:center; justify-content:center; padding:16px;";
    overlay.innerHTML = `
      <div style="background:var(--bg-card); border-radius:16px; padding:22px 20px; max-width:520px; width:100%; max-height:85vh; overflow-y:auto; box-shadow:0 20px 60px rgba(0,0,0,.2); position:relative;">
        <button onclick="document.getElementById('staffSalesBreakdownOverlay').remove()"
          style="position:absolute; top:12px; right:12px; background:var(--bg-hover); border:none; width:28px; height:28px; border-radius:8px; cursor:pointer; color:var(--text-muted);">✕</button>
        <h3 style="margin:0 0 16px; font-size:17px; font-weight:800; color:var(--text-primary);">👤 ${escapeHtml(data.name)}</h3>
        <div style="display:flex; flex-direction:column; gap:10px; font-size:14px;">
          <div style="display:flex; justify-content:space-between;">
            <span style="color:var(--text-muted);">📋 ${t("sa_today_orders", "Buyurtmalar")}</span>
            <span style="font-weight:700; color:var(--text-primary);">${fmt(data.ordersCount)} ${t("unit_pcs", "ta")}</span>
          </div>
          <div style="display:flex; justify-content:space-between;">
            <span style="color:var(--text-muted);">💰 ${t("rpt_total_sale_label", "Jami sotuv")}</span>
            <span style="font-weight:700; color:var(--text-primary);">${fmtSum(data.sale)}</span>
          </div>
          <div style="display:flex; justify-content:space-between;">
            <span style="color:var(--text-muted);">🧾 ${t("waiter_service_fee_label", "Xizmat haqi")}</span>
            <span style="font-weight:700; color:var(--text-primary);">${fmtSum(data.waiterServiceFee)}</span>
          </div>
          <div style="display:flex; justify-content:space-between;">
            <span style="color:var(--text-muted);">🎁 ${t("rpt_discount_given_label", "Berilgan chegirma")}</span>
            <span style="font-weight:700; color:#ef4444;">-${fmtSum(data.discount)}</span>
          </div>
          <div style="display:flex; justify-content:space-between;">
            <span style="color:var(--text-muted);">📊 ${t("rpt_avg_check_label", "O'rtacha chek")}</span>
            <span style="font-weight:700; color:var(--text-primary);">${fmtSum(avgCheck)}</span>
          </div>
          <div style="display:flex; justify-content:space-between; align-items:center;">
            <span style="color:var(--text-muted);">💵 ${t("rpt_payout_share_label", "Ulush (%)")}</span>
            <span style="display:flex; align-items:center; gap:6px;">
              <span title="${escapeHtml(payoutBasisLabel)}" style="font-size:11px; font-weight:600; color:#6366f1; background:var(--admin-purple-bg); padding:2px 8px; border-radius:20px;">${escapeHtml(payoutBasisLabel)}</span>
              <span style="font-weight:700; color:var(--text-primary);">${payoutPercent}%</span>
            </span>
          </div>
          <div style="border-top:1.5px dashed var(--border); margin-top:4px; padding-top:10px; display:flex; justify-content:space-between; font-size:16px;">
            <span style="font-weight:800; color:var(--text-primary);">💰 ${t("rpt_payable_amount_label", "To'lanadigan summa")}</span>
            <span style="font-weight:800; color:#16a34a;">${fmtSum(payoutAmount)}</span>
          </div>
        </div>
      </div>`;
    document.body.appendChild(overlay);
  };

